\subsection{Number of irreducible special polynomials}\label{sec:numberirredspecial}
In Section~\ref{SubSECT:disp}, we have already outlined the procedure for computing the normal part of the denominator of $g$ satisfying $\sigma(g)-g=f$. The challenge that remains is to handle the special part. As demonstrated in Example~\ref{Exam:strange}, a peculiar situation arises where the denominator of $g$ contains a special polynomial that does not already appear in the denominator of~$f$. Hence, to determine the denominator of~$g$, it becomes necessary to identify all irreducible special polynomials. However, the computation of all special polynomials remains an unresolved issue at present. In this subsection, we aim to establish that the number of irreducible special polynomials in $R$ that do not pairwise differ by elements of $K^*$ is bounded by the number of generators of $R$ over $C(x)$. This provides a crucial insight into the limited diversity of irreducible special polynomials. In Section~\ref{SUBSECT:structureofspecialpolynomials}, under certain assumptions, we will unveil the structure of irreducible special polynomials.
We begin with the following lemma that is a direct consequence of Theorem 2.1.12 on page 114 of \cite{Levin2008}.
\begin{lemma}
	\label{lm:constants}
	Suppose that $\cF$ is a $\sigma$-field of characteristic zero with algebraically closed field $C$ of constants, and $f\in \cF$ satisfying that $\sigma^\ell(f)=f$ for some $\ell>0$. Then $f\in C$.
\end{lemma}
\begin{corollary}
	\label{cor:sumofspecialpolynomials}
	Suppose that $p_1, p_2,\dots, p_m$ are special polynomials that are linearly independent over $K$, $\alpha_2,\dots,\alpha_m\in K$. Then $p_1+\alpha_2 p_2+\dots+\alpha_m p_m$ is a special polynomial if and only if $\alpha_2=\cdots=\alpha_m=0$.
\end{corollary}
\begin{proof}
	It suffices to show the necessary part. Suppose that $p_1+\alpha_2 p_2+\dots+\alpha_m p_m$ is a special polynomial. Then there is a positive integer $\ell$ and $\gamma,\beta_1,\dots,\beta_m\in K$ such that $\sigma^\ell(p_i)=\beta_i p_i$ and
	$$
	\sigma^\ell(p_1+\alpha_2 p_2+\dots+\alpha_m p_m)=\gamma (p_1+\alpha_2 p_2+\dots+\alpha_m p_m).
	$$
	A straightforward calculation reveals that $\beta_1=\gamma$, and $\sigma^\ell(\alpha_i)\beta_i=\beta_1\alpha_i$ for all $2\leq i\leq m$. This implies that $\sigma^\ell(\alpha_i p_i)=\beta_1 \alpha_i p_i$ and consequently, $\sigma^{\ell}(\alpha_i p_i/p_1)=\alpha_i p_i/p_1$, for all $2\leq i \leq m$. According to Lemma~\ref{lm:constants}, $\alpha_i p_i/p_1\in C$. For each $2\leq i\leq m$, as $p_i$ and $p_1$ are linearly independent over~$K$, it follows that $\alpha_i=0$.
\end{proof}
\begin{proposition}
	\label{prop:algebraicindependence}
	Suppose that $p_1,\dots, p_m$ are irreducible special polynomials that are pairwise not shift equivalent. Denote by $\ell_i$ the smallest positive integer such that $p_i \mid \sigma^{\ell_i}(p_i)$. Then the $\sigma^j(p_i), i=1,\dots,m, j=0,\dots,\ell_i-1$ are algebraically independent over~$K$.
\end{proposition}
\begin{proof}
	Set $N =\lcm(\ell_1,\dots,\ell_m)$. Then $\sigma^N(\sigma^j(p_i))=\alpha_{i,j}\sigma^j(p_i)$ for some $\alpha_{i,j}\in K$.
	Suppose on the contrary that the $\sigma^j(p_i), i=1,\dots,m, j=0,\dots,\ell_i-1$ are algebraically dependent over $K$.  Due to the difference analogue of Kolchin-Ostrowski theorem (see \cite{Hardouin2008-hypertranscendance,Ogawara2017}), there are integers $d_{i,j}, i=1,\dots,m,j=0,\dots,\ell_i-1$, not all zero, and $\beta\in K^*$ such that
	$$
	\prod_{i=1}^m \prod_{j=0}^{\ell_i-1} \alpha_{i,j}^{d_{i,j}}=\frac{\sigma^N(\beta)}{\beta}.
	$$
	Since $\sigma^N( \prod_{i,j} \sigma^j(p_i)^{d_{i,j}})=  \prod_{i,j} \alpha_{i,j}^{d_{i,j}} \prod_{i,j} \sigma^j(p_i)^{d_{i,j}}$, we have that
	$$
	\sigma^{N}\left(\frac{ \prod_{i,j} \sigma^j(p_i)^{d_{i,j}}}{\beta}\right)= \frac{\prod_{i,j} \sigma^j(p_i)^{d_{i,j}}}{\beta}.
	$$
	Due to Lemma~\ref{lm:constants}, $ \prod_{i,j} \sigma^j(p_i)^{d_{i,j}}=c\beta$ for some $c\in C$.
	Denote $S_1=\{(i,j) \mid d_{i,j}>0\}$ and $S_2=\{(i,j) \mid d_{i,j}<0\}$. Since the $d_{i,j}$ are not all zero and $t_0,\dots,t_{n-1}$ are algebraically independent over~$K$, neither $S_1$ nor $S_2$ is empty. This leads to
	$$
	\prod_{(i,j)\in S_1}\sigma^j(p_i)^{d_{i,j}}=c\beta\prod_{(i,j)\in S_2}\sigma^j(p_i)^{-d_{i,j}}.
	$$
	Choose $(i_1,j_1)\in S_1$.  Then $\sigma^{j_1}(p_{i_1})$ divides $\prod_{(i,j)\in S_2}\sigma^j(p_i)^{-d_{i,j}}$ and thus there exists $(i_2,j_2)\in S_2$ such that $\sigma^{j_1}(p_{i_1})$ divides $\sigma^{j_2}(p_{i_2})$.  As both  $\sigma^{j_1}(p_{i_1})$ and $\sigma^{j_2}(p_{i_2})$ are irreducible, $\sigma^{j_1}(p_{i_1})=\gamma\sigma^{j_2}(p_{i_2})$ for some $\gamma\in K$. If $i_1=i_2$ then $0\leq j_1\neq j_2\leq \ell_{i_1}-1$. Without loss of generality, assume $j_2>j_1$. Then $\sigma^{j_2-j_1}(p_{i_1})=p_{i_1}/\sigma^{-j_1}(\gamma)$, which contradicts the minimality of $\ell_{i_1}$. If $i_1\neq i_2$ then $p_{i_1}$ and $p_{i_2}$ are shift equivalent, contradicting the initial assumption.
\end{proof}

Since $F$ is a field generated over $K$ by $n$ indeterminates, the transcendence degree of $F$ over $K$ is equal to $n$. So we have the following corollary.
\begin{corollary}
	\label{cor:numbersofspecialpolynomials}
	Suppose that $p_1,\dots, p_m$ are irreducible special polynomials that are pairwise not shift equivalent. Then $\sum_{i=1}^m \ell_i \leq n$, where $\ell_i$ is the smallest positive integer such that $p_i \mid \sigma^{\ell_i}(p_i)$.
\end{corollary}
