We start with the $C$-finite case. In this case, we will demonstrate that the degree of all irreducible special polynomials is always equal to~$1$, without requiring the assumption that $\sum_{i=1}^m \ell_i = n$.
\begin{proposition}
	\label{prop:cfinitecase} Suppose that $A\in \GL_n(C)$. Then all irreducible special polynomials are linear in $t_0,t_1,\dots,t_{n-1}$.
\end{proposition}
\begin{proof}
	Let $B\in \GL_n(C)$ such that $BAB^{-1}=\diag(J_1,J_2,\dots,J_\ell)$, where $J_i$ is a Jordan block of order $n_i$. We claim that $n_i=1$ for all $1\leq i \leq \ell$. Without loss of generality, assume that $n_1>1$ and $\alpha_1$ is the eigenvalue of $J_1$.
	Set $\bar{T}=(\bar{t}_0,\dots,\bar{t}_{n-1})^t=B(t_0,\dots,t_{n-1})^t$. Then $\sigma(\bar{T})=BAB^{-1}\bar{T}$. Therefore $\sigma(\bar{t}_{n_1-1})=\alpha_1 \bar{t}_{n_1-1}+\bar{t}_{n_1}$ and $\sigma(\bar{t}_{n_1})=\alpha_1\bar{t}_{n_1}$. From these, it follows that $\sigma(\frac{\bar{t}_{n_1-1}}{\bar{t}_{n_1}})=\frac{\bar{t}_{n_1-1}}{\bar{t}_{n_1}}+\frac{1}{\alpha_1}$. Consequently,
	$$
	\sigma\left(\frac{\bar{t}_{n_1-1}}{\bar{t}_{n_1}}-\frac{x}{\alpha_1}\right)=\frac{\bar{t}_{n_1-1}}{\bar{t}_{n_1}}-\frac{x}{\alpha_1}.
	$$
	In other words, $\bar{t}_{n_1-1}/\bar{t}_{n_1}-x/\alpha_1\in C$, which is a contradiction with Hypothesis~\ref{hypo}. This proves our claim. Therefore $BAB^{-1}=\diag(\alpha_1,\dots,\alpha_n)$, where $\alpha_i\in C$. Finally, suppose that $p$ is an irreducible special polynomial. Note that $p$ can be expressed as a polynomial in $\bar{t}_0,\bar{t}_1,\dots,\bar{t}_{n-1}$. Corollary~\ref{cor:sumofspecialpolynomials} implies that $p$ is a monomial in $\bar{t}_0,\bar{t}_1,\dots,\bar{t}_{n-1}$. Hence $p=\beta \bar{t}_i$ for some $0\leq i \leq n-1$ and $\beta\in K$, and so it is linear in $t_0,t_1,\dots,t_{n-1}$.
\end{proof}
\begin{remark}
	\label{rem:cfinite}
	In the proof of Proposition~\ref{prop:cfinitecase}, the special polynomials $\bar{t}_0,\dots,\bar{t}_{n-1}$ are pairwise not shift equivalent and then the condition $\sum_{i=1}^m \ell_i=n$ is automatically satisfied. In fact, suppose $\sigma(\bar{t}_{i_1})=\beta\bar{t}_{i_2}$ for some $0\leq i_1\neq i_2\leq n-1$ and $\beta\in K$. Since $\sigma(\bar{t}_{i_1})=\alpha\bar{t}_{i_1}$ for some $\alpha\in K$, it follows that $\bar{t}_1,\bar{t}_2$ are linearly dependent over~$K$, which contradicts the fact that $\bar{t}_0,\dots,\bar{t}_{n-1}$ are algebraically independent over~$K$.
\end{remark}
Before proceeding to the general case, let's recall some fundamental results from difference Galois theory. For detailed information, readers can refer to Chapter~1 of \cite{vanderPutSinger1997-difference}. Let $\cR$ be the Picard-Vessiot ring for $\sigma(Y)=AY$ over~$K$, where $A$ is given as in \eqref{eqn:differencesystem}. In $\cR$, there exist idempotents $e_0,e_1,\dots,e_{s-1}$ such that
$$
\cR=\cR_0\oplus \cR_1 \oplus \dots \oplus \cR_{s-1},
$$
where $\cR_i=e_i\cR$ and $\cR_i$ is a domain. Moreover, $\cR_i$ serves as the Picard-Vessiot ring for $\sigma^s(Y)=A_{(s)}Y$ over $K$ with
$$
A_{(s)}=\sigma^{s-1}(A)\dots\sigma(A)A.
$$
Let $G$ be the Galois group of $\sigma(Y)=AY$ over $K$ and $H$ be the Galois group of $\sigma^s(Y)=A_{(s)}Y$ over~$K$. By Corollary~1.17 \cite[p.13]{vanderPutSinger1997-difference} we have $[G:H]=s$ and consequently, $H$~contains $G^{\circ}$, the identity component of~$G$. On the other hand, due to Proposition~1.20, $\cR_i$ is a trivial $H$-torsor which implies that $H$ is connected since $\cR_i$ is a domain. Hence $H=G^\circ$. In the following, it will be shown that the hypothesis $\sum_{i=1}^m \ell_i=n$ implies that the group $G^\circ$ is a torus. Consequently, the system $\sigma^s(Y)=A_{(s)}Y$ is equivalent to a diagonal system, indicating that appropriate linear combinations of $t_0,t_1,\dots,t_{n-1}$ are special polynomials. Indeed, they are all irreducible special polynomials.\begin{lemma}
	\label{lm:goodfundamentalmatrix}
	Suppose that $p_1,\dots, p_m$ are special polynomials. Then there exists a fundamental matrix $\cZ\in \GL_n(\cR)$ of $\sigma(Y)=AY$ such that $p_i(\cZ_j)$ is invertible in $\cR$ for all $1\leq i \leq m, 1\leq j \leq n$, where $\cZ_j$ denotes the $j$th column of $\cZ$.
\end{lemma}
\begin{proof}
	Let $N$ be a positive integer such that $p_i\mid \sigma^N(p_i)$ for all $1\leq i\leq m$ and let $q=(\prod_{i=1}^mp_i) \sigma(\prod_{i=1}^m p_i)\cdots \sigma^{N-1}(\prod_{i=1}^m p_i)$. Then $\sigma(q)=\alpha q$ for some $\alpha\in K$. We first show the lemma for $q$.

	Let $\cZ\in \GL_n(\cR)$ be a fundamental matrix of $\sigma(Y)=AY$. We claim that there exists an $M\in \GL_n(C)$ such that $q((\cZ M)_j)\neq 0$. Let $\bfu=(u_1,\dots,u_n)^t$ be a vector with indeterminate entries. Since $\cZ$ is invertible, as a polynomial in $\cR[\bfu]$, $q(\cZ \bfu)\neq 0$. Write $q(\cZ \bfu)=\sum_{j=1}^d f_{j}(\bfu) \bfm_j$, where $f_{j}(\bfu)\in C[\bfu]$ and $\bfm_1,\dots,\bfm_d\in \cR$ are linearly independent over~$C$. As $q(\cZ\bfu)\neq 0$, at least one of $f_1(\bfu),\dots,f_d(\bfu)$ is not zero, say $ f_{j_1}(\bfu)\neq 0$. Set $U$ to be the Zariski open subset of $C^n$ consisting of all $\bfa$ in $C^n$ such that $f_{j_1}(\bfa)\neq 0$. Then $U\times \dots \times U$ is a non-empty Zariski open subset of $C^{n\times n}$, where the direct product takes $n$ times. Let $M\in U\times \dots \times U$ be such that $\det(M)\neq 0$. Such $M$ exists because $U\times \dots \times U$ is Zariski dense in $C^{n\times n}$. Then for each column $\bfc$ of~$M$, it follows that $f_{j_1}(\bfc)\neq 0$, and thus $q(\cZ \bfc)\neq 0$. Since $M$ is invertible, $\cZ M$ is also a fundamental matrix of $\sigma(Y)=AY$. This proves our claim.

	Let $\bfc$ be a column of $M$. Then
	$$
	\sigma(q(\cZ \bfc))=q^\sigma(A\cZ\bfc)=\sigma(q)(\cZ\bfc)=\alpha q(\cZ\bfc)
	$$
	where $q^\sigma$ denotes the polynomial obtained by applying $\sigma$ to the coefficients of $q$. Hence, $q(\cZ\bfc)$ generates a nonzero $\sigma$-ideal in $\cR$. Since $\cR$ is $\sigma$-simple, this ideal must be equal to $\cR$ and thus $q(\cZ\bfc)$ is invertible in $\cR$. Finally, for each $1\leq i\leq m$, since $q(\cZ\bfc)=p_i(\cZ\bfc)h_i$ for some $h_i\in \cR$, $p_i(\cZ\bfc)$ is invertible in $\cR$.
\end{proof}

\begin{lemma}
	\label{lm:dimensionofGaloisgroups}
	Suppose that there exist irreducible special polynomials $p_1,\dots, p_m$ that are pairwise not shift equivalent, satisfying that $\sum_{i=1}^m \ell_i=n$, where $\ell_i$ is the smallest positive integer such that $p_i\mid \sigma^{\ell_i}(p_i)$. Then $\dim(G)=n$.
\end{lemma}
\begin{proof}
	It suffices to show that $\dim(G^\circ)=n$.
	Set
	$$
	  q_{\ell_0+\ell_1+\dots+\ell_i+j}=\sigma^{j-1}(p_{i+1})
	$$
	where $0\leq i\leq m-1$, $1\leq j \leq \ell_i$, and $\ell_0=0$. By Lemma~\ref{lm:goodfundamentalmatrix}, there exists a fundamental matrix $\cZ\in\GL_n(\cR) $ of $\sigma(Y)=AY$ such that $q_i(\cZ_j)$ is invertible in $\cR$ for all $1\leq i,j\leq n$, where $\cZ_j$ denotes the $j$th column of $\cZ$.
	Consider $\cR_0$, the Picard-Vessiot ring for $\sigma^s(Y)=A_{(s)}Y$ over~$K$. Let $\cF$ be the field of fractions of $\cR_0$. Since $G^\circ$ is the Galois group of $\sigma^s(Y)=A_{(s)}Y$ over $K$, $\dim(G^\circ)=\trdeg(\cF/K)$. Note that $e_0\cZ$ is a fundamental matrix of $\sigma^s(Y)=A_{(s)}Y$ and $e_0q_i(\cZ_j)=q_i(e_0\cZ_j)$ is invertible in $\cR_0$. Set $N={\rm lcm}(\ell_1,\dots,\ell_m)$. Then $q_i\mid \sigma^{sN}(q_i)$ for all $1\leq i\leq n$. Suppose that $\sigma^{sN}(q_i)=\alpha_i q_i$ with $\alpha_i\in K$. Then for each $1\leq i\leq n$, it holds that $\sigma^{sN}(q_i(e_0\cZ_j))=\alpha_i q_i(e_0\cZ_j)$ for all $1\leq j \leq n$.

	We claim that for each $1\leq j \leq n$,  $q_1(e_0\cZ_j),\dots,q_n(e_0\cZ_j)$ are algebraically independent over~$K$. Assume on the contrary that $q_1(e_0\cZ_j),\dots,q_n(e_0\cZ_j)$ are algebraically dependent over $K$. Using an argument similar to that in the proof of Proposition~\ref{prop:algebraicindependence}, we obtain
	integers $d_i$, not all zero, and a nonzero $\beta\in K$ such that
	$$
	\sigma^{sN}\left(\frac{\prod_iq_i^{d_i}}{\beta}\right)=\frac{\prod_iq_i^{d_i}}{\beta}.
	$$
	Due to Lemma~\ref{lm:constants}, $\prod_iq_i^{d_i}=c\beta$ for some $c\in C$.
	In other words, $q_1,\dots,q_n$ are algebraically dependent over~$K$. This contradicts the conclusion of Proposition~\ref{prop:algebraicindependence}. The claim is established.

	Now, for $1\leq j_1\neq j_2\leq n$, we have that
	$$\sigma^{sN}(q_i(e_0\cZ_{j_1})/q_i(e_0\cZ_{j_2}))=q_i(e_0\cZ_{j_1})/q_i(e_0\cZ_{j_2}).$$
	By Lemma~\ref{lm:constants} (replacing $\sigma$ with $\sigma^s$), $q_i(e_0\cZ_{j_1})=c_{i,j_1,j_2}q_i(e_0\cZ_{j_2})$ for all $1\leq i\leq n$, where $c_{i,j_1,j_2}\in C$. Denote by $\tilde{\cF}$ the subfield of $\cF$ generated by all $q_i(e_0\cZ_j)$ over $K$. Then the previous discussion implies that
	$
	\trdeg(\tilde{\cF}/K)=n.
	$
	Note that for each $1\leq j \leq n$, every entry of $e_0\cZ_j$ is algebraic over
        $K(q_1(e_0\cZ_j),\dots, q_n(e_0\cZ_j))$
        (and thus algebraic over $\tilde{\cF}$),
  because $q_1(e_0\cZ_j),\dots,q_n(e_0\cZ_j)$ are algebraically independent over $K$ and they are polynomial in the entries of $e_0\cZ_j$. Hence $\cF$ is a finite algebraic extension of $\tilde{\cF}$, as $\cF=K(e_0\cZ)$. So $\trdeg(\cF/K)=n$ and then $\dim(G^\circ)=n$. Consequently, $\dim(G)=n$.
\end{proof}

\begin{theorem}
	\label{thm:systemwithmanyspecialpolynomials}
	Under the same assumption as in Lemma~\ref{lm:dimensionofGaloisgroups}, all irreducible special polynomials are linear in $t_0, t_1,\dots,t_{n-1}$.
\end{theorem}
\begin{proof}
	Let $q_i,\alpha_i$ be as in the proof of Lemma~\ref{lm:dimensionofGaloisgroups}.
	We first show that $G^\circ$ is a torus. Due to Lemma~\ref{lm:dimensionofGaloisgroups}, $\dim(G^\circ)=n$. Hence the rank of $X(G^\circ)$, the group of characters of $G^\circ$ (which is a free abelian group), is at most $n$. As $\sigma^{sN}(q_i(e_0\cZ_1))=\alpha_i q_i(e_0\cZ_1)$, for each $g\in G^\circ$, $\sigma^{sN}(g(q_i(e_0\cZ_1)))=\alpha_i g(q_i(e_0\cZ_1))$. Hence $g(q_i(e_0\cZ_1))=\chi_i(g)g(q_i(e_0\cZ_1))$, where $\chi_i(g)\in C$. In other words, $q_i(e_0\cZ_1)$ induces a character $\chi_i\in X(G^\circ)$. Suppose that there are integers $d_i$, not all zero, such that $\prod_i\chi_i^{d_i}=\id$, where $\id$ is the unitary of $X(G^\circ)$. Then for all $g\in G^\circ$,
	\begin{align*}
		g\left(\prod_iq_i(e_0\cZ_1)^{d_i}\right)&=\prod_i\chi_i^{d_i}(g)\prod_iq_i(e_0\cZ_1)^{d_i}=\prod_iq_i(e_0\cZ_1)^{d_i}.
	\end{align*}
	The Galois correspondence (see, for example, Lemma~1.28 on page~20 of \cite{vanderPutSinger1997-difference}) implies that $\prod_iq_i(e_0\cZ_1)^{d_i}\in K$, which contradicts the fact that $q_1(e_0\cZ_1),\dots,q_n(e_0\cZ_1)$ are algebraically independent over~$K$. Therefore the rank of $X(G^\circ)$ is exactly equal to~$n$. Let $\tilde{\chi}_1, \dots,\tilde{\chi}_n$ be a base of $X(G^\circ)$, as a free abelian group. Consider the morphism
	\begin{align*}
		\phi\colon G^\circ &\longrightarrow \GL_1(C)^n \\
		g&\longmapsto (\tilde{\chi}_1(g),\dots,\tilde{\chi}_n(g)).
	\end{align*}
	Then $\phi$ is surjective with finite kernel because $\dim(G^\circ)=n$. Moreover, due to Lemma~B.20 of \cite{Feng-Hrushovskialgorithm}, $\ker(\phi)$ is generated as an algebraic group by all unipotent elements of $G^\circ$.  Note that if $h\in \GL_n(C)$ is unipotent then $h$ is of finite order if and only if $h=I$, the identity matrix.  So $\ker(\phi)=\{I\}$ and $\phi$ is an isomorphism. This proves that $G^\circ$ is a torus.

	By Theorem~2.1 of \cite{HendriksSinger1999}, there exists a $T\in \GL_n(K)$ such that
	$$
	\sigma^s(T)A_{(s)}T^{-1}=\diag(b_1,\dots,b_n),
	$$
	where $b_i\in K$.  Set $(\bar{t}_0,\dots,\bar{t}_{n-1})^t=T(t_0,\dots,t_{n-1})^t$. Then $\sigma^s(\bar{t}_i)=b_i\bar{t}_i$ for all $0\leq i \leq n-1$. In other words, $\bar{t}_0,\dots,\bar{t}_{n-1}$ are special polynomials. Finally, using an argument similar to the proof of Proposition~\ref{prop:cfinitecase}, it follows that every irreducible special polynomial is linear in $t_0,t_1,\dots,t_{n-1}$.
\end{proof}

