%{S} = \big\{n(\omega, \, \gamma), \frac{\partial n }{\partial \omega}(\omega, \, \gamma) \big\} \subset \Z[\alpha][\omega, \, \gamma], \vspace{1mm} \\
\Sigma = \left \{(\omega, \, \gamma) \in \mathbb{R}^{2} \; | \; \ n(\omega, \, \gamma)=0,\ \dfrac{\partial n }{\partial \omega}(\omega, \, \gamma)=0 \right\}, \vspace{1mm} \\ \Sigma_{\infty} = \big\{ \gamma \in \R  \; | \;  \Lc_{\omega}(n) = 0\big\}.
\end{array}
