\begin{document}

\maketitle

\begin{abstract}
In the $k$-Orthogonal Vectors ($k$-OV) problem we are given $k$ sets, each containing $n$ binary vectors of dimension $d=n^{o(1)}$, and our goal is to pick one vector from each set so that at each coordinate at least one vector has a zero. It is a central problem in fine-grained complexity, conjectured to require $n^{k-o(1)}$ time in the worst case.

We propose a way to \emph{plant} a solution among vectors with i.i.d.~$p$-biased entries, for appropriately chosen $p$, so that the planted solution is the unique one. Our conjecture is that the resulting $k$-OV instances still require time $n^{k-o(1)}$ to solve, \emph{on average}.

Our planted distribution has the property that any subset of strictly less than $k$ vectors 
has the \emph{same} marginal distribution as in the model distribution, consisting of i.i.d.~$p$-biased random vectors. We use this property to give average-case search-to-decision reductions for $k$-OV.
\end{abstract}

\section{Introduction}

The security of cryptographic systems crucially relies on heuristic assumptions about average-case hardness of certain computational problems.  Sustained cryptanalysis alongside technological advances
such as large-scale quantum computers, put these hardness assumptions under constant risk of being invalidated. It is therefore desirable to try to design cryptographic schemes based on new computational problems, preferably ones whose hardness is well-studied. 

The field of computational complexity developed over the last fifty years a good understanding of hardness of certain problems -- e.g., SAT is widely believed to require at least superpolynomial, maybe even exponential time~\cite{Williams19} -- however these are worst-case problems, and hence unsuitable for direct use as a basis for cryptography.

Fine-grained complexity~\cite{VVW18} is a younger branch of computational complexity that studies ``hardness of easy problems'', i.e., problems known to be solvable in polynomial time but supposedly not faster than some specified polynomial, say not faster than in cubic time. It gives rise to \emph{fine-grained cryptography}~\cite{BRSV17,LaVigneLW19,Rosen20}; the idea that it might be possible to build cryptography, notably public-key encryption, based on conjectured average-case hardness of polynomial-time problems studied in fine-grained complexity. These problems are easier than NP-hard ones, 
%(which seem too hard to be a basis for cryptography), 
but for polynomials of sufficiently high degree  may still be hard enough to give honest parties an adequate advantage over malicious attackers.

\subsection{The k-Orthogonal Vectors Problem}
The Orthogonal Vectors (OV) problem~\cite{Williams05}, together with its generalization $k$-OV, is one of the three main hard problems studied in fine-grained complexity, alongside 3SUM and APSP~\cite{VVW18}. Arguably, among the three, OV is the one whose (worst-case) hardness we understand the most -- in particular because it is implied by the Strong Exponential Time Hypothesis (SETH)~\cite{ImpagliazzoPZ01}, which is about the very well studied SAT problem.

We say that vectors $u_1, ..., u_k \in \{0,1\}^d$ are \emph{orthogonal} if, for all $j \in [d]$, $\prod_{\ell=1}^k u_\ell[j] = 0$, meaning that for every coordinate there is at least one zero entry among the $k$ vectors.
For $k \geq 2$, let ${U_1,...,U_k \in \{0,1\}^{n\times d}}$ be collections of $n$ $d$-dimensional binary vectors, where $U_{\ell,i}$ denotes the $i$-th vector of $U_\ell$.
The $k$-Orthogonal Vectors problem ($k$-OV) asks whether there exist $(s_1,\ldots,s_k) \in [n]^k$ such that $U_{1,s_1},U_{2,s_2},\ldots,U_{k,s_k}$ are orthogonal.

\paragraph{Worst-case complexity.} The naive algorithm solves $k$-OV in time $O(n^kd)$. For any fixed constant $c$, the algorithms by Abboud et al.~\cite{AbboudWY15} and Chan and Williams~\cite{ChanW20} solve OV in dimension $d=c \log n$ in time $O(n^{2-\varepsilon_c})$ for $\varepsilon_c > 0$. However, Gao et al.~\cite{GaoIKW18} conjecture that no such strongly subquadratic algorithm exists for superlogarithmic dimension $d = \omega(\log n)$. This conjecture (known as Low-dimension Orthogonal Vector Conjecture) is also implied by SETH~\cite{Williams05}. Both the upper bound for $d=O(\log n)$ and the SETH-implied hardness for $d=\omega(\log n)$ generalize to $k$-OV, for any constant $k \geq 2$, where the running time barrier is $n^k$~\cite{VVW18}.

\paragraph{Average-case complexity.}

For cryptographic purposes we care about \emph{average-case} hardness --
because we want to be able to efficiently sample instances that are hard to solve (in contrast to only having an existential knowledge that there are some hard instances). Moreover, the sampler shall correctly tell (with high probability) whether its output is a \yes- or \no-instance.

One way to achieve this is to embed a solution in an instance sampled from a distribution that generates \no-instances with high probability. This method of \emph{planting} a solution has been applied to a number of problems, e.g., $k$-Clique~\cite{JuelsP00} and (in the fine-grained setting) $k$-SUM~\cite{DinurKK24,AgrawalSSVV24} (a generalization of 3SUM) and Zero-$k$-Clique~\cite{LaVigneLW19} (a generalization of Zero-Triangle, which is a problem harder than both 3SUM and APSP), but not for ($k$-)OV. The following question remains wide-open~\cite{BRSV17, DalirrooyfardLW20,corr/abs-2503-21951}:
\begin{center}
\emph{How to plant orthogonal vectors (so that they are hard to find)?}
\end{center}


\subsection{Our results}

We propose a way of planting a solution in $k$-OV instances where each vector entry is i.i.d.~according to a $p$-biased\footnote{We say that a random bit is $p$-biased if it equals $1$ with probability $p$ and equals $0$ with probability $1-p$.} coin flip, for an appropriately chosen value of $p$ so that the planted solution is the only one in the instance, with good probability. We conjecture that solving these instances require $n^{k-o(1)}$ time on average.

\paragraph{Superlogarithmic dimension.}
The $k$-OV problem might have appeared as a poor candidate for a fine-grained average-case hard problem, as Kane and Williams~\cite{KaneW19} showed that for any fixed \(p \in (0,1)\), $k$-OV instances of i.i.d.~$p$-biased entries can be solved in \(O(n^{k-\varepsilon_p})\) time for some \(\varepsilon_p > 0\) by AC0 circuits.
However, such instances are only non-trivial for \(d = \Theta(\log n)\), a parameter setting which can be anyway solved in time $O(n^{k - \varepsilon})$, even in the worst case, using the algorithm of Chan and Williams~\cite{ChanW20}.
To obtain a candidate hard distribution based on i.i.d.\ entries, we therefore choose to sample the entries as $1$ with subconstant probability $p(n) = o(1)$, which leads to non-trivial instances in the superlogarithmic dimension regime $d = \omega(\log n)$. In
Appendix~\ref{section:attack}
we present another simple argument why a logarithmic dimension is not sufficient, further justifying our choice.

\paragraph{$(k-1)$-wise independence.}
Our planting procedure has the following notable property: any subset of $k-1$ (or less) out of the $k$ vectors that form the planted solution has the marginal distribution identical to that of $k-1$ independently sampled vectors with i.i.d.~$p$-biased random entries. In particular, each individual vector of the solution has the same marginal distribution as any other vector in the instance. This would not be true if we planted $k$ random vectors conditioned on orthogonality (i.e., a type of solution that may appear spontaneously with small probability), because such vectors tend to be sparser than the expectation. This sparsity is what makes the Kane--Williams algorithm~\cite{KaneW19} work, and lack thereof makes our instances immune to that algorithm.

We note that the $(k-1)$-wise independence property holds ``for free'' in natural distributions for $k$-SUM~\cite{AgrawalSSVV24,DinurKK24} and Zero-$k$-Clique~\cite{LaVigneLW19} because of the natural symmetry of cyclic groups $\mathbb{Z}_m$. However, it is a priori unclear how to get it for $k$-OV.

\paragraph{Search-to-decision reductions.}
To demonstrate the usefulness of the $(k-1)$-wise independence property, we give a fine-grained average-case search-to-decision reduction for our conjectured hard $k$-OV distribution. Actually, we give two such reductions, for two different parameter regimes. The simpler one, in Section~\ref{section:search2decision}, introduced an $O(\log n)$ overhead in the failure probability, so it is relevant only if the decision algorithm succeeds with probability higher than $1-\frac{1}{\log n}$. The other reduction, in Section~\ref{section:search2decision2}, works with small constant failure probabilities on both ends.

\paragraph{Planting multiple solutions.}
We also argue that $(k-1)$-wise independence allow planting more than one solution in a single instance, which we believe might be useful for building cryptographic primitives.

\vskip 1em

\noindent
Let us remark that all our results are nontrivial already for $k=2$, i.e., for the Orthogonal Vectors problem. However, from the point of view of cryptographic applications, larger values of $k$ are more interesting (as they potentially offer a bigger advantage for the honest parties), so we present all our results in full generality.

\subsection{Technical overview}

\paragraph{Planting.}
How do we generate $k$ orthogonal vectors such that any $k-1$ of them look innocent? First of all, we can focus on generating a single coordinate, and then repeat the process independently for each of the $d$ coordinates. Consider the joint distribution of $k$ i.i.d.~$p$-biased random bits. We need to modify it to set the probability of $k$ ones to $0$. If we just do it, and scale up the remaining probabilities accordingly, the probability of $k-1$ ones turns out wrong. After we fix that, the probability of $k-2$ ones is off, and so on, in a manner similar to the exclusion-inclusion principle. By doing this mental exercise we end up with a formula for the joint distribution of $k$ bits in a single coordinate of the $k$ vectors to be planted. How do we actually sample from this distribution? Since it has the $(k-1)$-wise independence property, the following approach must work: First sample $k-1$ i.i.d.~$p$-biased bits, and then sample the $k$-th bit with probability depending on the number of ones among the first $k-1$ bits. In Section~\ref{section:planted_dist} we show how to set this last probability exactly.

\paragraph{Search-to-decision reductions.}
Both our reductions are based on the same basic idea: In order to find the planted solution, we replace some of the vectors in the input instance with newly sampled vectors with i.i.d.~$p$-biased entries and run the decision algorithm on such a modified instance. If at least one of the planted vectors got resampled, the resulting instance has the same distribution as if no planting occurred (thanks to the $(k-1)$-wise independence), and so the decision algorithm returns \no{} with good probability. Otherwise the planted solution is still there and the decision algorithm likely says \yes.

Our first reduction (see Section~\ref{section:search2decision}) applies this idea to perform a binary search. It introduces a factor of $k \log n$ overhead in the running time and also in the failure probability, because we need to take a union bound over all invocations of the decision algorithm returning correct answers.

Our second reduction (see Section~\ref{section:search2decision2}) is an adaptation of a search-to-decision reduction for $k$-SUM due to Agrawal et al.~\cite{AgrawalSSVV24}. In short, the reduction repeatedly resamples a random subset of vectors, runs the decision algorithm, and keeps track for each of the original vectors, how many times the decision algorithm returned \yes{} when this vector was not resampled. Statistically, this count should be larger for vectors in the planted solution. A careful probabilistic analysis shows that this is indeed the case.

\subsection{Open problems}

\paragraph{Fine-grained asymmetric cryptography.}
A key goal of fine-grained cryptography is to devise an advanced asymmetric cryptography scheme -- such as public key encryption -- whose security is based on hardness of a well understood problem from fine-grained complexity. So far the closest to this goal seems to be the key exchange protocol due to LaVigne, Lincoln, and Vassilevska Williams~\cite{LaVigneLW19}, which is based on hardness of the Zero-$k$-Clique problem. Despite being based on a parameterized problem (that allows for arbitrary polynomial $n^{k-o(1)}$-hardness by simply choosing a large enough $k$), the protocol offers only quadratic security, i.e., breaking the encryption takes only quadratically more than it takes to encrypt and decrypt a message. This limitation seems inherent to the protocol because it is based on a similar idea as Merkle puzzles~\cite{Merkle78}.

It is an open problem if fine-grained cryptography with superquadratic security is possible. We believe that $k$-OV could be a good hard problem for that purpose, because of a different structure, which addition-based problems, like $k$-SUM and Zero-$k$-Clique, are lacking. % It was not considered before because there was no candidate hard distribution. Now it is time to revisit the problem.

In recent work, Alman, Huang, and Yeo~\cite{AlmanHY25} show that if one-way functions do not exist then average-case hardness fine-grained assumptions on planted $k$-SUM and Zero-$k$-Clique are false for sufficiently large constant $k$. Being a planted problem, the same is expected to apply to $k$-OV~\cite{AlmanHY25}. A construction of public-key encryption from planted $k$-OV would be interesting even in a world where one-way functions do exist, as they are not known to imply public-key encryption~\cite{ImpagliazzoR89}.

\paragraph{Faster algorithms for average-case OV.}
Algorithms for random OV instances seem to be underexplored. Up until recently~\cite{AlmanAZ25} it was not known if the average-case OV admits even a subpolynomial improvement compared to the worst case. With this paper we hope to inspire more research in this direction. We would even be happy to see our conjecture refuted.

\section{The model distribution}
Fix $k \geq 2$, and let $d=\alpha(n)\log n$ for $\alpha(n) = \omega(1)$. We define the family of \emph{model distributions} $\Model$ that generate $k$ matrices $U_1,...,U_k \in \{0,1\}^{n\times d}$ where all entries are i.i.d.\ $p$-biased bits with probability
\[
  p = \left( 1 - 2^{-\frac{2k}{\alpha(n)}} \right)^\frac{1}{k} \approx \left(\frac{2k\ln(2)}{\alpha(n)}\right)^{\frac{1}{k}}.
\]
As it becomes apparent later, for the planting algorithm to work it is crucial that $p \leq 1/2$, but thanks to $\alpha(n) = \omega(1)$ this holds for large enough $n$.

We show that the model distribution indeed generates \no-solutions with good probability.

\begin{lemma}
A $k$-OV instance sampled from the model distribution $\Model$ is a \no-instance with probability at least $1-\frac{1}{n^k}$.
\end{lemma}

\begin{proof}
For a $k$-OV instance $\OV = (U_1,\ldots,U_k) \sim \Model$, a fixed combination of vectors $u_1, \ldots, u_k$ (where $u_\ell \in U_\ell$) is orthogonal iff, for each coordinate $j \in [d]$, not all of the $k$ vectors have one in that coordinate. Since $k$ i.i.d.\ $p$-biased bits are all ones with probability $p^k$, the probability that $u_1,\ldots,u_k$ are orthogonal (determined by the all-ones event not occurring in any of the $d$ coordinates) is:
\[
  \Pr[u_1,...,u_k \text{ are orthogonal}] = \left(1 - p^k\right)^d = \left(2^{-\frac{2k}{\alpha(n)}}\right)^{\alpha(n)\log(n)} = n^{-2k}.
\]

By linearity of expectation, the expected value for the number of solutions among all $n^k$ possible combinations of $k$ vectors, denoted by $c(\OV)$, is
\[
  \mathbb{E}[c(\OV)] = \sum_{\substack{u_i \in U_i\\(1 \leq i \leq k)}} \Pr[u_1,\ldots,u_k \text{ are orthogonal}] = n^k \cdot n^{-2k} = \frac{1}{n^k}.
\]
This gives us a bound on the probability of \emph{any} solution occurring:
\[
  \Pr[c(\OV) > 0] = \sum_{i=1}^{n^k} \Pr[c(\OV) = i] \leq \sum_{i=1}^{n^k} i \cdot \Pr[c(\OV) = i] = \mathbb{E}[c(\OV)] = \frac{1}{n^k}.
\]
Hence, an instance sampled from $\Model$ is a \no-instance with probability $1-\frac{1}{n^k}$.
\end{proof}

We remark that one can make the probability of sampling a \no-instance arbitrarily high; in order to get the probability $1-\frac{1}{n^c}$ it suffices to replace $2k$ with $k+c$ in the formula for the probability parameter $p$. However, having in mind the cryptographic motivation, $\frac{1}{n^k}$ seems a reasonable default choice for the failure probability of the sampler, because with the same probability the attacker can just guess the solution.

\section{The planted distribution}
\label{section:planted_dist}

To plant a solution at locations $s_1,\ldots,s_k \in [n]$ in an instance $\OV$ sampled from $\Model$, we apply the following randomized algorithm.

\medskip
\noindent$\Plant(\OV,s_1,\ldots, s_k)$:
\begin{enumerate}
  \item For each coordinate $1 \leq j \leq d$:
    \begin{enumerate}
    \item Let $m$ be the number of ones among $U_{1,s_1}[j],\ldots,U_{k,s_k}[j]$.
    \item If $m - k$ is even, flip $U_{k,s_k}[j]$ with probability $\left( \frac{p}{1-p} \right)^{k-m}$. (Here we need $p \leq 1/2$.)
      \end{enumerate}
  \item Return $\OV$.
\end{enumerate}
We justify this way of planting in Section~\ref{section:k-1-wise-independence}.
For now, observe that if all vectors $U_{1,s_1},\ldots,U_{k,s_k}$ feature a one at coordinate $j$, we have $m = k$ and $\Plant$ flips the final bit $U_{k,s_k}[j]$ to a zero with probability
\[
\left( \frac{p}{1-p} \right)^{k-m} = \left( \frac{p}{1-p} \right)^0 = 1.
\]
Thus, $\Plant(\OV, s_1,\ldots,s_k)$ outputs a \yes-instance of $k$-OV with a solution at $s_1,\ldots,s_k$.

We sample \yes-instances of $k$-OV by planting a solution in an instance $\OV \sim \Model$ at locations $s_1,\ldots,s_k$ chosen uniformly at random.

\medskip
\noindent\textbf{Distribution} $\Planted$:
\begin{enumerate}
  \item Sample $\OV$ from $\Model$.
  \item Sample $(s_1,\ldots,s_k)$ uniformly at random from $[n]^k$.
  \item Return $\Plant(\OV, s_1,\ldots,s_k)$.
\end{enumerate}

The above observation about $\Plant$ immediately yields the following.
\begin{lemma}
A $k$-OV instance sampled from the planted distribution $\Planted$ is a \yes-instance with probability $1$.
\end{lemma}


\section{$(k-1)$-wise independence of planted vectors}\label{section:k-1-wise-independence}
Our method of planting orthogonal vectors arises from the idea that for any planted problem, any proper ``piece'' of the planted solution should be indistinguishable from any comparable piece of the instance as a whole, conditioned on the latter still being consistent with being a part of a solution itself.

For example, in the case of planting a $k$-clique in a graph \(G\) this requirement is trivial. Indeed, the projection of the clique onto a smaller subset of $k' < k$ vertices yields a $k'$-clique, which are exactly those subgraphs of $G$ of size $k'$ which could feasibly belong to a solution.

In contrast to the previous example, in the case of $k$-SUM, any set of $k - 1$ elements $x_1, \dots, x_{k-1}$ in an instance could feasibly be part of a solution, as one can always construct a $k-$th number $x_k$ such that $\sum_{i=1}^k x_i = 0$.
Thus, by the principle we described, to plant a solution in an instance with i.i.d.\ uniformly random elements, the marginal distribution of the distribution of planted solutions $(x_1,\dots,x_k)$ given by any projection to $k-1$ elements should itself be uniformly random.
This holds true in the case of the planted $k$-SUM~\cite{AgrawalSSVV24}, where the planted solution is distributed uniformly over the set of all $k$-tuples that form valid $k$-SUM solutions.
The case of planted Zero-$k$-Clique~\cite{LaVigneLW19} is analogous.
For both of these problems, $k$ elements from the model distribution conditioned on them feasibly forming a solution yields a distribution that is suitable for planting according to the described principle. % TODO: Phrase this better.

This is different from the $k$-OV problem with a model distribution of i.i.d.\ vector entries.
Here, as with $k$-SUM and Zero-$k$-Clique, any set of $k - 1$ elements (in this case vectors) could form a solution to $k$-OV.
All that is needed is for the last vector to feature a $0$ in all those coordinates where the other $k-1$ all were $1$.
However, sparse vectors are far more likely to be part of a solutions than dense ones.
Therefore, conditioning $k$ i.i.d.\ $p$-biased vectors on being orthogonal yields a distribution which does not follow our principle;
Projecting onto any subset of $k' < k$ vectors results in vectors that are on average sparser than (and thus different from) $k'$ i.i.d.\ $p$-biased vectors.
As we will show now, our method of planting \emph{does} satisfy this principle: Any subset of $k-1$ planted vectors are independent and identically distributed $p$-biased vectors.

Let $M \sim \Model$ and $\OV = \Plant(M, s_1,\ldots,s_k)$.
Recall that both sampling from the model distribution $\Model$ and the planting by $\Plant$ are independent and identical for each coordinate $j \in [d]$. Hence, all $k$-bit sequences $x = (U_{1,s_1}[j], U_{2,s_2}[j], \ldots,  U_{k,s_k}[j]) \in \{0,1\}^k$, for all $j \in [d]$, are independent and identically distributed, according to a distribution whose probability density function we denote by $\Pk : \{0,1\}^k \rightarrow \mathbb{R}$.
\begin{lemma}\label{lem:marginal}
Let $x \in \{0,1\}^k$ contain $m$ ones, i.e., $||x||_1 = m$. Then
\[
\Pk(x) = p^m(1-p)^{k-m} - (-1)^{k-m}p^k.
\]
\end{lemma}
\begin{proof}
Fix a coordinate $j \in [d]$. Let $X = (M_{1,s_1}[j], M_{2,s_2}[j], \ldots, M_{k,s_k}[j])$ be the random variable denoting the entries of the $j$-th coordinate among the vectors at locations $s_1, \dots, s_k$ before planting.
We proceed by case distinction.

\proofsubparagraph{Case 1.} If $m - k$ is even, the probability of $x$ occurring in the given coordinate $j \in [d]$ of the planted solution is given by
\begin{align*}
\Pk(x)
={}& \Pr\left[ X = x \text{ and } \Plant \text{ does not flip the final bit} \right]\\
={}& p^m(1-p)^{k-m} \cdot \left( 1 - \left( \frac{p}{1-p} \right)^{k-m} \right)\\
={}& p^m(1-p)^{k-m} - 1 \cdot p^k\\
={}& p^m(1-p)^{k-m} - (-1)^{k-m} p^k.
\end{align*}

\proofsubparagraph{Case 2a.} If $m - k$ is odd and $x = y1$ for some $y \in \{0,1\}^{k-1}$, then $x = y1$ may occur either directly in the model instance, or by $y0$ (for which $m - k$ is even) occurring in the model instance and $\Plant$ flipping the final bit:
\begin{align*}
\Pk(x)
={}& \Pr\left[ X = y1 \right] + \Pr\left[ X = y0 \text{ and } \Plant \text{ flips the final bit} \right]\\
={}& p^m(1-p)^{k-m} + p^{m-1}(1-p)^{k-(m-1)} \cdot \left( \frac{p}{1-p} \right)^{k-(m-1)}\\
={}& p^m(1-p)^{k-m} + p^k\\
={}& p^m(1-p)^{k-m} - (-1)^{k-m}p^k.
\end{align*}

\proofsubparagraph{Case 2b.} Similarly, if $m - k$ is odd and $x = y0$ for some $y \in \{0,1\}^{k-1}$, then $x = y0$ can occur either directly in the model instance or by $\Plant$ flipping the final bit of the sequence $y1$:
\begin{align*}
\Pk(x)
={}& \Pr\left[ X = y0 \right] + \Pr\left[ X = y1 \text{ and } \Plant \text{ flips the final bit} \right]\\
={}& p^m(1-p)^{k-m} + p^{m+1}(1-p)^{k-(m+1)} \cdot \left( \frac{p}{1-p} \right)^{k-(m+1)}\\
={}& p^m(1-p)^{k-m} + p^k\\
={}& p^m(1-p)^{k-m} - (-1)^{m-k} p^k.
\end{align*}
\end{proof}

\begin{remark}\label{rem:symmetry}
It follows immediately from Lemma~\ref{lem:marginal} that the method of planting is invariant under permutations of the $k$ collections $U_1,\ldots,U_k$.
\end{remark}

Having $\Pk$ as the distribution of planted vectors, rather than, e.g., the $k$-vector joint model distribution conditioned on orthogonality, ensures \emph{$(k - 1)$-wise independence} among the planted vectors.
I.e., the projection of $k$ planted vectors onto any subset of size $k' < k$ is identically distributed to $k'$ vectors from the model distribution.

\begin{lemma}[$(k-1)$-wise independence]\label{lemma:k-1-independence}
Marginalizing any one of the $k$ bits of $\Pk$ yields $k-1$ independent $p$-biased bits.
\end{lemma}
% \begin{proof}
% Let $\PkMargin$ denote the marginal distribution.
% We may assume w.l.o.g.\ that the last bit is marginalized.
% Let $x \in \{0,1\}^{k-1}$ contain $m$ ones, that is $||x||_1 = m$.
% Then
% \begin{align*}
% \PkMargin(x) &= \Pk(x0) + \Pk(x1)\\
% &= p^m(1-p)^{k-m} - (-1)^{k-m} p^k + p^{m+1}(1-p)^{k-(m+1)} - (-1)^{k-{m+1}} p^k\\
% &= (1-p) \cdot p^m(1-p)^{(k-1)-m} + p \cdot p^{m}(1-p)^{(k-1)-m}\\
% &= p^m(1-p)^{(k-1)-m}.
