% % Easier proof:
\begin{proof}
By Remark~\ref{rem:symmetry} we may assume w.l.o.g.\ that the last bit is the one marginalized out.
The lemma then follows from the definition of $\Plant$, as the first $k-1$ entries of any coordinate in the planted vectors are unchanged from the model instance, and are therefore independent $p$-biased bits.
\end{proof}

This property is useful in bounding the probability of a planted instance containing a solution besides the planted one.
\begin{lemma}
A $k$-OV instance sampled from the planted distribution $\Planted$ has more than one solution with probability less than $\frac{1}{n^k}$.
\end{lemma}
\begin{proof}
While the $k$ planted vectors are guaranteed to form a solution, by $(k-1)$-wise independence, \emph{all} combinations of $0 \leq k' < k$ planted vectors and $k - k'$ non-planted vectors form a set of $k$ independent $p$-biased vectors which is therefore a solution to the $k$-OV problem with probability $(1-p)^d = \frac{1}{n^{2k}}$.
By linearity of expectation,
\[
  \E[c(\OV)] = 1 + (1 - p^k)^d \cdot (n^k - 1) < 1 + \frac{1}{n^k}.
\]
Which then gives the desired result.
\[
\Pr[c(U) > 1] = \sum_{i = 2}^{n^k} \Pr[c(U) = i] \leq \sum_{i = 1}^{n^k} (i-1) \cdot \Pr[c(U) = i] = \E[c(\OV) - 1] < \frac{1}{n^k}.
\]
\end{proof}

\paragraph{Uniqueness.}
Our way of planting is unique in the following sense.
\begin{theorem}
Let $Q : \{0,1\}^k \to \mathbb{R}$ be a probability distribution such that $Q(1^k) = 0$ and that marginalizing any one of the $k$ bits yields $k-1$ independent $p$-biased bits.
Then $Q = \Pk$.
\end{theorem}
\begin{proof}
We show that $Q(x) = \Pk(x)$ for all $x \in \{0,1\}^k$.
Let $m$ denote the number of ones in $x$, that is $||x||_1 = m$.
We proceed by induction over $k - m$, i.e.\ the number of \emph{zeros} in $x$.
\proofsubparagraph{Base case: $k - m = 0$.}
Then $m = k$ and $x = 1^k$.
Thus $Q(x) = Q(1^k) = 0 = \Pk(x)$.

\proofsubparagraph{Inductive case: $k - m > 0$.}
We assume w.l.o.g.\ that the $k - m$ zeros are the \emph{last} bits of $x$, i.e., $x = 1^m0^{k-m}$.
Marginalizing the final $k-m > 0$ bits of $Q$ yields $k - (k - m) = m$ independent $p$-biased bits, whereby the probability of all $m$ remaining bits being ones is
\[
p^m = \sum_{y \in \{0,1\}^{k-m}} Q(1^m y) = Q(\underbrace{1^m0^{m-k}}_{= x}) + \sum_{\substack{y \in \{0,1\}^{k-m}\\y \not= 0^{k-m}}} Q(1^m y).
\]
Thereby, 
\begin{align*}
Q(x) &= p^m - \sum_{\substack{y \in \{0,1\}^{k-m}\\y \not= 0^{k-m}}} Q(1^m y)\\
&= p^m - \sum_{\substack{y \in \{0,1\}^{k-m}\\y \not= 0^{k-m}}} \Pk(1^m y) \tag*{(By the induction hypothesis)}\\
&= p^m + \Pk(x) - \sum_{y \in \{0,1\}^{k-m}} \Pk(1^m y)\\
\intertext{where the sum term is merely the probability of $1^m$ in the marginal distribution of $\Pk$, which by Lemma~\ref{lemma:k-1-independence} in turn consists of $m$ independent $p$-biased bits. Hence}
&= p^m + \Pk(x) - p^m = \Pk(x).
\end{align*}
\end{proof}

\section{Conjectured hard problems}

In this section we formally define the problems that we conjecture to require $n^{k-o(1)}$ time.

\begin{definition}[Solving planted \textbf{decision} $k$-OV]
  Let $\mathcal{A}$ be an algorithm that given a $k$-OV instance $\OV$ outputs either 0 or 1.
  For $\alpha(n) = \Omega(1)$, we say $\mathcal{A}$ \emph{solves} the \emph{decision} $k\text{-OV}^\alpha$ problem with success probability $\delta(n)$, if for both $b \in \{0,1\}$ and large enough $n$,
  \[
    \Pr_{\OV \sim k\text{-OV}_b^\alpha(n)} [\mathcal{A}(\OV) = b] \geq \delta(n),
  \]
  where randomness is taken over both the instance $\OV$ and the random coins used by $\mathcal{A}$.
\end{definition}

Similarly, we define a notion of recovering a solution from a planted instance.
\begin{definition}[Solving planted \textbf{search} $k$-OV]
  Let $\mathcal{A}$ be an algorithm that given a $k$-OV instance $\OV$ outputs a tuple $(s_1, ..., s_k) \in \{1,...,n\}^k$.
  For a given $\alpha(n) = \Omega(1)$, we say $\mathcal{A}$ \emph{solves} the \emph{planted search $k\text{-OV}^\alpha$ problem} with success probability $\delta(n)$ if for large enough $n$,
  \[
    \Pr_{\substack{\OV \sim \Planted\\(s_1,\ldots,s_k) \gets \mathcal{A}(\OV) }} [U_{1,s_1},...,U_{k,s_k} \text{ are orthogonal}] \geq \delta(n),
  \]
  where randomness is taken over both the instance $\OV$ and the random coins used by $\mathcal{A}$.
\end{definition}

Now we are ready to formally state our main conjecture.

\begin{conjecture}
  For any $\alpha(n) = \omega(1)$ and $\varepsilon > 0$, there exists no algorithm $\mathcal{A}$ that solves the planted decision $k$-OV problem with any constant success probability $\delta > \frac{1}{2}$ in time $O(n^{k-\varepsilon})$.
\end{conjecture}


\section{Search-to-decision reduction via binary search}\label{section:search2decision}
\newcommand{\Ad}{\mathcal{A}^\mathrm{decide}}
\newcommand{\As}{\mathcal{A}^{\mathrm{search}}}
We reduce the search problem of finding the planted solution to the decision problem of determining whether an instance contains a planted solution.
This means that given a decision algorithm that can correctly distinguish whether an instance was sampled from the model or planted distribution with sufficient probability, one can recover the planted secret through this reduction.
The reduction introduces a factor $O(\log n)$ increase in both the running time and error probability of the algorithm.

The idea is to find each planted vector using something akin to binary search on each collection $A_i$.
We can split $A_i$ into two partitions of roughly equal size and run the decision algorithm twice, on instances where one of the two partitions is first replaced by newly sampled $p$-biased vectors.
The vector planted in $A_i$ is guaranteed to be replaced in one of these cases, and by $(k-1)$-wise independence the resulting instance follows the model distribution.
The search space is thus cut in half and we can recurse on this smaller search space to eventually find the planted vector.

\begin{theorem}[Search to decision reduction]\label{theorem:search-to-decision}
  Let $\alpha(n) = \polylog(n)$ and let $\Ad$ be an algorithm that solves the planted decision $k$-OV problem with success probability $1 - \delta(n)$ in time $T(n)$.
  Then there exists an algorithm $\As$ that solves the planted search $k$-OV problem with success probability
  $1 - k\lceil\log n\rceil \cdot \delta(n)$ in expected time $\Olog(T(n) + n)$.
\end{theorem}
\begin{proof}
  Consider an instance $\inst = (U_1, \dots, U_k) \sim \Planted$.
  First let us focus only on recovering the location $i \in [n]$ of the planted vector in the first collection $U_1$.
  The reduction begins with the ``full'' search space $S := [n]$, and narrows it down by half in each iteration, so that the desired $i$ is recovered after $\lceil \log n \rceil$ iterations.

  At each iteration, the current search space $S$ is arbitrarily partitioned in two sets of equal size (up to one vector, id .
  The decision algorithm $\Ad$ is then executed on two new instances, where the respective sets of vectors in $U_1$ are replaced with newly sampled $p$-biased vectors.

  By the $(k-1)$-wise independence, if the vector belonging to the solution is replaced, all vectors are independently and identically distributed $p$-biased vectors, i.e., the instance is distributed according to $\Model$.
  On the other hand, if the solution survives resampling, the instance remains distributed according to $\Planted$.
  Therefore, the output of $\Ad$ is used to decide which of the two  partition blocks should be assumed as the new search space.

  The reduction is correct if $\Ad$ decides correctly at every iteration.
  Of course, $\Ad$ might fail with probability $\delta(n)$. By a union bound over all $\lceil \log n \rceil$ invocations of $\Ad$ this happens with probability at most $\lceil \log n \rceil \cdot \delta(n)$.
  Thereby $\As$ recovers the location $i$ of the first planted vector with success probability at least $1 - \lceil \log n \rceil \cdot \delta(n)$.

  As for the runtime, $\Ad$ with runtime $T(n)$ is invoked $O(\log n)$ times, and across all iterations $n-1$ vectors are resampled in total.
Since a single $p$-biased bit can be sampled in expected time $O(- \log p) = O(\log \alpha(n)) = O(\log \log n)$, sampling a $d$-dimensional vector takes $\polylog(n)$ time in expectation.
  Therefore, recovering the location of the first planted vector takes time $\Olog(T(n) + n)$.

  The same process is repeated another $k - 1$ times to recover the locations of the planted vectors among $U_2,...,U_k$.
  As $k$ is constant there is no asymptotic overhead in the running time while the success probability drops to $1 - k\lceil\log n\rceil \cdot \delta(n)$.
\end{proof}

\section{Search-to-decision reduction via counters}
\label{section:search2decision2}
\newcommand{\Mix}{\mathsf{Mix}}
We present a second search-to-decision reduction, adapted from that of Agrawal et al.~\cite{AgrawalSSVV24} for planted $k$-SUM.
As in the method in Section~\ref{section:search2decision}, we use the fact that an algorithm $\Ad$ for the decision $k$-OV problem, when given a planted $k$-OV instance with some of the vectors resampled, correctly detects whether any of the planted vectors were among the resampled vectors.
However, instead of iteratively narrowing a pool of candidate vectors, we iterate this process on the entire instance and for each vector $u$ keep a count of the number of iterations in which $u$ survived and $\Ad$'s output was 1.
After $O(\log(n))$ iterations we output the vectors with the highest counts among all $k$ collections, which we show coincides with the planted solution (with good probability).

\begin{theorem}[Search to decision reduction]\label{theorem:k-sum-style-s2d}
  For any $\alpha(n) = \polylog(n)$ and $\delta > 0$, there exists an $\epsilon > 0$ such that an algorithm solves the planted decision $k$-OV problem with success probability at least $1 - \epsilon$ in time $T(n)$
  yields an algorithm that solves the planted search $k$-OV problem with success probability at least $1 - \delta$ in expected time $\Olog(T(n) + n)$.
\end{theorem}



In more detail, let $\Mix$ be the following randomized algorithm, which takes a $k$-OV instance $\inst$, and resamples some of the vectors:

\medskip
\noindent\textbf{Algorithm} $\Mix(\inst)$:
\begin{enumerate}
  \item For each $\ell \in [k]$ and $i \in [n]$:
    \begin{enumerate}
    \item With probability $1 - 2^{-\frac{1}{k}}$, replace $U_{\ell,i}$ by a newly-sampled $p$-biased vector
      \end{enumerate}
  \item Output $\inst$
\end{enumerate}

For $\ell \in [k]$, let $S_\ell \subseteq [n]$ indicate the indices of the vectors of $U_\ell$ which are replaced by $\Mix$.
For a vector $u$ in $\inst$ and a given execution of $\Mix$, we say $u$ \emph{survives} if $\Mix$ does not replace $u$.
We say $\mathbf{s} = (s_1, \dots, s_k)$ \emph{survives} if $U_{\ell, s_\ell}$ survives for each $\ell \in [k]$.

Now let $B(\mathbf{s})$ be the binary random variable indicating whether $\mathbf{s}$ survives.
Our chosen probability for $\Mix$ to resample a vector yields the following.
\begin{lemma}
For a $k$-OV instance $\inst$ and any $\mathbf{s} \in [n]^k$, $\mathbf{s}$ survives with probability one half, i.e.,
  $\Pr_{\Mix}[B(\mathbf{s}) = 1] = \frac{1}{2}$.
\end{lemma}
\begin{proof}
Each vector is independently picked to be replaced with probability $1 - 2^{-\frac{1}{k}}$.
The chance of all $k$ vectors surviving is
\begin{align*}
  \Pr_{\Mix}[B(\mathbf{s}) = 1] = \left(1 - \left( 1 - 2^{-\frac{1}{k}} \right) \right)^k = 2^{-\frac{1}{k} \cdot k} = \frac{1}{2}.
\end{align*}
\end{proof}

As laid out before, our search algorithm repeatedly executes $\Mix$ and then the given decision algorithm $\Ad$. The hopes is that the output of the latter correlates with the survival of the planted solution.
We therefore also keep track of which vectors survive whenever $\Ad$ believes there is still a planted solution in the instance output by $\Mix$.

\medskip
\noindent\textbf{Algorithm} $\As(\inst)$:
\begin{enumerate}
  \item Initialize a counter $C_{\ell,i} := 0$ for each $\ell \in [k]$ and $i \in [n]$.
  \item Repeat $m = \Theta(\log n)$ times:
    \begin{enumerate}
    \item $\inst[V] \gets \Mix(\inst)$
    \item $b := \Ad(\inst[V])$
    \item If $b = 1$:
    \begin{enumerate}
    \item Set $C_{\ell,i} := C_{\ell,i} + 1$ for every $U_{\ell,i}$ that was not replaced by $\Mix$
    \end{enumerate}
      \end{enumerate}
  \item Set $s_\ell := \argmax_{i \in [n]} C_{\ell,i}$ for each $\ell \in [k]$
  \item Output $\mathbf{s} = (s_1, \dots, s_k)$
\end{enumerate}

This works well for instances $\inst$ where $\Ad$ is good at detecting whether a particular solution survives.
To capture this notion, we say an instance $\inst$ is \emph{good}, if it has only one solution, at some location $\mathbf{s}$, \emph{and} the output of $\Ad$ indicates whether $\mathbf{s}$ survives except for a small constant probability;
Concretely,
\[
\Pr_{\Mix}[\Ad(\Mix(\inst)) \not= B(\mathbf{s})] < \frac{1}{2^3}\left(1 - 2^{-\frac{1}{k}} \right).
\]

In the following, let $\mathsf{Sample}$ be a randomized algorithm that outputs a planted instance sampled from $\Planted$ as well as the location $\mathbf{s}$ of the planted solution.

\begin{lemma}\label{lemma:most-Us-good}
For any $\delta > 0$, there exists an $\epsilon > 0$ such that given an algorithm that solves the planted decision $k$-OV problem with success probability at least $1 - \epsilon$, an instance $\inst \sim \Planted$ is \emph{good} except with probability at most $\frac{\delta}{2}$.
\end{lemma}
\begin{proof}
We show first that for an apt choice of $\epsilon$, the decision algorithm $\Ad$ correctly detects if the solution planted by $\mathsf{Sample}$ (which produces instances distributed according to $\Planted$) survives except with probability at most $\frac{\delta}{4}$.
Then, since for large enough $n$, instances $\inst \sim \Planted$ will only contain a single solution except with probability $\frac{\delta}{4}$, by a union bound we get a good instance except with probability at most $\frac{\delta}{2}$.

For the first step, consider the following distribution:

\medskip
\noindent\textbf{Distribution} $\Dist{B}$:
\begin{enumerate}
  \item $\inst[U], \mathbf{s} \gets \mathsf{Sample}$
  \item $\inst[V] \gets \Mix(\inst[U])$
  \item Output $(\inst[V], B = B(\mathbf{s})).$
\end{enumerate}

Observe that, if we condition on $B = 1$, the planted solution survives $\Mix$, which merely resamples some of the i.i.d.\ $p$-biased vectors in the instance.
Thus, $\inst[V]$ is distributed according to $\Planted$.
On the other hand, if $B = 0$, at least one of the planted vectors is replaced by a newly-sampled $p$-biased vector.
By $(k-1)$-wise independence, the subset of planted vectors that survive are i.i.d.\ $p$-biased vectors, as are all other vectors in $\inst[V]$.
Hence, conditioning on $B = 0$ yields the model distribution $\Model$.

Therefore, for an algorithm $\Ad$ that solves the planted decision $k$-OV problem with success probability at least $1 - \epsilon$, we have
\begin{equation*}
  \Pr_{\Dist{B}}[\Ad(\inst[V]) \not= B] \leq \epsilon.
\end{equation*}
Now, let $Z(\OV, \mathbf{s})$ be the random variable that, for a given instance $\inst$ with a solution planted at $\mathbf{s}$, denotes the probability of $\Ad(\Mix(U)) \not= B(\mathbf{s})$, where the randomness is taken over the internal coins used by $\Mix$.
Then
\begin{align*}
  \epsilon &\geq \Pr_{\Dist{B}}[\Ad(\inst[V]) \not= B(\mathbf{s})]\\
  &= \E_{\substack{(\inst, \mathbf{s}) \gets \mathsf{Sample}}} \left[ \Pr_{\Mix}[\Ad(\Mix(\inst)) \not= B(\mathbf{s})] \right]\\
  &= \E_{(\inst, \mathbf{s}) \gets \mathsf{Sample}} \left[ Z(\inst, \mathbf{s}) \right].
\end{align*}
Choosing $\epsilon < \frac{\delta}{2^5}(1 - 2^{-\frac{1}{k}})$, Markov's inequality yields the following bound:
\begin{align*}
  \Pr_{(\inst, \mathbf{s}) \gets \mathsf{Sample}} \left[ Z(\inst, \mathbf{s}) \geq \frac{1}{2^3}\left(1 - 2^{-\frac{1}{k}} \right) \right]
  \leq \Pr_{(\inst, \mathbf{s}) \gets \mathsf{Sample}} \left[ Z(\inst, \mathbf{s}) \geq \frac{4}{\delta} \E[Z(\inst, \mathbf{s})] \right] < \frac{\delta}{4}.
\end{align*}

Next, observe that $\mathbf{s}$ is the only solution in the instance $\inst$ output by $\mathsf{Sample}$ with high probability,
\[
  \Pr_{(\inst, \mathbf{s}) \gets \mathsf{Sample}} \left[ \inst  \text{ has a solution besides } \mathbf{s} \right]
  = \Pr_{\inst \gets \Planted} \left[ c(\inst) > 1 \right] < \frac{1}{n^k}.
\]
In particular, for large enough $n$, there is more than one solution with probability less than $\frac{\delta}{4}$.
Thus, by a union bound over this and our result in the first step, we find that an instance $\inst \sim \Planted$ is good except with probability at most $\frac{\delta}{2}$:
\begin{align*}
  & \Pr_{\inst \gets \Planted} \left[ \inst \text{ is good} \right]\\
  ={}& \Pr_{\inst \gets \Planted} \left[ \inst \text{ has a single solution } \mathbf{s} \text{ and } Z(\inst, \mathbf{s}) < \frac{1}{2^3}\left(1 - 2^{-\frac{1}{k}} \right) \right]\\
  ={}& \Pr_{\inst, \mathbf{s} \gets \mathsf{Sample}} \left[ \mathbf{s} \text{ is the only solution of } \inst \text{ and } Z(\inst, \mathbf{s}) < \frac{1}{2^3}\left(1 - 2^{-\frac{1}{k}} \right) \right]\\
  \geq{}& 1 - \Pr_{\inst, \mathbf{s} \gets \mathsf{Sample}} \left[\inst[U] \text{ has a solution besides } \mathbf{s} \right]
             - \Pr_{\inst, \mathbf{s} \gets \mathsf{Sample}} \left[ Z(\inst, \mathbf{s}) \geq \frac{1}{2^3}\left(1 - 2^{-\frac{1}{k}} \right) \right]\\
  >{}& 1 - \frac{\delta}{4} - \frac{\delta}{4} = 1 - \frac{\delta}{2}.
\end{align*}
\end{proof}

We now show that the search algorithm performs well on this large fraction of good instances.
\begin{lemma}\label{lemma:asearch-works-on-good-Us}
Let $\delta > 0$ and let $\Ad$ be an algorithm that solves the planted decision $k$-OV problem.
Then $\As$ fails to recover the solution $\mathbf{s}$ of good instances with probability less than $\frac{\delta}{2}$.
\end{lemma}
\begin{proof}
Let $\inst$ be a good instance with its only solution at $\mathbf{s}$.
After $t$ iterations, we expect the counters for vectors in the solution $\mathbf{s}$ to be the highest:
\begin{align*}
  \E[C_{\ell,i} \mid s_\ell \not= i]
  &= t \cdot \Pr_{\Mix} \left[ U_{\ell,i} \text{ survives and } \Ad(\Mix(\inst)) = 1 \right]
  \\ &\leq t \cdot \left( \Pr_{\Mix} \left[ U_{\ell,i} \text{ survives and } B(\mathbf{s}) = 1\right] + \Pr_{\Mix} \left[ \Ad(\Mix(\inst)) \not= B(\mathbf{s}) \right] \right)
  \\ &< t \cdot \left( \frac{1}{\sqrt[k]{2}} \cdot \frac{1}{2} + \frac{1}{2^3}\left(1 - \frac{1}{\sqrt[k]{2}} \right) \right),
       \\[10pt] 
  \E[C_{\ell,i} \mid s_\ell = i]
  &\geq t \cdot \Pr_{\Mix} \left[ \mathbf{s} \text{ survives and } \Ad(\Mix(\inst)) = 1 \right]
  \\ &\geq t \cdot \Pr_{\Mix} \left[ B(\mathbf{s}) = 1 \text{ and } \Ad(\Mix(\inst)) = B(\mathbf{s}) \right]
  \\ &\geq t \cdot \left(1 - \Pr_{\Mix} \left[ B(\mathbf{s}) = 0\right] - \Pr_{\Mix} \left[ \Ad(\Mix(\inst)) \not= B(\mathbf{s}) \right] \right)
  \\ &> t \cdot \left(1 - \frac{1}{2} - \frac{1}{2^3}\left(1 - \frac{1}{\sqrt[k]{2}} \right) \right)
  = t \cdot \left(\frac{1}{2} - \frac{1}{2^3}\left(1 - \frac{1}{\sqrt[k]{2}} \right) \right).
\end{align*}
Picking the $k$ highest counters is guaranteed to yield the solution $\mathbf{s}$ if all counters $C_{\ell,i}$ deviate by less than half the difference of the two expected values, namely
\begin{align*}
  \Delta :={}& \frac{1}{2}\left(\E[C_{\ell,i} \mid s_\ell = i] - \E[C_{\ell,i} \mid s_\ell \not= i]\right)
  \\ \geq{}& 
  \frac{1}{2} t \left(\left(\frac{1}{2} - \frac{1}{2^3}\left(1 - \frac{1}{\sqrt[k]{2}} \right) \right)
         - \left( \frac{1}{\sqrt[k]{2}} \cdot \frac{1}{2} + \frac{1}{2^3}\left(1 - \frac{1}{\sqrt[k]{2}} \right) \right) \right).
  \\ ={}& 
  \frac{1}{2} t \left(\frac{1}{2} \left(1 - \frac{1}{\sqrt[k]{2}} \right) - \frac{1}{2^2}\left(1 - \frac{1}{\sqrt[k]{2}} \right) \right)
  \\ ={}& 
  t \cdot \frac{1}{8} \left(1 - \frac{1}{\sqrt[k]{2}} \right)
\end{align*}

Each counter $C_{\ell,i}$ is the sum of $t$ i.i.d.\ binary random variables.
By a Chernoff bound, a counter $C_{\ell,i}$ for a vector which is not in the planted solution, i.e.\ $s_\ell \not= i$ will exceed its expected value by $\Delta$ with probability at most
\begin{align*}
  \Pr \left[ C_{\ell,i} \geq \E[C_{\ell,i}] + \Delta \mid s_\ell \not= i \right]
  < \mathrm{exp}\left( - \frac{2}{t} \left[ \frac{1}{8} \left(1 - \frac{1}{\sqrt[k]{2}} \right) \right]^2 \right).
\end{align*}
Similarly, a counter $C_{\ell,i}$ for a vector that \emph{is} part of a planted solution will fall short of its expected value by $\Delta$ with probability at most
\[
  \Pr \left[ C_{\ell,i} \leq \E[C_{\ell,i}] - \Delta \mid s_\ell = i \right]
  < \mathrm{exp}\left( - \frac{2}{t} \left[ \frac{1}{8} \left(1 - \frac{1}{\sqrt[k]{2}} \right) \right]^2 \right).
\]
For a choice of $t = \frac{1}{2} \cdot \left[ \frac{1}{8} \left(1 - \frac{1}{\sqrt[k]{2}} \right) \right]^{-2} \log \frac{2kn}{\delta} = O(\log n)$ iterations, both of these probabilities are at most $\frac{\delta}{2kn}$.
If \emph{none} of the $k \cdot n$ counters deviate by $\Delta$, the ranges of counters for vectors at $\mathbf{s}$ and those for vectors not at $\mathbf{s}$ will be disjoint and selecting for the highest counters is guaranteed to yield $\mathbf{s}$.
Thus, by a union bound over all $k \cdot n$ counters, we fail to recover $\mathbf{s}$ with probability at most $kn \cdot \frac{\delta}{2kn} = \frac{\delta}{2}$.
\end{proof}

A runtime analysis of $\As$ now completes the proof of our theorem.
\begin{proof}[Proof of Theorem \ref{theorem:k-sum-style-s2d}]
By Lemma~\ref{lemma:most-Us-good}, there exists an $\epsilon > 0$ such that for a given algorithm $\Ad$ that solves the planted decision $k$-OV problem with success probability at least $1 - \epsilon$, an instance $\inst \sim \Planted$ is good except with probability at most $\frac{\delta}{2}$.
By Lemma~\ref{lemma:asearch-works-on-good-Us}, $\As$ is able to recover the solution $\mathbf{s}$ from a good instance except with probability at most $\frac{\delta}{2}$.
By a union bound against the instance not being good or $\As$ failing on the good instance, $\As$ solved the planted search $k$-OV problem with success probability at least $1 - \delta$.

As laid out in the proof of Theorem~\ref{theorem:search-to-decision},
a single $d$-dimensional $p$-biased vector can be sampled $\polylog(n)$ expected time.
On average, a single execution of $\Mix$ samples $k \cdot n \cdot (1 - 2^{-\frac{1}{k}}) = O(n)$ new vectors, which therefore can be done in $\Olog(n)$ time.

As for $\As$, both the initialization and the final evaluation of the counters takes linear time;
The $t = O(\log n)$ iterations each involve one execution of $\Mix$ and $\Ad$, which take $\Olog(n)$ and $T(n)$ time respectively for an overall runtime of $\Olog(T(n) + n)$.
\end{proof}

