\subsection{Energy Prediction and Latent Space Exploration}
\begin{figure}[!htb]
    \centering
\includegraphics[width=1.0\linewidth]{Energy.png}
    \caption{Energy Predictions and Latent Space Visualization. (a-b) Predicted vs actually potential energy; (c) visualization of graph latent spaces via UMAP projection}
    \label{fig:energy}
