    \centering
    \includegraphics[width=1.0\linewidth]{model_mse.png}
    \caption{Model performance vs Latent Dimension (a) Potential energy prediction RMSE vs Latent Dimension (b) Edge attribution (pairwise distances) RMSE vs Latent Dimension}
