\subsection{Theorem 2 Full Demonstration}
\label{the2_full}
We define a Sobolev space $\mathcal{U} = W^{s, q}(\mathbb{R}^3, \mathbb{R})$ and Bochner space $\mathcal{V} = L^p(\mathbb{R}^3, \mathbb{R})$ with $1\leq p, q \le \infty$, $s\geq 0$, and norms $||\cdot||_{\mathcal{U}}$ and $||\cdot||_{\mathcal{V}}$, respectively. The physical information of the system is encoded by the abstract form
\begin{equation}
    \mathcal{A}\boldsymbol{u} = v
\end{equation}
, where $\mathcal{A}: \mathcal{U} \rightarrow \mathcal{V}$ is an arbitrary operator satisfying $||v||_{\mathcal{V}} < \infty$, and $||\mathcal{A} \boldsymbol{u}||_{\mathcal{V}} < \infty, \forall \,  ||\boldsymbol{u}||_{\mathcal{U}} < \infty$. As a concrete example of our setting, $\boldsymbol{u}(\cdot; \theta)$ is a neural network parametrized by $\theta$. $\mathcal{A}$ can be the operator that calculates fitted RDF by our neural networks, and $v$ encodes our priori in RDF from the physical law.

\begin{assump}\label{assumption: operator_regularity}
(Regularities of $\mathcal{A}$) For any $\boldsymbol{u}, \boldsymbol{u}'\in \mathcal{U}$, 
\begin{equation}\label{eq: operator_regularity}
    ||\boldsymbol{u} - \boldsymbol{u}'||_{\mathcal{U}} \leq C^{(1)} ||\mathcal{A}\boldsymbol{u} - \mathcal{A}\boldsymbol{u}'||_{\mathcal{V}}
\end{equation}
\end{assump}

\begin{assump}\label{assumption: quadrature_error}
(Quadrature error) For an arbitrary function $g \in \mathcal{V}$, we define its integral $\Bar{g} := \int g(\boldsymbol{u})d\boldsymbol{u}$, and the corresponding quadrature approximation
\begin{equation}
    \Bar{g}_N := \sum_{i=1}^N w_ig(\boldsymbol{u}_i)
\end{equation}
, where $\boldsymbol{u}_i$ is the quadrature point with its weights $w_i$. For low-dimensional space, it is safe to assume that 
\begin{equation}\label{eq: quadrature_error}
    |\Bar{g} - \Bar{g}_N| \leq C^{(2)}N^{-\alpha}
\end{equation}
, for some $\alpha > 0$.
\end{assump}

The optimal parameter $\theta^*$ is obtained by minimizing the training error
\begin{equation}\label{eq: nn_train_error}
\begin{aligned}
\mathcal{E}_{\text{train}} &:= ||\mathcal{A}\boldsymbol{u}(\cdot; \theta) - v||^2_{L^2} = \int_{\mathbb{R}^3} (\mathcal{A}\boldsymbol{u}(\boldsymbol{x}; \theta) - v)^2\, dx\\
& \approx \sum_{i=1}^N w_i (\mathcal{A}\boldsymbol{u}(\boldsymbol{x}_i, \theta) - v)^2
\end{aligned}
\end{equation}
, where $\{\boldsymbol{x}_i\}_{i=1}^N$ are the sample points in the training set $\mathcal{T}$, with $\{w_i\}_{i=1}^N$ the quadrature weights. We also define the test error
\begin{equation}\label{eq: nn_test_error}
    \mathcal{E}_{\text{test}} := ||\boldsymbol{u}(\cdot; \theta) - \boldsymbol{u}(\cdot; \theta^*)||_{\mathcal{U}}
\end{equation}
The following theorem and its corollary provide an upper bound for the test error in terms of training and validation error.

\begin{theorem}
Suppose the operator $\mathcal{A}$ satisfies \eqref{eq: operator_regularity}, the quadrature error satisfies \eqref{eq: quadrature_error}, and the neural networks are trained by minimizing \eqref{eq: nn_train_error}, then 
\begin{equation}
    \mathcal{E}_{\text{test}} \leq C^{(1)}\mathcal{E}_{\text{train}} + C^{(1)} (C^{(2)})^{1/2} N^{-\alpha/2}
\end{equation}
\end{theorem}
\begin{proof}
\begin{equation}
\begin{aligned}
\mathcal{E}_{\text{test}} & = ||\boldsymbol{u}(\cdot; \theta) - \boldsymbol{u}(\cdot; \theta^*)||_{\mathcal{U}} \leq C^{(1)} ||\mathcal{A}\boldsymbol{u} - \mathcal{A}\boldsymbol{u}'||_{\mathcal{V}}\\
& \leq C^{(1)}\left(\sum_{i=1}^N w_i (\mathcal{A}\boldsymbol{u}(\boldsymbol{x}_i, \theta) - v)^2  + C^{(2)}N^{-\alpha}\right)^{1/2} \\
& \leq C^{(1)}\mathcal{E}_{\text{train}} + C^{(1)}(C^{(2)})^{1/2}N^{-\alpha/2}
\end{aligned}
\end{equation}
\end{proof}

\begin{corol}
Suppose the operator $\mathcal{A}$ satisfies \eqref{eq: operator_regularity}, the quadrature error satisfies \eqref{eq: quadrature_error}, and the neural networks are trained by minimizing \eqref{eq: nn_train_error}. Furthermore, the validation points and test points are sampled from the same distribution as the training samples $\{\boldsymbol{x}_i\}_{i=1}^N$ in the training set. Then, 
\begin{equation}
\Bar{\mathcal{E}}_{\text{test}} \leq C^{(1)} \left( \Bar{\mathcal{E}}_{\text{train}} + \mathcal{E}_{\text{vg}} + \frac{1}{\sqrt{N}} \sqrt{\hat{\sigma}^2(\theta^*)}\right),
\end{equation}
where $\Bar{\mathcal{E}}_{\text{train}}$ and $\Bar{\mathcal{E}}_{\text{test}}$ is the average train error and test errors across training and test data sets during different training processes, defined as
\begin{equation}
\begin{aligned}
\Bar{\mathcal{E}}_{\text{train}} &= \int_{\mathbb{R}^{3N}} \mathcal{E}_{\text{train}}(\boldsymbol{x}_{1\cdots N}^\mathcal{T})d\mathcal{T}, \quad \Bar{\mathcal{E}}_{\text{test}} &= \int_{\mathbb{R}^{3N}} \mathcal{E}_{\text{test}}(\boldsymbol{x}_{1\cdots N}^\mathcal{T})d\mathcal{T}''
\end{aligned}
\end{equation}
, with $\int \cdot d\mathcal{T}$ and $\int \cdot d\mathcal{T}''$ represents aggregation across different training data sets $\mathcal{T}$ and test data sets $\mathcal{T}''$, respectively. $\Bar{\mathcal{E}}_{\text{valid}}$ represents the expected difference between the training samples and validation samples, defined as
\begin{equation}
    \Bar{\mathcal{E}}_{\text{valid}} = \frac{1}{N} \int_{\mathbb{D}^{3N}} \sum_{j=1} |\mathcal{A}\boldsymbol{u}(\boldsymbol{x}_{1\cdots N}^\mathcal{T}; \theta) - \mathcal{A}\boldsymbol{u}(\boldsymbol{x}_{1\cdots N}^{\mathcal{T}}; \theta^*)| d\mathcal{T}'
\end{equation}
, where  $\int \cdot d\mathcal{T}'$ represents sum across different validation sample sets. $\mathcal{E}_{vg} := \mathbb{E}|\Bar{\mathcal{E}}_{\text{train}} - \Bar{\mathcal{E}}_{\text{test}}|$ is the validation gap between training and validation data set. $\hat{\sigma}^2(\theta^*)$ is the variance of $\theta^*$ obtained by multiple training results,
\begin{equation}
\begin{aligned}
\hat{\sigma}^2(\theta^*) & = \mathbb{E} \Biggl( \int_{\mathbb{R}^{3N}} |\mathcal{A}\boldsymbol{u}(\boldsymbol{x}_{1\cdots N}^\mathcal{T}; \theta) - \mathcal{A}\boldsymbol{u}(\boldsymbol{x}_1^N; \theta^*)|\, d\boldsymbol{x}_{1\cdots N}^\mathcal{T} \\
& \quad\quad  - \int_{\mathcal{T}} \int_{\mathbb{D}^{3N}}|\mathcal{A}\boldsymbol{u}(\boldsymbol{x}_{1\cdots N}^\mathcal{T}; \theta) - \mathcal{A}\boldsymbol{u}(\boldsymbol{x}_1^N; \theta^*)| \, d\boldsymbol{x}_{1\cdots N}^{\mathcal{T}} \, d\mathcal{T} \Biggr)^2.
\end{aligned}
\end{equation}
\end{corol}





\begin{proof}
\begin{equation}
\begin{aligned}
\Bar{\mathcal{E}}_{\text{test}} & = \mathbb{E}||\boldsymbol{u}(\cdot; \theta) - \boldsymbol{u}(\cdot; \theta^*)||_{\mathcal{U}} \leq C^{(1)} \mathbb{E}  ||\mathcal{A}\boldsymbol{u} - \mathcal{A}\boldsymbol{u}'||_{\mathcal{V}}\\
& \leq C^{(1)} \left( \mathbb{E}\left(\mathbb{E}(||\mathcal{A}\boldsymbol{u} - \mathcal{A}\boldsymbol{u}'||_{\mathcal{V}})|\mathcal{T}\right) + \Bar{\mathcal{E}}_{\text{valid}} - \Bar{\mathcal{E}}_{\text{valid}} + \Bar{\mathcal{E}}_{\text{test}} - \Bar{\mathcal{E}}_{\text{test}}\right)\\
& \leq C^{(1)} \left( \Bar{\mathcal{E}}_{\text{train}} + \mathcal{E}_{\text{vg}} + \frac{1}{\sqrt{N}} \sqrt{ \mathbb{E} \left( \left| \mathbb{E} \left(||\mathcal{A}\boldsymbol{u} - \mathcal{A}\boldsymbol{u}'||_{\mathcal{V}}|\mathcal{T} \right) - \bar{\mathcal{E}}_V \right|^2 \right) }
\right)
\end{aligned}
\end{equation}
, and $\hat{\sigma}^2(\theta^*)$ estimates $\mathbb{E} \left( \left| \mathbb{E} \left(||\mathcal{A}\boldsymbol{u} - \mathcal{A}\boldsymbol{u}'||_{\mathcal{V}}|\mathcal{T} \right) - \bar{\mathcal{E}}_V \right|^2 \right)$.

\end{proof}


\subsection{Data Pre-processing}
\label{dataprocess}

Before model training, we convert raw simulation outputs into a graph‐based dataset in four stages. First, we parse LAMMPS files to extract atomic coordinates and element labels, and we read corresponding potential energies from the EAM output and get \(\{\mathbf{r}_i, t_i, E\}\) . To ensure balanced sampling across thermodynamic states, we randomly select up to 5000 snapshots per temperature. Next, we normalize the energy values to a 0–100 scale, avoiding division by zero when the range is degenerate. Each configuration is then transformed into a PyTorch‐Geometric Data object: atom types become one‐hot node features, interatomic displacements (with periodic boundary corrections) and distances form edge attributes, and we store true positions for later radial‐distribution‐function regularization. 

\textbf{Periodic-boundary displacements:}

    For each pair \((i,j)\),
    \[
      \Delta \mathbf{r}_{ij}
      = \bigl(\mathbf{r}_i - \mathbf{r}_j + \tfrac{L}{2}\bigr)\bmod L \;-\; \tfrac{L}{2},
      \quad
      d_{ij} = \|\Delta \mathbf{r}_{ij}\|_2,
    \]
    where \(L\) is the box length.

\textbf{Graph construction:}

\textbf{Node features}: one-hot encode each atom type \(t_i\) into \(\mathbf{x}_i\in\{0,1\}^{n_{\rm types}}\).\\
\textbf{Edge attributes}: for all pairs with \(d_{ij}<r_{\rm cutoff}\), set
      \(\mathbf{a}_{ij} = [\,\Delta \mathbf{r}_{ij},\,d_{ij}\,]\).


Finally, we assemble these graphs into an 80/20 train–test split and wrap them in DataLoaders (batch size = 64, also shuffled for training) to feed into our GlassVAE pipeline.
