\subparagraph*{Other Related Work. } Several works have studied the complexity of repeated computation. In communication complexity, this began with the influential proof of the randomized communication lower bound for the disjointness function \cite{KalyanasundaramSchnitger87, Razborov92}, which is the composition of the OR function on $n$ bits with the AND gadget. Their techniques were modified to prove direct sum type statements \cite{CSWY, JRS, HJMR} and streaming lower bounds \cite{BJKS}. Around the same time Raz \cite{Raz} proved the parallel repetition theorem, which was simplified by Holenstein \cite{Holenstein} and Rao \cite{Rao}. Barak, Braverman, Chen and Rao \cite{BBCR} adapted the techniques developed for the parallel repetition theorem  to prove general direct sum statements for randomized communication complexity. Several aspects of this were improved over the last decade, for example \cite{BRWY} gave a direct product theorem and \cite{Kol,Sherstov} gave near-optimal distributional direct-sum statements for product distributions. Recently, Yu \cite{Yu} gave an XOR lemma for bounded-round randomized communication, which we improved in our work with Rao \cite{IR24a} to obtain an XOR lemma for general randomized communication.

\subparagraph*{Techniques.} The following lemma is key to the proof of \Cref{thm:main}.
\begin{lemma}\label{lem:dense-rectangle}
If $f \circ g$ can be covered with $2^{T}$ monochromatic rectangles, then $g$ contains a monochromatic rectangle of density $2^{-2T/\mathsf{s}(f)}\cdot (4\cdot\rk(g))^{-2}$.
\end{lemma}

A similar statement was also derived in \cite{IR24b}, where $f$ was assumed to be the parity function on $n$ bits. 
We explain the high-level idea of the proof in a few lines and how it differs from the proof in \cite{IR24b}. Let $u(x,y)$ denote the uniform distribution on $\calX^n\times \calY^n$. A key observation made in \cite{IR24b} is that there exists a rectangle $R$ that is constant for $\oplus\circ g$, a coordinate $i$, inputs $x_1,\ldots,x_{i-1}$ and $y_{i+1},\ldots,y_n$ such that
\begin{enumerate}
\item\label{item:one} $|\mathsf{supp}(u(x_i,y_i\vert x_1,\ldots,x_{i-1},y_{i+1},\ldots,y_n,R))| \geq \Omega(|\calX|\cdot|\calY|\cdot2^{-T/n})$, where $\mathsf{supp}$ denotes the support of a distribution, and 
\item\label{item:two} there exists a bit $b\in \{0,1\}$ so that for every $(x',y') \in R$ consistent with $x_1,\ldots,x_{i-1}$ and $y_{i+1},\ldots,y_n$ we have $\oplus_{j\neq i} g(x_j',y_j') = b$.
\end{enumerate}

Since $R$ is constant for $\oplus \circ g$, \Cref{item:one,item:two} together imply that $g(x_i,y_i)$ is fixed for every $(x_i,y_i)$ in the support of $u(x_i,y_i\vert x_1,\ldots,x_{i-1},y_{i+1},\ldots,y_n,R)$. Moreover, since $x,y$ are independent in $u$, the support is a rectangle.

%In the above discussion, \Cref{item:two} was formulated specifically for the parity function. 
To prove lower bounds for general function composition, we need an appropriate generalization of the parity constraint in \Cref{item:two}. We enforce such a constraint by switching from the uniform distribution to a correlated distribution. %At a high level, this presents another challenge: when $x,y$ are correlated, the support of $p(x_i,y_i\vert R)$ conditioned on a rectangle $R$ need not itself be a rectangle. %Nevertheless, we are able to resolve this by using the fact that $R$ correctly computed   

For simplicity, assume $\mathsf{s}(f) = n$ and that
$g$ is balanced. By definition, there exists $z\in \{0,1\}^n$ with $f(z) \neq f(z_1,\ldots,z_{i-1},1-z_i,z_{i+1},\ldots,z_n)$, for all $i$. Consider the distribution $p(x,y)$ on $\calX^n\times \calY^n$ obtained by sampling each $(x_i,y_i)$ uniformly conditioned on $g(x_i,y_i) = z_i$. Now, we obtain a weaker statement than \Cref{item:one}, which suffices for our purposes. We show that there exists a rectangle $R$ that is constant for $f\circ g$, a coordinate $i$ and inputs $x_1,\ldots,x_{i-1},y_{i+1},\ldots,y_n$ such that the sets
\begin{align*}
    A &:=  \mathsf{supp}(p(x_i\vert x_1,\ldots,x_{i-1},y_{i+1},\ldots,y_n,R)) \text{ and }\\
    B &:= \mathsf{supp}(p(y_i\vert x_1,\ldots,x_{i-1},y_{i+1},\ldots,y_n,R)),
\end{align*}
satisfy $|A| \geq \Omega(|\calX|\cdot 2^{-T/n})$  and $|B| \geq \Omega(|\calY|\cdot 2^{-T/n})$.

Similar to the proof of \Cref{item:one}, this uses the sub-additivity of entropy, we refer the reader to \Cref{claim:subadditivity} for more details. Next, we show that $A\times B$ is a monochromatic rectangle for $g$. We note that \[\mathsf{supp}(p(x_i,y_i\vert x_{1},\ldots,x_{i-1},y_{i+1},\ldots,y_n,R)) \subseteq A\times B,\] and although $g$ is constant on the former set (by the definition of $p$), it is not obvious that the same holds for the $A\times B$. Nevertheless, we show that this is indeed the case. 

The intuition for this is as follows. For any $(x_i,y_i)\in A\times B$, one can use the definitions of $A,B$ and $p(x,y)$, to show that there exist $(x',y')\in R$ satisfying $x'_i=x_i$, $y'_i = y_i$ and $g(x'_j,y'_j) = z_j$, for all $j \neq i$. Therefore, if $g(x_i,y_i) \neq z_i$, then $f\circ g(x',y') \neq f(z)$, by the sensitivity of $f$. This is a contradiction because for every $(x,y)\in R \supseteq \mathsf{supp}(p(x,y\vert R))$, $f\circ g$ evaluates to $f(z)$. %Indeed, for any $(x_i,y_i)\in K$, there exists $(x',y')\in R$ with $x'_{j} = x_{j}$ for all $j< i$ and  $y'_{j} = y_{j}$ for all $j> i$. Hence, $g\circ f(x',y') = g(z_1,\ldots,z_{i-1},f(x_i,y_i),z_{i+1},\ldots,z_n)$. Since $R$ is monochromatic and $R \cap \mathsf{supp}(p(xy)) \neq \emptyset$, every point in $R$ must evaluate to $f(z)$. Therefore, if $f(x_i,y_i) \neq z_i$, then $f\circ g(x',y') \neq f(z)$, by the sensitivity of $f$. %Indeed, if this was not the case, then there must exist inputs $x' \in  \supp(p(x\vert x_1,\ldots,x_{i-1},y_{i+1},\ldots,y_n,R))$ and $y'\in \supp(p(y\vert x_1,\ldots,x_{i-1},y_{i+1},\ldots,y_n,R))$ such that $x'_j = x_j$ for all $j< i$ and $y'_j = y_j$ for all $j> i$. Thus $(x',y') \in R$ and moreover, for all $j\neq i$, $g(x'_j,y'_j) = z_j$. However, if $g(x'_i,y'_i) = 1- z_i$, then by the sensitivity of $f$, we have $f\circ g(x',y') \neq f(z)$. This is a contradiction because for every $(x,y)$ in the support of $p(x,y\vert R)$, it must be that $f\circ g(x,y) = f(z)$ by definition of $p$.

The main difference between the above high-level description and the proof of \Cref{thm:main} is that $g$ need not be balanced. To address this, we consider two cases. First, we assume that $g$ is extremely biased, say $\Pr[g(x,y) = 1] > 1 - 1/(4\cdot \rk(g))$. In this case, we obtain a monochromatic rectangle for $g$ using an observation of Gavinsky and Lovett \cite{GL}, ignoring the cover for $f\circ g$. Otherwise, $g$ is not too biased and we can apply the above discussion, albeit with a loss of $1/(4\cdot \rk(g))$ in the final bound.

\subparagraph*{Organization. } We recall relevant definitions in \Cref{sec:prelim} and prove \Cref{lem:dense-rectangle} in \Cref{sec:lemma-proof}. \Cref{thm:main} and \Cref{cor} are proved in \Cref{sec:main-thm-proof}.


\section{Preliminaries}\label{sec:prelim}
For shorthand, we denote by $[n]$ the set $\{1,\ldots,n\}$. For an element $x\in \calX^n$, we will refer to $x_1,\ldots,x_{i-1}$ by $x_{< i}$ and similarly, we will refer to $x_{i},\ldots,x_n$ by $x_{\geq i}$. Similarly, for a random variable $X$ taking values in $\calX^n$, we use $X_{< i}$ to denote $X_1,\ldots,X_{i-1}$. All logarithms will be taken base 2. Given a distribution $p(x)$ we use $\mathsf{supp}(p(x))$ to denote the set of points in the support of $p(x)$. We recall some relevant mathematical facts, which we will use later.


\begin{definition}[Entropy]
    Given a random variable $A$ distributed according $p(a)$ the entropy of $X$ is given by
    \[H(A) := \E_{p(a)}\bigg[\log \frac{1}{p(a)}\bigg].\]
\end{definition}

\begin{fact}\label{fact:entropy-upper-bound}
    If $A$ has finite support, then $H(A) \leq \log|\mathsf{supp}(p(a))|$, with equality if $p(a)$ is the uniform distribution. 
\end{fact}

Given two jointly distributed random variables $A$ and $B$ distributed according to $p(ab)$, the conditional entropy of $B$ given $A$ is defined as 
\begin{equation*}
H(B\vert A) :=  \E_{p(ab)}\bigg[\log\frac{1}{p(b\vert a)}\bigg].
\end{equation*}

It is well-known that $H(B\vert A) \leq H(B)$. We also recall the chain rule for entropy
\begin{align}\label{eq:chain-rule}
H(AB) = H(A) + H(B\vert A).
\end{align}

Next, we recall the notion of KL-divergence.

\begin{definition}[KL-divergence]
Given two probability distributions $p(a)$ and $q(a)$, the \emph{KL-divergence} between $p$ and $q$ is defined as 
\[
    \D(p||q) := \E_{p(a)}\bigg[\log \frac{p(a)}{q(a)}\bigg].
\]
\end{definition}

\begin{fact}\label{claim:KL-non-negative}
    For any two distributions $p(a)$ and $q(a)$, it holds that $ \D(p||q) \geq 0$.
\end{fact}

Next, we recall two complexity measures associated with Boolean functions: decision tree complexity and degree. A decision tree of depth $d$ is an adaptive (deterministic) query algorithm, making at most $d$ queries to compute a given function. The algorithm queries variables $x_{i_1},\ldots,x_{i_d}$ adaptively and outputs a bit based on the values of the variables. We say that a decision tree computes a function $f$, if on every input $x$, the algorithm outputs $f(x)$. The decision tree complexity of $f$, denoted $\mathsf{DT}(f)$ is the least depth of a decision tree among those that compute $f$. 
%A decision tree is a rooted binary tree, where each internal vertex is labeled by a variable, each leaf by a bit in $\{0,1\}$, and the two outgoing edges from each vertex are labeled by distinct bits. Moreover, on any root to leaf path no two vertices share the same label. 
We also recall that for every function $f:\{0,1\}^n \to \{0,1\}$, there exists a unique real, multilinear polynomial \[q(x) = \sum_{S\subseteq [n]} c_S\cdot \prod_{i\in S}x_i,\] such that $q(x) = f(x)$ for all $x\in \{0,1\}^n$. The degree of $f$, denoted $\mathsf{deg}(f)$, is the degree of $q$. 

We conclude this section with some facts regarding communication complexity and its connections to the rank of matrices, whose proofs can be found in \cite{RY}. First, we recall that rank is sub-additive.

\begin{fact}\label{fact:rk-subadd}
    For two matrices $A_1$ and $A_2$, we have $\rk(A_1+A_2) \leq \rk(A_1) + \rk(A_2)$.
\end{fact}

Next, we note that the communication complexity of a function is at least the logarithm of rank of the corresponding matrix.

\begin{fact}\label{fact:log-rk}
    For any function $g:\calX\times \calY\to \{0,1\}$, we have $D(g) \geq \lceil\log\rk(g)\rceil$.
\end{fact}

Lastly, we need the fact that a protocol with a small number of leaves can be simulated by a short protocol (see \cite{RY} Theorem 1.7). 

\begin{fact}\label{fact:rebalancing}
    Given a protocol $\pi$ with $\ell$ leaves, there exists a protocol with communication at most $\lceil2 \log_{3/2}\ell\rceil$ that outputs $\pi(x,y)$ on inputs $x$ and $y$.
\end{fact}



\section{Proof of \Cref{lem:dense-rectangle}}\label{sec:lemma-proof}
    First, assume that $\abs{\E_{x,y}[g(x,y)] -1/2} > 1/2 -  1/(4\cdot \rk (f))$. In this case, we claim $g$ contains a monochromatic rectangle of constant density. Indeed, 
    \begin{align*}
        \abs{\E_{x,y}[g(x,y)] - \frac{1}{2}} = \max\bigg\{\Pr_{x,y}[g(x,y) = 1] - \frac{1}{2},\Pr_{x,y}[g(x,y) = 0] - \frac{1}{2} \bigg\},
    \end{align*}
    and we can assume without loss of generality that 
    \[\Pr_{x,y}[g(x,y) = 1] > 1 - \frac{1}{4\cdot \rk(g)}.\]
    Let $E$ be the set of all $x$ such that  $\Pr_y[g(x,y) = 1] \leq 1 - 1/(2\cdot \rk(g))$. We have,
    \begin{align*}
        \Pr_{x,y}[g(x,y) = 1] &\leq  \Pr_x[x\in E]\cdot \bigg(1 -\frac{1}{2\cdot \rk(g)}\bigg) + \Pr_x[x\notin E] \\
        &= 1 - \frac{\Pr_x[x\in E]}{2\cdot \rk(g)},
    \end{align*}
    which implies that $\Pr_{x}[x\in E] \leq 1/2$. Let $x_1,\ldots,x_r\in E^c$ be such that the corresponding rows are maximally linearly independent in $M_g$. Moreover, let $G = \{y: f(x_i,y) =1,  \forall i\in [r]\}$. By a union bound, we have \[\Pr_y[y\notin G]  \leq r\cdot \frac{1}{2\rk(g)} \leq \frac{1}{2}.\] We observe that $E^c\times G$ is a monochromatic rectangle of density at least $1/4$. Since $2^{-2T/s}\cdot(4\cdot\rk(g))^{-2} \leq 1/16 < 1/4$ we have found a monochromatic rectangle of the desired density.

    Next, suppose that $\abs{\E_{x,y}[g(x,y)] - 1/2} < 1/2 -  1/(4\cdot \rk (f))$. We have
    \begin{align}\label{eq:balanced}
        \frac{1}{4\cdot\rk(g)} \leq \Pr_{x,y}[g(x,y) = 0], \Pr_{x,y}[g(x,y) = 1] < 1 - \frac{1}{4\cdot\rk(g)}.
    \end{align}

    For shorthand let $s$ be the sensitivity of $g$. By definition, there exists an input $z\in \{0,1\}^n$ and a set $S\subseteq [n]$ such that 
    \[f(z) \neq f(z_{< i},1 - z_i,z_{> i}).\] 
    We may assume without loss of generality that $S \supseteq [s]$, for otherwise, this can be ensured by renaming the coordinates. Let $u(x,y)$ denote the uniform distribution over all inputs $(x,y)\in \calX^n\times \calY^n$, and let $p(x,y)$ be a distribution obtained by sampling each $(x_i,y_i)$ randomly and independently subject to $g(x_i,y_i) = z_i$. By \Cref{eq:balanced} we have the following inequality relating the two distributions:
    \begin{align}
        \max_{x,y} \frac{p(x_{\leq s},y_{\leq s})}{u(x_{\leq s},y_{\leq s})} &= \max_{xy} \prod_{i\leq s}\frac{u(x_i,y_i\vert g(x_i,y_i) = z_i)}{u(x_i,y_i)} \nonumber \\
        &= \prod_{i\leq s} \frac{1}{\Pr_{u(x_i,y_i)}[g(x_i,y_i) = z_i]} \leq  (4\cdot \rk(g))^{s}. \label{obs:max-bound}
    \end{align}

    Recall that $f\circ g$ can be covered with at most $2^T$ monochromatic rectangles, say $R_1,\ldots,R_{2^T}$. Thus, there exists a rectangle $R$ in the cover with $p(R) \geq 2^{-T}$. 
    Let $X$ and $Y$ be random variables denoting rows and columns of $\calX^n$ and $\calY^n$ respectively, where $XY$ is distributed according to $p(x,y\vert R)$.
    \begin{claim}\label{claim:subadditivity}
        \[\sum_{i\in [s]} H(X_i\vert X_{< i},X_{> s},Y_{> i}) + H(Y_i\vert X_{< i},X_{> s},Y_{> i}) \geq s\log\frac{|\calX|\cdot|\calY|}{(4\cdot\rk(g))^2} - 2T.  \]
    \end{claim}
    \begin{proof}
    Applying the chain rule for entropy we get
    \begin{align*}
        &\sum_{i\in [s]} H(X_i\vert X_{< i},X_{> s},Y_{> i}) + H(Y_i\vert X_{< i},X_{> s},Y_{> i}) \\&\geq \sum_{i\in [s]} H(X_i\vert X_{< i},X_{> s},Y) + H(Y_i\vert X,Y_{> i}) 
        = H(X\vert X_{> s},Y) + H(Y\vert X,Y_{> s}).
    \end{align*}
    Let $p'(x,y)$ be the distribution obtained by sampling $(x_j,y_j)$ uniformly at random, for each $j\in [s]$, and according to $p(x_j,y_j)$ for each $j\notin S$. Using this notation, we bound the term $H(X\vert X_{> s},Y)$ above as follows  
    \begin{align*}
    &H(X\vert Y,X_{> s}) \\&= \E_{p(x,y\vert R)}\bigg[\log\frac{1}{p(x\vert y,x_{> s},R)}\bigg] \\
    &= \E_{p(x,y\vert R)}\bigg[\log\frac{p(R)\cdot p(x_{> s},y\vert R)}{p(x,y)}\bigg] \\
    &\geq \E_{p(x,y\vert R)}\bigg[\log\frac{p(x_{> s},y\vert R)}{(4\cdot\rk(g))^s\cdot u(x_{\leq s},y_{\leq s})\cdot p(x_{> s},y_{> s})}\bigg] - T \tag{\Cref{obs:max-bound} and $p(R)\geq 2^{-T}$}\\
    &= \E_{p(x,y\vert R)}\bigg[\log\frac{|\calX|^s\cdot p(x_{> s},y\vert R)}{p'(x_{> s},y)}\bigg] - T - s\log(4\cdot\rk(g))\\
    &= s\log \frac{|\calX|}{4\cdot\rk(g)} + \D(p(x_{>s},y\vert R)||p'(x_{> s},y)) - T \geq s\log \frac{|\calX|}{4\cdot\rk(g)} -T,
    \end{align*}    
    which follows by \Cref{claim:KL-non-negative}. A similar calculation shows that $H(Y\vert X,Y_{> s}) \geq s\log \frac{|\calY|}{4\cdot\rk(g)} - T$, yielding the desired bound.
    \end{proof}

    By an averaging argument, we obtain an index $i\in[s]$ and $x_{< i},x_{>s},y_{> i}$ such that
    \begin{align*}
        H(X_i\vert x_{< i},x_{>s},y_{> i}) + H(Y_i\vert x_{< i},x_{>s},y_{> i}) \geq \log\frac{|\calX|\cdot|\calY|}{(4\cdot\rk(g))^2} - \frac{2T}{s}.
    \end{align*}
    For shorthand, let \[A := \mathsf{supp}(p(x_i\vert x_{<i},x_{>s},y_{>i},R)) \text{ and } B:= \mathsf{supp}(p(y_i\vert x_{<i},x_{>s},y_{>i},R)).\]

    Using \Cref{fact:entropy-upper-bound} we conclude that the rectangle given by $A\times B$ has size at least 
