            &= \E_{\rho(xym)}\Bigg[\log \frac{\rho(x\vert ym)}{\rho(x)}\bigg] + \sum_{i=1}^n\E_{\rho(xym)}\Bigg[\log \frac{\rho(x_i \vert x_{< i}y_{> i}m)}{\rho(x_i\vert x_{< i}ym)}\bigg]\\
            &= \Dfrac{\rho(X\vert YM)}{\rho(X)} - \sum_{i=1}^n\Dfrac{\rho(X_i\vert X_{<i}YM)}{\rho(X_i\vert X_{< i}Y_{> i}M)} \leq \Dfrac{\rho(X\vert YM)}{\rho(X)}.
        \end{align*}
        Next, we observe that
        \begin{align*}
            \Dfrac{\rho(X\vert YM)}{\rho(X)} &= \E_{\rho(xym)}\bigg[\log\frac{\rho(x\vert ym)}{\rho(x)}\bigg] \\
            &\leq \log\E_{\rho(xym)}\bigg[\frac{\rho(x\vert ym)}{\rho(x)}\bigg]\\
            &= \log\bigg(\sum_{xym}\rho(x)\cdot \rho(ym\vert x)\cdot \frac{\rho(x\vert ym)}{\rho(x)}\bigg)
        \end{align*}
    \end{proof}
\end{proof}
