\title{Balanced and Fair Partitioning of Friends%
    \footnote{%
        An extended abstract of this work has been published in the Proceedings of the 39th {AAAI} Conference on Artificial Intelligence, AAAI~'25~\cite{DeligkasEIKS2025}. %
    }%
}

