\section{Preliminaries}
\label{preparation}
\setcounter{equation}{0}

In this section, we present several useful lemmas, which will be frequently used in our proof.
Let $\P_h : L^2(\Omega) \rightarrow {\DG}_0$ be the $L^2$ projector: For $u\in L^2(\Omega)$, seek $\P_h u \in {\DG}_0$, such that
\begin{align}
	(\mathcal{P}_h u - u , v_h) =0,  \quad \forall ~ v_h \in {\DG}_0 \,.\label{equ-dg0-projector}
\end{align}
Let ${\Pi}_h: \bH(\D) \rightarrow {\RT_{\! \! 0} }$ be the quasi Raviart--Thomas projector
developed by Ern et al. in \cite{Ern-Gudi}.
Then, the following diagram commutes \cite{Ern-Gudi}
\begin{align}
	\begin{array}{crlrlrl}%ccccccc
		\bH(\D)
		& \xrightarrow{\quad \D \quad}
		& \quad L^2(\Omega)              \\
		\Pi_h~ \!\!\Bigg\downarrow ~~~~ &                              &
		~ \P_h~ \!\! \Bigg\downarrow                                     \\
		\RT_{\! \! 0}
		& \xrightarrow{\quad \D \quad}
		& \quad~ {\DG}_0
	\end{array}
	\label{diagram}
\end{align}
Moreover, the following lemma holds under the minimal necessary Sobolev regularity \cite{Ern-Gudi}.
\begin{lemma}
	The quasi-projector $\Pi_h$ maps $\bH(\D)$ to $\RT_{\! \! 0}$ and there holds
	\begin{align}
		\label{RTNp-error}
		\| \bv - \Pi_h\bv\|^2_{L^2(\Omega)}
		& +  h^2 \| \D \, (\bv - \Pi_h\bv )\|_{L^2(\Omega)}^2
		\nn                                                       \\
		& \le C \left( h^{\min{(s,1)}} \|\bv\|_{\bH^s(\Omega)} +
		\delta_{s<1} \, h \, \|\nabla\cdot\bv\|_{L^2(\Omega)} \right)^2\,,
	\end{align}
	where $\delta_{s<1}:=1$ if $s<1$ and $\delta_{s<1}:=0$ if $s\ge1$.
	In addition, the projector $\Pi_h$ is globally $L^2$-stable up to $hp$
	data oscillation of the divergence and $\bH(\D)$-stable
	\begin{empheq}[left=\empheqlbrace]{align}
		& \|\Pi_h\bv\|^2_{L^2(\Omega)} \le C \left( \|\bv\|^2_{L^2(\Omega)}
		+ h^2 \| \D \, \bv - \P_h (\D \, \bv) \|_{L^2(\Omega)}^2 \right) \, ,
		\label{RTNp-stable}
		\\
		&
		\|\Pi_h \bv\|^2_{L^2(\Omega)} +  \|\D \, \Pi_h \bv\|^2_{L^2(\Omega)}
		\le C \left( \|\bv\|^2_{L^2(\Omega)} + \|\D \, \bv\|^2_{L^2(\Omega)} \right)\,.
		\label{RTNp-stable-Hdiv}
	\end{empheq}

\end{lemma}


Moreover, the following error estimates hold for $\Pi_h$ and $\P_h$, see
\cite{Ciarlet} and \cite[Section 3]{ACWY}
\begin{empheq}[left=\empheqlbrace]{align}
	& \| v- \P_h v\|_{H^{-t}(\Omega)} \le C h^{t+s} \|v\|_{H^s(\Omega)} \,,
	&& \textrm{for}~ 0 \le t,s \le 1\,.
	\label{L2-projection-error-u}
	\\
	& \|\D(\bm{v} -\Pi_h \bm{v}) \|_{L^2(\Omega)} \le  C h^{s} \|\D \, \bm{v}\|_{H^s(\Omega)}\,,
	&& \textrm{for}~ 0 \le s \le 1  \,,
	\\
	& \| (\bm{v} - \Pi_h \bm{v}) \cdot  \bn\|_{H^{-t}(\Gamma)} \le Ch^{t+s}  \|\bm{v}\|_{H^s(\Gamma)}\,,
	&& \textrm{for}~ 0 \le t,s \le 1 \, ,
	\label{RT-projection-error-boundary}
\end{empheq}
The below inverse estimate for the normal trace holds \cite[Lemma 4.1]{ACWY}
\begin{align}
	\| \bm{v}_h \cdot \bn \|_{L^2(\Gamma)} \le C h^{-\frac{1}{2}}
	\|\bm{v}_h\|_{L^2(\Omega)}\,,
	\qquad
	\forall \bm{v}_h \in \RT_{\! \! 0}  \,.
	\label{RT-element-boundness-boundary}
\end{align}


The following results on traces are needed in our analysis,
see \cite[Theorem 1.5.1.2,Theorem 1.5.1.3]{Grisvard1985EllipticPI}.

\begin{lemma}
	\label{trace-lemma-origin}
	Let $\Omega$ be a bounded Lipschitz domain.
	Assume $\mathrm{tr}:H^s(\Omega) \to L^2_{loc}(\Gamma)$ is the trace operator on $\Gamma$,
	then for $u\in H^s(\Omega)$ with ${1}/{2} < s\le 1$, there holds
	\begin{equation}
		\|\mathrm{tr}(u)\|_{H^{s-\frac{1}{2}}(\Gamma)} \le C \|u\|_{H^{s}(\Omega)}\,,
	\end{equation}
	where C depends on the domain $\Omega$ only.
\end{lemma}

\begin{corollary}
	\label{trace-lemma}
	Let $\Omega$ be a bounded Lipschitz domain.  
	For $u\in H^{1+s}(\Omega)$ with ${1}/{2} < s \le 1$, there holds
	\begin{equation}
		\|\mathrm{tr}(\frac{\partial u}{\partial \bn})\|_{H^{s-\frac{1}{2}}(\Gamma)} \le C \|u\|_{H^{1+s}(\Omega)}\,,
	\end{equation}
	where $C$ depends on $\Omega$ only, $\bn$ is the outer normal on the boundary $\Gamma$.
\end{corollary}

\begin{lemma}
  \label{lemma-regularity}
  The solution $u$ to the Poisson equation with a homogeneous Dirichlet boundary condition
  \begin{equation}
    \left\{ {
      \begin{array}{l}
	{-\Delta u =  f \,, \quad \quad \mathrm{in} ~ \Omega\,, } \\
	{u = 0\,, \qquad\quad  ~\mathrm{on}~ \Gamma\,,}
    \end{array}}
    \right.
    \label{poisson-standard}
  \end{equation}
  satisfies
  \begin{align}
    \|u\|_{H^{1+\lambda}(\Omega)} \le C \|f\|_{L^2(\Omega)},
  \end{align}
  where $f\in L^2(\Omega)$, $C$ is a positive constant independent of $u$ and $f$.
  The index $\lambda$ only depends on the domain $\Omega$.
  For two dimensional polygons, we have
  \begin{equation}
    \lambda_{\textrm{2D}} \in \big( \frac{1}{2}, \, \frac{\pi}{\max_j \Theta_j} \big)  \, ,
    \label{s-index-2d}
  \end{equation}
  where $\{\Theta_j\}$ denotes the re-entrant interior angles of $\Omega$.
  For three dimensional nonconvex polyhedral domain, the regularity of $u$ depends on both
  the edge opening angle at edges $\{ e \}$ and the shape of the domain near corners $\{v\}$,
  i.e., edges and corners may introduce certain singularities.
  \textcolor{black}
  {Assume $\mathcal{E}$ and $\mathcal{V}$ represent all the edges and vertices respectively,
  the solution $u$ satisfies the splitting
  \begin{equation}
  	u = u_r + \sum_{e\in \mathcal{E}} \alpha_e \psi_e u_e +  \sum_{v\in \mathcal{V}} \alpha_v \psi_v u_v \,,
  \end{equation}
  where $u_r \in H^2(\Omega)$ denotes the regular part,
  $\psi_e$ and $\psi_v$ are cutoff functions
  that equal 1 in neighborhoods of $e$ and $v$, respectively. 
  Here, $u_e$ and $u_v$ denote the singular functions associated with the edge and vertex.
  $\alpha_e$ and $\alpha_v$ represent their corresponding singularity coefficients.}
  \color{black}
  Moreover, there holds
  \begin{equation}
    \label{s-index-3d-part1}
    u_e \in H^{1+\lambda_{\textrm{3D}}}(\Omega),
    \quad \textrm{with} \quad
    \frac{1}{2} < \lambda_{\textrm{3D}} < \frac{\pi}{\max_{e \in \mathcal{E}} \Theta_e} \,,
  \end{equation}
  and 
  \begin{equation}
    \label{s-index-3d-part2}
    \begin{aligned}
    u_v \in H^{1+\lambda_{\textrm{3D}}}(\Omega),
    \quad \textrm{with} \quad      
      & \frac{1}{2} < \lambda_{\textrm{3D}} < \frac{1}{2} + \min_{v \in \mathcal{V}}\{ \lambda_{v,D} , 2\},
    \end{aligned}
  \end{equation}
  \color{black}
  where $\Theta_e$ denotes the edge opening angle at the edge $e$,
  and $\lambda_{v,D}>0$ depends on the smallest Dirichlet eigenvalue of the surface Laplacian
  around corner $v$, see \cite{Chatzipantelidis-BIT2006,Dauge,Grisvard1992Singular} for details.

\end{lemma}

If the domain $\Omega$ is convex, there holds
\begin{align}
	\|u\|_{H^{2}(\Omega)} \le C \|f\|_{L^2(\Omega)}.
\end{align}

In the rest of this paper, we use a unified index $s$ to describe the regularity of \refe{poisson-standard}
\begin{align}
  \|u\|_{H^{1+s}(\Omega)} \le C \|f\|_{L^2(\Omega)}, \quad
  \textrm{with} \quad
  \left\{
  \begin{array}{ll}
  	s = 1
  	& \textrm{if $\Omega$ is convex,}
  	\\[2pt]
  	s = \sup \{ \lambda_{\textrm{2D}} \} - \epsilon
  	& \textrm{in 2D},
  	\\[2pt]
  	s = \sup \{ \lambda_{\textrm{3D}} \} - \epsilon
  	& \textrm{in 3D},
  \end{array}
  \right.
  \label{index-unified}
\end{align}
where
\textcolor{black}{
  $\lambda_{\textrm{2D}}$ is defined in \refe{s-index-2d}
  and
  $\lambda_{\textrm{3D}}$ is defined in \refe{s-index-3d-part1}-\refe{s-index-3d-part2},
  respectively,}
and  $\epsilon>0$ is any arbitrarily small number.
We can see that for Lipschitz polygonal/polyhedral domains,
the solution $u$ to \refe{poisson-standard} always belongs to $H^{3/2+\epsilon}(\Omega)$,
\textcolor{black}{see \cite[Theorem 3.1]{Berggren2004}}.
Recall the definition of $V$ in \refe{very-weak-test-space},
the $H^{3/2+\epsilon}$ regularity 
ensures that $\partial_{\mathbf{n}} v \in L^{2}(\Gamma)$ for any $v \in V$.


The standard Raviart--Thomas mixed FEM for \refe{poisson-standard} is to
seek $(\bs_h,u_h) \in \RT_{\! \! 0} \times \DG_{\! 0} $, such that
\begin{empheq}[left=\empheqlbrace]{align}
	&(\bs_h \,,\, \bm{\chi}_h) + (u_h \,, \D \bm{\chi}_h )= 0 \,,
	&& \forall \bm{\chi}_h \in \RT_{\! \! 0} \,,
	\label{mixed-fem1-standard}
	\\
	& -(\D \bs_h, v_h) = (f,v_h),
	&&
	\forall \,v_h \in \DG_{\! 0} \, .
	\label{mixed-fem2-standard}
\end{empheq}
The following estimates hold \cite[Lemma 6.1]{Ern-Gudi}
\begin{align}
	\|\bs_h - \bs\|_{L^2(\Omega)} \le C h^s  \|f\|_{L^2(\Omega)}  \quad
	\textrm{and} \quad
	\|u_h - u \|_{L^2(\Omega)} \le C h \|f\|_{L^2(\Omega)}\,,
\end{align}
where the index $s$ is defined in \refe{index-unified}.

