\section{The proof of the main result}
\label{proof-main-result}
\setcounter{equation}{0}

Following the idea of Apel, Nicaise and Pfefferer in \cite{Apel}, we introduce a regularized
elliptic problem for the original Poisson equation \refe{pde}-\refe{pde-bc}.
We shall introduce the linear Lagrange element space $P_1$ on the mesh $\mathcal{T}_{h}$.
Moreover, let $P_1^\partial:=P_1|_{\Gamma}$.
Let $g^h \in H^{1/2}(\Gamma)$ denote a sequence of functions such that
\begin{align}
	\lim_{h \to 0} \|g - g^h\|_{L^2(\Gamma)} = 0.
\end{align}
The construction of $g^h$ can be done by the $L^2$-projection of $g$ onto $P_1^\partial$,
which is analyzed in Berggren's pioneering work \cite{Berggren2004}.
Alternatively, one can use the Carstensen interpolant \cite{Carstensen1999}.
\color{black}
For the sequence $\{g^h\}$, there holds \cite{Berggren2004},\cite[Lemma 2.14]{Apel}\color{black}
\begin{align}
	\label{gh-error}
	\| g^h - g \|_{H^{-s}(\Gamma)} \le Ch^{t+s}\|g\|_{H^t(\Gamma)}, \quad
	\forall \, t, ~s \in [0,1],
\end{align}
provided $g \in H^t(\Gamma)$.

Now, for given $g^h \in H^{{1}/{2}}(\Gamma)$, $f \in L^2(\Omega)$,
we introduce a mixed weak form: Seek $\bs^h \in \bH(\D), u^h \in L^2(\Omega)$, such that
\begin{empheq}[left=\empheqlbrace]{align}
	&( \bs^h ,\,  \bm{\chi})
	+(u^h,\, \D  \bm{\chi})= \langle g^h, \, \bm{\chi} \cdot \n \rangle \, ,
	&& \forall ~ \bm{\chi} \in \bH(\D)\,,
	\label{auxiliary-variational-problem-1}
	\\
	&(-\D \bs^h,\, v) = (f, \, v) \,,
	&& \forall ~ v \in L^2(\Omega)\,.
	\label{auxiliary-variational-problem-2}
\end{empheq}
The existence of the solution $(\bs^h,u^h)$ to the above mixed variational form
is obvious \cite{Boffi-Brezzi-Fortin,Gatica}, which satisfies the following standard estimate
\begin{align}
	\|\bs^h\|_{\bH(\D)} + \|u^h\|_{L^2(\Omega)} \le C\left( \|f\|_{L^2(\Omega)}+ \|g^h\|_{H^{\frac{1}{2}}(\Gamma)}\right).
	\label{mixedFEM-standard-estimate}
\end{align}
The following lemma shows the convergence of solutions $\{u^h\}$
of the auxiliary problem to the very weak solution $u$.	
\color{black}
	This result follows directly from \cite[Corollary 3.3]{Apel}, since the unique weak solution
	to the primal formulation is also the unique weak solution to its corresponding mixed formulation.
	While the original corollary is stated for polygonal domains,
	the proof is still valid for Lipschitz polyhedral domain
	as Lemma \ref{trace-lemma} provides the required trace regularity.
\color{black}
\begin{lemma}
	\label{error-auxiliary-variational-problem}
	For given $g^h \in \{ g^h \}$, the variational form
	\refe{auxiliary-variational-problem-1}-\refe{auxiliary-variational-problem-2}
	admits a unique solution $u^h \in L^2(\Omega)$.
	The limit $u := \lim_{h \rightarrow 0} u^h$  exists and is the very weak solution.
	Moreover, there holds,
	\begin{align}
		\label{error-auxiliary-uh}
		\| u^h - u \|_{L^2(\Omega)}  \le C h^{s-\frac{1}{2}}  \|g\|_{L^2(\Gamma)} \,,
	\end{align}
	where the index $s$ is defined in \refe{index-unified}.  
\end{lemma}

Based on the regularization error \refe{error-auxiliary-uh}
in Lemma \ref{error-auxiliary-variational-problem},
we prove the error estimate \refe{main-error-estimate-u}
in the main Theorem \ref{main-theorem}.
The proof consists of two steps. In the first step,
we derive an estimate for $\bs^h-\bs_h$.
In the second part, we present an error estimate for $u^h-u_h$.


By subtracting the regularized equations
\refe{auxiliary-variational-problem-1}-\refe{auxiliary-variational-problem-2}
from mixed FEM \refe{mixed-fem1}-\refe{mixed-fem2}, we deduce the error equations
\begin{empheq}[left=\empheqlbrace]{align}
	\label{error-pre-1}
	&(\bs^h - \bs_h , \bm{\chi}_h) + (u^h-u_h , \D \bm{\chi}_h)
	= \langle g^h-g\,, \bm{\chi}_h \cdot \bn \rangle ,
	&& \forall \bm{\chi}_h \in \RT_{\! \! 0} \,,
	\\
	\label{error-pre-2}
	& (\D (\bs^h-\bs_h) , v_h) = 0 ,
	&& \forall v_h \in \DG_0 \,.
\end{empheq}
Here, we shall introduce the $L^2$ projector of $u^h$,
\begin{align}
	(\P_h u^h - u^h , v_h ) = 0,   \qquad \forall  v_h \in \DG_{\! 0} \,.
	\nn
\end{align}
Then, the projection error satisfies
\begin{eqnarray}
	\|\P_h u^h - u^h\|_{L^2(\Omega)} & \le & C h \|u^h\|_{H^1(\Omega)}
	\nn \\
	& \le & C h (\|f\|_{L^2(\Omega)} + \|g^h\|_{H^{\frac{1}{2}}(\Gamma)})
	\nn \\
	& \le & C h \|f\|_{L^2(\Omega)} + C h^{\frac{1}{2}}\|g\|_{L^{2}(\Gamma)}.
	\label{error-uh-mid}
\end{eqnarray}
where we have used an inverse inequality and the fact that $g^h \in P_1^{\partial}$.
As $\D \RT_{\! \! 0} \subset \DG_{\! 0} $, the error equations
\refe{error-pre-1}-\refe{error-pre-2} can be rewritten as
\begin{empheq}[left=\empheqlbrace]{align}
	& (\bs^h - \bs_h , \bm{\chi}_h)  +(\P_h u^h -u_h , \D \bm{\chi}_h)
	= \langle g^h-g\,, \bm{\chi}_h  \cdot \bn \rangle ,  && \forall  \bm{\chi}_h \in \RT_{\! \! 0} \,,
	\label{error1}
	\\
	& (\D (\bs^h-\bs_h) , v_h) = 0 ,
	&&   \forall v_h \in \DG_0 \,.
	\label{error2}
\end{empheq}

An estimate for $\bs_h$ is given in the lemma below.
\begin{lemma}
	\label{lemma-sigma-eror}
	If $f \in L^2(\Omega)$, $g \in
	L^2(\Gamma)$ and $g^h \in H^{{1}/{2}}(\Gamma)$, we have
	\begin{align}
		\label{error-sigma}
		\| \bs^h - \bs_h\|_{L^2(\Omega)} \le C( h^{-\frac{1}{2}} \|g\|_{L^2(\Gamma)} + \|f\|_{L^2(\Omega)})\,,
	\end{align}
	where the constant $C$ is independent of $h$.
\end{lemma}
\
{\noindent \bf Proof.}
From the commuting diagram \refe{diagram}, the equation \refe{error2} can be rewritten as
\begin{eqnarray}
	(\D \, (\bs^h - \bs_h), v_h)
	& = &
	(\D \, (\bs^h -  \Pi_h \bs^h), v_h )
	+(\D \, (\Pi_h\bs^h -  \bs_h), v_h)
	\nn \\
	& = & (\D (\Pi_h\bs^h -  \bs_h), v_h)
	=0,
	\quad \forall v_h \in \DG_{\! 0}\,,
	\nn
\end{eqnarray}
which, by taking $v_h = \D ( \Pi_h\bs^h -\bs_h ) $ implies the fact
\begin{align}
	\label{div-sigma-free}
	\D (\Pi_h\bs^h - \bs_h)=0\,.
\end{align}
Next, by taking $\bm{\chi}_h = \Pi_h \bs^h - \bs_h$ into \refe{error1}, we obtain
\begin{align}
	\|\Pi_h\bs^h - \bs_h\|^2_{L^2(\Omega)}
	& =(\Pi_h\bs^h - \bs^h,  \Pi_h\bs^h - \bs_h)
	+ \langle g^h - g, (\Pi_h\bs^h - \bs_h) \cdot \bn \rangle
	\nn \\
	& \le \|\Pi_h\bs^h - \bs^h\|_{L^2(\Omega)}
	\|\Pi_h\bs^h - \bs_h\|_{L^2(\Omega)}
	\nn \\
	&  \quad
	+ \| g^h - g\|_{L^2(\Gamma)} \|(\Pi_h\bs^h-\bs_h) \cdot
	\bn\|_{L^2(\Gamma)}
	\nn \\
	\textrm{(by \refe{RTNp-error})} \quad
	& \le C (\|\bs^h\|_{L^2(\Omega)} + h \|\D \bs^h\|_{L^2(\Omega)} )
	\|\Pi_h\bs^h -  \bs_h\|_{L^2(\Omega)}
	\nn \\
	\textrm{(by inverse inquality)} \quad
	& \quad + Ch^{ -\frac{1}{2} } \| g^h - g\|_{L^2(\Gamma)}
	\|(\Pi_h\bs^h-\bs_h) \cdot
	\bn\|_{H^{-\frac{1}{2}}(\Gamma)}
	\nn \\
	& \le C \|\bs^h\|_{\bH(\D)}
	\|\Pi_h\bs^h - \bs_h\|_{L^2(\Omega)}
	+ Ch^{-\frac{1}{2}} \|g\|_{L^2(\Gamma)} \| \Pi_h\bs^h - \bs_h\|_{\bH(\D)}
	\nn \\
	\textrm{(by \refe{mixedFEM-standard-estimate})} \quad
	& \le C( h^{-\frac{1}{2}}  \|g\|_{L^2(\Gamma)} + \|f\|_{L^2(\Omega)} +\|g^h\|_{H^{\frac{1}{2}}(\Gamma)})
	\| \Pi_h\bs^h - \bs_h\|_{L^2(\Omega)}\,,
	\nn
\end{align}
which, by using an inverse inequality for $g^h$, leads to the result below
\begin{align}
	\|\Pi_h\bs^h - \bs_h\|_{L^2(\Omega)}  \le C( h^{-\frac{1}{2}}  \|g\|_{L^2(\Gamma)} + \|f\|_{L^2(\Omega)}).
	\label{final-sigma-error}
\end{align}
From \refe{RTNp-error}, we see that the quasi-projection estimate holds
\begin{eqnarray}
	\|\Pi_h\bs^h - \bs^h\|_{L^2(\Omega)} & \le & C\|\bs^h\|_{L^2(\Omega)}+Ch\|\D \, \bs^h\|_{L^2(\Omega)}
	\nn
	\\
	& \le & C (\|g^h\|_{H^{\frac{1}{2}}(\Gamma)}+\|f\|_{L^2(\Omega)})+Ch\|f\|_{L^2(\Omega)}
	\nn
	\\
	& \le & C h^{-\frac{1}{2}}\|g\|_{L^2(\Gamma)} + C\|f\|_{L^2(\Omega)}.
	\label{quasi-projection-sigma-error}
\end{eqnarray}

By combining estimate \refe{final-sigma-error}
and projection estimate \refe{quasi-projection-sigma-error},
the error estimate \refe{error-sigma} is proved.
\qed



Next, we turn to prove the main error estimate \refe{main-error-estimate-u} for $u_h$.

{\noindent \bf Proof.}
Notice that
\begin{align}
	\|u-u_h\|_{L^2(\Omega)} \le \|u-u^h\|_{L^2(\Omega)}  + \|u^h - \P_h u^h\|_{L^2(\Omega)}
	+ \|\P_h u^h - u_h\|_{L^2(\Omega)}\,.
\end{align}
Clearly, we only need to estimate the last term.
To this end, we introduce a dual Poisson's equation with a homogeneous Dirichlet boundary condition,
\begin{empheq}[left=\empheqlbrace]{align}
	& - \Delta z = \P_h u^h - u_h \,, && \textrm{in} ~ \Omega\,,
	\\ \nn
	& z =0\,,  && \textrm{on}~  \partial \Omega \,.
\end{empheq}
By introducing  $\bm{\omega}= \nabla z$ as an extra variable,
the mixed FEM for the above equation is to seek $(\bm{\omega}_h, z_h) \in \RT_{\! \! 0} \times \DG_{\! 0}$
such that
\begin{empheq}[left=\empheqlbrace]{align}
	& (\bm{\omega}_h, \bm{\nu}_h ) + (z_h, \D \bm{\nu}_h ) = 0 \,,
	&& \forall \bm{\nu}_h \in \RT_{\! \! 0}\,,
	\\
	& -(\D \bm{\omega}_h,  v_h ) = (\P_h u^h - u_h, v_h)\,,
	&& \forall v_h \in \DG_{\! 0} \,.
	\label{error-standard-proof}
\end{empheq}
By the standard error estimate of mixed FEMs for elliptic equation \cite{Ern-Gudi}, there holds
\begin{empheq}[left=\empheqlbrace]{align}
	\label{standard-mixed-fems-error}
	& \|\nabla z -\bm{\omega}_h\|_{L^2(\Omega)} \le
	C \left( h^s \|\bm{\omega}\|_{\bH^s(\Omega)} + h \|\D \bm{\omega}\|_{L^2(\Omega)} \right) \le C h^s \|\P_h u - u_h\|_{L^2(\Omega)} \,,
	\nn \\
	& \| \Pi_h \nabla z - \bm{\omega}_h \|_{L^2(\Omega)} \le C h^s \, \| \P_h u^h - u_h \|_{L^2(\Omega)} \,,
	\\
	& \| z-z_h \|_{L^2(\Omega)} \le C h\| \P_h u - u_h\|_{L^2(\Omega)}\,.
	\nn
\end{empheq}
By taking $v_h=\P_h u^h - u_h$ into \refe{error-standard-proof}, we can see that
the $L^2$-norm of $\P_h u^h - u_h$ satisfies
\begin{align}
	\label{error-u}
	\|\P_h u^h - u_h\|_{L^2(\Omega)}^2
	& = -(\D \bm{\omega}_h ,\P_h u^h - u_h)
	\nn                                                                                       \\
	\textrm{(by \refe{error1})} \quad
	& =  \langle g-g^h, \bm{\omega}_{h} \cdot \bn \rangle  + (\bs^h - \bs_h , \bm{\omega}_h)
	\nn                                                                                       \\
	& = \mathcal{J}_1 + \mathcal{J}_2\,.
\end{align}
By using the trace inequality in Corollary \ref{trace-lemma},
the projector error for the normal trace \refe{RT-projection-error-boundary}
and the inverse inequality \refe{RT-element-boundness-boundary},
the term $\mathcal{J}_1$ can be bounded by
\begin{align}
	\label{error-J1}
	\left| \mathcal{J}_1 \right|
	& = \left| \langle g-g^h, (\bm{\omega}_{h}- \Pi_h \nabla z) \cdot \bn \rangle
	+ \langle g-g^h, (\Pi_h \nabla z - \nabla z) \cdot \bn \rangle
	+ \langle g-g^h, \nabla z \cdot \bn  \rangle  \right|
	\nn
	\\[3.5pt]
	& \le \|g-g^h\|_{L^2(\Gamma)} \|(\bm{\omega}_{h}- \Pi_h \nabla z) \cdot \bn \|_{L^2(\Gamma)}
	+ \|g-g^h\|_{L^2(\Gamma)} \|( \Pi_h \nabla z - \nabla z )
	\cdot \bn \|_{L^2(\Gamma)}
	\nn
	\\[3.5pt]
	& \quad + \|g-g^h\|_{H^{-(s-\frac{1}{2})}(\Gamma)} \|\nabla z \cdot \bn \|_{H^{(s-\frac{1}{2})}(\Gamma)}
	\nn \\
	& \le C h^{-\frac{1}{2}}\|(\bm{\omega}_{h}- \Pi_h \nabla z) \|_{L^2(\Omega)} \|g\|_{L^2(\Gamma)}
	+ C h^{s-\frac{1}{2}} \|\nabla z\|_{H^{s-\frac{1}{2}}(\Gamma)} \|g\|_{L^2(\Gamma)}
	\nn \\
	&  \quad
	+ C h^{s-\frac{1}{2}} \|g\|_{L^2(\Gamma)} \| z\|_{H^{s+1}(\Omega)}
	\nn \\
	& \le   C h^{s-\frac{1}{2}} \|\P_h u^h  -u_h\|_{L^2(\Omega)}  \|g\|_{L^2(\Gamma)}
	+ C h^{s-\frac{1}{2}} \|\nabla z\|_{H^{s}(\Omega)} \|g\|_{L^2(\Gamma)}
	\nn \\
	&  \quad
	+ C h^{s-\frac{1}{2}} \|g\|_{L^2(\Gamma)} \| z\|_{H^{s+1}(\Omega)}
	\nn \\
	& \le C h^{s-\frac{1}{2}} \|g\|_{L^2(\Gamma)}
	\|\P_h u^h -u_h\|_{L^2(\Omega)} \, .
\end{align}
By the standard error estimate \refe{standard-mixed-fems-error}, the term $\mathcal{J}_2$
can be bounded by
\begin{align}
	\label{error-J2}
	\left| \mathcal{J}_2 \right|
	& \le |(\bs^h  -\bs_h , \bm{\omega}_h - \nabla z)| + |(\bs^h-\bs_h , \nabla z  )|
	\nn \\
	\textrm{(by \textrm{\refe{error2}})} \quad
	& = |(\bs^h  -\bs_h , \bm{\omega}_h - \nabla z) | + |(\D(\bs^h - \bs_h) , z - \P_h z)|
	\nn \\[3.5pt]
	& \le \|\bs^h-\bs_h\|_{L^2(\Omega)} \|\bm{\omega}_h - \nabla z\|_{L^2(\Omega)}
	+ \|\D(\bs^h - \bs_h)\|_{L^2(\Omega)} \| z - \P_h z\|_{L^2(\Omega)}
	\nn \\[3.5pt]
	\textrm{(by \refe{error-sigma} and \refe{standard-mixed-fems-error})} \quad
	& \le  C h^s  \left(h^{-\frac{1}{2}}\|g\|_{L^2(\Gamma)} + C\|f\|_{L^2(\Omega)} \right)
	\|\P_h u^h - u_h\|_{L^2(\Omega)}
	\nn \\
	& \quad
	+ Ch \|f\|_{L^2(\Omega)} \|z\|_{H^{1}(\Omega) }
	\nn \\
	& \le C\left(h^s\|f\|_{L^2(\Omega)} + h^{s-\frac{1}{2}}\|g\|_{L^2(\Gamma)}   \right)
	\|\P_h u^h - u_h\|_{L^2(\Omega)} \,.
\end{align}
Taking estimates \refe{error-J1} and \refe{error-J2} into \refe{error-u},
the desired estimate follows
\begin{align}
	\label{error-uh-pre}
	\| \P_h u^h - u_h \|_{L^2(\Omega)}
	\le C h^{s- \frac{1}{2}} \|g\|_{L^2(\Gamma)} + C h^s \|f\|_{L^2(\Omega)} \,.
\end{align}

Finally, combining estimates in \refe{error-estimate-u},
\refe{error-auxiliary-uh}, \refe{error-uh-mid} and
\refe{error-uh-pre}, the main results in Theorem \ref{main-theorem} is proved.
\qquad \endproof

