\section{Estimates for problems with more regular boundary data}
\label{more-smooth-data}
\setcounter{equation}{0}

Classical mixed FEM theory covers the case $g \in H^{t}(\Gamma)$ with $t \ge 1/2$.
In this section, we investigate the model problem \refe{pde}-\refe{pde-bc}
with boundary data $g \in H^{t}(\Gamma)$ for $0 < t < 1/2$.
An improved convergence rate can be derived and the
main results for the mixed FEM \refe{mixed-fem1}-\refe{mixed-fem2} are
summarized in the following corollary.

\begin{corollary}
	\label{byproduct-theorem}

	Let $f \in L^2(\Omega)$, $g \in H^t(\Gamma)$ for $0 < t < 1/2$.
	The mixed FEM \refe{mixed-fem1}-\refe{mixed-fem2} admits a unique solution $u_h$
	satisfying the following estimate
	\begin{align}
		\| u_{h} - u \|_{L^2(\Omega)} \le
		C h^{t+s-\frac{1}{2}}\|g\|_{H^t(\Gamma)} + C h^{s} \|f\|_{L^2(\Omega)}\,,
		\label{byproduct-error-estimate-u}
	\end{align}
	where $u$ is the very weak solution.
\end{corollary}

\noindent{\bf Proof.}
The regularized boundary data $g^h$ satisfies
\begin{align}
	\|g - g^h\|_{H^{-s}(\Gamma)} \le C h^{t+s} \|g\|_{H^{t}(\Gamma)}
\end{align}
\textcolor{black}{From \cite[Remark 5.4]{Apel}}, we have an improved estimate for
the regularized solution $u^h$
\color{black}
\begin{align}
	\| u^h- u\|_{L^2(\Omega)}  \le  C h^{t+s-\frac{1}{2}} \|g\|_{H^{t}(\Gamma)}\,.
	\label{regularization-error-improved}
\end{align}
And the projection error satisfies
\begin{eqnarray}
	\|\P_h u^h - u^h\|_{L^2(\Omega)} & \le & C h \|u^h\|_{H^1(\Omega)}
	\nn
	\\
	& \le & C h (\|g^h\|_{H^{\frac{1}{2}}(\Gamma)} + \|f\|_{L^2(\Omega)})
	\nn
	\\
	& \le & C h^{t+\frac{1}{2}}\|g\|_{H^{t}(\Gamma)} + C h \|f\|_{L^2(\Omega)}\,.
	\label{error-uh-mid-byproduct}
\end{eqnarray}

Recall the proof of Lemma \ref{lemma-sigma-eror}, we have
\begin{align}
	\|\Pi_h\bs^h - \bs_h\|^2_{L^2(\Omega)}
	& \le C (\|\bs^h\|_{L^2(\Omega)} + h \|\D \bs^h\|_{L^2(\Omega)} )
	\|\Pi_h\bs^h -  \bs_h\|_{L^2(\Omega)}
	\nn                                                                     \\
	& \quad + Ch^{ t-\frac{1}{2} } \|g\|_{H^t(\Gamma)}
	\|(\Pi_h\bs^h-\bs_h) \cdot
	\bn\|_{H^{-\frac{1}{2}}(\Gamma)} 
	\nn                                                                     \\
	& \le C( h^{t-\frac{1}{2}}  \|g\|_{H^t(\Gamma)} + \|f\|_{L^2(\Omega)}) 
	\|\Pi_h\bs^h - \bs_h\|_{L^2(\Omega)}\,.
	\label{final-sigma-errorbyproduct}
\end{align}
and the quasi projection estimate
\begin{eqnarray}
	\|\Pi_h\bs^h - \bs^h\|_{L^2(\Omega)} & \le &  C \|g^h\|_{H^{\frac{1}{2}}(\Gamma)} + C\|f\|_{L^2(\Omega)}
	\nn
	\\
	& \le & C h^{t-\frac{1}{2}}\|g\|_{H^t(\Gamma)} + C\|f\|_{L^2(\Omega)}\,.
	\label{quasi-projection-sigma-error-pbyproduct}
\end{eqnarray}
An improved estimate for $\bs_h$ follows directly
\begin{align}
	\label{error-sigma-improved}
	\| \bs^h - \bs_h\|_{L^2(\Omega)} \le C( h^{t-\frac{1}{2}} \|g\|_{H^t(\Gamma)} + \|f\|_{L^2(\Omega)})\,.
\end{align}

Then, from \refe{error-u} the error  $\|\P_h u^h - u_h\|_{L^2(\Omega)}$ satisfies
\begin{align}
	\label{error-u-improved}
	\|\P_h u^h - u_h\|_{L^2(\Omega)}^2
	& = -(\D \bm{\omega}_h ,\P_h u^h - u_h)
	\nn                                                                                      \\
	\textrm{(by \refe{error1})} \quad
	& =  \langle g-g^h, \bm{\omega}_{h} \cdot \bn \rangle  -(\bs^h - \bs_h , \bm{\omega}_h)
	\nn                                                                                      \\
	& = \mathcal{J}_3 + \mathcal{J}_4\,,
\end{align}
where $\mathcal{J}_3$ can be bounded by
\begin{align}
	\label{error-J3}
	\left| \mathcal{J}_3 \right|
	& \le \|g-g^h\|_{L^2(\Gamma)} \|(\bm{\omega}_{h}- \Pi_h \nabla z) \cdot \bn \|_{L^2(\Gamma)}
	+ \|g-g^h\|_{L^2(\Gamma)} \|( \Pi_h \nabla z - \nabla z )
	\cdot \bn \|_{L^2(\Gamma)}
	\nn                                                                                                     \\[3.5pt]
	& \quad + \|g-g^h\|_{H^{-(s-\frac{1}{2})}(\Gamma)} \|\nabla z \cdot \bn \|_{H^{s-\frac{1}{2}}(\Gamma)}
	\nn                                                                                                     \\
	& \le C h^{t-\frac{1}{2}}\|(\bm{\omega}_{h}- \Pi_h \nabla z) \|_{L^2(\Omega)} \|g\|_{H^t(\Gamma)}
	+ C h^{t+s-\frac{1}{2}} \|\nabla z\|_{H^{s-\frac{1}{2}}(\Gamma)} \|g\|_{H^s(\Gamma)}
	\nn                                                                                                     \\[3.5pt]
	& \quad + C h^{t+s-\frac{1}{2}} \|g\|_{H^t(\Gamma)} \| z\|_{H^{s+1}(\Omega)}
	\nn                                                                                                     \\
	& \le C  h^{t+s-\frac{1}{2}}\|g\|_{H^{t}(\Gamma)}
	\|\P_h u^h -u_h\|_{L^2(\Omega)},
\end{align}
and $\mathcal{J}_4$ can be bounded by
\begin{align}
	\label{error-J4}
	\left| \mathcal{J}_4 \right|
	& \le \|\bs^h-\bs_h\|_{L^2(\Omega)} \|\bm{\omega}_h - \nabla z\|_{L^2(\Omega)}
	+ \|\D(\bs^h - \bs_h)\|_{L^2(\Omega)} \| z - \P_h z\|_{L^2(\Omega)}
	\nn                                                                                      \\[3.5pt]
	\textrm{(by \refe{error-sigma-improved} and \refe{standard-mixed-fems-error})} \quad
	& \le  C h^s  \left(h^{t-\frac{1}{2}}\|g\|_{H^t(\Gamma)} + \|f\|_{L^2(\Omega)} \right)
	\|\P_h u^h - u_h\|_{L^2(\Omega)}
	\nn
	\\
	& \quad  + Ch \|f\|_{L^2(\Omega)} \|z\|_{H^{1}(\Omega) }
	\nn                                                                                      \\
	& \le C\left(h^{t+s-\frac{1}{2}}\|g\|_{H^t(\Gamma)} + h^s\|f\|_{L^2(\Omega)} \right)
	\|\P_h u^h - u_h\|_{L^2(\Omega)} \,.
\end{align}
Taking the above two estimates into \refe{error-u-improved} yields an improved estimate
\begin{align}
	\|\P_h u^h - u_h\|_{L^2(\Omega)} \le
	C\left( h^{t+s-\frac{1}{2}}\|g\|_{H^t(\Gamma)} + h^s\|f\|_{L^2(\Omega)}  \right).
\end{align}
At last, combining the above estimates
with \refe{regularization-error-improved} and  \refe{error-uh-mid-byproduct},
Corollary \ref{byproduct-theorem} is proved.
\quad \endproof

