The following Lemma is trivial from the definition of $\mathrm{Ei}(z)$.
\begin{lemma}
\begin{align}
\frac{\diff}{\diff z} \mathrm{Ei}(z) = \frac{\exp(z)}{z}
\label{eq:diffEi}
\end{align}
\end{lemma}
Hereinafter, we use the following symbol, $\lambda_2$, to simplify the notation.
\begin{dfn}
\begin{align}
& \lmb \defeq \frac{1}{2(1-z_2)} \label{eq:lmbdef}\\
& \de \defeq z_2 - z_1 \label{eq:dedef}
\end{align}
\end{dfn}

\begin{dfn}
\begin{align}
& g_0(p ; b)  \defeq 1 + \frac{2}{ (3 - z_1 - 2 z_2 - b) } \exp\left(-\lmb(b-p)\right) \\
& \begin{aligned} 
    g_\pi(p; b) \defeq &
    \; { \frac{2\lmb}{ p+\de} } 
    - \frac{2\lmb}{ (b+\de) } \frac{(1-z_1-b)}{ (3 - z_1 - 2 z_2 - b) } \exp\left(-\lmb(b-p)\right) \cr
    & {} - 2 \lmb^2 \exp\left(\lmb(p+\de)\right) 
    \Bigl( \mathrm{Ei}\left( -\lmb (b + \de ) \right) - \mathrm{Ei}\left( -\lmb(p+\de)\right) \Bigr) 
    \end{aligned} \\
& g(p ; b, \pi)  \defeq  g_0(p; b) - \pi \, g_\pi(p; b) \\
& \begin{aligned}
    h(p ; a)  \defeq &
    \;   4 \lmb \exp\left( -\lmb(p-a)\right)  - \frac{ 4\lmb (a-\de) }{ (p-\de) } \cr
    & {} + 4 \lmb^2 (a-\de) \exp\left(-\lmb(p-\de)\right) 
    \Bigl( \mathrm{Ei}\left( \lmb (p - \de ) \right) - \mathrm{Ei}\left( \lmb(a-\de)\right) \Bigr)
    \end{aligned} 
\end{align}
\end{dfn}
\noindent
Here, the symbol $g(p; b,\pi)$  is defined as a function of $p$ that contains $b$ and $\pi$ as parameters.
Similarly, the symbol $h(p; a)$ is a function of $p$ that contains $a$ as a parameter.
Then, straightforward calculation shows the following properties.
\begin{lemma}
\begin{align}
& g(p; b, \pi) - \frac{1}{\lmb} \frac{\diff}{\diff p} g(p; b, \pi)  = 1 - \frac{ 2 \pi } { (p+\de)^2 } \label{eq:gdiff} \\
& g(b; b, \pi ) = \frac{ 1 }{(3-z_1-2z_2-b)}
\left( \left( 5-z_1-2z_2-b \right)
- \frac{2\pi}{(b+\de)}
\right)
\label{eq:gbb} \\
& h(p; a) + \frac{1}{\lmb} \frac{\diff}{\diff p} h(p; a)  =  \frac{ 4(a-\de) } { (p-\de)^2 } \label{eq:hdiff}\\
& h(a; a) = 0 \label{eq:haa0}
\end{align}
\end{lemma}

