\subsection{Mixed Strategy Equilibrium $1$}

Suppose the location pair $(z_1,z_2)$ is in the range satisfying the following.
\begin{align}
& z_1 \le 1/2 \label{eq:rgn1a} \\
& z_1+z_2 \ge 1 \label{eq:rgn1b} \\
& \left( 1-z_1 \right) \left( \frac{1}{2} + z_1 + z_2 \right) < 2z_1 \label{eq:rgn1c}
\end{align}
Suppose the following equation for $w$ has a positive solution $w>0$.
\begin{align}
\frac{1}{ 2 \lmb } h(z_2; z_2-w) + z_1 + z_2 + \frac{1}{2} - \frac{ 2w }{ z_1 } = \frac{ 2 (z_1-w) }{ (1-z_1) }
\label{eq:defw1}
\end{align}
We further require that the location pair $(z_1,z_2)$ satisfies the following inequality. 
\begin{align}
& 2 - \frac{w}{2} - \left( \frac{3}{2} - z_2 \right) g_0(z_1; z_1) \cr
&{} + \left( \frac{w}{z_2(z_2-w)} + \left( \frac{3}{2} - z_2 \right) g_\pi (z_1; z_1) - \frac{1}{(1-z_2)} \right) 
\frac{ g_0(z_1-w;z_1) }{ g_\pi(z_1-w;z_1) } \leq 0
\label{eq:condw1}
\end{align}


\begin{prop}[Mixed Strategy Equilibrium $1$]\label{thm:sol1}

Suppose that the location pair $(z_1,z_2)$ is inside of the region given by \Eq{eq:rgn1a}--(\ref{eq:rgn1c}), and that \Eq{eq:defw1} has a solution $w$ that satisfies the inequality \Eq{eq:condw1}
Then, the mixed strategy given by the following cumulative distribution function is an equilibrium,
\begin{align}
&F_1^\star(p_1) =
\begin{dcases*}
0 & (for $p_1\le z_1-w$) \\
g(p_1; z_1, \pi_2^\star)
& (for $z_1-w \le p_1 \le z_1$ ) \\
g(z_1; z_1, \pi_2^\star) & (for $z_1 \le p_1 < 1-z_1$ ) \\
1 & (for $p_1 > 1-z_1$ )
\end{dcases*} \label{eq:F1sol1}\\
\vspace{2\baselineskip}\cr
&F_2^\star(p_2) =
\begin{dcases*}
0 & (for $p_2\le z_2-w$) \\
h(p_2; z_2-w) 
& (for $z_2-w \le p_2 < z_2$ ) \\
1 & (for $p_2 > z_2$ )
\end{dcases*} \label{eq:F2sol1}
\end{align}
with the equilibrium profits given by the following.
\begin{align}
& \pi_1^\star = 2(z_1-w) 
\label{eq:pi1e1} \\
& \pi_2^\star = \frac{ g_0(z_1-w;z_1) }{ g_\pi(z_1-w;z_1) } 
\label{eq:pi2e1}
\end{align}
\end{prop}

The supports of these distributions are as follows.
\begin{align}
& \mathrm{supp} \  F_1^\star = [z_1-w, z_1] \cup \{ 1-z_1 \} \label{eq:supp1sol1} \\
& \mathrm{supp} \  F_2^\star = [z_2-w, z_2] \label{eq:supp2sol1}
\end{align}
The distribution $F_1$ of Firm $1$ is continuous at $p_1 = z_1-w$, as ensured by \Eq{eq:pi2e1}, and at $p_1=z_1$ as trivially seen from \Eq{eq:F1sol1}. It has an atom at $p_1=1-z_1$. The distribution $F_2$ of Firm $2$ is continuous at $p_2=z_2-w$ due to \Eq{eq:haa0}. It has an atom at $p_2=z_2$.

The expected profit $\mathrm{E}[\pi_i](p_i)$ of Firm $i$ when it chooses a price $p_i$ is given by the following integration over the price distribution of its counterpart.
\begin{align}
& \mathrm{E}[\pi_1](p_1) = p_1 \left( 1 + \int_{p_1-\de}^{p_1+\de} \frac{ z_1+z_2-p_1+p_2}{2} \diff F_2^\star(p_2) + \left( 1 - F_2^\star(p_1+\de) \right)  \right) \label{eq:expect1} \\
& \mathrm{E}[\pi_2](p_2) = p_2 \left( 1 + \int_{p_2-\de}^{p_2+\de} \frac{ z_1+z_2+p_1-p_2}{2} \diff F_1^\star(p_1) + \left( 1 - F_1^\star(p_2+\de) \right)  \right) \label{eq:expect2}
\end{align}
That $\mathrm{E}[\pi_1](p_1) = \pi_1^\star$ for $z_1-w\leq p_1 \leq z_1$ can be proved by using \Eq{eq:hdiff}. That $\mathrm{E}[\pi_1](p_1) = \pi_1^\star$ for $p_1 = 1 - z_1$ is ensured owing to \Eq{eq:defw1}. That $\mathrm{E}[\pi_2](p_2) = \pi_2^\star$ for $z_2-w\leq p_2 \leq z_2$ can be proved by using \Eq{eq:gdiff}. Finally, \Eq{eq:condw1} ensures that $\mathrm{E}[\pi_2](1-z_2) < \pi_2^\star$ so that Firm 2 has no incentive to choose the price $1-z_2$, which is outside the support given by \Eq{eq:supp2sol1}. This completes the proof that the probability distributions given by \Eq{eq:F1sol1} and \Eq{eq:F2sol1} are a price equilibrium. See Appendix~\ref{Mix1proof} for details of the proofs.

Note that for the Proposition~\ref{thm:sol1} to hold, not only must $(z_1,z_2)$ be in the range of equation \Eq{eq:rgn1a}--\Eq{eq:rgn1c}, but the condition in equation \Eq{eq:condw1} must hold. The numerical solution of $(z_1,z_2)$ where Proposition~\ref{thm:sol1} holds is shown in Figure~\ref{fig:regions}. 

