\subsection{Mixed Strategy Equilibrium $2$}

Here, we suppose that the location pair $(z_1,z_2)$ is in the following range.
\begin{align}
& 1/2 \le z_1 < z_2 \label{eq:rgn2a} \\
& \left( 1-2z_1+z_2 \right) \left( 2 - z_2 \right) > z_2 \label{eq:rgn2b}
\end{align}
And suppose the following equation for $w$ has a positive solution $w>0$.
\begin{align}
h(1-2z_1+z_2; 1-2z_1+z_2-w) = 1
\label{eq:defw2}
\end{align}
We further restrict the range of $(z_1,z_2)$ so that the following two inequalities are satisfied. 
\begin{align}
& \left(z_1 - (1-z_2)(z_2-z_1)  + \frac{(1-z_2)w}{2} \right) \cr
& {} \ge  \left( \frac{z_1}{(1-2z_1+z_2)} + \frac{(1-z_2)}{(1-2z_1+z_2-w)} - 1\right)  
\frac{ g_0( 1-z_1-w; 1-z_1) }{ g_\pi( 1-z_1-w; 1-z_1) }
\label{eq:condw2a} \\
& \frac{ g_0( 1-z_1-w; 1-z_1) }{ g_\pi( 1-z_1-w; 1-z_1) } \geq z_2 
\label{eq:condw2b}
\end{align}

\begin{prop}[Mixed Strategy Equilibrium $2$]\label{thm:sol2}
Suppose that the location pair $(z_1,z_2)$ is inside of the region given by \Eq{eq:rgn2a}--(\ref{eq:rgn2b}), and that \Eq{eq:defw2} has a solution $w$ that satisfies the inequality \Eq{eq:condw2a} and \Eq{eq:condw2b}.
Then, the mixed strategy given by the following cumulative distribution function is an equilibrium,
\begin{align}
&F_1^\star(p_1) =
\begin{dcases*}
0 & (for $p_1\le 1-z_1-w$) \\
g(p_1; 1-z_1, \pi_2^\star)
& (for $1-z_1-w \le p_1 < 1-z_1$ ) \\
1 & (for $p_1 > 1-z_1$ )
\end{dcases*} \label{eq:F1sol2}\\
\vspace{2\baselineskip}\cr
&F_2^\star(p_2) =
\begin{dcases*}
0 & (for $p_2\le 1 - 2z_1 + z_2-w$) \\
h(p_2; 1-2z_1+z_2-w)
& (for $1-2z_1+z_2-w \le p_2 \le 1-2z_1+z_2$ ) \\
1 & (for $p_2 \ge 1-2z_1+z_2 $ )
\end{dcases*} \label{eq:F2sol2}
\end{align}
with the equilibrium profits given by the following.
\begin{align}
& \pi_1^\star = 2(1 - z_1-w) 
\label{eq:pi1e2} \\
& \pi_2^\star = \frac{ g_0( 1-z_1-w; 1-z_1) }{ g_\pi( 1-z_1-w; 1-z_1) }
\label{eq:pi2e2}
\end{align}
\end{prop}

The supports of $F_1^\star$ and $F_2^\star$ are $1-z_1-w\leq p_1 \leq 1-z_1$ and $1-2z_1+z_2-w \leq p_2 \leq 1-2z_1+z_2$, respectively.
The distribution $F_1^\star$ of Firm 1 is continuous at $p_1 = 1-z_1-w$, as ensured by \Eq{eq:pi2e2}. It has an atom at $p_1=1-z_1$. The distribution $F_2^\star$ of Firm 2 is continuous at $p_2=1-2z_1+z_2-w$ owing to \Eq{eq:haa0}, and at  $p_2=1-2z_1+z_2$ owing to \Eq{eq:defw2}. 

That $\mathrm{E}[\pi_1](p_1) = \pi_1^\star$ for $1-z_1-w\leq p_1 \leq 1-z_1$ can be proved by using \Eq{eq:hdiff}. That $\mathrm{E}[\pi_2](p_2) = \pi_2^\star$ for $z_2-w\leq p_2 \leq z_2$ can be proved by using \Eq{eq:gdiff}. \Eq{eq:condw2b} ensures that $\pi_2^\star \geq z_2$ due to \Eq{eq:pi2e2}, so that Firm 2 has no incentive to choose the price $p_2=z_2$, in which case it can gain only from its fan and the profit would be $z_2$. 
Finally, \Eq{eq:condw2a} ensures that $\mathrm{E}[\pi_2](1-z_2) < \pi_2^\star$ so that Firm 2 has no incentive to choose the price lower than $1-z_2$ to win the shoppers against Firm 1. This completes the proof that the probability distributions given by \Eq{eq:F1sol2} and \Eq{eq:F2sol2} are a price equilibrium.  See Appendix~\ref{Mix2proof} for details of the proofs.

Note that for the Proposition~\ref{thm:sol2} to hold, not only must $(z_1,z_2)$ be in the range of equation \Eq{eq:rgn2a}--\Eq{eq:rgn2b}, but the condition in both equation \Eq{eq:condw2a} and \Eq{eq:condw2b} must hold. The numerical solution of $(z_1,z_2)$ where Proposition~\ref{thm:sol2} holds is shown in Figure~\ref{fig:regions}. 
