\subsection{Mixed Strategy Equilibrium $3$}

Suppose the location pair $(z_1,z_2)$ is in the following range.
\begin{align}
& 1/2 \le z_1 < z_2 \label{eq:rgn3a} \\
& \left( 1-2z_1+z_2 \right) \left( 2 - z_2 \right) > z_2 \label{eq:rgn3b}
\end{align}
Suppose the following equation for $w$ has a positive solution $w>0$.
\begin{align}
g_0(1-z_1-w; 1-z_1) - z_2 \, g_\pi(1-z_1-w; 1-z_1) = 0
\label{eq:defw3}
\end{align}
We further restrict the range of $(z_1,z_2)$ so that the following two inequalities are satisfied. 
\begin{align}
& 
h(1-2z_1+z_2; 1-2z_1+z_2-w) \leq 1
\label{eq:condw3a} \\
& 
(z_2-z_1)z_2 + 2z_1
+ \frac{(1-z_2)w}{2} - \frac{z_1z_2}{( 1-2z_1+z_2 )} - \frac{(1-z_2)z_2}{  (1-2z_1+z_2-w) }
\geq 0
\label{eq:condw3b}  
\end{align}


\begin{prop}[Mixed Strategy Equilibrium $3$]\label{thm:sol3}

Suppose that the location pair $(z_1,z_2)$ is inside of the region given by \Eq{eq:rgn3a}--(\ref{eq:rgn3b}), and that \Eq{eq:defw3} has a solution $w$ that satisfies the inequality \Eq{eq:condw3a} and \Eq{eq:condw3b}.
Then, the mixed strategy given by the following cumulative distribution function is an equilibrium,
\begin{align}
&F_1^\star(p_1) =
\begin{dcases*}
0 & (for $p_1\le 1-z_1-w$) \\
g(p_1; 1-z_1, \pi_2^\star)
& (for $1-z_1-w \le p_1 < 1-z_1$ ) \\
1 & (for $p_1 > 1-z_1$ )
\end{dcases*} \label{eq:F1sol3}\\
\vspace{2\baselineskip}\cr
&F_2^\star(p_2) =
\begin{dcases*}
0 & (for $p_2\le 1 - 2z_1 + z_2-w$) \\
h(p_2; 1-2z_1+z_2-w)
& (for $1-2z_1+z_2-w \le p_2 \le 1-2z_1+z_2$ ) \\
h(1-2z_1+z_2; 1-2z_1+z_2-w)
& (for $1-2z_1+z_2 \le p_2 < z_2  $ ) \\
1 & (for $p_2 > z_2 $ )
\end{dcases*} \label{eq:F2sol3}
\end{align}
with the equilibrium profits given by the following.
\begin{align}
& \pi_1^\star = 2(1-z_1-w) 
\label{eq:pi1e3} \\
& \pi_2^\star = z_2
\label{eq:pi2e3}
\end{align}
\end{prop}


The supports of these distributions are as follows.
\begin{align}
& \mathrm{supp} \  F_1^\star = [1-z_1-w, 1-z_1] \label{eq:supp1sol3} \\
& \mathrm{supp} \  F_2^\star = [1-2z_1+z_2-w, 1-2z_1+z_2]  \cup \{ z_2 \} \label{eq:supp2sol3}
\end{align}
The distribution $F_1^\star$ of Firm 1 is continuous at $p_1 = 1 - z_1-w$, as ensured by \Eq{eq:defw3}. It has an atom at $p_1=1-z_1$. The distribution $F_2^\star$ of Firm 2 is continuous at $p_2=1-2z_1+z_2-w$ due to \Eq{eq:haa0}, and at $p_2=1-2z_1+z_2$ as trivially seen from \Eq{eq:F2sol3}. It has an atom at $p_2=z_2$.

That $\mathrm{E}[\pi_1](p_1) = \pi_1^\star$ for $1-z_1-w\leq p_1 \leq 1-z_1$ can be proved by using \Eq{eq:hdiff}. That $\mathrm{E}[\pi_2](p_2) = \pi_2^\star$ for $1-2z_1+z_2-w\leq p_2 \leq 1-2z_1+z_2$ can be proved by using \Eq{eq:gdiff}. That $\mathrm{E}[\pi_2](p_2) = \pi_2^\star$ for $p_2 = z_2$ can be easily proved by noting that the whole support of $F_1$ is contained in $p_1<z_2-\de=z_1$ and therefore Firm 2 can gain only from its fan when $p_2=z_2$. 
Finally, \Eq{eq:condw3a} ensures that $\mathrm{E}[\pi_2](1-z_2) < \pi_2^\star$ so that Firm 2 has no incentive to choose the price lower than $1-z_2$ to win the shoppers against Firm 1. This completes the proof that the probability distributions given by \Eq{eq:F1sol3} and \Eq{eq:F2sol3} are a price equilibrium. See Appendix~\ref{Mix3proof} for details of the proofs.

Note that for the Proposition~\ref{thm:sol3} to hold, not only must $(z_1,z_2)$ be in the range of \Eq{eq:rgn3a}--\Eq{eq:rgn3b}, but the condition in \Eq{eq:condw3a} and \Eq{eq:condw3b} must hold. The numerical solution of $(z_1,z_2)$ where Proposition~\ref{thm:sol3} holds is shown in Figure~\ref{fig:regions}.
