\subsection{Proof for Proposition~\ref{thm:sol1}}\label{Mix1proof}
The following lemmas give the proof of Proposition~\ref{thm:sol1}.
\begin{lemma}
For the probability distribution given by \Eq{eq:F2sol1} and when $z_1-w< p_1 < z_1$,
\begin{align}
\mathrm{E}[\pi_1](p_1) = \pi_1^\star.
\end{align}
\end{lemma}
\begin{proof}
By \Eq{eq:F2sol1}, $F_2(p_2)$ has no atoms in $z_1-w+(z_2-z_1)< p_2 < z_1+(z_2-z_1)$. Therefore, if $z_1-w< p_1 < z_1$, then
\begin{align*}
\mathrm{E}[\pi_1](p_1) ={} & p_1 \left( 1 
+ \int_{z_2-w}^{p_1+\de} \left( \frac{z_1+z_2+p_2-p_1}{2} \right) \diff F_2(p_2) + \left( 1 - F_2\left( p_1+\de \right) \right)
\right) \cr
={} & p_1 \Bigl( 2 - F_2( p_1+\de )
+ \left[\left( \frac{z_1+z_2+p_2-p_1}{2} \right) F_2(p_2) \right]_{z_2-w}^{p_1+\de} - \int_{z_2-w}^{p_1+\de} \frac{1}{2} F_2(p_2) \thinspace \diff p_2 \Bigr) \cr & \quad \text{($\because$ Integration by parts)} \cr
={} & p_1 \left( 2 - (1-z_2) F_2( p_1+\de )
 -  \int_{z_2-w}^{p_1+(z_2-z_1)} \frac{1}{2} h(p_2; z_2-w) \thinspace \diff p_2  
\right) \cr 
={} & p_1 \Biggl( 2 
- (1-z_2) h(p_1+\de; z_2-w) \cr
& \phantom{p_1 \Biggl( } {} - \int_{z_2-w}^{p_1+\de} 
\left(
- \frac{1}{2\lmb} \frac{\diff}{\diff p} h(p_2; z_2-w)  +  \frac{ 2(z_1-w) } { (p-\de)^2 }
\right) \diff p_2  
\Biggr) \  (\because\ \mbox{\Eq{eq:hdiff}}) \cr
={} & p_1 \left( 2 
- (1-z_2) h(p_1+\de; z_2-w) + (1-z_2) h(p_1+\de; z_2-w) + \frac{2(z_1-w)}{ p_1 } - 2
\right) \cr
={} & 2(z_1-w)
\end{align*}
\end{proof}

\begin{lemma}
For the probability distribution given by \Eq{eq:F2sol1} and when $p_1=1-z_1$,
\begin{align}
\mathrm{E}[\pi_1](p_1) = \pi_1^\star.
\end{align}
\end{lemma}
\begin{proof}
By \Eq{eq:F2sol1}, $F_2(p_2)$ has an atom at $p_2=z_2$. Therefore,
\begin{align}
\mathrm{P}[p_2=z_2] = F_2(z_2+0) - F_2(z_2-0) = 1 - h(z_2; z_2-w)
\end{align}
\begin{align}
\mathrm{E}[\pi_1](1-z_1) ={} & (1-z_1) \Biggl( 1 
+ \int_{z_2-w}^{z_2} \left( \frac{z_1+z_2+p_2-(1-z_1)}{2} \right) \diff F_2(p_2) \cr
& \phantom{(1-z_1) \Biggl(} {} + \left( \frac{z_1+z_2+z_2-(1-z_1)}{2} \right) \left( 1 - h(z_2; z_2-w) \right)
\Biggr) \cr
={} & (1-z_1) \Biggl( 1 
+ \left( z_1+z_2 - \frac{1}{2} \right) h(z_2; z_2-w)
- \int_{z_2-w}^{z_2} \frac{1}{2} F_2(p_2) \thinspace \diff p_2 \cr
&\phantom{(1-z_1) \Biggl(} {} + \left( z_1+z_2 - \frac{1}{2} \right) \left( 1 - h(z_2; z_2-w) \right)
\Bigr) \cr
={} & (1-z_1) \left( z_1+z_2 + \frac{1}{2}
- \int_{z_2-w}^{z_2} \left(
- \frac{1}{2\lmb} \frac{\diff}{\diff p} h(p_2; z_2-w)  +  \frac{ 2(z_1-w) } { (p-\de)^2 }
\right) \diff p_2  
\right) \cr
={} & (1-z_1) \left( z_1+z_2 + \frac{1}{2} + 
\frac{1}{2\lambda_2} h(z_2; z_2-w)  
+ \frac{2(z_1-w)}{ z_1 } - 2
\right) \cr
={} & (1-z_1) \left( z_1+z_2 + \frac{1}{2} - \frac{2w}{ z_1 } 
+ \frac{1}{2\lambda_2} h(z_2; z_2-w)  
\right) \label{eq:Epi1p1sh1}
\end{align}
Now, by virtue of \Eq{eq:defw1}, we obtain $\mathrm{E}[\pi_1](1-z_1) =2(z_1-w)$.
\end{proof}

\begin{lemma}
For the probability distribution given by \Eq{eq:F1sol1} and when $z_2-w\le p_2 \le z_2$,
\begin{align}
\mathrm{E}[\pi_2](p_2) = \pi_2^\star.
\end{align}
\end{lemma}
\begin{proof}
By \Eq{eq:F1sol1}, $F_1(p_1)$ has an atom at $p_1=1-z_1$. Therefore,
\begin{align}
\mathrm{P}[p_1=1-z_1] = F_1(1 - z_1 + 0) - F_1(1 - z_1-0) = 1 - g(z_1; z_1, \pi_2^\star)
\end{align}
\begin{align*}
\mathrm{E}[\pi_2](p_2) ={} & p_2 \Biggl(
1 + \int_{p_2-\de}^{z_1} \left(1-\frac{z_1+z_2+p_2-p_1}{2}\right) \diff F_1(p_1) \cr 
&\phantom{p_2 \Biggl(} {}+ \left(1-\frac{z_1+z_2+p_2-(1-z_1)}{2}\right)\left( 1 - g(z_1; z_1, \pi_2^\star) \right)\Biggr) \cr
={} & p_2 \Biggl(
1 + \left(\frac{2-z_2-p_2}{2}\right) F_1(z_1)
- (1-z_2) F_1(p_2-\de) 
- \int_{p_2-\de}^{z_1} \frac{1}{2} F_1(p_1) \thinspace \diff p_1 \cr
&\phantom{p_2 \Biggl(} {} \phantom{p_2\Biggl(} + \left(\frac{3-2z_1-z_2-p_2}{2}\right)
\left( 1 - g(z_1; z_1, \pi_2^\star) \right)
\Biggr) \cr
={} & p_2 \Biggl(
\left(\frac{5-2z_1-z_2-p_2}{2}\right)
+ \left(\frac{-1+2z_1}{2}\right)g(z_1; z_1, \pi_2^\star)
- (1-z_2) g(p_2-\de; z_1, \pi_2^\star) \cr
&\phantom{p_2 \Biggl(} {} - \int_{p_2-\de}^{z_1} \frac{1}{2} g(p_1; z_1, \pi_2^\star) \thinspace \diff p_1 
\Biggr) \cr
={} & p_2 \Biggl( 
\left( \frac{5-2z_1-z_2-p_2}{2}\right)
+ \left(\frac{-1+2z_1}{2}\right) g(z_1; z_1, \pi_2^\star)
- (1-z_2) g(p_2-\de; z_1, \pi_2^\star)  \cr
& \phantom{p_2\Biggl(}
- \int_{p_2-\de}^{z_1} \left( 
\frac{1}{2\lambda_2} \frac{\diff}{\diff p_1} g(p_1; z_1, \pi_2^\star)
+ \frac{1}{2} - \frac{\pi_2^\star}{ (p_1+\de)^2 }   \right) \thinspace \diff p_1 
\Biggr) \ (\because\ \mbox{\Eq{eq:gdiff}}) \cr
={} & p_2 \left( \frac{5}{2} - z_1 - z_2 
+ \left( z_1 + z_2 - \frac{3}{2} \right) g(z_1; z_1, \pi_2^\star) 
- \frac{\pi_2^\star}{z_2} + \frac{\pi_2^\star}{p_2} \right) \cr
={} & \pi_2^\star \ (\because\ \mbox{\Eq{eq:gbb}})
\end{align*}
\end{proof}

\begin{lemma}
For the probability distribution given by \Eq{eq:F1sol1} and when $p_2 = 1 - z_2$,
\begin{align}
\mathrm{E}[\pi_2](p_2-0) \leq \pi_2^\star. \label{eq:pi2bndM1}
\end{align}
\end{lemma}
\begin{proof}
\begin{align*}
\mathrm{E}[\pi_2](1-z_2-0) = & (1-z_2) 
 \left( 1 + \int_{z_1-w}^{z_1} \left(1-\frac{z_1+1-p_1}{2}\right) \diff F_1(p_1)  
 + \left( 1 - g(z_1;z_1,\pi_2^\star) \right)
 \right) \cr
 ={} &  (1-z_2) \left( 1 + \frac{1}{2} F_1(z_1) - \int_{z_1-w}^{z_1} \frac{1}{2} F_1(p_1) \thinspace \diff p_1 
 + \left( 1 - g(z_1;z_1,\pi_2^\star) \right)
 \right) \cr
 ={} &  (1-z_2) \left( 2 - \frac{1}{2} g(z_1;z_1,\pi_2^\star) - \int_{z_1-w}^{z_1} \frac{1}{2} g(p_1;z_1,\pi_2^\star) \thinspace \diff p_1 
 \right) \cr
 ={} &  (1-z_2) \Biggl( 2 - \frac{1}{2} g(z_1;z_1,\pi_2^\star) \cr
&\phantom{(1-z_2) \Biggl(} {} - \int_{z_1-w}^{z_1} \left( \frac{1}{2\lambda_2} \frac{\diff}{\diff p_1} g(p_1; z_1, \pi_2^\star) + \frac{1}{2} - \frac{\pi_2^\star}{ (p_1+\de)^2 }  \right) \thinspace \diff p_1  \Biggr) \cr
 ={} &  (1-z_2) \left( 2 - \left(\frac{3}{2}-z_2\right) g(z_1; z_1, \pi_2^\star) - \frac{w}{2} 
 - \frac{\pi_2^\star}{ z_2 } + \frac{\pi_2^\star}{ (z_2-w) }
 \right) \cr
 ={} &  (1-z_2) \Biggl( 2 - \frac{w}{2} - \left(\frac{3}{2}-z_2\right) g_0(z_1; z_1)  \cr
 & \phantom{(1-z_2) \Biggl(} {} +
 \left( \frac{1}{z_2-w} - \frac{1}{z_2} + \left(\frac{3}{2}-z_2\right) g_\pi(z_1; z_1) \right) \pi_2^\star
 \Biggr) \cr
 \leq {} & (1-z_2) \, \frac{\pi_2^\star}{1-z_2} \ (\because\ \mbox{\Eq{eq:condw1} and \Eq{eq:pi2e1}}) \cr
 = {} & \pi_2^\star
\end{align*}
\end{proof}

Strictly speaking, this is still not sufficient to prove that this price distribution is equilibrium. It is required to satisfy $\mathrm{E}[\pi_2](p_2)\leq \pi_2^\star$ for \emph{all} $p_2$, not only at $p_2=1-z_2$, so that Firm 2 has no incentive to deviate from this strategy. However, numerical verification showed that once \Eq{eq:pi2bndM1} holds, we have $\mathrm{E}[\pi_2](p_2)\leq \pi_2^\star$ for all the other $p_2$.

\subsection{Proof for Proposition~\ref{thm:sol2}}\label{Mix2proof}
The following lemmas give the proof of Proposition~\ref{thm:sol2}.
\begin{lemma}
For the probability distribution given by \Eq{eq:F2sol2} and when $1-z_1-w< p_1 < 1-z_1$,
\begin{align}
\mathrm{E}[\pi_1](p_1) = \pi_1^\star.
\end{align}
\end{lemma}
\begin{proof}
By \Eq{eq:F2sol2}, $F_2^\star(p_2)$ has no atoms in $1-z_1-w+(z_2-z_1)< p_2 < 1-z_1+(z_2-z_1)$. Therefore, when $1-z_1-w< p_1 < 1-z_1$,
\begin{align*}
\mathrm{E}[\pi_1](p_1) ={} & p_1 \left( 1 
+ \int_{1-2z_1+z_2-w}^{p_1+\de} \left( \frac{z_1+z_2+p_2-p_1}{2} \right) \thinspace \diff F_2^\star(p_2) + \left( 1 - F_2\left( p_1+\de \right) \right)
\right) \cr
={} & p_1 \biggl( 1 
+ \left[ \left( \frac{z_1+z_2+p_2-p_1}{2} \right) F_2^\star(p_2) \right]_{1-2z_1+z_2-w}^{p_1+\de} -  \int_{1-2z_1+z_2-w}^{p_1+\de} \frac{1}{2} F_2^\star(p_2) \thinspace \diff p_2 \cr
&\phantom{p_1 \bigg(} {} + 1 - F_2( p_1+\de ) 
\biggr)  \cr &  \text{($\because$ Integration by parts)} \cr
={} & p_1 \left( 2 
- (1-z_2) F_2(p_1+\de) - \int_{1-2z_1+z_2-w}^{p_1+\de} \frac{1}{2} h(p_2; 1-2z_1+z_2-w) \thinspace \diff p_2  ) 
\right) \cr
={} & p_1 \biggl( 2 
- (1-z_2) h(p_1+\de; 1-2z_1+z_2-w) \cr 
& \phantom{p_1 \biggl(} {}- \int_{1-2z_1+z_2-w}^{p_1+\de} 
\left( - \frac{1}{2\lambda_2} \frac{\diff}{\diff p_2} h(p_2; 1-2z_1+z_2-w)
+ \frac{2(1-z_1-w)}{ (p_2-\de)^2 }  \right) \thinspace \diff p_2  
\biggr) \cr & (\because\ \text{\Eq{eq:hdiff}}) \cr
={} & p_1 \biggl( 2 
- (1-z_2) h(p_1+\de; 1-2z_1+z_2-w) \cr 
& \phantom{p_1 \biggl(} {} +
\frac{1}{2\lambda_2} h(p_1+\de; 1-2z_1+z_2-w)
+ \frac{2(1-z_1-w)}{ p_1 } - 2 \biggr) \cr
={} & 2(1-z_1-w) \quad (\because \text{\Eq{eq:lmbdef}})
\end{align*}
\end{proof}


\begin{lemma}
For the probability distribution given by \Eq{eq:F1sol2} and when $1-2z_1+z_2-w < p_2 < 1-2z_1+z_2$,
\begin{align}
\mathrm{E}[\pi_2](p_2) = \pi_2^\star.
\label{eq:pi2const2}
\end{align}
\end{lemma}
\begin{proof}
By \Eq{eq:F1sol2}, $F_1^\star(p_1)$ has an atom at $p_1=1-z_1$. Therefore,
\begin{align}
\mathrm{P}[p_1=1-z_1] = 1 - F_1^\star(1-z_1-0) 
= 1 - g(1-z_1; 1-z_1, \pi_2^\star) 
\label{eq:F1b2}
\end{align}
\begin{align*}
\mathrm{E}[\pi_2](p_2) ={} & p_2 \Biggl(
1 + \int_{p_2-\de}^{1-z_1} \left(1-\frac{z_1+z_2+p_2-p_1}{2}\right) \thinspace \diff F_1^\star(p_1) \cr 
& \phantom{p_2\Biggl(} 
{} + \left(1-\frac{z_1+z_2+p_2-(1-z_1)}{2}\right)
\mathrm{P}[p_1=1-z_1]
\Biggr) \cr
={} & p_2 \Biggl(
1 + \left(\frac{3-2z_1-z_2-p_2}{2}\right) F_1^\star(1-z_1-0)
- (1-z_2) F_1^\star(p_2-\de) \cr 
& \phantom{p_2\Biggl(} 
{} 
- \int_{p_2-\de}^{1-z_1} \frac{1}{2} F_1^\star(p_1) \thinspace \diff p_1 
+ \left(\frac{3-2z_1-z_2-p_2}{2}\right)
\left( 1 - F_1^\star(1-z_1-0) \right)
\Biggr) \cr
={} & p_2 \Biggl(
\left(\frac{5-2z_1-z_2-p_2}{2}\right)
- (1-z_2) F_1^\star(p_2-\de) 
- \int_{p_2-\de}^{1-z_1} \frac{1}{2} F_1^\star(p_1) \thinspace \diff p_1 
\Biggr) \cr
={} & p_2 \Biggl(
\left(\frac{5-2z_1-z_2-p_2}{2}\right)
- (1-z_2) g(p_2-\de; 1-z_1, \pi_2^\star) \cr &
\phantom{p_2 \Biggl(} {} - \int_{p_2-\de}^{1-z_1} \frac{1}{2} g(p_1; 1-z_1, \pi_2^\star) \thinspace \diff p_1 
\Biggr) \cr
={} & p_2 \Biggl(
\left(\frac{5-2z_1-z_2-p_2}{2}\right)
- (1-z_2) g(p_2-\de; 1-z_1, \pi_2^\star) \cr
& \phantom{p_2\Biggl(}
- \int_{p_2-\de}^{1-z_1} \left( \frac{1}{2\lambda_2} \frac{\diff}{\diff p_1} g(p_1; 1-z_1, \pi_2^\star) + \frac{1}{2} - \frac{\pi_2^\star}{ (p_1+\de)^2 }  \right) \thinspace \diff p_1 
\Biggr) \quad (\because \text{\Eq{eq:gdiff}}) \cr
={} & p_2 \Biggl(
\left(\frac{5-2z_1-z_2-p_2}{2}\right)
- (1-z_2) g(p_2-\de; 1-z_1, \pi_2^\star) 
\cr
& \phantom{p_2\Biggl(} {}
- \frac{1}{2\lambda_2} g(1-z_1; 1-z_1, \pi_2^\star)
+ \frac{1}{2\lambda_2} g(p_2-\de; 1-z_1, \pi_2^\star)\cr
& \phantom{p_2\Biggl(} {}
- \frac{(1-z_1-p_2+\de)}{2} - \frac{\pi_2^\star}{ (1-z_1+\de)} +  \frac{\pi_2^\star}{ p_2 }   
\Biggr) \cr
={} & p_2 \left( 2 - z_2 
- \frac{\pi_2^\star}{1-2z_1+z_2} + \frac{\pi_2^\star}{p_2} 
-  \frac{1}{2\lambda_2} g(1-z_1; 1-z_1, \pi_2^\star)
\right) \cr
={} & p_2 \left( 
2 - z_2 
- \frac{\pi_2^\star}{1-2z_1+z_2} + \frac{\pi_2^\star}{p_2} 
- \frac{1}{2} \left( (4-2z_2) - \frac{2\pi_2^\star}{1-z_1+\de}  \right) \right) \quad(\because \text{\Eq{eq:gbb}})\cr
={} & \pi_2^\star
\end{align*}
\end{proof}

\begin{lemma}
For the probability distribution given by \Eq{eq:F1sol2} and when $p_2 = z_2-0$,
\begin{align}
\mathrm{E}[\pi_2](p_2) \leq \pi_2^\star. \label{eq:pi2bndM2a}
\end{align}
\end{lemma}
\begin{proof}
Due to \Eq{eq:F1sol2}, the price $p_1$ of Firm 1 is lower than $1-z_1$ with probability 1. The latter is lower than $z_2-\de$ because of \Eq{eq:dedef} and \Eq{eq:rgn2a}. Therefore, when $p_2=z_2$, Firm 2 gains only from its fan. Then,
\begin{align*}
\mathrm{E}[\pi_2](z_2-0) = z_2 \leq \pi_2^\star,
\end{align*}
owing to \Eq{eq:condw2b} and \Eq{eq:pi2e2}.
\end{proof}

\begin{lemma}
For the probability distribution given by \Eq{eq:F1sol2} and when $p_2 = 1 - z_2 -0$,
\begin{align}
\mathrm{E}[\pi_2](p_2) \leq \pi_2^\star. \label{eq:pi2bndM2b}
\end{align}
\end{lemma}
\begin{proof}
In this case, we have $p_2+\de = 1 - z_1 -0$. Therefore, when Firm 1 chooses $p_1=1-z_1$, Firm 2 gains all of the shoppers. 
\begin{align*}
\mathrm{E}[\pi_2](1-z_2-0) = {} & {} (1-z_2) 
\left( 1 + \int_{1-z_1-w}^{1-z_1} \left(1-\frac{z_1+1-p_1}{2}\right) \diff F_1^\star(p_1) 
+ \left( 1 - F_1^\star(1-z_1-0) \right)
\right) \cr
={} &  (1-z_2) \left( 2 - z_1 F_1^\star(1-z_1-0) - \int_{1-z_1-w}^{1-z_1} \frac{1}{2} F_1^\star(p_1) \thinspace \diff p_1 
\right) \cr
={} &  (1-z_2) \left( 2 - z_1 g(1-z_1; 1-z_1, \pi_2^\star) - \int_{1-z_1-w}^{1-z_1} \frac{1}{2} g(p_1; 1-z_1, \pi_2^\star) \thinspace \diff p_1 
\right) \cr
={} &  (1-z_2) \Biggl( 2 - z_1 g(1-z_1; 1-z_1, \pi_2^\star) 
\cr & \phantom{(1-z_2)\Biggl(} {} 
- \int_{1-z_1-w}^{1-z_1} \left( \frac{1}{2\lambda_2} \frac{\diff}{\diff p_1} g(p_1; 1-z_1, \pi_2^\star) +\frac{1}{2} - \frac{\pi_2^\star}{(p_1+\de)^2} \right) \thinspace \diff p_1 
\Biggr) \cr
={} &  (1-z_2) \Biggl( 2 - \left(1+z_1-z_2\right) g(1-z_1; 1-z_1, \pi_2^\star) - \frac{w}{2}
\cr & \phantom{(1-z_2)\Biggl(} {} 
- \frac{\pi_2^\star}{ (1-2z_1+z_2) } + \frac{\pi_2^\star}{  (1-2z_1+z_2-w) }
\Biggr) \cr
={} &  (1-z_2) \Biggl( 2 - \left(\frac{1+z_1-z_2}{2-2z_2}\right) \left( (4-2z_2) - \frac{2\pi_2^\star}{(1-2z_1+z_2)} \right) - \frac{w}{2}
\cr & \phantom{(1-z_2)\Biggl(} {} 
- \frac{\pi_2^\star}{ (1-2z_1+z_2) } + \frac{\pi_2^\star}{  (1-2z_1+z_2-w) }
\Biggr) \cr
={} &  \left( \frac{z_1}{(1-2z_1+z_2)} + \frac{(1-z_2)}{(1-2z_1+z_2-w)}\right) \pi_2^\star \cr
& - \left(z_1 - (1-z_2)(z_2-z_1)  + \frac{(1-z_2)w}{2} \right) \cr
\leq {} & \pi_2^\star,
\end{align*}
owing to \Eq{eq:condw2a} and \Eq{eq:pi2e2}.
\end{proof}

As was the case for the proof of Proposition~\ref{thm:sol1}, this is strictly not sufficient to prove that this price distribution is equilibrium. It is required to satisfy $\mathrm{E}[\pi_2](p_2)\leq \pi_2^\star$ for \emph{all} $p_2$, not only at $p_2=1-z_2$, so that Firm 2 has no incentive to deviate from this strategy. However, numerical verification showed that once \Eq{eq:pi2bndM2a} and \Eq{eq:pi2bndM2b} hold, we have $\mathrm{E}[\pi_2](p_2)\leq \pi_2^\star$ for all the other $p_2$.

\subsection{Proof for Proposition~\ref{thm:sol3}}\label{Mix3proof}
The following lemmas give the proof of Proposition~\ref{thm:sol3}.
\begin{lemma}
For the probability distribution given by \Eq{eq:F2sol3} and when $1-z_1-w< p_1 < 1-z_1$,
\begin{align}
\mathrm{E}[\pi_1](p_1) = \pi_1^\star
\end{align}
\end{lemma}
\begin{proof}
By \Eq{eq:F2sol3}, $F_2(p_2)$ has no atoms in $1-z_1-w+(z_2-z_1)< p_2 < 1-z_1+(z_2-z_1)$. Therefore, if $1-z_1-w< p_1 < 1-z_1$, then
\begin{align}
\mathrm{E}[\pi_1](p_1) ={} & p_1 \left( 1 
+ \int_{1-2z_1+z_2-w}^{p_1+\de} \left( \frac{z_1+z_2+p_2-p_1}{2} \right) \diff F_2^\star(p_2) + \left( 1 - F_2^\star \left( p_1+\de \right) \right)
\right) \cr
={} & p_1 \Biggl( 1 
+ \left[ \left( \frac{z_1+z_2+p_2-p_1}{2} \right) F_2^\star(p_2) \right]_{1-2z_1+z_2-w}^{p_1+\de} 
\cr & \phantom{p_1 \Biggl(} {}
-  \int_{1-2z_1+z_2-w}^{p_1+\de} \frac{1}{2} F_2^\star(p_2) \thinspace \diff p_2 + 1 - F_2^\star( p_1+\de ) 
\Biggr)  \cr & \text{($\because$ Integration by parts)} \cr
={} & p_1 \left( 1 
+ z_2 F_2^\star(p_1+\de) -  \int_{1-2z_1+z_2-w}^{p_1+\de} \frac{1}{2} F_2^\star(p_2) \thinspace \diff p_2 + 1 - F_2^\star( p_1+\de ) 
\right)\cr
={} & p_1 \biggl( 2 
- (1-z_2) h(p_1+\de; 1-2z_1+z_2-w) 
\cr & \phantom{p_1 \biggl(} {}
- \int_{1-2z_1+z_2-w}^{p_1+\de} \frac{1}{2} h(p_2; 1-2z_1+z_2-w) \thinspace \diff p_2  
\biggr) \cr
={} & p_1 \Biggl( 2 
- (1-z_2) h(p_1+\de; 1-2z_1+z_2-w) 
\cr & \phantom{p_1\Biggl(} {}- \int_{1-2z_1+z_2-w}^{p_1+\de} 
\left( - \frac{1}{2\lambda_2} \frac{\diff}{\diff p_2} h(p_2; 1-2z_1+z_2-w) + \frac{2(1-z_1-w)}{ (p_2-\de)^2 } \right) \thinspace \diff p_2  
\Biggr) 
\cr & \quad (\because \text{\Eq{eq:hdiff}}) \cr
={} & p_1 \Biggl( 2 
- (1-z_2) h(p_1+\de; 1-2z_1+z_2-w) 
\cr & \phantom{p_1 \Biggl(} {}
+ (1-z_2) h(p_1+\de; 1-2z_1+z_2-w)
+ \frac{2(1-z_1-w)}{ p_1 } - 2
\Biggr) \cr
={} & 2(1-z_1-w)
\end{align}
\end{proof}

\begin{lemma}
For the probability distribution given by \Eq{eq:F1sol3} and when $1-2z_1+z_2-w < p_2 < 1-2z_1+z_2$,
\begin{align}
\mathrm{E}[\pi_2](p_2) = \pi_2^\star
\label{eq:pi2const3}
\end{align}
\end{lemma}
\begin{proof}
By \Eq{eq:F1sol3}, $F_1^\star(p_1)$ has an atom at $p_1=1-z_1$. Therefore, by \Eq{eq:gbb} and \Eq{eq:pi2e3}
\begin{align}
\mathrm{P}[p_1=1-z_1] = 1 - F_1^\star(1-z_1-0) 
= 1 - g(1-z_1; 1-z_1, \pi_2^\star) = -2\lambda_2 + \frac{2\lambda_2 z_2 }{1-2z_1+z_2}. 
\label{eq:F1b3}
\end{align}
\begin{align*}
\mathrm{E}[\pi_2](p_2) ={} & p_2 \Biggl( 1 + \int_{p_2-\de}^{1-z_1} \left(1-\frac{z_1+z_2+p_2-p_1}{2}\right) \diff F_1^\star(p_1) 
\cr & \phantom{p_2\Biggl(} {}
+ \left(1-\frac{z_1+z_2+p_2-(1-z_1)}{2}\right)
\mathrm{P}[p_1=1-z_1]
\Biggr) \cr
={} & p_2 \Biggl(
1 + \left(\frac{3-2z_1-z_2-p_2}{2}\right) F_1^\star(1-z_1-0)
- (1-z_2) F_1^\star(p_2-\de) 
\cr & \phantom{p_2 \Biggl(} {}
- \int_{p_2-\de}^{1-z_1} \frac{1}{2} F_1^\star(p_1) \thinspace \diff p_1 
+ \left(\frac{3-2z_1-z_2-p_2}{2}\right)
\left( 1 - F_1^\star(1-z_1-0) \right)
\Biggr) \cr
={} & p_2 \Biggl(
\left(\frac{5-2z_1-z_2-p_2}{2}\right)
- (1-z_2) g(p_2-\de; 1-z_1, \pi_2^\star)
\cr & \phantom{p_2 \Biggl(} {}
- \int_{p_2-\de}^{1-z_1} \frac{1}{2} g(p_1; 1-z_1, \pi_2^\star) \thinspace \diff p_1 
\Biggr) \cr
={} & p_2 \Biggl(
\left(\frac{5-2z_1-z_2-p_2}{2}\right)
- (1-z_2) g(p_2-\de; 1-z_1, \pi_2^\star) 
\cr & \phantom{p_2\Biggl(}
- \int_{p_2-\de}^{1-z_1} \left(
\frac{1}{2\lambda_2} \frac{\diff}{\diff p_1} g(p_1; 1-z_1, \pi_2^\star)
+ \frac{1}{2} - \frac{z_2}{ (p_1+\de)^2 } \right) \thinspace \diff p_1 
\Biggr) \quad (\because \text{\Eq{eq:gdiff}}) \cr
={} & p_2 \Biggl(
\left(\frac{5-2z_1-z_2-p_2}{2}\right)
- (1-z_2) g(p_2-\de; 1-z_1, \pi_2^\star) 
\cr & \phantom{p_2\Biggl(} {}
- \frac{1}{2\lambda_2} g(1-z_1; 1-z_1, \pi_2^\star)
+ \frac{1}{2\lambda_2} g(p_2-\de; 1-z_1, \pi_2^\star)
\cr & \phantom{p_2\Biggl(}
-\frac{(1-2z_1+z_2-p_2)}{2} 
- \frac{z_2}{1-2z_1+z_2} + \frac{z_2}{p_2} 
\Biggr) \cr
={} & p_2 \left( 2 - z_2 
- \frac{z_2}{1-2z_1+z_2} + \frac{z_2}{p_2} 
-  \frac{1}{2\lambda_2} g(1-z_1; 1-z_1, \pi_2^\star)
\right) \cr
={} & p_2 \left( 
2 - z_2 
- \frac{z_2}{1-2z_1+z_2} + \frac{z_2}{p_2} 
-  \frac{1}{2\lambda_2} - 1 + \frac{z_2}{1-2z_1+z_2} \right) 
\quad (\because \text{\Eq{eq:gbb}})
\cr
={} & z_2 
\end{align*}
\end{proof}

\begin{lemma}
For the probability distribution given by \Eq{eq:F1sol3} and when $p_2=z_2$,
\begin{align}
\mathrm{E}[\pi_2](p_2) = \mathrm{E}[\pi_2](z_2) = \pi_2^\star
\end{align}
\end{lemma}
\begin{proof}
In this case, the price $p_1$ of Firm 1 is always lower than $p_2-\de$, because $p_2-\de = z_2 - (z_2-z_1 ) =z_1 > 1-z_1$ ($\because$ \Eq{eq:rgn3a}), which is the upper limit of $\mathrm{supp}F_1^\star$.
Therefore, Firm 2 gains only from its fan, and $\mathrm{E}[\pi_2] = p_2\times 1 = z_2$.
\end{proof}

\begin{lemma}
For the probability distribution given by \Eq{eq:F1sol3} and when $p_2 = 1-z_2-0$,
\begin{align}
\mathrm{E}[\pi_2](p_2) \le \pi_2^\star
\label{eq:pi2bndM3}
\end{align}
\end{lemma}
\begin{proof}
In this case, because $p_2-\de = 1 - z_2-\de = 1-z_1$, Firm 2 gains all the shoppers when Firm 1 chooses the price $p_1=1-z_1$. Since $F_1^\star$ of \Eq{eq:F1sol3} has an atom at $p_1=1-z_1$, the expected profit of Firm 2 is evaluated as follows.
\begin{align*}
& \mathrm{E}[\pi_2](1-z_2-0) \cr & {}= (1-z_2) 
\Biggl( 1 + \int_{1-z_1-w}^{1-z_1} \left(1-\frac{z_1+1-p_1}{2}\right) \diff F_1^\star(p_1)
+ \left( 1 - F_1^\star(1-z_1-0) \right)
 \Biggr) \cr
& {} = (1-z_2) \Biggl( 1 + (1-z_1) F_1^\star(1-z_1-0) - \int_{1-z_1-w}^{1-z_1} \frac{1}{2} F_1^\star(p_1) \thinspace \diff p_1 
+ \left( 1 - F_1^\star(1-z_1-0) \right)
\Biggr) \cr
& {} = (1-z_2) \Biggl( 2 - z_1 F_1^\star(1-z_1-0) - \int_{1-z_1-w}^{1-z_1} \frac{1}{2} F_1^\star(p_1) \thinspace \diff p_1 
\Biggr) \cr
& {} = (1-z_2) \Biggl( 2 - z_1 g(1-z_1; 1-z_1, \pi_2^\star) - \int_{1-z_1-w}^{1-z_1} \frac{1}{2} g(p_1; 1-z_1, \pi_2^\star) \thinspace \diff p_1 
\Biggr) \cr
& {} = (1-z_2) \Biggl( 2 - z_1 g(1-z_1; 1-z_1, \pi_2^\star) 
\cr & \phantom{{} = (1-z_2)\Biggl(} {} - \int_{1-z_1-w}^{1-z_1} \left( \frac{1}{2\lambda_2} \frac{\diff}{\diff p_1} g(p_1; 1-z_1, \pi_2^\star) + \frac{1}{2} - \frac{z_2}{ (p_1+\de)^2 }   \right) \thinspace \diff p_1 
\Biggr) \quad (\because \text{\Eq{eq:gdiff}})
\cr & {} = 
(1-z_2) \Biggl( 2 - \left( 1 - z_2 + z_1 \right) g(1-z_1; 1-z_1, \pi_2^\star)
\cr & \phantom{{} = (1-z_2) \Biggl( }
{} - \frac{w}{2} 
- \frac{z_2}{ (1-2z_1+z_2) } + \frac{z_2}{  (1-2z_1+z_2-w) }
\Biggr) 
\cr & {} = 
(1-z_2) \Biggl(
2 - \frac{\left(1+z_1-z_2\right)}{2(1-z_2)} \left(  (4-2z_2) - \frac{2z_2}{1-2z_1+z_2}  \right)
\cr & \phantom{{} = (1-z_2) \Biggl( }
{} - \frac{w}{2} - \frac{z_2}{ (1-2z_1+z_2) } + \frac{z_2}{  (1-2z_1+z_2-w) }
\Biggr) \quad (\because \text{\Eq{eq:gbb}})
\cr & {} = 
2(1-z_2) - (1+z_1-z_2)(2-z_2)
-\frac{(1-z_2)w}{2} + \frac{z_1z_2}{( 1-2z_1+z_2 )} + \frac{(1-z_2)z_2}{  (1-2z_1+z_2-w) }
\cr & {} = z_2 - (z_2-z_1)z_2 - 2z_1
-\frac{(1-z_2)w}{2} + \frac{z_1z_2}{( 1-2z_1+z_2 )} + \frac{(1-z_2)z_2}{  (1-2z_1+z_2-w) }
\cr & {} \leq z_2
\quad (\because \text{\Eq{eq:condw3b}})
\end{align*}
\end{proof}
As for the previous two cases, this is strictly not sufficient to prove that this price distribution is equilibrium. It is required to satisfy $\mathrm{E}[\pi_2](p_2)\leq \pi_2^\star$ for \emph{all} $p_2$, not only at $p_2=1-z_2$, so that Firm 2 has no incentive to deviate from this strategy. However, numerical verification showed that once \Eq{eq:pi2bndM3} holds, we have $\mathrm{E}[\pi_2](p_2)\leq \pi_2^\star$ for all the other $p_2$.


\section{Numerical details}

To draw the two-dimensional plots of regions (Fig.~\ref{fig:regions}), equilibrium profits (Fig.~\ref{fig:pi}), and the support width (Fig.~\ref{fig:w}), grid points on the $z_1$-$z_2$ plane were sampled in the region $0< z_1 < 1$ and $1/2 < z_2 < 1$ with the spacing of 0.002 for both axes, which amounts to $500\times250$ grid points. Further, to make a blow-up of the mixed strategy regions, the range $0.42 < z_1 < 0.6$ was sampled with finer spacing of 0.0005 for $z_1$, that is, $360\times250$ points. At each point $(z_1,z_2)$, the conditions listed in Propositions \ref{case1characterized1},  \ref{case1characterized2}, \ref{pure4-1}, \ref{pure4-2}, \ref{thm:sol1}, \ref{thm:sol2}, and \ref{thm:sol3} were checked. Evaluation of the exponential integral function $\mathrm{Ei}(x)$ was done by series expansion for positive $x$ (\cite{Press2007}). For negative $x$, numerical integration of the defining equation for $\mathrm{Ei}(b)-\mathrm{Ei}(a)=\int_a^b \exp(t)/t \, \diff t$ was performed by the Sympson rule. The division of the integration range was successively refined until the relative error becomes less than $10^{-12}$.
All the numerical calculations in the present work were performed by making a code in C++ language at the double-precision level. 

Whenever a point $(z_1,z_2)$ is assigned to M1, M2, or M3, the equilibrium strategy is validated by checking the condition $\mathrm{E}[\pi_j] \leq \pi_j^{\star}$ ($j=1,2$) outside of the support. (Note that $\mathrm{E}[\pi_j] = \pi_j^{\star}$ inside the support is proved analytically in the previous part.) To do this, the price $p_j$ was sampled in the following regions with the spacing of 0.001.
\begin{align*}
& 0 < p_1 < z_1 - w, z_1 < p_1 < 1 - z_1, 0< p_2 <z_2-w, & \mathrm{for\ M1}, \cr
& 0 < p_1 < 1 - z_1 - w, 0< p_2 < 1 - 2 z_1 + z_2-w, & \mathrm{for\ M2}, \cr
& 0 < p_1 < 1 - z_1 - w, 0 < p_2 < 1 - 2 z_1+z_2 -w,  1-2z_1+z_2< p_2 <z_2, & \mathrm{for\ M3}. %\cr
\end{align*}
For each price, the quantity $\mathrm{E}[\pi_j] - \pi_j^{\star}$ was evaluated, which should be less than zero if the strategy is indeed an equilibrium. The maximum value, among all the points tested in the above procedure, found for this quantity was $6.99\times10^{-13}$. This is practically equal to zero, considering the double-precision numbers have fifteen significant digits and the numerical accuracy for $\mathrm{Ei}$ is $10^{-12}$ as mentioned above. Therefore, the condition $\mathrm{E}[\pi_j] - \pi_j^{\star} \leq 0$ was numerically validated.


The program code used for the numerical check is available as a file named \verb#price_eq_w_uninf.cpp#. 
When complied and executed, it outputs five files. Each row of \verb#map.dat# and \verb#map_mixed.dat#, calculated in the subroutine \verb#makeMap#, shows the following data in this order:\\
\centerline{
$z_1$\ \ \ $z_2$\ \ \ region\ \ \ $w$\ \ \ $\pi_1^{\star}$\ \ \ $\pi_2^{\star}$
}\\
\noindent
where region assignment is coded as $1=\mathrm{P1}$, $2=\mathrm{P2}$, $3=\mathrm{P3}$, $17=\mathrm{M1}$, $18=\mathrm{M2}$, $19=\mathrm{M3}$, and $-1={}$not in the scope of the present report.
The files \verb#CDF_M1.dat#, \verb#CDF_M2.dat#, and \verb#CDF_M3.dat#, calculated in the subroutine \verb#drawCDF#, shows the cumulative distribution functions $F_1^{\star}(p_1)$ and $F_2^{\star}(p_2)$ with each row meaning\\
\centerline{
$p_1$\ \ \ $F_1^{\star}(p_1)$\ \ \ $p_2$\ \ \ $F_2^{\star}(p_2)$
}\\
\noindent
Finally, the subroutine \verb#check_ineq# outputs the maximum value of  $\mathrm{E}[\pi_j] - \pi_j^{\star}$ to the standard output.

