\end{figure}

    \begin{itemize}
        \item {\em Both $p'$ and $q'$ have degree 3.} This case is depicted in  Figure~\ref{degree-fig}(a). Since $\delta$ is a longest path in the tree, $p'$ has a neighbor $p''$ in $T$, different from $p$, that is also a leaf.  Since $p$ and $p''$ are leaves, the three triangles that correspond to $p,p',p''$ consist of $4$ consecutive edges of $\partial P$ that are visible from their middle vertex. A similar argument holds for $q'$. Since the diameter is at least 3, the four edges that we get for $q'$ are different from those for $p'$. The two middle vertices cover the $8$ edges, and thus statement 3 holds.
        \item {\em One of $p'$ and $q'$ has degree 3 and the other has degree 2.} Due to symmetry assume that $p'$ has degree $3$, as in  Figure~\ref{degree-fig}(b). As in the previous case, we get four consecutive edges of $\partial P$ for $p'$ that can be covered by their middle vertex. The two triangles that correspond to  $q,q'$ consist of three consecutive edges of $\partial P$ where one of their vertices, say $v$, is incident to both triangles. The vertex $v$ covers these three edges and another edge $e$ on the remaining portion of $\partial P$. If $e$ is among the four edges of $p'$, then statement 2 holds; otherwise statement 3 holds.
        \item {\em Both $p'$ and $q'$ have degree 2.} See  Figure~\ref{degree-fig}(c). Define $e$, $v$, and its four covering edges as in the previous case. Let $e'$ and $v'$ be the analogous edge and vertex for $p'$. If $v=v'$, then $v$ covers six consecutive edges; thus, statement 1 holds. Assume that $v\neq v'$. Then, the four edges of $p'$ and the four edges of $q'$ share at most one edge, which could be $e$ or $e'$. If they share an edge then statement 2 holds, otherwise statement 3 holds.\qedhere
    \end{itemize}
\end{proof}

\begin{theorem}
In any polygon $P$ with $n\ge 4$ vertices there exists a set of at most $\lfloor \frac{n-2}{2} \rfloor$ points that guard the boundary of $P$ contiguously.
%The boundary of any polygon with $n\ge 4$ vertices can be covered contiguously by at most {\color{mycolor}$\lfloor \frac{n-2}{2} \rfloor$ guards}.
   %if $n$ is even and  $\lfloor \frac{n-3}{2} \rfloor$ guards if $n$ is odd. 
   This bound is tight for even and odd $n$.
\end{theorem}

%\todoin{SO: we don't need the floors. or we can write $\lfloor (n-2)/2 \rfloor$ for both even and odd.}

\begin{proof}
If $n=4,5$, then one vertex of the polygon covers the entire boundary (to verify this, observe that in any triangulation of a $5$-gon, there is a vertex that is incident to the three resulting triangles). If $n=6$, then any triangulation contains a diagonal that partitions the boundary of $P$ into 2 and 4 consecutive edges;\footnote{For any $k\ge 2$ there is a diagonal that cuts off at least $k$ and at most $2k {-}2$ edges of the polygon; see~\cite{Biniaz2024}.} each partite can be covered by one vertex. If $n=7$, then there is a diagonal that partitions the boundary of $P$ into 3 and 4 consecutive edges; again, each partite can be covered by one vertex.   

Assume that $n\ge 8$. Then, at least one of the cases in Lemma~\ref{cover-lemma} holds. For each case, we show how to cover $\partial P$ by the number of guards that is claimed.

\begin{itemize}
    \item {\em Statement 1 holds.} We cover $6$ consecutive edges by $1$ guard and the remaining chain of $n{-}6$ edges by at most $\lfloor\frac{n-5}{2}\rfloor$ guards. Thus, the total number of guards is at most $\lfloor\frac{n-3}{2}\rfloor$. 
    \item {\em Statement 2 holds.} We cover $7$ consecutive edges by $2$ guards and the remaining chain of $n{-}7$  edges by at most $\lfloor\frac{n-6}{2}\rfloor$ guards.
    %if $n{-}7$ is odd, and by $\lfloor\frac{n-7}{2}\rfloor$ guards if $n{-}7$ is even. 
    The total number of guards is at most {\color{mycolor}$\lfloor\frac{n-2}{2}\rfloor$}.
    %if $n$ is even, and $\lfloor\frac{n-3}{2}\rfloor$ if $n$ is odd.
    \item {\em Statement 3 holds.} We cover the $8$ edges by two guards. If $8$ edges are consecutive, then we cover the remaining chain as in the previous case. Assume they are not consecutive and thus split into two sets, each having four consecutive edges. The remaining $n{-}8$ edges of $\partial P$ form two disjoint chains of $n_1$ and $n_2$ edges that can be covered by at most $\lfloor\frac{n_1+1}{2}\rfloor$ and $\lfloor\frac{n_2+1}{2}\rfloor$ guards, respectively. The total number of guards is at most {\color{mycolor}$\lfloor\frac{n_1+1}{2}\rfloor+\lfloor\frac{n_2+1}{2}\rfloor+2\le\frac{n-2}{2}$. 
    This equals $\lfloor\frac{n-2}{2}\rfloor$ when $n$ is even. When $n$ is odd, one of the chain sizes, say $n_1$, is even, and hence the chain itself can be covered by at most $\lfloor\frac{n_1}{2}\rfloor$ guards, which would result in at most $\frac{n-3}{2}\le \lfloor\frac{n-2}{2}\rfloor$ total guards.}
\end{itemize}

\begin{figure}[htb]
	\centering
\setlength{\tabcolsep}{0in}	\includegraphics[width=.6\columnwidth]{fig/lower-bound.pdf}\\	\caption{Illustration of the lower bound $\lfloor\frac{n-2}{2}\rfloor$ guards. The polygonal arcs around the boundary are maximal chains that can each be guarded by a single guard.}
\label{lower-bound-fig}
\end{figure}

To verify the lower bound, see the polygon in Figure~\ref{lower-bound-fig} of size $n=4k+2$, for some integer $k$, which consists of two convex chains of odd length $\frac{n}{2}$. The chains are placed close to each other such that the midpoints of no three consecutive edges on a chain are visible from the same point in the polygon.  A guard cannot cover more than two consecutive midpoints on each chain. To cover each chain, we need at least $\lfloor\frac{n/2+1}{2}\rfloor$ guards, out of which only two guards that cover the two endpoints of the chain can be shared. Thus, we need at least $2\lfloor\frac{n/2+1}{2}\rfloor-2=\lfloor\frac{n-2}{2}\rfloor$ guards to cover the boundary of this polygon contiguously. This verifies the tightness of the bound for even $n$.
By adding a vertex on any edge of the polygon in Figure~\ref{lower-bound-fig}, a lower bound example for odd $n$ is obtained. 
\end{proof}





\section{Preliminaries for the Algorithms}
For two points $p$ and $q$ in the plane, we denote by $pq$ the straight line segment between $p$ and $q$. A {\em ray} from $p$ toward $q$, denoted $\overrightarrow{pq}$, is the half-line
that starts from $p$ and passes through $q$. A {\em wedge} is a region of the plane that is bounded by two rays starting from the same point known as the {\em apex} of the wedge. Notice that such two rays partition the plane into two wedges. 

Let $P$ be a simple polygon. Two
points $p$ and $q$ of $P$ are said to be {\em visible} (or {\em see} each other) if the line segment $pq$ lies
totally inside (in the interior or on the boundary of) $P$. The {\em visibility
region} of $P$ from a point $q\in P$, denoted $V(P,q)$, is the set of all points of $P$ that are visible
from $q$; see Figure~\ref{guard-fig}. It is well-known that $V(P,q)$ is a simple polygon and can be computed in linear time, see e.g.~\cite{ElGindy1981,Lee1983,Preparata1985}.  {\color{mycolor}The region $V(P,q)$ is also referred to as the {\em visibility polygon} of $q$.
%In fact, the visibility polygon is {\em star-shaped} in which all points are visible from a point called the {\em center}.
The visibility polygon is {\em star-shaped}, i.e., all its points are visible from a single point called a {\em center}. The set of all centers of a star-shaped polygon is called its {\em kernel}; it can be computed in linear time~\cite{Lee1979}.}

