\begin{lemma}
\label{reflex-inside-lemma}
For any guard $g\in\Gamma^*$,  each ray of $w(g)$ is bounded by exactly one reflex vertex of $P$. Such a vertex bounds the ray from outside.
\end{lemma} 
\begin{proof}
This first statement is a direct implication of Lemma~\ref{on-ray-lemma} and Lemma~\ref{no-vertex-extension}. 


We prove the second statement by   contradiction. Assume that a reflex vertex $r$ bounds a ray $A$ of $w(g)$ from inside. Then $r$ is an endpoint of $\partial(g)$. Let $B$ denote the other ray of $w(g)$, which is bounded from inside or outside as in Figure~\ref{bounded-inside-fig}.
%In this case the other ray of $w(g)$ is also bounded from inside because otherwise we get a contradiction to continuity of $\partial(g)$. 
We consider two cases:

\begin{itemize}
    \item $g\notin \partial$. Then by Lemma~\ref{edge-lemma}, $g$ lies on the extension of $e(g)$, and moreover $e(g)$ belongs to $\partial (g)$. 
%In this case the other ray of $w(g)$ is also bounded from inside because otherwise we get a contradiction to continuity of $\partial(g)$. 
Let $C$ and $D$ be the rays from $g$ towards and away from $e(g)$, respectively, as in Figure~\ref{bounded-inside-fig}(a).  {\color{mycolor} Let  $\alpha$ be the angle between $B$ and $C$ that lies inside $w(g)$. If $\alpha$} is at most $\pi$, then by moving $g$ on $C$  either $g$ reaches a vertex-extension, or another edge-extension, or an endpoint of $e(g)$. This movement does not decrease $\partial(g)$ because the endpoint $r$ of $\partial(g)$ remains visible from $g$ as there is no reflex vertex in the interior of $A$, and the other endpoint of $\partial(g)$, which is on $B$, remains visible since the movement angle  $\alpha$ is at most $\pi$. In all cases we get a new optimal solution that contradicts the fact that $g$ is not in $Q$. Assume that $\alpha> \pi$ {\color{mycolor}(this could happen for example if in Figure~\ref{bounded-inside-fig}(a) the edge $e(g)$ and consequently the rays $C$ and $D$ were reflected around $g$).} By moving $g$ on $D$, either $g$ lies on a vertex-extension, or on another edge-extension, or it reaches $\partial$. In all cases, we get an optimal solution for which $g$ is in $Q$, which is a contradiction.

 \item $g\in \partial$. If $w(g)\leq \pi$ then by moving $g$ along the bisector of $w(g)$ we increase the covering angle of $g$ without decreasing $\partial(g)$, a contradiction to our choice of $\Gamma^*$. Assume that $w(g)> \pi$. Let $C$ be the ray from $g$ along  $e(g)$ such that the angle between $B$ and $C$ inside $w(g)$ is at most $\pi$ as in Figure~\ref{bounded-inside-fig}(b). By moving $g$ on $e(g)$ along $C$, either $g$ lies on a vertex-extension, or on another edge-extension, or it reaches an endpoint of $e(g)$. As in the previous case, this movement does not decrease $\partial(g)$. In all cases, we get an optimal solution for which $g$ is in $Q$, a contradiction. 
\qedhere
\end{itemize}
\end{proof}






\begin{lemma}
\label{angle-lemma}
For every guard $g\in\Gamma^*$, it holds that $w(g)\ge \pi$. 
\end{lemma}
\begin{proof}
First, assume that $g\notin e(g)$, and hence, it lies in the interior of $P$.
By Lemma~\ref{reflex-inside-lemma}, each ray of $w(g)$ is bounded by exactly one reflex vertex from outside.
If $w(g)< \pi$ then by  moving $g$ inside $w(g)$, along the extension of $e(g)$, we increase $w(g)$ without decreasing $\partial(g)$ as in Figure~\ref{edge-fig}(a). This contradicts our choice of $\Gamma^*$.  


Now assume that $g\in e(g)$. If $w(g)< \pi$ then by moving $g$ along the bisector of $w(g)$ we increase its covering angle without decreasing $\partial(g)$, a contradiction to our choice of $\Gamma^*$.  
\end{proof}




