        \hline
        \noindent
        \scalebox{.9}{
       	\begin{minipage}[t]{.7\linewidth}
        \begin{algorithm}[H]
        \caption{Algorithm for code generation.}
        \label{algo:codegen}
        \SetAlgoLined
        \LinesNumbered
        \SetKwInOut{Input}{Input}
        \SetKwInOut{Output}{Output}
        \SetKwRepeat{Do}{do}{while}
        \Input{
