	\section{Preliminaries}\label{sec:preliminaries}

	%
%

\paragraph{Sets and intervals}  Given a set $A$, we denote by $\pow{A}$ the \emph{powerset} of $A$. We denote by $\bbN$ the natural numbers. Given $n,m \in \bbN$ with $n \leq m$, we denote by $[n]$ the set $\{1, \ldots, n\}$ and by $[n..m]$ the interval $\{n, n+1, \ldots, m\}$ over $\bbN$. 
We denote by $\bbQplus$ the non-negative rational numbers, and by $\bbQinf$ the set $\bbQplus \cup \{\infty\}$ where $q < \infty$ for every $q \in \bbQplus$. 
A subset $I \subseteq \bbQplus$ is an \emph{interval over $\bbQplus$} if for every $p, q \in I$ and $r \in \bbQplus$, if $p \leq r \leq q$, then $r \in I$.
We will use the standard notation for specifying intervals over $\bbQplus$, namely, as pairs in $\bbQplus \times \bbQinf$ with squared or circled brackets. For example, $(\frac{1}{2}, 3] = \{p \in \bbQplus \mid \frac{1}{2} < p \leq 3\}$, $(1, 2) = \{p  \in \bbQplus \mid 1 < p < 2\}$, and $[7, \infty) = \{p \in \bbQplus \mid 7 \leq p < \infty\}$ are intervals over $\bbQplus$ under this notation.

%

\paragraph{Events and streams} We fix a set $\tset$ of \emph{event types}, a set $\aset$ of \emph{attributes names}, and a set $\dset$ of \emph{data values} (e.g., integers, floats, strings). An \emph{event} $e$ is a partial mapping $e: \aset \rightarrow \dset$ that maps attributes names in $\aset$ to data values in $\dset$. We denote $\eatt{e}$ the domain of $e$, called the \emph{attributes of $e$}, and we assume that $\eatt{e}$ is finite. 
We denote by $e(A)$ the data value of the attribute $A \in \aset$ whenever $A \in \eatt{e}$. Further, each event $e$ has a \emph{type} in $\tset$ denoted by~$\etype{e}$. We define the \emph{size} $|e|$ of an event $e$ as the number of RAM registers to encode $e$. We write $\eset$ to denote the \emph{set of all events} over event types $\tset$, attributes names $\aset$, and data values $\dset$.
A \emph{stream} is an (arbitrary long) sequence $\Stream = e_1 e_2 \ldots e_{n}$ of events where $|\Stream| = n$ is the length of the stream. 

\begin{example} \label{ex:stream}
	As a running example (from~\cite[Section 3]{GrezRUV21}), suppose the scenario of a national park sensor network measuring the temperature and humidity of the park. For the sake of simplification, assume that there are two types of events: $T$ and $H$. A \emph{temperature event} $e$ has $\etype{e} = T$ and $\eatt{e} = \{temp\}$ where $e(temp)$ contains the temperature value in  degrees Celsius (e.g., $e(temp) = \text{20°}$). A \emph{humidity event} $e$ has $\etype{e} = H$ and $\eatt{e} = \{hum\}$ where $e(hum)$ contains the value as a percentage (e.g., $e(hum) = \text{40\%}$). In Figure~\ref{fig:stream}, we display a stream $\StreamEx$ for this scenario.
\end{example}


