\paragraph{Complex events} Fix a finite set $\xset$ of \emph{variables} and assume that $\tset \subseteq \xset$, where $\tset$ is the set of event types as defined earlier. Let $\Stream$ be a stream of length~$n$. A \emph{complex event}\footnote{In~\cite{GrezRUV21,BucchiGQRV22},triples of the form $(i, j, \mu)$ are called valuations and complex events are triples $(i, j, D)$ where $D \subseteq [i..j]$. In this work, we prefer to call $(i, j, \mu)$ as complex events to simplify the presentation.} of $\Stream$ is a triple $(i, j, \mu)$ where $i, j \in [n]$, $i \leq j$, and $\mu:\xset \rightarrow \pow{[i..j]}$ is a function with finite domain. Intuitively, $i$ and $j$ marks the beginning and end of the interval where the complex event happens, and $\mu$ stores the events in the interval $[i..j]$ that fired the complex event.
In the following, we will usually use $C$ to denote a complex event $(i, j, \mu)$ of $\Stream$ and omit $\Stream$ if the stream is clear from the context. We will use $\ctime(C)$, $\cstart(C)$, and $\cend(C)$ to denote the interval $[i..j]$, the start $i$, and the end $j$ of $C$, respectively. Further, by some abuse of notation we will also use $C(X)$ for $X \in \xset$ to denote the set $\mu(X)$ of $C$.  

\begin{example}\label{ex:complex-events}
	Complex events of the stream $\StreamEx$ of Figure~\ref{fig:stream} can be $C_1=(5,9, \{X \mapsto \{5\}, Y \mapsto \{9\}, H \mapsto \varnothing, T \mapsto \varnothing\})$ and  $C_2=(2,9, \{X \mapsto \{2\}, Y \mapsto \{9\}, H \mapsto \varnothing, T \mapsto \varnothing\})$ where $X$ and $Y$ are variables in $\xset$.
\end{example}

The following operations on complex events will be useful throughout the paper. We define the \emph{union} of complex events $C_1$ and $C_2$, denoted by $C_1 \cup C_2$, as the complex event $C'$ such that $\cstart(C') = \min\{\cstart(C_1), \cstart(C_2)\}$, $\cend(C') = \max\{\cend(C_1), \cend(C_2)\}$, and $C'(X) = C_1(X) \cup C_2(X)$ for every $X \in \xset$. Further, we define the \emph{projection over $L$} of a complex event $C$, denoted by $\pi_L(C)$, as the complex event $C'$ such that $\ctime(C') = \ctime(C)$ and $C'(X) = C(X)$ whenever $X \in L$, and $C'(X) = \emptyset$, otherwise. Finally, we denote by $(i,j, \mu_\emptyset)$ the complex event with trivial mapping $\mu_\emptyset$ such that $\mu_\emptyset(X) = \emptyset$ for every $X \in \xset$.

\paragraph{Predicates of events} A \emph{predicate} is a possibly infinite set $P$ of events. 
For instance (see Example~\ref{ex:stream}), $P$ could be the set of all $T$-events $e$ such that $e(temp) \leq \text{20°}$.
In our examples, we will use the notation $A \sim a$ where $A \in \aset$ and $a \in \dset$ to denote the predicate $P = \{e \mid e(A) \sim a\}$ (e.g., $temp \leq \text{20°}$).
We say that an event $e$ satisfies predicate $P$, denoted $e \models P$, if, and only if, $e \in P$.
We generalize this notation from events to a set of events $E$ such that $E \models P$ if, and only if, $e \models P$ for every~$e \in E$. 

We assume a fixed \emph{set of predicates} $\pset$. Further, we assume that there is a basic set of predicates $\psetbasic \subseteq \pset$ (e.g., $temp \leq \text{20°}$) and $\pset$ is the closure of $\psetbasic$ under intersection and negation (i.e., $P_1 \cap P_2 \in \pset$ and $\eset \setminus P \in \pset$ for every $P, P_1, P_2 \in \pset$) where $\eset$ is a predicate in $\pset$, that we usually denote by $\true$. 
For every $P \in \pset$, we define a size of a predicate $|P|$ as follows: $|P| = 1$ if $P \in \psetbasic$ (i.e., constant size), $|P| = |P_1| + |P_2|$ if $P = P_1 \cap P_2$, and $|P| = |P'|+1$ if $P = \eset \setminus P'$.
%
For every $P \in \pset$, we assume that the time to check if $e \models P$ is in $\mathcal{O}(|e|)$.

\paragraph{Complex event logic} In this work, we use the \emph{Complex Event Logic} (CEL) introduced in~\cite{GrezRUV21} and implemented in CORE~\cite{BucchiGQRV22} as our basic query language for CER. The syntax of a CEL formula $\varphi$ is given by the grammar:
\[
	\varphi \ := \  R  \ \mid \ \varphi \kAS X \ \mid \ \varphi \kFILTER X[P] \ \mid \   \varphi \kOR \varphi \mid \ \varphi \kAND \varphi \ \mid \ \varphi \sq \varphi \ \mid \ \varphi \ssq \varphi \ \mid \ \varphi\ks \ \mid \ \varphi\sks \ \mid \ \pi_L(\varphi)
\]
where $R \in \tset$ is an event type, $X \in \xset$ is a variable, $P \in \pset$ is a predicate, and $L \subseteq \xset$ is a set of variables.  
We define the semantics of a CEL formula $\varphi$ over a stream $\Stream$, recursively, as a set of complex events over $\Stream$. In Figure~\ref{fig:cel-semantics}, we define the semantics of each CEL operator like in~\cite{BucchiGQRV22,GrezRUV21}. 
\begin{figure}[t]
	\small
	\centering
	\begin{align*}
		\sem{R}(\Stream) & \ = \ \{ (i,i, \mu) \ \mid \!\!
		\begin{array}[t]{l}
			\type(e_i) = R \ \wedge \ \mu(R) = \{i\} \ \wedge \  \forall X \neq R. \ \mu(X) = \emptyset\} 
		\end{array}  \\ 
		\sem{\varphi \kAS X}(\Stream) & \  = \  \{ C \ \mid \!\!
		\begin{array}[t]{l}
			\exists \, C' \in \sem{\varphi}(\Stream). \ \ \ctime(C) = \ctime(C') \ \wedge \ C(X) = \bigcup_{Y} C'(Y)   \\
			\wedge \ \forall Z \neq X. \  C(Z) = C'(Z) \} 
		\end{array} \\
		\sem{\varphi \kFILTER X[P]}(\Stream) & \ = \  \{ C \ \mid \!\!
		\begin{array}[t]{l}
			C \in \sem{\varphi}(\Stream)  \ \wedge \ C(X) \models P \} 
		\end{array} \\
		\sem{\varphi_1 \kOR \varphi_2}(\Stream) & \ = \ \sem{\varphi_1}(\Stream) \ \cup \  \sem{\varphi_2}(\Stream) \\
		\sem{\varphi_1 \kAND \varphi_2}(\Stream) & \ = \ \sem{\varphi_1}(\Stream) \ \cap \  \sem{\varphi_2}(\Stream) \\
		\sem{\varphi_1 \sq \varphi_2}(\Stream) & \ = \ \{ C_1 \cup C_2 \ \mid \!\!
		\begin{array}[t]{l}
			C_1 \in \sem{\varphi_1}(\Stream) \, \wedge \, C_2 \in \sem{\varphi_2}(\Stream) \, \wedge \, \cend(C_1) < \cstart(C_2)   \}
		\end{array}  \\
		\sem{\varphi_1 \ssq \varphi_2}(\Stream) & \ = \ \{ C_1 \cup C_2 \ \mid \!\!
		\begin{array}[t]{l}
			C_1 \in \sem{\varphi_1}(\Stream) \, \wedge \,  C_2 \in \sem{\varphi_2}(\Stream) \, \wedge \,
			\cend(C_1) + 1 = \cstart(C_2) \}
		\end{array}  \\
		\sem{\varphi\ks}(\Stream) & \ = \ \sem{\varphi}(\Stream) \ \cup \ \sem{\varphi \sq \varphi \ks}(\Stream) \\
		\sem{\varphi\sks}(\Stream) & \ = \ \sem{\varphi}(\Stream) \ \cup \ \sem{\varphi \ssq \varphi \sks}(\Stream) \\
		\sem{\PROJ{L}\!(\varphi)}(\Stream) & \ = \ \{ \pi_L(C) \ \mid \!\!
		\begin{array}[t]{l}
			C \in \sem{\varphi}(\Stream) \}
