		\item Let $\varphi = \psi\xssq{I}\psi$, then $\cT_\varphi = (Q_{\psi_1} \cup Q_{\psi_2}\cup \{q_{new}\}, \pset, \xset, \zset_{\psi_1}\cup \zset_{\psi_2} \cup \{z_X\}, \Delta_\varphi,  q_{0\psi_1}, F_{\psi_2} )$ where $z_X$ is a new clock, $q_{new}$ is a new state, and $\Delta_\varphi = \Delta_{\psi_1} \cup \Delta_{\psi_2} \cup \{(p,P,\gamma,L,Z\cup \{z_X\},q_{new}) \mid (p,P,\gamma,L,Z,q_f)\in \Delta_{\psi_1} \land q_f\in F_{\psi_1}\} \cup \{(q_{new}, P, \gamma \land \gamma_I, L, Z, q) \mid \exists (q_{0\psi_2}, P, \gamma, L, Z, q) \in \Delta_{\psi_2}\}$. This automaton is basically the same than the automaton for $\psi_1 \ssq \psi_2$, except that it adds a time constraint between the two formulas.  The proof for this operator is analogous to the one for operator $\xsq{I}$.
		\smallskip

		\item Let $\varphi = \psi\xks{I}$, then $\cT_\varphi = (Q_\psi \cup \{q_{new}\}, \pset, \xset, \zset_{\psi}\cup \{z_X\}, \Delta_\varphi,  q_{0\psi}, F_\psi)$ where $q_{new}$ is a fresh state, $z_X$ is a new clock, $\Delta_\varphi = \Delta_\psi \cup \{(p,P,\gamma,L,Z\cup \{z_X\},q_{new}) \mid \exists q' \in F_\psi.(p,P,\gamma,L,Z,q') \in \Delta_\psi\} \cup \{(q_{new},P,\TRUE,\varnothing,\varnothing,q_{new})\} \cup \{(q_{new},P,\gamma\land \gamma_I,L,Z,q) \mid (q_{0\psi},P,\gamma,L,Z,q) \in \Delta_\psi\} \cup \{(q_{new},P,\gamma \land (0 \in I),L,Z\cup \{z_X\},q_{new}) \mid \exists q_f\,.\, (q_{0\psi},P,\gamma,L,Z,q_f) \in \Delta_\psi\}$, $\gamma_I$ is the clock condition that checks if the value of the clock $z_X$ is in the interval $I$ and $(0 \in I)$ is $\TRUE$ is the expression evaluates to true and $\FALSE$ otherwise.

		\smallskip

		Let $\varphi = \psi \xks{I}$. We assume by induction that $\semaux{\psi}(\Stream) = \semaux{\cT_{\psi}}(\Stream)$, and will prove that $\semaux{\psi\xks{I}}(\Stream) = \semaux{\cT_{\varphi}}(\Stream)$. Let $(i, j, \mu)\in \semaux{\psi\xks{I}}(\Stream)$. Then, by construction, either $(i, j, \mu)\in \semaux{\psi}(\Stream)$ or $(i, j, \mu)\in \semaux{\psi\xsq{I}\psi\xks{I}}(\Stream)$. We will continue this proof using induction. As a base case, if $(i, j, \mu)\in \semaux{\psi}(\Stream)$, then by initial assumption $(i, j, \mu)\in \semaux{\cT_\varphi}(\Stream)$, because the transitions from $\cT_{\psi}$ are preserved in $\cT_{\varphi}$. We will then assume that if $(i, k, \mu_1)\in \semaux{\psi}(\Stream)$ and $(k', j, \mu_2) \in \semaux{\psi\xks{I}}(\Stream)$, then $(i, j, \mu) \in \semaux{\cT_{\varphi}}(\Stream)$. We then know that there exists runs $(q_0, \nu_0) \xrightarrow{P_i, \gamma_i / L_i, Z_i} \dots \xrightarrow{P_k, \gamma_k / L_k, Z_k} (q_f, \nu_k)$ over $\cT_{\psi}$ and $(q_0, \nu_0)\xrightarrow{P_{k'+1},  \gamma_{k'+1} / L_{k'+1}, Z_{k'+1}}\dots\xrightarrow{P_j, \gamma_j / L_j, Z_j} (q_f, \nu_j)$ over $\cT_{\varphi}$, with $k < k'$, and that $t_{k'} - t_{k} \in I$. Finally, if $(i, j, \mu)\in \semaux{\psi\xsq{I}\psi\xks{I}}(\Stream)$, then there exists a run $\rho: (q_0, \nu_0) \xrightarrow{P_i, \gamma_i/ L_i, Z_i} \dots \xrightarrow{P_k, \gamma_k / L_k, Z_k} (q_{new}, \nu_k)\xrightarrow{P_{k+1},\gamma_{k+1} / L_{k+1}, Z_{k+1}}\dots\xrightarrow{P_{k'}, \gamma_{k'}/ L_{k'}, Z_{k'}}(q_{k'}, \nu_{k}')\xrightarrow{P_{k'+1}, \gamma_{k'+1} / L_{k'+1}, Z_{k'+1}}\dots\xrightarrow{P_j, \gamma_j/ L_j, Z_j} (q_f, \nu_j)$. Therefore $(i, j, \mu)\in \semaux{\cT_{\psi\xsq{I}\psi\xks{I}}}(\Stream)$.

		On the other hand, let $C=(i, j, \mu)\in \semaux{\cT_{\varphi}}(\Stream)$. Then, there exists a run $\rho: (q_0, \nu_0) \xrightarrow{P_i, \gamma_i/ L_i, Z_i} \dots \xrightarrow{P_j, \gamma_j / L_j, Z_j} (q_f, \nu_f)$. We will prove the result by induction. Let's first assume that the run doesn't pass through the state $q_{new}$. Then, the automaton passes only through states that were present in $\cT_\psi$, so it is clear that $(i, j, \mu) \in \semaux{\psi}(\Stream) \subseteq \semaux{\varphi}(\Stream)$. Now let's assume the run over $\Stream$ passes $n$ times through the new state $q_{new}$. We can take from the stream $n+1$ substreams, such that each subevent $(k, k', \mu') \in \semaux{\cT_\psi}(\Stream)$ doesn't pass through $q_{new}$ (by construction). Let's call $k$ the last index of the first subevent and $k'$ the first index of the last subevent. We can then take two sub-events from $C$ , the first one being $C_1 = (i, k, \mu_1)$ and the second one being $C_2 = (k', j, \mu_2)$, where $k < k'$. We know by construction that $\nu_{k'-1}(z_X) - \nu_k(z_X) + \delta t_{k'} \in I$. As such, we know that $C_1 \in \semaux{\cT_{\psi}}(\Stream)$ and $C_2 \in \semaux{\cT_{\varphi}}(\Stream)$, but its run passes at most $n-1$ times through $q_{new}$. That said, $C_1 \in \semaux{\psi}(\Stream)$, $C_2\in \semaux{\psi\xks{\in I}}(\Stream)$, and $t_{k'}-t_{k} \in I$. We conclude that $C \in \semaux{\varphi}(\Stream)$.


		\item If $\varphi = \psi \timesks{I}$, then $\cT_\varphi = (Q_\psi \cup \{q_{new}\}, \pset, \xset, \zset_{\psi}\cup \{z_X\}, \Delta_\varphi, q_{0\psi}, F_\psi)$ where $q_{new}$ is a fresh state, $z_X$ is a new clock, $\Delta_\varphi = \Delta_\psi \cup \{(p,P,\gamma,L,Z\cup \{z_X\},q_{new}) \mid \exists q' \in F_\psi.(p,P,\gamma,L,Z,q') \in \Delta_\psi\} \cup \{(q_{new},P,\gamma\land \gamma_I,L,Z,q) \mid (q_{0\psi},P,\gamma,L,Z,q) \in \Delta_\psi\} \cup \{(q_{new},P,\gamma \land (0 \in I),L,Z\cup \{z_X\},q_{new}) \mid \exists q_f\,.\, (q_{0\psi},P,\gamma,L,Z,q_f) \in \Delta_\psi\}$, $\gamma_I$ is the clock constraint that checks if the valuation of the clock $z_X$ is in $I$ and $(0 \in I)$ is $\TRUE$ if the expression evaluates to true and $\FALSE$ otherwise. The proof for this operator is analogous to the one for operator $\xks{I}$.
	\end{itemize}	

\end{proof}

\subsection*{Proof of Proposition~\ref{pro:cea2cel}}
We will establish a method to build a timed CEL query equivalent to the language of a timed CEA $\cT = (Q, \pset, \xset, \zset, \Delta, q_0, F)$. For that matter, we will begin introducing the definitions of \emph{disjunction-free} and \emph{strongly-deterministic}, adapted from the definitions introduced in \cite{AsarinCM2002}. A timed CEA $\cT = (Q, \pset, \xset, \zset, \Delta, q_0, F)$ is \emph{disjunction-free} if for every transition $(p, P, \gamma, L, Z, q) \in \Delta$, we have that $\gamma$ is a formula with no disjunctions. A timed CEA $\cT = (Q, \pset, \xset, \zset, \Delta, q_0, F)$ is \emph{strongly-deterministic} if for every two transitions $(p, P_1, \gamma_1, L_1, Z_1, q_1)$, $(p, P_2, \gamma_2, L_2, Z_2, q_2) \in \Delta$ where $P_1 \cap P_2 \ne \varnothing$, we have that $L_1 \ne L_2$, namely, the determinism only depends on the value of the next tuple no matter the values of the clocks.

\begin{lemma}
	Any timed CEA $\cT = (Q, \pset, \xset, \zset, \Delta, q_0, F)$ can be converted into an equivalent disjunction-free automaton.
\end{lemma}

\begin{proof}
	The first step is to convert every transition guard to disjunctive normal form (DNF) $\gamma = \gamma_1 \lor\dots\lor \gamma_k$ where each $\gamma_i$ is a conjunction. We then replace every transition $\tau = (q, P, \gamma, L, Z, q')$ by k transitions of the form $(q, P, \gamma_i, L, Z, q')$, for $i \in [1..k]$. Furthermore, every transition will have a clock constraint equivalent to $z_X \le \varepsilon_1 \land z_X \ge \varepsilon_2$, where $\varepsilon_1 \in \bbQplus \cup \{+\infty\}$ and $\varepsilon_2 \in \bbQplus \cup \{-\infty\}$, which we will use instead of the complex clock constraint. This assumption will be use later in other constructions where $z_X \leq +\infty$ or $-\infty \leq z_X$ are always true.
\end{proof}

From now on, in this section, we will only work with disjunction-free automata. To successfully convert a timed CEA into a timed CEL formula, we will start by converting a single-clock timed CEA into a timed CEL formula. This will take several steps, that we will go through next.

Let $\rho$ be a run over $\cT$, and $\tau_1\tau_2\dots \tau_n$ be the transitions taken in that run. A single clock timed CEA is k-check-bounded if for every consecutive transitions $\tau_i, \dots \tau_j$ with $k+1$ transitions where the clock condition is not trivial, then there exists $i \le l < j$ such that $\tau_l$ resets the clock.

Next, we prove that we are able to convert the single-clock timed CEA into a k-check-bounded timed CEA.

\begin{lemma}\label{lemma:check-bounded}
	For every single-clock timed CEA $\cT = (Q, \pset, \xset, \zset, \Delta, q_0, F)$, there exists an equivalent $k$-check-bounded timed CEA for some $k$.
\end{lemma}

\begin{proof}
	The main idea behind this demostration is the following: Let $\rho$ be a run of $\cT$ over $w = w_1 \dots w_n$. Let $i$ be an index where the clock $z_X$ is resetted, and $j$ be the next index where it is resetted. Let $z_X \le \varepsilon_1, \dots, z_X \le \varepsilon_m$ be the constraints checked, in order of appearance. If $\varepsilon_k \le \varepsilon_{k'}$, with $k' < k$, then a run that satisfies $\varepsilon_k$ also satisfies $\varepsilon_{k'}$. This is because the clocks can only increase their value and there are no resets. Then, we can do the following procedure: We define $m_1 = \min \{\varepsilon_i \mid i \in [1, m]\}$, the lower clock constraint. We then define $p_1 = \max\{i \mid \varepsilon_i = m_1\}$, the latest appeareance of $\varepsilon_1$. This is the first clock constraint that we will keep in our updated automaton, because it being true implies all of the previous clock constraints. For our next clock constraint, we will define $m_2 = \min \{\varepsilon_i \mid i \in (p_1, m]\}$, the lower clock constraint which is checked after the index $p_1$, and $p_2 = \max \{i \mid \varepsilon_i = m_2\}$. This will be the second clock constraint that we will check in our run, because it is the next one that provides information that is not redundant. This way, we can continue to trim our clock constraints, finally getting a run that has a limited number of constraint checks before a next clock reset.

	To build our equivalent automaton, we need to define our sets of clock constraints:

	\begin{itemize}
		\item $C_\leq = \{\varepsilon \mid z_X < \varepsilon \text{ or } z_X \le \varepsilon \text{ is a subformula of a clock condition in $\Delta$}\}$
		\item $C_\geq = \{\varepsilon \mid z_X > \varepsilon \text{ or } z_X \ge \varepsilon \text{ is a subformula of a clock condition in $\Delta$}\}$
	\end{itemize}

	Note that equal clock conditions are not added. That is because a clock condition $z_X = c$ is treated as a conjunction of clock conditions, $z_X \le c \land z_X \ge c$. That being defined, we will construct the automaton. $\cT_{cb} = (Q', \pset, \xset, \zset, \Delta', q_0', F')$, with: 

	\begin{itemize}
		\item $Q' = Q \times (C_{\leq} \cup \{-\infty\}) \times \{<, \le\} \times (C_{\leq} \cup \{\infty\})\times \{<, \le\} \times (C_{\geq} \cup \{-\infty\}) \times \{>, \ge\}$
		\item $q_0' = (q_0, -\infty, <, \infty, \le, -\infty, \ge)$, and
		\item $F' = F \times (C_{\leq}\cup \{-\infty\}) \times \{<, \le\} \times \{\infty\} \times \{\le\} \times (C_{\geq}\cup \{-\infty\})\times \{>, \ge\}$
	\end{itemize}

	Each state is added three clock condition bounds, where the first corresponds to the last checked lower-equal clock condition, the second corresponds to the last skipped lower-equal clock condition and the third corresponds to the last checked greater-equal clock condition. We add these guards so we can skip the redundant transitions. The transitions next are for the greater equal and lower equal cases separately, but it is easy to merge them into one automaton. The full proof is omitted because of readability.

	We define the operation $(\varepsilon_1, \sim_1) < (\varepsilon_2, \sim_2)$ if either $\varepsilon_1 < \varepsilon_2$, or $\varepsilon_1 = \varepsilon_2$, $\sim_1$ is $<$ and $\sim_2$ is $\le$.	
	Also, $(\varepsilon_1, \sim_1) > (\varepsilon_2, \sim_2)$ if either $\varepsilon_1 > \varepsilon_2$, or $\varepsilon_1 = \varepsilon_2$, $\sim_1$ is $>$ and $\sim_2$ is $\ge$.

	We will begin defining $\Delta_\le$. The transitions it contains take six forms. The first ones are transitions of the form $((p, \varepsilon_c, \sim_c, \varepsilon_m, \sim_m), P, \true, L, \varnothing, (q, \varepsilon_c, \sim_c, \varepsilon_{m}', \sim_m'))$, where $(p, P, z_X \le \varepsilon, L, \varnothing, q) \in \Delta$, $(\varepsilon_{c}, \sim_c) < (\varepsilon, \le)$, and $(\varepsilon_{m}', \sim_m') = \min \{(\varepsilon, \le), (\varepsilon_{m}, \sim_m)\}$.
	The second kinds of transitions are transitions of the form $((p, \varepsilon_c, \sim_c, \varepsilon_m, \sim_m), P, \true, L, \varnothing, (q, \varepsilon_c, \sim_c, \varepsilon_{m}', \sim_m'))$, where $(p, P, z_X < \varepsilon, L, \varnothing, q) \in \Delta$, $\varepsilon_{c} < \varepsilon$, and $(\varepsilon_{m}', \sim_m') = \min \{(\varepsilon, <), (\varepsilon_{m}, \sim_m)\}$. These types of transitions skip the clock constraint, but save it so that a later one implies it. 
	The third are of the form $((p, \varepsilon_{c}, \sim_c, \varepsilon_{m}, \sim_m), P, z_X \le \varepsilon, L, \varnothing, (q, \varepsilon, \le, \infty, \le))$, where $(p, P, z_X \le \varepsilon, L, \varnothing, q) \in \Delta$, where $(\varepsilon_{c}, \sim_c) < (\varepsilon, \le)$, $(\varepsilon, \le) \le (\varepsilon_m, \sim_m)$.
	The fourth are of the form $((p, \varepsilon_{c}, \sim_{c}, \varepsilon_{m}, \sim_{m}), P, z_X < \varepsilon, L, \varnothing, (q, \varepsilon, <, \infty, \le))$, where $(p, P, z_X < \varepsilon, L, \varnothing, q) \in \Delta$, where $\varepsilon_{c} < \varepsilon \le \varepsilon_{m}$. These types of transitions force the clock constraint, ensuring that it implies the skipped constraints and clear the skipped constraint. 
	The fifth ones are of the form $((p, \varepsilon_{c}, \sim_c, \varepsilon_{m}, \sim_{m}), P, z_X \le \varepsilon, L, \{z_X\}, (q, -\infty, <, \infty, \le))$, where $(p, P, z_X \le \varepsilon, L, \{z_X\}, q) \in \Delta$, $(\varepsilon_{c}, \sim_c) < (\varepsilon, \le)$, $(\varepsilon, \le) \le (\varepsilon_m, \sim_m)$. 
	The sixth ones are of the form $((p, \varepsilon_{c}, \sim_c, \varepsilon_{m}, \sim_m), P, z_X < \varepsilon, L, \{z_X\}, (q, -\infty, <, \infty, \le))$ where $(p, P, z_X < \varepsilon, L, \{z_X\}, q) \in \Delta$, where $\varepsilon_{c} < \varepsilon\le \varepsilon_{m}$. These types of transitions are the same than the previous ones, but also resets the clock and restores the stored constraints.

	Now we will define $\Delta_\ge$. The transitions it contains take eight forms. The first are transitions of the form $((p, \varepsilon_{c}, \sim_c), P, z_X \ge \varepsilon, L, \varnothing, (q, \varepsilon, \ge))$, where $(p, P, z_X \ge \varepsilon, L, \varnothing, q) \in \Delta$ and $\varepsilon > \varepsilon_{c}$.
	The second are transitions of the form $((p, \varepsilon_{c}, \sim_c), P, z_X > \varepsilon, L, \varnothing, (q, \varepsilon, >))$, where $(p, P, z_X > \varepsilon, L, \varnothing, q) \in \Delta$, $(\varepsilon, >) > (\varepsilon_{c}, \sim_c)$. These types of transitions check the constraint and store it so that the next constraint is forced to be greater.
	The third are transitions of the form $((p, \varepsilon_{c}, \sim_c), P, \true, L, \varnothing, (q, \varepsilon_{c}, \sim_c))$, where $(p, P, z_X \ge \varepsilon, L, \varnothing, q) \in \Delta$, and $\varepsilon\le \varepsilon_{c}$.
	The fourth are transitions of the form $((p, \varepsilon_{c}, \sim_{c}), P, \true, L, \varnothing, (q, \varepsilon_{c}, \sim_c))$, where $(p, P, z_X > \varepsilon, L, \varnothing, q) \in \Delta$, and $(\varepsilon, >) \le (\varepsilon_{c}, \sim_c)$. These types of transitions skip the clock constraint, at it is already implied by the previous checks.
	The fifth are transitions of the form $((p, \varepsilon_{c}, \sim_c), P, z_X \ge \varepsilon, L, \{z_X\}, (q, - \infty, \ge))$, where $(p, P, z_X \ge \varepsilon, L, \{z_X\}, q) \in \Delta$ and $\varepsilon > \varepsilon_{c}$.
	The sixth are transitions of the form $((p, \varepsilon_{c}, \sim_c), P, z_X > \varepsilon, L, \{z_X\}, (q, - \infty, \ge))$, where $(p, P, z_X > \varepsilon, L, \{z_X\}, q) \in \Delta$, $(\varepsilon, >) > (\varepsilon_{c}, \sim_c)$.
	The seventh are transitions of the form $((p, \varepsilon_{c}, \sim_c), P, \true, L, \{z_X\}, (q, - \infty, \ge))$, where $(p, P, z_X \ge \varepsilon, L, \{z_X\}, q) \in \Delta$, and $\varepsilon\le \varepsilon_{c}$.
	The eighth are transitions of the form $((p, \varepsilon_{c}, \sim_{c}), P, \true, L, \{z_X\}, (q, - \infty, \ge))$, where $(p, P, z_X > \varepsilon, L, \{z_X\}, q) \in \Delta$, and $(\varepsilon, >) \le (\varepsilon_{c}, \sim_c)$. These are analogous to the previous transitions, but also reset the saved constraint because of the clock reset.

	One can check that $\cT_{cb}$ is $k$-check bounded with $k \leq |C_\leq| + |C_\geq|$ and the proof of correctness follows from the construction.
\end{proof}

By Lemma~\ref{lemma:check-bounded}, in the sequel we will only work with \emph{k-check-bounded} timed CEA when they are single-clock. Next, we will introduce the notion of \emph{reset-distinct}. A reset-distinct timed CEA is a timed CEA that does not have transitions that reset a clock and check a clock condition at the same time. We will show that any reset-distinct single-clock timed CEA can be converted into a formula in CEL. 
\begin{lemma}
	A reset-distinct and $k$-check bounded single-clock timed CEA $\cT$ has an equivalent formula in timed CEL $\phi$.
\end{lemma}
\begin{proof}
	We will create a timed CEL formula from the timed CEA described earlier. Let $\cT = (Q, \pset, \xset, \zset, \Delta, q_0, F)$ be a reset-distinct and $k$-check bounded timed CEA. We will introduce the following variables.
	First, we have the variable $S_{pq}^O$, that creates an expression in timed CEL starting from state $p$ and going to state $q$, passing only through states in $O \subseteq Q$, without any resets or clock-checks. The expressions are build recursively from the following formulas. The base case, for just one transition, $S_{q_iq_j}^{\varnothing} = \kOR_{(q_i, P, \true, L, \varnothing, q_j)\in \Delta}\PROJ{L}(P \kAS L)$, and the inductive case, $S_{q_iq_j}^{O \cup \{q_l\}} = S_{q_iq_l}^O \ssq S_{q_lq_l}^O\sks \ssq S_{q_lq_j}^O \kOR S_{q_iq_l}^O \ssq S_{q_lq_j}^O \kOR S_{q_iq_j}^O$. Here, $P \kAS L$ is an abuse of notation, denoting the use of operator $\kAS$ with every variable in $L$.

	Next, we introduce the formula for the subsets of the automaton that start from state $p$, pass first through with a transition that has a reset, and then pass through $h$ time windows, $R^h_{pq}$, arriving to state $q$. The base case ($0$ time windows) is $R_{q_iq_j}^0 = \kOR_{(q_i, P, \true, L, \{z\}, q_l)\in \Delta} \PROJ{L}(P \kAS L)\ssq S_{q_lq_j}^Q$, and the inductive case is divided into the cases that pass through $h+1$ time windows and end with a non-time-window transition, $R_{n,q_iq_j}^{h+1} = \kOR_{(q_l, P, z \in I, L, \varnothing, q_l)\in \Delta} \left ( \twin{R_{q_iq_l}^{h} \ssq \PROJ{L}(P \kAS L)}{I} \ssq S_{q_lq_j}^{Q} \right ) $ and into the cases that pass through $h+1$ time windows and end with a time-window transition, $R_{t,q_iq_j}^{h+1} = \kOR_{(q_l, P, z \in I, L, \varnothing, q_j)\in \Delta} \left ( \twin{R_{q_iq_l}^{h} \ssq \PROJ{L}(P \kAS L)}{I} \right )$. Then, $R_{q_iq_j}^{h+1} = R_{n,q_iq_j}^{h+1} \kOR R_{t,q_iq_j}^{h+1}$.

	Next, we introduce the formula for one or more of the previously introduced reset-starting parts of the automaton. The formula $F_{pq}^O$ denotes the contiguous reset-starting parts of the automata starting in $p$, ending in $q$ and having as start or end states of each subpart only states in $O$. The base case is $F_{q_iq_j}^\varnothing = \kOR_{h=0}^{k}R_{q_iq_j}^{h}$, the union of every combination of time windows, and the inductive case is $F_{q_iq_j}^{O \cup \{q_l\}} = F_{q_iq_l}^O \ssq F_{q_lq_l}^O\sks \ssq F_{q_lq_j} \kOR F_{q_iq_l}^O \ssq F_{q_lq_j}\kOR F_{q_iq_j}^O$, similar as the $S_{pq}^O$ formula. Finally, the formula $\varphi$ for the full automaton is stated as 
	\[
	\varphi = \kOR_{q_l\in Q} \left (\kOR_{q_f \in F} \left (S_{q_0q_l}^Q \ssq F_{q_lq_f}\right ) \right ) \kOR \kOR_{q_f \in F}\left ( S_{q_0q_f} \kOR F_{q_0q_f}\right )
	\]
\end{proof}

Now that we know that any reset-distinct single-clock timed CEA can be converted into a CEL formula, we will convert the \emph{timed CEA} into a conjunction of reset-distinct timed CEAs. This transformation will allow us to easily convert the \emph{timed CEA} into a timed CEL formula.

\begin{lemma}\label{lemma:reset-distinct-AND}
	Let $\cT = (Q, \pset, \xset, \{z\}, \Delta, q_0, F)$ be a single-clock timed CEA, where $\xset'$ is the set of variables used by $\cT$. There exist two reset-distinct timed CEAs $\cT_1$ and $\cT_2$ such that, if $\phi_1$ and $\phi_2$ are the equivalent timed CEL formulas of $\cT_1$ and $\cT_2$, respectively, then $L(\PROJ{\xset'}(\phi_1\kAND \phi_2)) = L(\cT)$.
\end{lemma}

\begin{proof}
	First we will create a new strongly-deterministic timed CEA $\cT'$ based on automaton $\cT$. We will do so by replacing any transition $(q, P, \gamma, L, Z, q')$ by $(q, P, \gamma, L\cup \{X_i\}, Z)$, where $X_i$ is a new variable, choosing a different $i$ for every transition going out of the same state $q$. This new automaton is not equivalent to the initial automaton, but we can obtain it easily by applying the operation $L(\PROJ{\xset'}(\phi')) = L(\cT)$, where $\phi'$ is the formula for automaton $\cT'$ and $\xset'$ is the set of variables of the initial automaton.

	Having our new strongly-deterministic timed CEA $\cT'$, we will separate it into two different timed CEAs $\cT_1$ and $\cT_2$ with respective formulas $\phi_1$ and $\phi_2$, such that $L(\phi_1 \kAND \phi_2) = L(\phi')$. 
	The idea is to separate the resets of $\cT$ between even and odd resets during a run. Then $\cT_1$ will do the resets and checks at even positions and $\cT_2$ will do the same but at odd positions. 
	The first automaton is $\cT_1 = (Q\times \{1, 2\}, \pset, \xset, \{z\}, \Delta_1, (q_0, 1), F \times \{1, 2\})$, where:
	\[
	\begin{array}{rclc}
		\Delta_1 & = & \{((p, 1), P, \gamma, L, \varnothing, (q, 2))\mid (p, P, \gamma, L, \{z\}, q) \in \Delta\} &  \cup \\
		& & \{((p, 2), P, \true, L, \{z\}, (q, 1))\mid (p, P, \gamma, L, \{z\}, q) \in \Delta\} & \cup \\
		& & \{((p, 1), P, \gamma, L, \varnothing, (q, 1))\mid (p, P, \gamma, L, \varnothing, q) \in \Delta\} & \cup \\
		& &  \{((p, 2), P, \true, L, \varnothing, (q, 2))\mid (p, P, \gamma, L, \varnothing, q) \in \Delta\}.
	\end{array}
	\] 
	This automaton only checks time-windows from resets that are in an even position on the run.

	The second automaton is $\cT_2 = (Q\times \{1, 2\}, \pset, \xset, \{z\}, \Delta_2,(q_0, 1), F \times \{1, 2\})$, where:
	\[
	\begin{array}{rclc}
		\Delta_2 & = & \{((p, 1), P, \true, L, \{z\}, (q, 2))\mid (p, P, \gamma, L, \varnothing, q) \in \Delta\} & \cup \\
		& & \{((p, 2), P, \gamma, L, \varnothing, (q, 1))\mid (p, P, \gamma, L, \{z\}, q) \in \Delta\} & \cup \\
		& & \{((p, 1), P, \true, L, \varnothing, (q, 1))\mid (p, P, \gamma, L, \varnothing, q) \in \Delta\} & \cup \\
		& &  \{((p, 2), P, \gamma, L, \varnothing, (q, 2))\mid (p, P, \gamma, L, \varnothing, q) \in \Delta\}. 
	\end{array}
	\]
	This automaton only checks time-windows from resets that are in an odd position on the run. These new timed CEAs are reset-distinct because there are no transitions that have a clock reset and a non-trivial clock condition, and the proof of equivalence is straightforward.
\end{proof}

It is important to note that the resulting reset-distinct automata are still k-check-bounded, strongly deterministic, have a single clock, and are disjunction free, because the transformations do not alter these properties.

The previous lemmas allow us to introduce the following lemma on transforming timed CEAs to timed CEL formulas:

\begin{lemma}
	Any single-clock timed CEA $\cT$ can be converted into an equivalent timed CEL formula.
\end{lemma}

The proof is straightforward. We will now transform the several-clock timed CEA into a timed CEL formula. Finally, using all the previous lemmas, we will prove the Proposition~\ref{pro:cea2cel}.

\begin{proof}[Proof of Proposition~\ref{pro:cea2cel}]
	We begin by transforming the timed CEA $\cT$ into a strongly deterministic automaton $\cT'$, by using the same method introduced earlier in Lemma~\ref{lemma:reset-distinct-AND}. Note that if $\semaux{\cT} = \semaux{\phi_\cT}$ and $\semaux{\cT'} = \semaux{\phi_{\cT'}}$, then $\semaux{\PROJ{\xset'}(\phi_{\cT'})} = \semaux{\phi_\cT}$, where $\xset'$ are the variables used in the automaton $\cT$. To be able to transform the automaton into a timed CEL formula, we will separate the new automaton $\cT'$ into several single-clock timed CEA $\cT_1'\dots \cT_n'$, such that the ``conjunction'' of $\sem{\cT_1'}, \dots, \sem{ \cT_n'}$ (i.e., $\kAND$) is equivalent to $\sem{\cT'}$. This can be done by separating the automaton into $n$ single-clock timed CEA, one for each different clock. Each automaton $\cT_i'$ will change all checks over a clock different to $z_i$ by $\TRUE$, leaving only the checks using the clock $z_i$. It is clear that the intersection of every automata has the same semantics as $\cT'$.

	We know that each single-clock automaton $\cT_1, \dots \cT_n$ can be converted into a timed CEL formula $\varphi_1, \dots \varphi_n$. So finally, the timed CEL formula for the full automaton will be:
	\[
	\varphi = \PROJ{\xset'}(\kAND_{i=1}^{n} \ \ \varphi_i)
	\]
	Note that the operators used for the construction of the formula are $\kOR$, $\PROJ{L}$, $\ssq$, $\sks$, $\kAS$, $\twin{...}{I}$ and $\kAND$. This does not use any of the operators in $\{;, +, \timesq{\sim c}, \timessq{I}, \timeks{I}, \timesks{I}\}$. 
\end{proof} 	
