\begin{algorithm*}[t]
	\caption{Methods for updating the CAECS. All of these methods return safe nodes. In this algorithm, $\getgadget(n)$ returns the largest valid gadget starting from the node $n$, and $\mergegadgets(g_1, g_2)$ returns a new gadget corresponding to $g_1\circ g_2$.}\label{alg:update-caecs}
