	\begin{varwidth}[t]{0.80\textwidth}
		\begin{algorithmic}[1]


			\LineComment{Creates a new bottom node}
			\Procedure{{\dbottom}}{$i$, $t_i$}%
			\State $b \gets \createbottom(i, t_i)$
			\State \Return $b$
			\EndProcedure	

			\State

			\LineComment{Returns the union of two nodes}
			\LineComment{Requires that $\max(n_1) = \max(n_2)$}
			\Procedure{{\dunion}}{$n_1$, $n_2$}
			\State $g_1 \gets \getgadget(n_1)$
			\State $g_2 \gets \getgadget(n_2)$
			\If {$\left(\begin{array}{l}
					\disbottom(\exit(g_1))\lor\\
					\disextend(\exit(g_1))\\
					\land \disbottom(\exit(g_2))\lor\\ \disextend(\exit(g_2))
				\end{array}\right)$}
			\State $u \gets \createunion()$
			\State $\dleft(u) \gets \entry(g_1)$
			\State $\dright(u) \gets \entry(g_2)$
			\State \Return $u$
			\ElsIf {$\left(\begin{array}{c}
					\disunion(\exit(g_1)) \\
					\land \disunion(\exit(g_2))
				\end{array}\right)$}
			\State $u_1, u_2, u_3 \gets \createunions()$
			\State $g_3 \gets \getgadget(\dleft(\exit(g_1)))$
			\State $g_4 \gets \getgadget(\dleft(\exit(g_2)))$
			\State $g_5 \gets \getgadget(\dright(\exit(g_1)))$
			\State $g_6 \gets \getgadget(\dright(\exit(g_2)))$
			\State $g_{1+3} \gets \mergegadgets(g_1, g_3)$
			\State $g_{2+4} \gets \mergegadgets(g_2, g_4)$
			\State $g_{1+5} \gets \mergegadgets(g_1, g_5)$
			\State $g_{2+6} \gets \mergegadgets(g_2, g_6)$
			\If{$\left(\begin{array}{c}
					\maxreset(\entry(g_{5}))\\
					 < \maxreset(\entry(g_{6}))
				\end{array}\right)$} \label{line:maxswap}
			\State $\swap(g_5, g_6)$
			\EndIf
			\State $\dright(u_1) \gets u_2$
			\State $\dright(u_2) \gets u_3$
			\State $\exit(g_{1+3}) \gets \exit(g_3)$
			\State $\exit(g_{2+4}) \gets \exit(g_4)$
			\State $\exit(g_{1+5}) \gets \exit(g_5)$
			\State $\exit(g_{2+6})\gets \exit(g_6)$
			\State $\dleft(u_1) \gets \entry(g_{1+3})$
			\State $\dleft(u_2) \gets \entry(g_{2+4})$
			\State $\dleft(u_3) \gets \entry(g_{1+5})$
			\State $\dright(u_3) \gets \entry(g_{2+6})$

			\State \Return $u_1$

			\algstore{myalg}


		\end{algorithmic}
	\end{varwidth}
