			\algrestore{myalg}
			\Else
			\If{$\disunion(\exit(g_1))$}
			\State $\swap(g_1, g_2)$
			\EndIf
			\State $u_1,u_2 \gets \createunions()$

			\State $g_3 \gets \getgadget(\dleft(\exit(g_2)))$
			\State $g_4 \gets \getgadget(\dright(\exit(g_2)))$

			\State $g_{2+3}\gets \mergegadgets(g_2, g_3)$
			\State $g_{2+4}\gets \mergegadgets(g_2, g_4)$
			\State $\dleft(u_1) \gets u_2$

			\State $\exit(g_{2+3}) \gets \exit(g_3)$
			\State $\exit(g_{2+4}) \gets \exit(g_4)$

			\State $\dleft(u_1) = \entry(g_1)$
			\State $\dleft(u_2) = \entry(g_{2+3})$
			\State $\dright(u_2) = \entry(g_{2+4})$
			\State \Return $u_1$

			\EndIf
			\EndProcedure

			\State


			\LineComment{Creates a new extended node}
			\Procedure{{\dextend}}{$n$, $j$, $L$}
			\State $e \gets \createextend(j, L)$
			\State $\dleft(e) \gets n$
			\State \Return $e$
			\EndProcedure

			\State

			\LineComment{Adds a new reset node}
			\Procedure{{\dreset}}{$n$, $t$}
			\State $g_1 \gets \createresetgadget(t)$
			\State $g_2 \gets \getgadget(n)$
			\State $g_{1+2}\gets \mergegadgets(g_1, g_2)$
			\State $\exit(g_{1+2}) \gets \exit(g_2)$
			\State \Return $\entry(g_{1+2})$
			\EndProcedure

			\State

			\LineComment{Adds a new clock-check node}
			\Procedure{{\dclockcheck}}{$n$, $t_0$, $c$}
			\If{$t_0 - \maxreset(n) > c$} \label{line:maxcheck}
			\State $n' \gets \createempty()$
			\State $\uleft(n') \gets n$
			\State \Return $n'$
			\EndIf
			\State $g_1 \gets \createclockcheckgadget(t_0, c)$
			\State $g_2 \gets \getgadget(n)$
			\State $g_{1+2}\gets \mergegadgets(g_1, g_2)$
			\State $\exit(g_{1+2}) \gets \exit(g_2)$
			\State \Return $\entry(g_{1+2})$
			\EndProcedure


		\end{algorithmic}
	\end{varwidth}
	\smallskip
\end{algorithm*}

\paragraph{Union-lists and their operations}
Now we define the second data structure for the streaming evaluation algorithm. 
We introduce the notion of \textit{union-list}, a structure to store the pointers from nodes of the CAECS to states of the automaton while reading the stream. The \textit{union-list} is a list $u_0\dots u_n$ of nodes of the CAECS. It is required that the first element of the union-list is the root of a type 1 structure, and that all the nodes comply with $\maxreset(u_0) \ge \maxreset(u_j)$ for all $j < n$ and $\maxreset(u_i)>\maxreset(u_{i+1})$ for all $1 \le i \le n-1$, meaning that the \textit{union-list} is ordered by strictly decreasing max-reset. Note that as the input automaton is monotonic, the order of the union list will allow us to easily discard nodes that will not satisfy a time constraint. Only the lower equal case is demonstrated as the greater equal case is analog, but ordered inversely.

The \textit{union-list} has 5 main methods to perform its updates: $\newul(u_0)$, $\insertul(ul, u)$, $\mergeul(ul)$, $\ulclockcheck(\ulist, t_0, c)$ and $\ulreset(\ulist, t)$. The first method, $\newul(u_0)$ creates a new \textit{union-list} with the node $u_0$. The node $u_0$ is required to be a type 1 structure to comply with the previously stated requirement. The second method, $\insertul(ul, u)$ inserts node $u$ in the \textit{union-list} so that the max-resets continue to be ordered. If there already is a node $u'\in ul$ such that $\maxreset(u') = j$, then the node $u'$ is replaced by the node returned by $\dunion(u, u')$. The third method, $\mergeul(ul)$, returns a new node $u''$ such that $\semauxop{u''} = \semauxop{u_0}\cup \dots \cup \semauxop{u_n}$, where $u_0\dots u_n$ are the nodes of the \textit{union-list}. More in detail, if the \textit{union-list} has only one element, it returns that element, and if it has $n>1$ elements it creates $n-1$ union nodes and places the \textit{union-list} nodes so that the time-ordered property is followed (as shown in Figure~\ref{fig:merge-ul}). The fourth method, $\ulclockcheck(\ulist, t_0, c)$, applies $\dclockcheck(n, t_0, c)$ to every node $n$ of the union-list, and returns a new union-list with the nodes in the same order, but filtering out the nodes that become empty nodes. If every node of the union list is an empty node after performing $\ulclockcheck$, then the union-list is deleted. It is important to note that as the union-list is time-ordered, then only the nodes to the right can be left as empty. It is also easy to note that the resulting union-list is also time-ordered, and the first node is the root of a type 1 structure.
The fifth method, $\ulreset(\ulist, t)$ applies $\dreset(n, t)$ to every node $n$ of the union-list. Then it creates a new union-list with the following procedure: first, it instantiates the union-list with the first resulting node as its first node (as it is guaranteed to have $\odepth \le 2$). Afterwards, it calls $\dunion$ repeatedly over the following nodes (as they have the same $\maxreset$), and leaves the resulting node as the second node of the new union-list. Finally, it returns the new union-list. That union-list is time-ordered because all of its nodes have the same $\maxreset$, and it is easy to see that its first node is the root of a type 1 structure (it contains no unions).
