%
\section{McKean--Pontryagin Minimum Principle} \label{sec:Hamiltonian}
%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

In this section, we develop a novel mean-field approach to the PMP starting from an Eulerian perspective in the spirit of ideal fluid dynamics \cite{Salmon88}. Specifically, we combine the HJB equation (\ref{eq:HJB}) and a Liouville equation for the flow of densities $\rho_t(x)$ under a single variational principle. In order to do so, we  assume that the initial states $X_0 = a$ in (\ref{eq:FSDE}) are no longer fixed but distributed instead according to a given distribution $p_0(x)$. Following \cite{Salmon88}, we then transform the variational principle into a Lagrangian framework in terms of evolving positions $X_t \in \mathbb{R}^{d_x}$ and momenta (co-states) $P_t \in \mathbb{R}^{d_x}$. These equations are Hamiltonian and provide the novel McKean--Pontryagin formulation. While we consider the finite horizon optimal control problem (\ref{eq:costJ}) in this section; an extension to infinite horizon optimal control problems can be found in Section \ref{sec:discounted}. 

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%
\subsection{Eulerian formulation}
%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

In this subsection, we develop a variational formulation for the HJB equation (\ref{eq:HJB}).
The first step is to formally decouple the diffusion term in (\ref{eq:HJB}) through an additional function $\phi_t$, i.e.,
\begin{subequations}
     \label{eq:HJB2}
     \begin{align}
-\partial_t v_t &= b \cdot \nabla_x v_t + \frac{1}{2} \Sigma : D_x^2 
\phi_t + c -  \frac{1}{2} \|RG(x)^{\rm T}\nabla_x v_t\|^2_R, \\
0&= \phi_t- v_t.
\end{align}
\end{subequations}
The second step is to introduce Lagrange multipliers $\rho_t(x)$ and $\beta_t(x)$ in order to enforce (\ref{eq:HJB2}) in terms of the action functional
\begin{subequations} \label{eq:action Euler}
\begin{align}
\mathcal{S}(v,\rho,\beta) &= -\int_0^T  \int_{\mathbb{R}^{d_x}} \left\{ \partial_t v_t + \nabla_x v_t \cdot b
+ c - \frac{1}{2}\|RG^{\rm T} \nabla_x v_t\|^2_R\right\} \rho_t {\rm d}x \,{\rm d}t \,+\\
&\qquad \qquad 
\int_0^T  \int_{\mathbb{R}^{d_x}} \left\{
\beta_t \cdot \nabla_x (\phi_t - v_t) + \frac{1}{2} \nabla_x \cdot (\Sigma \nabla_x \phi_t)\,
\right\} \rho_t {\rm d}x \,{\rm d}t \,+\\
&\qquad \qquad 
\int_{\mathbb{R}^{d_x}} \left\{
(v_T-f)\,\rho_T - v_0 p_0 \right\}{\rm d}x,
\end{align}
\end{subequations}
where we have used $\Sigma : D_x^2 v= \nabla_x \cdot (\Sigma \nabla_x v)$.

More specifically, the Lagrange multiplier $\beta_t$ enforces the constraint (\ref{eq:HJB2}b) (up to a constant), while the Lagrange multiplier $\rho_t$ enforces the HJB formulation (\ref{eq:HJB2}a). Furthermore, variation with respect to $v_t$ leads, after integration by parts, to the Liouville equation
\begin{equation} \label{eq:Liouville}
\partial_t \rho_t = -\nabla_x \cdot \left( \rho_t (b - \beta_t - GRG^{\rm T} \nabla_x v_t) \right), \qquad \rho_0 = p_0,
\end{equation}
in the density $\rho_t$. The associated ODE is given by
\begin{equation} \label{eq:ODE}
    \dot{X}_t = b(X_t) - \beta_t(X_t) - G(X_t) R G(X_t)^{\rm T} \nabla_x v_t(X_t), \qquad 
    X_0 \sim p_0.
\end{equation}

While (\ref{eq:HJB2}a) is obtained independently of the choice of $\beta_t$, a further variation with respect to $\phi_t$ leads to
\begin{equation}
-\nabla_x \cdot (\rho_t \beta_t) + \frac{1}{2} \nabla_x \cdot (\Sigma \nabla_x \rho_t)=0
\end{equation}
and, hence, to
\begin{equation} \label{eq:beta natural}
\beta_t = \frac{1}{2}\Sigma \nabla_x \log \rho_t.
\end{equation}
With this choice of $\beta_t$, the associated Liouville equation (\ref{eq:Liouville}) turns into
the Fokker--Planck equation (\ref{eq:FPE}) for the SDE (\ref{eq:FSDE}). In other words, (\ref{eq:ODE}) and (\ref{eq:beta natural}) lead to an ODE mean-field reformulation of the SDE (\ref{eq:FSDE}) as considered previously, for example, in \cite{MRO20}.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%
\subsection{Lagrangian formulation}
%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

Let us now convert (\ref{eq:action Euler}) into a corresponding Lagrangian formulation \cite{Salmon88}. Let $X_\tau(a)$ denotes the solution of (\ref{eq:ODE}) at time $\tau=t$
with initial condition $X_0 = a$. Here we have introduced $\tau$ as a new time variable in order to distinguish the two time derivatives arising from the Lagrangian (total time-derivative) and Eulerian (partial time-derivative) perspective. Furthermore, the initial conditions $a \sim p_0$ may be viewed as labels in the sense of Lagrangian fluid dynamics. We therefore consider functions $x(a)$, $p(x)$, $u(a)$, and $\beta(a)$ and note that
\begin{equation}
\int_{\mathbb{R}^{d_x}} g(X_\tau(a))\,p_0 (a) {\rm d}a = \int_{\mathbb{R}^{d_x}} g(x)\,\rho_t(x){\rm d}x
\end{equation}
for any function $g(x)$. Next we convert (\ref{eq:action Euler}) into its corresponding Lagrangian formulation and consider in particular
\begin{subequations}
    \begin{align}
       \mathcal{I} &:= -\int_0^T \int_{\mathbb{R}^{d_x}}
         \partial_t v_t(x) \, \rho_t(x) {\rm d}x    \,{\rm d}t  \\
         &=-\int_0^T \int_{\mathbb{R}^{d_x}}
         \partial_t v_t(X_{\tau=t}(a)) \, p_0(a) {\rm d}a    \,{\rm d}t\\
        &= \int_0^T \int_{\mathbb{R}^{d_x}} 
        P_\tau(a) \cdot \dot{X}_\tau(a) \, p_0(a){\rm d}a \,{\rm d}\tau -
        \int_{\mathbb{R}^{d_x}} \left(v_T(X_T(a)) - v_0(X_0(a))\right) \,p_0(a){\rm d}a,
    \end{align}
\end{subequations}
where we have introduced the momentum variable (co-state)
\begin{equation}
P_\tau(a) = \nabla_x v_\tau(X_\tau(a)),
\end{equation}
which amounts to an irrotational fluid in the sense of \cite{Salmon88}. Here
we have used
\begin{equation}
\partial_t v_t(x=X_{\tau=t}(a)) = \partial_\tau v_\tau (X_\tau(a)) -
\nabla_x v_\tau(X_\tau(a))\cdot \dot{X}_\tau (a)  
\end{equation}
as well as the fact that the total time derivative $\partial_\tau v_\tau(X_\tau(a))$ contributes boundary terms only. Furthermore,
\begin{subequations}
\begin{align}
    &\int_{\mathbb{R}^{d_x}}
\beta_t(x) \cdot \nabla_x (\phi_t(x) - v_t(x) )\,
\rho_t(x) {\rm d}x = \\
& \qquad \qquad \int_{\mathbb{R}^{d_x}}
\tilde \beta_\tau(a) \cdot \nabla_x \left( \phi_\tau (X_\tau(a)) - 
X_\tau(a) \cdot P_\tau(a)  \right)\,
p_0(a) {\rm d}a
\end{align}
\end{subequations}
with $\tilde \beta_\tau (a) = \beta_t(X_\tau(a))$.

The equations of motion in $(X_\tau,P_\tau)$ arise now from the phase space action principle \cite{Dirac,holmI} applied to 
\begin{equation} \label{eq:action S}
\mathcal{S}(X,P,\beta) = \int_{\mathbb{R}^{d_x}} \left\{ \int_0^T
\left(P_\tau \cdot \dot{X}_\tau - 
H (X_\tau,P_\tau,\beta_\tau) \right) {\rm d}\tau - f(X_T)  \right\} p_0 {\rm d}a
\end{equation}
with Hamiltonian density
\begin{subequations} \label{eq:reduced Hamiltonian density}
\begin{align}
H(x,p,\beta)(a) &:= -\frac{1}{2} \|R G(x(a))^{\rm T}p(a)\|^2_R + p(a)^{\rm T} b(x(a)) + c(x(a))  \,+  \\
& \qquad \qquad  \beta(a) \cdot \nabla_x \left(\phi(x(a)) - x(a)^{\rm T} p(a)\right)
+ \frac{1}{2}\Sigma : D_x^2 \phi(x(a)).
\end{align}
\end{subequations} 
The desired optimal closed loop control law (\ref{eq:optimal control law}) is provided by
\begin{equation} \label{eq:U}
    u_\tau(X_\tau(a)) = -R G(X_\tau(a))^{\rm T}P_\tau(a).
\end{equation}

Upon introducing the generator
\begin{equation} \label{eq:generator}
\mathcal{L}_\beta g = \beta \cdot \nabla_x g 
+ \frac{1}{2} \Sigma : D_x^2 g
\end{equation}
and
\begin{equation}
g(x) = \phi(x)-x^{\rm T} p ,
\end{equation}
we can rewrite (\ref{eq:reduced Hamiltonian density}) in more compact form as
\begin{subequations} \label{eq:reduced Hamiltonian density II}
\begin{align}
H(x,p,\beta)(a) &:= -\frac{1}{2} \|R G(x(a))^{\rm T}p(a)\|^2_R + p(a)^{\rm T} b(x(a))   + c(x(a)) \,+  \\
& \qquad \qquad \mathcal{L}_\beta \left(\phi(x(a))-x(a)^{\rm T} p(a)\right).
\end{align}
\end{subequations} 
Variation with respect to $\beta_\tau$ leads to the constraint 
\begin{equation} \label{eq:constraint}
\nabla_x \phi_\tau(X_\tau(a)) = P_\tau(a),
\end{equation}
which defines the function $\phi_\tau(x)$ in terms of $X_\tau(a)$ and $P_\tau(a)$ up to a constant.  Using the thus specified gradient of $\phi_\tau(x)$, we obtain the closed loop control
\begin{equation} \label{eq: control phi}
u_\tau(x) = -RG(x)^{\rm T} \nabla_x \phi_\tau(x).
\end{equation}

Finally, variations with respect to $X_\tau$ and $P_\tau$ lead to the Hamiltonian evolution equations 
\begin{subequations} \label{eq:PMP}
    \begin{align}
\dot{X}_\tau(a) &= \nabla_p H(X_\tau(a),P_\tau(a),\beta_\tau(a)) ,\\
-\dot{P}_\tau(a) &= \nabla_x H(X_\tau(a),P_\tau(a),\beta_\tau(a))
\end{align}
\end{subequations}
for each $a \in \mathbb{R}^{d_x}$. The boundary conditions are $X_0(a) = a \sim p_0$ and $P_T(a) = \nabla_x f(X_T(a))$. The equations (\ref{eq:PMP}) are of mean-field type through $\phi_t(x)$, which is determined by the constraint (\ref{eq:constraint}).

Dropping labels $a \in \mathbb{R}^{d_x}$ from now on and denoting time by $t$ again, the Hamiltonian equations of motion (\ref{eq:PMP}) become
\begin{subequations} \label{eq:Hamiltonian ODE}
    \begin{align}
        \dot{X}_t &= b(X_t) - G(X_t)RG(X_t)^{\rm T} P_t -  \beta_t \\
        &= b(X_t) - G(X_t)R G(X_t)^{\rm T}P_t - \mathcal{L}_{\beta_t}X_t,\\
        -\dot{P}_t 
        &= \left(D_x b(X_t)\right)^{\rm T}P_t 
        \,+ \\
        &\qquad \qquad \nabla_x \left\{ c(X_t) - \frac{1}{2} 
        \|RG(X_t)^{\rm T}P_t\|^2_R +  \mathcal{L}_{\beta_t} (\phi_t(X_t)-X_t\cdot P_t)\right\}\\
        &= \left(D_x b(X_t)\right)^{\rm T}P_t 
        - \frac{1}{2} \nabla_x 
        \|RG(X_t)^{\rm T}P_t\|^2_R + \nabla_x c(X_t) + \mathcal{L}_{\beta_t} \nabla_x \phi_t(X_t),
    \end{align}
\end{subequations}
which are to be compared to the classical PMP formulation (\ref{eq:deterministic PMP}). The only new terms arise in connection with the generator $\mathcal{L}_{\beta_t}$.


The following theorem provides the key result with regard to the gauge variable $\beta_t$ and demonstrates that (\ref{eq:Hamiltonian ODE}) indeed delivers the desired extension of the PMP to stochastic optimal control problems.

\begin{theorem} \label{theorem1}
For any choice of the gauge variable $\beta_t$, the resulting function $\phi_t(x)$
satisfies
\begin{equation}
    \nabla_x \phi_t(x) = \nabla_x v_t(x)
\end{equation}
where $v_t(x)$ is the value function satisfying the  HJB equation (\ref{eq:HJB}).
\end{theorem}

\begin{proof}
Let us derive the evolution equation for $\nabla_x \phi_t(x)$ implied by (\ref{eq:constraint}):
\begin{subequations} \label{eq:proof1}
    \begin{align}
        -\partial_t \nabla_x \phi_t(X_t) &= D_x^2 \phi_t(X_t)\dot{X}_t -\dot{P}_t\\
        &= D_x^2 \phi_t(X_t)\left( b(X_t) - G(X_t)R^{-1}G(X_t)^{\rm T}P_t - \beta_t\right) \,+\\
        &\qquad \frac{1}{2} \nabla_x  (\Sigma : D_x^2\phi_t(X_t)) + \nabla_x c(X_t)  -\frac{1}{2} \nabla_x \|RG(X_t)^{\rm T}P_t\|_R^2 
        \,+\\
        &\qquad \left(D_x b(X_t)\right)^{\rm T}P_t
        + D_x^2 \phi_t(X_t)\beta_t  \\
        &= D_x^2 \phi_t(X_t) \,b(X_t) -\frac{1}{2} \nabla_x \|R G(X_t)^{\rm T}\nabla_x \phi_t(X_t)\|^2_R 
        + \nabla_x c(X_t)\,+\\
        &\qquad 
        \frac{1}{2} \nabla_x  (\Sigma : D_x^2 \phi_t(X_t))+
        \left(D_x b(X_t) \right)^{\rm T}\nabla_x \phi_t(X_t)   .
    \end{align}
\end{subequations}
Hence, since it follows that $\tilde y_t :=\nabla_x \phi_t$ satisfies the reverse time partial differential equation
\begin{equation}
    -\partial_t \tilde y_t = \nabla_x (\tilde y_t \cdot b) + \frac{1}{2} 
    \nabla_x (\Sigma: D_x \tilde y_t)  + \nabla_x c - \frac{1}{2}\nabla_x \|RG^{\rm T}\tilde y_t\|^2_R
\end{equation}
and $\tilde y_T = \nabla_x f$, we find from (\ref{eq:Pontryagin}) that $\tilde y_t = y_t$ regardless of the choice of the gauge function $\beta_t$. 
\end{proof}


In line with (\ref{eq:beta natural}), a natural choice for the gauge function is
\begin{equation} \label{eq:natural beta 2}
    \beta_t = \frac{1}{2}\Sigma \nabla_x \log \rho_t(X_t),
\end{equation}
where $\rho_t(x)$ denotes the law of $X_t$ as defined by (\ref{eq:ODE}). This choice leads to
\begin{equation} \label{eq:natural generator}
    \mathcal{L}_{\beta_t}g =  -\frac{1}{2}\Sigma \nabla_x \log \rho_t \cdot \nabla_x g + \frac{1}{2} \Sigma : D_x^2 g,
\end{equation}
which is the generator of a reversible diffusion process with invariant measure $\rho_t$ \cite{Pavliotis2016}. Since $\mathcal{L}_{\beta_t}^\dagger \rho_t = 0$ for the dual operator $\mathcal{L}_{\beta_t}^\dagger$ \cite{Pavliotis2016}, this is also the choice of $\beta_t$ which makes the variation with respect to $\phi_t$ vanish. We recall that this choice of $\beta_t$ leads to $\rho_t = \pi_t$ with $\pi_t$ the law of $X_t$ arising from the SDE (\ref{eq:FSDE}).

Alternatively, consider 
\begin{equation} \label{eq:beta decouple}
\beta_t = -G(X_t) R G(X_t)^{\rm T} P_t,
\end{equation}
which eliminates the control from the evolution equation in $X_t$ since
\begin{equation}
G(X_t) U_t = -G(X_t) RG(X_t)^{\rm T} P_t = \beta_t.
\end{equation}
Hence a single forward and reverse time simulation of 
\begin{subequations} 
    \begin{align}
        \dot{X}_t &= b(X_t) ,\\
        -\dot{P}_t &= \left(D_x b(X_t) \right)^{\rm T}P_t 
        -\frac{1}{2} \nabla_x \|RG(X_t)^{\rm T} \nabla_x \phi_t(X_t)\|^2_R
        \,+\\ &\qquad \qquad \nabla_x c(X_t) + \frac{1}{2} \nabla_x  (\Sigma : D_x^2 \phi_t(X_t))
    \end{align}
\end{subequations}
subject to $X_0 =a \sim p_0$ and $P_T(a) = \nabla_x f(X_T(a))$ solves the stochastic optimal control problem. We note that such a decoupling is possible even when $\Sigma$ is singular or even zero. This is in difference to the classical as well as the stochastic PMP \cite{Carmona}.

Both choices for the gauge variable can also be combined into
\begin{equation}
    \beta_t = \frac{1}{2}\Sigma \nabla_x \log \rho_t(X_t) -
    G(X_t)RG(X_t)^{\rm T} P_t - G(X_t) u_t^{\rm ref}(X_t)  ,
\end{equation}
where $u_t^{\rm ref}(x)$ is a known reference control; if available. In the context of NMPC \cite{MPC,Allgower}, such a control could arise from the previous receding horizon control window.

