\section{Discounted cost optimal control problems} \label{sec:discounted}
%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

We now consider infinite horizon optimal control problems with discounted cost function (\ref{eq:costJ infinite}). Such problems can be dealt with by simply introducing the damping term $-\gamma P_t$ into the evolution equation for the momentum variable $P_t$ \cite{Carmona}. The boundary condition for $P_T$ is replaced by the transversality condition
\begin{equation}
\lim_{T\to\infty} e^{-\gamma T}P_T(a)\cdot X_T(a) = 0,
\end{equation}
which follows from (\ref{eq:action S}) adapted to the case of discounted cost; i.e.
\begin{equation} \label{eq:discount action}
    \mathcal{S}(X,P,\beta) =\int_{\mathbb{R}^{d_x}}
    \left\{ \int_0^\infty e^{-\gamma t}\left(P_t^{\rm T} \dot{X}_t - 
    H(X_t,P_t,\beta_t) 
    \right) {\rm d}t\right\} p_0 {\rm d}a,
\end{equation}
and the fact that boundary terms arising from integration by parts should vanish.

A formal derivation of the action function (\ref{eq:discount action}) can again
start from a reformulation of the associated HJB equation:
\begin{subequations}
     \label{eq:HJB2d}
     \begin{align}
-\partial_t v_t &=  -\gamma v_t + b \cdot \nabla_x v_t + \frac{1}{2} \nabla_x \cdot( \Sigma 
\nabla_x \phi_t) + c -  \frac{1}{2} \|RG(x)^{\rm T}\nabla_x v_t\|^2_R, \\
0&= \phi_t-v_t.
\end{align}
\end{subequations}
The second step is to introduce Lagrange multipliers $\rho_t$ and $\beta_t$ in order to enforce (\ref{eq:HJB2d}) in terms of the action functional
\begin{subequations} \label{eq:action Euler discount}
\begin{align}
\mathcal{S}(\tilde v,\rho,\beta) &= -\int_0^T  \int_{\mathbb{R}^{d_x}} \left\{ \partial_t \tilde v_t  + \nabla_x \tilde v_t \cdot b
+ e^{-\gamma t}c - \frac{e^{\gamma t}}{2}\|RG^{\rm T} \nabla_x \tilde v_t\|^2_R\right\} \rho_t {\rm d}x \,{\rm d}t \,+\\
&\qquad \qquad 
\int_0^T  \int_{\mathbb{R}^{d_x}} \left\{
 \beta_t \cdot \nabla_x (\tilde \phi_t - \tilde v_t) + \frac{1}{2} \nabla_x \cdot (\Sigma \nabla_x \tilde \phi_t)\right\}
\rho_t {\rm d}x \,{\rm d}t.
\end{align}
\end{subequations}
Here we have scaled the value function by $e^{-\gamma t}$; i.e.~$\tilde v_t = e^{-\gamma t}v_t$. After switching to the Lagrangian framework, we undo the scaling in
$\tilde P_t = \nabla_x \tilde v_t$ to obtain the action functional (\ref{eq:discount action}). The associated equations of motion are
\begin{subequations} \label{eq:PMP_infinite}
    \begin{align}
        \dot{X}_t&= \nabla_p H(X_t,P_t,\beta_t),\\
        -\dot{P}_t &= -\gamma P_t
        + \nabla_x H(X_t,P_t,\beta_t).
    \end{align}
\end{subequations}
The evolution equations (\ref{eq:PMP_infinite}) are still posed as a boundary value problem with (\ref{eq:PMP_infinite}a) solved forward in time and (\ref{eq:PMP_infinite}b) backward in time, respectively.

We call a solution of (\ref{eq:PMP_infinite}) with $\partial_t \phi_t  = 0$ a steady state solution and denote it by $\hat \phi$. Note that the positions $X_t$ can still undergo a time evolution; but need to satisfy
\begin{equation} \label{eq:steady state evolution}
    \dot{P}_t = D_x^2 \hat \phi (X_t) \dot{X}_t,
\end{equation}
which follows from (\ref{eq:constraint}). If we are interested in approximating such steady
state solutions, we can run both equations forward in time by replacing $\dot{P}_t$ by $-\dot{P}_t$ in (\ref{eq:PMP_infinite}) and adding an appropriate advection term, which results in
\begin{subequations} \label{eq:PMP_forward}
    \begin{align}
        \dot{X}_t&= \nabla_p H(X_t,\Pi_t,\beta_t),\\
        \dot{\Pi}_t &= -\gamma \Pi_t
        + \nabla_x H(X_t,\Pi_t,\beta_t) + 2 D_x^2 \phi_t(X_t)\dot{X}_t.
    \end{align}
\end{subequations}
Here we have introduced new momenta (co-states) $\Pi_t$ for clarity of presentation.

\begin{theorem}
Let us assume that $(X_t,P_t)$, $t\in \mathbb{R}$ represent a steady state solution of (\ref{eq:PMP_infinite}); i.e., (\ref{eq:steady state evolution}) holds for suitable $\hat \phi$. Then solutions $(X_t,\Pi_t)$ of (\ref{eq:PMP_forward}), $t\ge 0$, with initial condition $(X_0,\Pi_0) = (X_0,P_0)$ also represent a steady state solution.
\end{theorem}

\begin{proof}
Since (\ref{eq:PMP_forward}) implies
\begin{equation} \label{eq:constraint dot}
    \dot{\Pi}_t = -\partial_t \nabla_x \phi_t(X_t) + D_x^2 \phi_t(X_t) \dot{X}_t
\end{equation}
with $-\partial_t \phi_t(X_t)$ given by (\ref{eq:proof1}),
it follows from $\phi_t = \hat \phi$ that 
\begin{equation}
    \dot{\Pi}_t = D_x^2 \hat \phi(X_{t})\dot{X}_{t}
\end{equation}
in agreement with (\ref{eq:steady state evolution}). In other words, 
$(X_t,P_t) = (X_t,\Pi_t)$ for all $t\ge 0$ when initialized in steady state 
and steady state solutions are preserved under (\ref{eq:PMP_forward}).
\end{proof}

We close this section by mentioning that (\ref{eq:PMP_forward}) is related to iterative approaches for approximating the stationary value function (or $Q$ function) used in reinforcement learning and which are based on the stationary Bellman equation \cite{Meyn}. Our approach targets instead the momenta (gradients of the value function) directly. This has been found beneficial from a theoretical perspective \cite{Carmona} and provides flexibility in terms of constraints added on the states and controls. It is also often found that approximating the gradient directly instead of its underlying  function is more robust computationally. Compare, for example, density versus score estimation \cite{MRO20,GLMRT25}.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%
\section{Linear control problems}
%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%

We analyze the proposed formulations in the setting of controlled linear SDEs
\begin{equation}
{\rm d}X_t = AX_t + G U_t + \Sigma^{1/2}{\rm d}B_t, \qquad X_0 \sim {\rm N}(0,C_0)
\end{equation}
for infinite time discounted cost functional (\ref{eq:costJ infinite}) with running cost
\begin{equation}
c(x) = \frac{1}{2}x^{\rm T}C x
\end{equation}
and $R=I$. We write the function $\phi_t(x)$ as
\begin{equation}
    \phi_t(x) = \frac{1}{2}x^{\rm T}\Omega_t x.
\end{equation}
With this {\it ansatz} the Hamiltonian equations of motion (\ref{eq:PMP}) take the form
\begin{subequations}
    \begin{align}
        \dot{X}_t &= AX_t - G G^{\rm T}P_t - \frac{1}{2}\beta_t,\\
        -\dot{P}_t &= -\gamma P_t + A^{\rm T}P_t + CX_t + \frac{1}{2} \Omega_t \beta_t.
    \end{align}
\end{subequations}
The choice (\ref{eq:natural beta 2}) for the gauge variable $\beta_t$ leads to
\begin{equation}
    \beta_t = -\frac{1}{2}\Sigma C_t^{-1}X_t
\end{equation}
with $C_t$ the covariance matrix of the Gaussian distributed $X_t$ with mean zero. 
The constraint (\ref{eq:constraint}) becomes
\begin{equation}
P_t = \Omega_t X_t,
\end{equation}
which yields
\begin{subequations}
    \begin{align}
        -\dot{\Omega}_t X_t &=  \Omega_t \dot{X}_t-\dot{P}_t\\
        &=\Omega_t \left(AX_t - G G^{\rm T}P_t - \frac{1}{2}\beta_t\right)
        -\gamma P_t + A^{\rm T}P_t + CX_t + \frac{1}{2} \Omega_t \beta_t\\
        &= \left(-\gamma \Omega_t + \Omega_t A - G G^{\rm T}\Omega_t + A^{\rm T}\Omega_t + C \right) X_t
    \end{align}
\end{subequations}
and from which we can read off the backward Riccati equation for $\Omega_t$ \cite{Carmona}:
\begin{equation}
-\dot{\Omega} = -\gamma \Omega_t + \Omega_t A + A^{\rm T}\Omega_t - \Omega_t G G^{\rm T}\Omega_t  + C.
\end{equation}


Let us now investigate the forward evolution equations (\ref{eq:PMP_forward}). We obtain
\begin{subequations}
    \begin{align}
        \dot{X}_t &= AX_t - G G^{\rm T}P_t - \frac{1}{2}\beta_t\\
        \dot{\Pi}_t &= -\gamma \Pi_t + A^{\rm T}\Pi_t + CX_t + \frac{1}{2} \Omega_t \beta_t 
        + 2 \Omega_t \dot{X}_t
    \end{align}
\end{subequations}
subject to the constraint $\Pi_t = \Omega_t X_t$. This time we obtain
\begin{subequations}
    \begin{align}
        \dot{\Omega}_t X_t &=  -\Omega_t \dot{X}_t+\dot{\Pi}_t\\
        &= \Omega_t \left(AX_t - G G^{\rm T}\Pi_t - \frac{1}{2}\beta_t\right)
        - \gamma\Pi_t + A^{\rm T}\Pi_t + CX_t + \frac{1}{2} \Omega_t \beta_t \\
        &= \left(- \gamma \Omega_t + \Omega_t A  + A^{\rm T}\Omega_t - \Omega_t G G^{\rm T}\Omega_t + C \right) X_t
    \end{align}
\end{subequations}
and read off the forward Riccati equation
\begin{equation}
\dot{\Omega} = -\gamma \Omega_t + \Omega_t A + A^{\rm T}\Omega_t - G G^{\rm T}\Omega_t  + C.
\end{equation}
Clearly, the forward Riccati equation is stable if and only if the backward Riccati equation is stable and their stationary solutions agree. Of course, our approach is to propagate $X_t$ and $\Pi_t$ and to then find the appropriate $\Omega_t$ by enforcing the constraint $\Pi_t = \Omega_t X_t$ via regression; i.e.
\begin{equation}
\Omega_t = \arg \min_{\Omega\in \mathbb{R}^{d_x\times d_x}} \mathbb{E}\left[ \|\Pi_t - \Omega X_t\|^2\right].
\end{equation}
We describe numerical implementations for the general nonlinear setting in the subsequent section.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%
\section{Numerical implementation} \label{sec:implementation}
%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

Numerical implementations of (\ref{eq:Hamiltonian ODE}) rely on a set of particles $(X_t^{(i)},P_t^{(i)})$, $i=1,\ldots,M$, which evolve according to
\begin{subequations} \label{eq:interacting Hamiltonian ODE}
    \begin{align}
        \dot{X}_t^{(i)} &= \nabla_{P_i} \mathcal{H}(\{X_t^{(j)}\},\{P_t^{(j)}\}),\\
        -\dot{P}_t^{(i)} &= \nabla_{X_i} \mathcal{H}(\{X_t^{(j)}\},\{P_t^{(j)}\})
    \end{align}
\end{subequations}
for appropriate Hamiltonian $\mathcal{H}$ and subject to boundary conditions
\begin{equation}
X_0^{(i)} = a_i \sim \pi_0, \qquad
P_T^{(i)} = -\nabla_x f(X_T^{(i)}).
\end{equation}
In order to get closed form ODEs, we need to specify $\mathcal{H}$ which involves approximating 
$\phi_t(x)$ as defined by the constraint (\ref{eq:constraint}). We discuss a few choices below.
These approximations apply equally well to the discounted cost formulation (\ref{eq:PMP_forward}) of the McKean--Pontryagin minimum principle from Section \ref{sec:discounted}.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{A regression formulation}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
The constraint (\ref{eq:constraint}) can be approximated via the method of least squares. For example, one could use
\begin{equation} \label{eq:least squares}
\mathcal{V}_t(\gamma_t) = \frac{1}{2M} \sum_{i=1}^M
\| P_t^{(i)} - \nabla_x \tilde \phi(X_t^{(i)};\gamma_t)\|^2
\end{equation}
for suitable class of functions $\tilde \phi(\cdot;\gamma)$ parametrized by $\gamma \in \mathbb{R}^{d_\gamma}$. This approach is not strictly variational unless $\Sigma = 0$; but it can be applied to any choice of the gauge variable $\beta_t(a)$. See Section \ref{sec:variational} below for a strictly variational approach.

As a specific example, consider 
\begin{equation}
    \beta_t^{(i)} = \frac{1}{2} G(X_t^{(i)})R^{-1}G(X_t^{(i)})(A_tX_t^{(i)}+ c_t-P_t^{(i)})
\end{equation}
together with a bilinear {\it ansatz}
\begin{equation}
\tilde \phi(x;\gamma) = \frac{1}{2} x^{\rm T}Ax + x^{\rm T}c,
\end{equation}
which makes the term depending on $\Sigma$ in (\ref{eq:reduced Hamiltonian density}) vanish. Thus the Hamiltonian (\ref{eq:reduced Hamiltonian density}) gives rise to
\begin{subequations}
    \begin{align}
\mathcal{H}_t(\{X_t^{(j)}\},\{P_t^{(i)}\})
&= \sum_{i=1}^M \left\{ -\frac{1}{2}\|R G(X_t^{(i)})^{\rm T}P_t^{(i)}\|^2_R + 
(P_t^{(i)})^{\rm T} b(X_t^{(i)}) + c(X_t^{(i)})  \,+ \right.\\
&\qquad \qquad 
\left. \frac{1}{2} \|R G(X_t^{(i)})^{\rm T}(A_tX_t^{(i)}-c_t - P_t^{(i)})\|^2_R \right\}
\end{align}
\end{subequations}
and the equations of motion (\ref{eq:interacting Hamiltonian ODE}) reduce to
\begin{subequations} \label{eq:linear regression formula}
    \begin{align}
        \dot{X}_t^{(i)} &=
b(X_t^{(i)}) - G(X_t^{(i)}) R G(X_t^{(i)})^{\rm T}\left(A_t X_t^{(i)} + c_t\right),\\
-\dot{P}_t^{(i)} &=
(D_x b(X_t^{(i)}))^{\rm T}P_t^{(i)}
+ \nabla_x c(X_t^{(i)}) +
\frac{1}{2}\nabla_x \|R G(X_t^{(i)})^{\rm T}
(A_tX_t^{(i)}+c_t)\|_R^2\,-\\
&\qquad \qquad 
\nabla_x (G(X_t^{(i)})P_t^{(i)})^{\rm T} R G(X_t^{(i)})^{\rm T}(A_t X_t^{(i)}+c_t)
    \end{align}
\end{subequations}
with $A_t$ and $c_t$ determined by
\begin{equation}
A_t = C_t^{px}(C_t^{xx})^{-1}, \qquad
c_t = m^p_t-A_t m^x_t.
\end{equation}
Here $C_t^{px}$ and $C_t^{xx}$ denote the empirical covariance matrices between $\{P_t^{(i)}\}$ and $\{X_t^{(i)}\}$, and $\{X_t^{(i)}\}$ with itself, respectively. The empirical mean of $\{X_t^{(i)}\}$ and $\{P_t^{(i)}\}$, respectively, is denoted by $m_t^x$ and $m_t^p$, respectively. Note that $A_t$ is not symmetric in general; but can be made symmetric via $1/2(A_t^{\rm T} + A_t)$.

Formulation (\ref{eq:linear regression formula}) simplifies further in case $G$ does not depend on $x$; i.e.
\begin{subequations} 
    \begin{align}
        \dot{X}_t^{(i)} &=
b(X_t^{(i)}) - G R G^{\rm T}\left(A_t X_t^{(i)} + c_t\right),\\
-\dot{P}_t^{(i)} &=
(D_x b(X_t^{(i)}))^{\rm T}P_t^{(i)}
+ \nabla_x c(X_t^{(i)}) + A_t^{\rm T}G^{\rm T} R G^{\rm T}(A_t X_t^{(i)}+c_t-P_t^{(i)}).
    \end{align}
\end{subequations}

While the regression approach can be combined with any choice of $\beta_t$, the following two approaches rely on the specific choice (\ref{eq:natural beta 2}).

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%
\subsection{Discrete Schr\"odinger bridge approximation} 
\label{sec:DM}
%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
Let us consider (\ref{eq:reduced Hamiltonian density II}) with $\beta_t$ given by (\ref{eq:natural beta 2}) in more detail. We replace the resulting generator 
(\ref{eq:natural generator}) by a discrete Schr\"odinger bridge approximation $m_t^{(ij)}$ \cite{MarshallCoifman,WR20,GLRY24} over the set of particles $\{X_t^{(j)}\}$ giving rise to
\begin{subequations}
\begin{align}
\mathcal{H}(\{X_t^{(j)}\},\{P_t^{(j)}\}) &= \frac{1}{M}
\sum_{i=1}^M
\left\{ -\frac{1}{2}\|RG(X_t^{(i)})^{\rm T}P_t^{(i)}\|_R^2 +
P_t^{(i)} \cdot b(X_t^{(i)}) 
  \right\} \,+\\
& \qquad \qquad \frac{1}{M} \sum_{i=1}^M \left\{
 S_t^{(i)}(\{X_t^{(j)}\})+\beta_t^{(i)}\cdot P_t^{(i)} + c(X_t^{(i)}) \right\}
 \end{align}
\end{subequations}
with 
\begin{equation}
    \beta_t^{(i)} := -\sum_{i=1}^M m_t^{(ij)} X_t^{(j)}
\end{equation}
and
\begin{equation}
    S_t^{(i)}(\{X_t^{(j)}\}) := \sum_{j=1}^M m_t^{(ij)} \phi_t(X_t^{(j)}).
\end{equation}
The coefficients $m_t^{(ij)}\ge 0$ are defined by
\begin{equation}
    m_t^{(ij)} = \frac{1}{\varepsilon} \left( v_t^{(i)} d_t^{(ij)} v_t^{(j)} - \delta_{ij}\right), \qquad d_t^{(ij)} = 
    e^{-\frac{1}{2\varepsilon}\|X_t^{(i)}-X_t^{(j)}\|_\Sigma^2},
\end{equation}
with $\{v_t^{(i)}\}$ chosen such that 
\begin{equation}
\sum_i m_t^{(ij)} = \sum_j m_t^{(ij)} = 0.
\end{equation}
Here $\delta_{ij}$ denotes the Kronecker delta function; i.e., $\delta_{ij} = 1$ if $i=j$ and $\delta_{ij} = 0$ otherwise. The regularization parameter $\varepsilon>0$ needs to be chosen appropriately \cite{WR20}. A particularly elegant formulation arises from the choice $\varepsilon = \Delta t$ with $\Delta t>0$ the step-size of an Euler discretization of the Hamiltonian equations of motion \cite{GLRY24}. A fast iterative algorithm for computing the coefficients $v_t^{(i)}\ge 0$ has been given in \cite{MarshallCoifman,WR20}.

Writing down the associated Hamiltonian equations of motion (\ref{eq:interacting Hamiltonian ODE}), we obtain a fully variational implementation of the proposed McKean--Pontryagin minimum principle. However, computing gradients of $m_t^{(ij)}$ with respect to particle positions $X_t^{(k)}$ is non-trivial and we use the simpler approximation
\begin{subequations}
    \begin{align}
        \dot{X}_t^{(i)} &= b(X_t^{(i)}) - G(X_t^{(i)})R G(X_t^{(i)})^{\rm T} P_t^{(i)}
        - \sum_{j=1}^M m_t^{(ij)}X_t^{(j)},\\
        -\dot{P}_t^{(i)} &= (Db(X_t^{(i)})^{\rm T}P_t^{(i)} +\nabla_x c(X_t^{(i)})
        - \frac{1}{2} \nabla_x 
        \|RG(X_t^{(i)})^{\rm T}P_t^{(i)}\|^2_R + \sum_{j=1}^M m_t^{(ij)}P_t^{(j)}.
    \end{align}
\end{subequations}

The discrete Schr\"odinger bridge approximation does not require an explicit approximation of $\phi_t(x)$, which simplifies numerical implementations. If $\nabla_x \phi_t(x)$ is needed it can be obtained via (\ref{eq:least squares}).




%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%
\subsection{Variational approach} \label{sec:variational}
%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

A particularly versatile approach is to approximate $\beta_t$ and $\phi_t$ via a parametric {\it ansatz} $\beta_t(x) = \tilde \beta(x;\gamma_t)$ and $\phi_t(x) = \tilde \phi(x;\alpha_t)$, respectively, and to consider the empirical Hamiltonian
\begin{subequations}
\begin{align}
    &\mathcal{H}(\{X_t^{(j)}\},\{P_t^{(j)}\},\gamma,\alpha) \,=\\ 
    &\qquad \qquad \sum_{j=1}^M \left\{
    -\frac{1}{2} \|R G(X_t^{(j)})^{\rm T}P_t^{(j)}\|^2_R + P_t^{(j)}\cdot b(X_t^{(j)})   + c(X_t^{(j)}) \,+ \right. \\
& \qquad \qquad \left. \tilde \beta (X_t^{(j)},\gamma) \cdot \nabla_x \left(\tilde \phi(X_t^{(j)},\alpha)-X_t^{(j)}\cdot P_t^{(j)}\right) +
\frac{1}{2} \Sigma : D_x^2 \tilde \phi(X_t^{(j)};\alpha) \right\}
\end{align}
\end{subequations}
with equations of motion
\begin{subequations}
    \begin{align}
        \dot{X}_t^{(i)} &= 
        \nabla_{X^{(i)}}\mathcal{H}(\{X_t^{(j)}\},\{P_t^{(j)}\},\gamma_t,\alpha_t),\\
        -\dot{P}_t^{(i)} &= \mathcal{H}(\{X_t^{(j)}\},\{P_t^{(j)}\},\gamma_t,\alpha_t),\\
        (\gamma_t,\alpha_t) &= \arg \min_{(\gamma,\alpha)}\mathcal{H}(\{X_t^{(j)}\},\{P_t^{(j)}\},\gamma,\alpha).      
    \end{align}
\end{subequations}
Appropriate choices for $\tilde \beta$ and $\tilde \phi$ can follow the approaches considered, for example, in \cite{MRO20}.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%
\section{Numerical experiments} \label{sec:experiments}
%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

We present results from two numerical examples. Both cases involve infinite horizon 
cost functions of the form (\ref{eq:costJ infinite}) and controlled ODEs. We employ the initial value formulation (\ref{eq:PMP_forward}) with the additional  advection term approximated using
Nadaraya–Watson kernel regression \cite{Bierens}. The operator $\mathcal{L}_\beta$ is approximated numerically using discrete Schr\"odinger bridges as outlined in Section \ref{sec:DM}. In both cases, we add a diffusion (viscosity) regularization in (\ref{eq:reduced Hamiltonian density}) in line with the concept of viscosity solutions to the associated HJB equations and the vanishing viscosity method \cite{CL83}.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%
\subsection{Inverted pendulum}
%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\begin{figure}
\includegraphics[width=0.9\textwidth]{figure_PMP_IP_1c.eps}
\caption{Upper right panel: Time evolution of the ensemble mean angle and ensemble mean velocity. Upper left panel: Control law (\ref{eq:control law pendulum}) at final time as function of $(\theta,v)$. Lower right panel: Control law (\ref{eq:control law pendulum}) at final time as function of $\theta$.
Lower left panel: Control law (\ref{eq:control law pendulum}) at final time as function of $v$.
} 
\label{fig1}
\end{figure}

We consider a controlled inverted pendulum with friction \cite{Meyn}. The state variable $X = (\theta,v)^{\rm T}$ is two-dimensional with equations of motion
\begin{subequations} \label{eq:pendulum}
\begin{align}
\dot{\theta}_t &= v_t,\\
\dot{v}_t &= \sin (\theta_t) -\sigma v_t + \cos(\theta_t)U_t 
\end{align}
\end{subequations}
and $\sigma = 5$. Consider the running cost function 
\begin{equation}
c(x) = \frac{\alpha}{2} \left( \theta^2
+ v^2 \right)
\end{equation}
with $\alpha = 25$ and set $R=1$ in (\ref{eq:norm}). We use the discount factor $\gamma = 1$
in (\ref{eq:costJ infinite}). Note that $(0,0)$ is an unstable equilibrium point under $U_t \equiv 0$.

In order to implement and, in fact, regularize the McKean--Pontryagin formulation, we add diffusion (viscosity) by setting $\Sigma = 0.1I$ in (\ref{eq:reduced Hamiltonian density}). We initialize the particles at the stable equilibrium point $x_{\rm s} = (\pi,0)$ with added Gaussian noise of variance $0.1I$; i.e.~$X_0^{(i)} \sim {\rm N}(x_{\rm s},0.1I)$. The initial momenta are set to $P_0^{(i)} = -2SX_0^{(i)}$ with
\begin{equation}
S = \left( \begin{array}{cc} 0 & 1\\ 1 & 0
\end{array} \right).
\end{equation}

The discrete Schr\"odinger bridge based formulation from Section \ref{sec:DM} has been implemented with ensemble size $M = 200$ and $\varepsilon = \Delta t$. The resulting evolution equations (\ref{eq:PMP_forward}) have been simulated over 8000 Euler time-steps with time-step
$\Delta t = 0.025$.

The results can be found in Figure \ref{fig1}. It can be clearly seen that the mean-field formulation leaves the stable equilibrium and rapidly equilibrates at the unstable equilibrium. The resulting final control terms 
\begin{equation} \label{eq:control law pendulum}
U_t^{(i)} = -\cos(X_t^{(i)}) e_2^{\rm T}P_t^{(i)}, \qquad e_2 = \left( 0 \,1\right)^{\rm T},
\end{equation}
strongly depend on $\theta$ while the dependence on $v$ is less structured. 

We also note that keeping a non-zero diffusion matrix $\Sigma = 0.1I$ in (\ref{eq:reduced Hamiltonian density}) leads to a desirable exploration of state space and, hence, to a stabilization/regularization of the control problem. However, a wider exploration of state space implies the need for larger ensemble sizes. Hence a balance of computational cost and state space exploration via added diffusion is required in practice and needs to be explored further.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%
\subsection{Lorenz-63}
%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\begin{figure}
\includegraphics[width=0.9\textwidth]{figure_PMP_L63_1.eps}
\caption{Controlled Lorenz-63 model: Displayed is the ${\rm x}$-component of a single particle trajectory chosen at random from the ensemble $\{X_t^{(i)}\}$ and its associated control $U_t^{(i)}$ as a function of time.
} 
\label{fig2}
\end{figure}

We follow \cite{KK24} and consider an optimal control problem for the Lorenz-63 model
\begin{equation} \label{eq:l63}
\dot{X}_t = f(X_t) + G U_t, \qquad f(X) = \left( \begin{array}{l} \sigma({\rm y}-{\rm x})\\
-{\rm x}{\rm z} + r{\rm x}-{\rm y}\\ {\rm x}{\rm y}-b{\rm z} \end{array}\right),
\end{equation}
in the state variable $X = ({\rm x},{\rm y},{\rm z})^{\rm T} \in \mathbb{R}^3$ and with
parameters $\sigma =10$, $r=28$, and $b = 8/3$ \cite{lorenz1963deterministic}. The scalar-valued control $U_t$ acts only on the ${\rm x}$-component; i.e.~$G = (1,0,0)^{\rm T}$. The control problem is to restrict solutions of (\ref{eq:l63}) to ${\rm x}_t\ge 0$ and the authors of \cite{KK24} introduce the running cost 
\begin{equation}
c(X) = \frac{\alpha}{2} \left( \min({\rm x},0) \right)^2.
\end{equation}
In our experiments, we have followed this cost function and have set $\alpha = 5000$ and $R=1$
in (\ref{eq:norm}). Contrary to the setting of \cite{KK24}, we have implemented a discounted cost function (\ref{eq:costJ infinite}) with $\gamma = 1$ instead of a receding horizon NMPC approach \cite{Allgower,MPC}. 

We have implemented the Schr\"odinger bridge based McKean--Pontryagin formulation with $\varepsilon = 0.1$, step-size $\Delta t = 0.001$, and $M=100$ particles. We again added artificial diffusion (viscosity) via $\Sigma = 0.5I$ in (\ref{eq:reduced Hamiltonian density}). The results can be found in Figures \ref{fig2} and \ref{fig3}. The impact of the control can be clearly detected. In particular, by enforcing ${\rm x}_t \ge 0$, the chaotic nature of the Lorenz-63 model has been eliminated. The initial spiral towards to quasi-periodic attractor is due to the chosen initialization 
\begin{equation}
X_0 = (7.8590;7.1136;27.2293)^{\rm T} + \Xi_0, \qquad \Xi_0 \sim {\rm N}(0,0.1I),
\end{equation}
of the Lorenz-63 problem. Our results are in qualitative agreement with the findings from \cite{KK24} which are based on a combination of data assimilation \cite{reich2015probabilistic,Evensenetal2022} and NMPC \cite{Allgower,MPC}. 

