\subsection{Transition systems}

Let us now fix a signature $\namesig = (\arity{k})_{k
    \in\Ops}$ representing the I/O capability of our language.   For a
  set $X$, we write $\hsig X \eqdef \sum_{k\in\Ops}
  X^{\arity{k}}$---i.e.\ the set of pairs $\tuple{k,(x_i)_{i \in
      \arity{k}}}$ where $k \in K$ and $x_i \in X$ for all $i\in\arity{k}$.  We now define the notion of transition
  system, which has both nondeterministic and probabilistic versions.
\begin{definition} 
    \begin{enumerate}[wide]
    \item A \emph{nondeterministic system} consists of a set~$X$ and 
      function   $\zeta \colon X \to \pset\hsig X$.
   \item Such a system is \emph{total} when, for all $x \smin X$, the set $\zeta(x)$ is
     inhabited.
   \item Such a system is \emph{deterministic}
      (respectively, \emph{finitely
        branching}, \emph{countably
        branching}) when, for all $x \smin X$, the set  $\zeta(x)$ has at most one element 
       (respectively, is finite, is countable).
\item Given such a system: for $x \smin X$, let $x \Rrightup{k} (y_i)_{i\in\arity{k}}$ when 
      the
      set $\zeta (x)$ contains 
      $(k,(y_i)_{i\in\arity{k}})$.
    \end{enumerate}
  \end{definition}
  The transition  $x \Rrightup{k} (y_i)_{i\in\arity{k}}$ intuitively
  means that starting in
      state $x\in X$, the system may output $k$, pause
      to receive input, and then transition to state $y_i$ if the user
      inputs~$i \smin \arity{k}$.
%
  \begin{definition}
    \begin{enumerate}[wide]
    \item A \emph{probabilistic system} consists of a set~$X$ and
      function
      $\zeta \colon X \to \dist \hsig X$.
    \item Given such a system: for $x \smin X$, we write
      $x \Rrightup{p,k} (y_i)_{i\in\arity{k}}$ when the distribution
      $\zeta (x)$ assigns $p$ to $(k,(y_i)_{i\in\arity{k}})$.
    \item Given such a system: its \emph{support system} is the nondeterministic system
      $(X,\mathsf{supp} \circ \zeta)$, which is total and countably
      branching.  When it is finitely branching, we say that
      $(X,\zeta)$ is a 
      \emph{finitely probabilistic} system.
    \end{enumerate}
  \end{definition}
The  transition
      $x \Rrightup{p,k} (y_i)_{i\in\arity{k}}$ intuitively means that starting
      in state $x\in X$, the system, with probability $p$, will
      output~$k$, pause to receive input, and then transition to
      state~$y_i$  if the user then inputs $i \smin \arity{k}$.

In both kinds of system, the states are ``active''---they represent a
program that is running, not one that is paused and awaiting input.
  (Such systems may be called \enquote{generative},
 rather than \enquote{reactive}.)


%

Furthermore, the systems of interest in this paper are ``well-founded'' in the
following sense.
\begin{definition}[Well-Founded Nondeterministic Systems]\mbox{}
 %
  \begin{enumerate}[wide]
  \item A nondeterministic system $(X,\zeta)$ is
    \emph{well-founded} when there is no infinite sequence%
    %
    \begin{displaymath}
      %
      x_0 \Rrightup{k_0} (y^{0}_i)_{i\in\arity{k_0}},
      \betwixt y^{0}_{i_{0}} = x_1  \Rrightup{k_1}  (y^{1}_i)_{i \in
        \arity{k_1}}, \betwixt \cdots   
    \end{displaymath}
Equivalently: $X$ is the only \emph{inductive} subset, i.e., such $U\subseteq X$ that 
any $x\smin X$ whose successors are all in
$U$ is $U$ itself.
\item A probabilistic system $(X,\zeta)$ is \emph{well-founded} when
  its support system is well-founded.
  %
  %
  %
  %
  %
  \end{enumerate}
\end{definition}
%
Each of the languages mentioned in \cref{sec:axiom} gives rise to a well-founded system.  For example, take the countably
probabilistic language obtained from the signature $S$.  Writing~$\prog$ 
for the set of programs, we obtain a probabilistic system
$(\prog,\zeta)$, where the function $\zeta$ is defined by induction
over syntax: it sends
          \begin{itemize}
     \item $\inpu{k}(M_{i})_{i\in\arity{k}}$ to the
       principal distribution on $\tuple{k, (M_i)_{i\in\arity{k}}}$,
       \item $M +_p N$ to $\zeta(M) +_p \zeta(N)$,
       \item $\tesum_{n\in\nats}p_n\ml M_n$ to $\tesum_{n \in
           \nats} p_n\ml \zeta(M_n)$.
     \end{itemize}

\section{Bisimulation and traces}\label{sec:sys_trace}
\subsection{Bisimulation}

Before defining bisimulation, it is helpful to specify how~$\hsig$ and $\pset$ and
$\dist$ act on relations. For a distribution $d$ on
$A$ and any subset $U \subseteq A$, we write $d[U] \eqdef \sum_{x \in U} d(x)$.
\begin{definition}
  Let $A$ and $B$ be sets, and $\catr \subseteq A \times B$ a
  relation.
  \begin{enumerate}[wide]
  \item The relation $\hsig \catr \subseteq \hsig A \times \hsig B$
    relates $(k,(x_i)_{i\in\arity{k}})$ to  $(l,(y_i)_{i \in
      \arity{l}})$ when $k=l$ and for all $i \smin \arity{k}$ we have
    $(x_i,y_i)\in\catr$.
  \item The relation $\pset \catr \subseteq \pset A \times \pset B$
    relates $A \smin \pset A$ to $B \smin \pset B$ under the
    following condition: for every
    $x \smin A$ there is $y \smin B$ such that $(x,y)\in\catr$, and
   for every $y \smin B$ there is $x \smin A$ such that $(x,y)\in\catr$.
  \item \label{item:distrel} The relation $\dist \catr \subseteq \dist A \times \dist B$
    relates $d \smin \dist A$ to ${e \smin \dist B}$ under the following
    condition: for every 
    subset $U \subseteq A$, writing $\catr(U)$ for the set of all $\catr$-images of elements of $U$, we have $d[U] \leqslant e[\catr(U)]$.
    Equivalently: for every subset $V \subseteq B$, writing  $\catr^{\mone}(V)$ for the
    set of all $\catr$-preimages of elements of~$V$, we have $e[V]
\leqslant d[\catr^{\mone}(V)]$.
  \end{enumerate}
\end{definition}

Now we define bisimulation for nondeterministic and probabilistic
systems.\footnote{In early work~\cite{LarsenSkou91}, a
  probabilistic bisimulation was required to be an equivalence relation.}
\begin{definition}
  \begin{enumerate}[wide]
  \item Let $(X,\zeta)$ and $(Y,\xi)$ be nondeterministic transition
    systems.  A \emph{bisimulation} between them is a relation $\catr
    \subseteq X \times Y$ such that, for any $(x,y) \smin \catr$, we have
    $(\zeta(x), \zeta(y))\in\pset \hsig \catr$.
  \item Let $(X,\zeta)$ and $(Y,\xi)$ be probabilistic transition
    systems.  A \emph{bisimulation} between them is a relation $\catr
    \subseteq X \times Y$ such that, for any $(x,y) \smin \catr$, we have
    $(\zeta(x), \zeta(y))\in\dist \hsig \catr$.
  \end{enumerate}
  In each case, the greatest bisimulation is called \emph{bisimilarity}.
\end{definition}

\subsection{Plays}

As explained in the introduction, a ``play'' for our signature~$S$ 
is a alternating sequence of outputs and inputs.  To understand the
various kinds of play, imagine a program (in any of the languages in \cref{sec:axiom}) running.  When
execution has just started or an input has just 
been supplied, the program is
\emph{actively} working to produce the next output.  But after an
output has appeared, the program is paused and it \emph{passively} awaits input.  This
motivates the following terminology.

\begin{definition}[Plays] %
  \begin{enumerate}[wide]
  \item An \emph{active-ending play} of length ${n\in\nats}$ is a sequence of the form
    $k_0\comma i_0\comma k_1\comma i_1\comma \ldots,k_{n-1}\comma i_{n-1}$
    with $k_r\in\Ops$ and ${i_r\in\arity{k_r}}$.   An example is
    the empty play, denoted by~$\varepsilon$.
  \item A \emph{passive-ending play} $s$ of length $n\in\nats$ is a
    sequence of the form $k_0\comma i_0\comma k_1\comma i_1\comma \ldots\comma k_{n-1}\comma i_{n-1}\comma k_n$
    with $k_r\in\Ops$ and $i_r\in\arity{k_r}$.   The set of all
    possible next inputs is written  
    $\inarity{s} \eqdef \arity{k_n}$.
  \item An \emph{infinite play} is a sequence
     \begin{math}
      k_0,i_0,k_1,i_1,\ldots,
    \end{math}
    with~${k_r \in\Ops}$ and $i_r\in\arity{k_r}$.
  \end{enumerate}
\end{definition}
Individual plays can be arranged into a ``trace strategy'', which intuitively describes the trace semantics of a program.  As explained in
the introduction, this may be a set of plays (for a nondeterministic
program) or a function on plays (for a probabilistic program).

\subsection{Trace semantics for nondeterminism}

We now consider the trace semantics of a state within a
nondeterministic system.  The key notion is the following.
    \begin{definition}%
        %
        %
          A \emph{nondeterministic trace strategy} $\sigma$ consists
          of a set $\sigmapass$ of
          passive-ending plays and a set $\sigmaact$ of active-ending
          plays such that
          \begin{itemize}
          \item an active-ending play is in $\sigmaact$ iff it is either
            empty or of the form  $s.i$ for $s \smin \sigmapass$ and
            $i \smin \inarity{s}$
           \item for an active-ending play $s$ and output $k \smin
             \Ops$, if ${s.k\in\sigmapass}$, then $s\in\sigmaact$.
          \end{itemize}
        %
        %
        \end{definition}
Note that $\sigmapass$ determines $\sigmaact$.  For convenience, we
sometimes represent the strategy as the set $\sigmapass \cup \sigmaact$.
%
%


%
%
%
%
%

Now we can define trace semantics:
\begin{definition} \label{def:nondettrace}
  Let $(X,\zeta)$ be a nondeterministic system.  The \emph{trace
      semantics} of $x \smin X$, written $\tracesof{x}$, is the strategy
    consisting of all 
    passive-ending plays $k_0,i_0,k_1,i_1,\ldots,k_{n-1},i_{n-1}$ such
    that there is a sequence
    \begin{align*}
         x = x_0 \Rrightup{k_0} (y^{0}_i)_{i\in\arity{k_0}},
         &\betwixt y^{0}_{i_{0}} = x_1 %
           %
      \betwixt \cdots\\ &\betwixt   y^{n-1}_{i_{n-1}} = x_{n} \Rrightup{k_n} (y^{n}_i)_{i\in\arity{k_0}}
    \end{align*}
    and likewise for active-ending plays.     Two states with the same trace semantics are \emph{trace equivalent}.
\end{definition}
%
