    \subsection{Trace semantics for probability}\label{sec:t-sem}

 For a probabilistic system, we proceed similarly:
 \begin{definition}
A \emph{play-measure} $\sigma$ consists of a function $\sigmapass$
from passive-ending plays to $[0,1]$ and a function $\sigmaact$ from
active-ending plays to $[0,1]$ satisfying
\begin{align*}
   \sigmaact(s.i)  &\, = \sigmapass(s) &
  \sigmaact(t)     &\, = \sum_{k\in\Ops} \sigmapass(t.k) 
 \end{align*}
 The \emph{weight} of $\sigma$   %
 is $\sigmaact(\varepsilon)$.
\end{definition}
Note that $\sigmapass$ determines $\sigmaact$.  For convenience we
sometimes  represent $\sigma$ as the function $\sigmapass \cup \sigmaact$.
\begin{definition}
  A \emph{probabilistic trace strategy} is a play-measure of weight
  1.  
\end{definition}
An example of such a function is the trace semantics of the program in
\cref{sec:axiom}\plnote{More specific?} 
We proceed to define trace semantics in general:
\begin{definition} \label{def:probtrace}
  Let $(X,\zeta)$ be a probabilistic system.  The \emph{trace
       semantics} of $x \smin X$, written $\tracesof{x}$, is the probabilistic trace strategy sending  $k_0, i_0, \ldots, k_n$ to the sum over all sequences
    \begin{align*}
         x = x_0 \Rrightup{p_0,k_0} (y^{0}_i)_{i\in\arity{k_0}},
         ~~ y^{0}_{i_{0}} &\,= x_1 %
           %
      \cdots\\ \betwixt   y^{n-1}_{i_{n-1}} &\,= x_{n} \Rrightup{p_{n},k_n} (y^{n}_i)_{i\in\arity{k_0}}
       \end{align*}
       of the product $p_0 \cdots p_{n}$.
     \end{definition}
For each of our probabilistic languages:
\begin{itemize}
\item The programs form a transition system, so each program has a
  trace semantics via \cref{def:probtrace}.
\item A strategy is
  \emph{definable} when it is the trace semantics of a program.  More
  generally, a play-measure of weight $\lambda$ is \emph{definable}
  when it is either 0 or $\lambda \tracesof{M}$ for some program
  $M$.\footnote{The first disjunct is needed only in the case of a signature
    with no constants.}
\end{itemize}
 Trace semantics can also be given compositionally, as described further below 
 in~\Cref{pro:sem-compos}. Firstly, each $k \smin \Ops$ gives an $\arity{k}$-ary operation
 $\sfinpu{k}$ on strategies:
 \begin{eqnarray*}
   \sfinpu{k}(\sigma_i)_{i \in
   \arity{k}} & : & \left\{
                    \begin{array}{llll}
                      \varepsilon & \mapsto & 1 \\
                      k & \mapsto & 1 & \\
         %
                      k.i.s & \mapsto & \sigma_i(s) \\
                      l.s & \mapsto & 0 & (l \not= k)
                    \end{array} \right.
 \end{eqnarray*}
 Secondly, play-measures $(\sigma_i)_{i\in I}$ of total weight
 $\lambda \smin [0,1]$ can be added to give a play-measure
 \begin{spaceout}{lllll}
   \sum_{i \in I} \sigma_i & : & s & \mapsto & \sum_{i \in I} \sigma_i(s)
 \end{spaceout}%
 of weight $\lambda$.  A special case is the nullary sum, denoted 0, which 
 is the
 unique play-measure of weight 0.  Thirdly, we can multiply a scalar $b \smin [0,1]$ by a
 play-measure of weight $\lambda$ to give a play-measure
 \begin{spaceout}{lllll}
   b \ml \sigma & : & s & \mapsto & b \sigma(s)
 \end{spaceout}%
 of weight $b \lambda$.  These constructions
 yield a cancellative $\omega$-convex space of all 
 strategies.
 \begin{proposition}\label{pro:sem-compos}
 Here is a compositional description of the trace semantics:
    \begin{align*}
    \tracesof{\inpu{k}(M_{i})_{i\in\arity{k}}} =\; &
                                                       \sfinpu{k}(\tracesof{M_i})_{i \in I} \\
 \tracesof{M +_p N} 													 =\; & \tracesof{M} +_p \tracesof{N} \\
    \tracesof{\tesum_{n\in\nats}p_n\ml M_n} 			 =\; & \tesum_{n\in\nats} p_n\ml \tracesof{M_n}
  \end{align*}
\end{proposition}
%
For play-measures $\sigma$ and $\tau$, the notation $\sigma \leqslant
\tau$ means that $\sigma(s) \leqslant \tau(s)$ for every passive-ending
$s$.  When this is so and $w(\sigma) < \infty$, we write $\tau -
\sigma$ for the
unique play-measure $\rho$ such that $\tau = \sigma + \rho$.
Explicitly, $\rho$ sends a passive-ending play~$s$ to $\tau(s) -
\sigma(s)$.%


\subsection{Branching conditions}


\begin{definition}
  Let $\sigma$ be a nondeterministic trace strategy.
  \begin{enumerate}%
  \item For $t \smin \sigmaact$, a \emph{possible
      output} is $k \smin \Ops$ such that \mbox{$t.k\in\sigmapass$}.  
%
%
%
  \item We say that  $\sigma$ is
          \begin{itemize}
          \item \emph{total} when each $t \smin \sigmaact$ has at
            least one possible output
          \item \emph{finitely branching} when each  $t \smin \sigmaact$ has finitely many possible outputs
          \item \emph{countably branching} when each  $t \smin \sigmaact$-enabled has countably many possible outputs.\sgnote{What is ``enabled''?}
          \end{itemize}
  \end{enumerate}
\end{definition}
Thus, for any state of a total transition system, the trace semantics 
is total, and likewise for finite branching and countable branching.

\begin{definition}
  The \emph{support} of a play-measure $\sigma$, written
  $\supp{\sigma}$, is the nondeterministic trace strategy consisting
  of all plays $p$ such
  that $\sigma(p) > 0$.
\end{definition}
Thus $\supp{\sigma}$ is total (unless $\sigma = 0$) and countably
branching.  We say that $\sigma$ is \emph{finitely branching} if
$\supp{\sigma}$ is.

We see that, for any state of a probabilistic system,
the support of the trace semantics is the trace semantics in the
support system.  Hence, for any state of a finitely probabilistic
system, the trace semantics is finitely branching.

