\section{Completeness up to Impersonation}\label{sec:impers}

Although it is an open question whether trace
equivalent programs are always 
tensor-equivalent, we shall show that tensor-equivalence is complete
in a weaker sense.  This uses the
following notion.  
\begin{definition}
  Let $A$ be a convex space, and $a= (a_n)_{n\in \nats}$ a sequence in $A$.
  \begin{enumerate}[wide]
  \item An \emph{$a$-solution} is a sequence  $(r_n)_{n\in\nats}$ in
    $A$ satisfying $r_n = a_{n} +_{\frac{1}{2}} r_{n+1}$ for all $n
    \smin \nats$.
  \item If $A$ is an $\omega$-convex space, then the \emph{canonical
       $a$-solution} is the sequence $\bigl(\sum_{i\in\nats}
     2^{-n-i-1} \ml  a_{n+i}\bigr)_{n\in\nats}$.
  \end{enumerate}
\end{definition}
The \emph{head} of a sequence  $(r_n)_{n\in\nats}$ is the element
$r_0$.  
\begin{definition}
  Let $A$ be an $\omega$-convex space with elements~$x$ and $y$.  We
  say that $x$ is \emph{impersonated} by $y$ when there is a sequence
  $a$ such that
  \begin{itemize}
  \item $x$ is the head of the canonical $a$-solution, i.e.\ $x =
    \sum_{i\in\nats} 2^{-i-1} a_i$.
  \item $y$ is the head of an $a$-solution.
  \end{itemize}
\end{definition}

We see that impersonation implies equivalence up to cancellation:
\begin{lemma}\label{lem:impers-cancel}
  Let $A$ be an $\omega$-convex space with elements~$x$ and~$y$.  If
  $x$ is impersonated by $y$, then there is $u \smin A$ such that $x
  +_{\frac{1}{2}} u = y
  +_{\frac{1}{2}} u$.
\end{lemma}
%
We shall use yet another kind of normal form.
\begin{definition}
  A \emph{light pre-normal form} is a program of the form  $\sum_{n
   \in\nats} p_n \ml M_n$, where the components $(M_n)_{n\in\nats}$
use only binary probabilistic choice.  It is a \emph{light normal
  form} when the sequence $p$ is $(2^{-n-1})_{n\in\nats}$.
\end{definition}

\begin{lemma} \label{prop:light}
  Every program is light normalizable, i.e.\ equivalent to a light
  normal form.
\end{lemma}
\begin{theorem}[Completeness up to impersonation]\label{thm:upto-imp}
Let~$M$ and $N$ be trace-equivalent programs.  Then $M$ is
impersonated by $N$, up to tensor-equivalence.
\end{theorem}
\begin{proof}
 \cref{prop:light} tells us that $M$ is equivalent to a light normal form
  $\sum_{n\in\nats} 2^{-n-1}\ml P_n$, and therefore (up to $\equiv$) it is the head
  of the canonical $P$-solution.  For each $n \smin \nats$, we define a program~$Q_n$ trace-equivalent
to $\sum_{i\in\nats} 2^{-i-1}\ml P_{n+i}$ as follows.
  \begin{align*}
    Q_0   \eqdef &\; N \\
    Q_{n} \equiv &\; P_{n} +_{\frac{1}{2}} Q_{n+1} \betwixt \text{
                     by \cref{prop:subsplit}.}
  \end{align*}
  So (up to $\equiv$) we see that $N$ is the head of the $P$-solution~$Q$.
\end{proof}
%
Using \cref{lem:impers-cancel}, we obtain
%
\begin{corollary}[Completeness up to cancellation]\label{cor:up-to-cancel}
  Let $M$ and~$N$ be trace-equivalent programs.  Then there is a
  program~$U$ such that $M +_{\frac{1}{2}} U \equiv N +_{\frac{1}{2}} U$.
\end{corollary}
%
\section{Completeness for Finitary Signatures}\label{sec:comp-fin}

This section is devoted to proving that, for a \emph{finitary} signature $S = (\arity{k})_{k
  \in K}$,  any two trace-equivalent programs are tensor-equivalent.
We begin with the
following notion.
\begin{definition}
  Let $\sigma$ and $\tau$ be play-measures with \mbox{$w(\tau) < \infty$}.  We say that $\sigma$
  is \emph{uniformly below} $\tau$, written $\sigma \prec \tau$, when there is $d > 0$ such
  that
\begin{align*}
   %
    \sigma(s) + d \leqslant\; & \tau(s) \quad\quad \text{ for all $s
                                \smin \supp{\sigma}$.}
\end{align*}
\end{definition}
Thus $\sigma \prec \tau$ implies $\sigma \leqslant \tau$ and
$w(\sigma) < w(\tau)$.  The key property of $\prec$ is the following.
\begin{lemma} \label{prop:prec}
  Let $(\tau_i)_{i\in\nats}$ be a sequence of play-measures with
  total weight $\lambda \in [0,1]$.  For any play-measure $\sigma$ such that $\sigma \prec \sum_{i\in\nats} \tau_i$, there is $n \smin
  \nats$ such that $\sigma \prec \sum_{i < n} \tau_i$.  
\end{lemma}
\begin{proof}
Take a witness $d \smin (0,1]$ for $\sigma \prec \sum_{i\in\nats}
\tau_i$.  Take $n \smin \nats$ such that $\sum_{i \geqslant n} w(\tau_i)
  \leqslant \frac{1}{2}d$.  We show that $\frac{1}{2}d$ witnesses $\sigma \prec \sum_{i
    < n} \tau_i$.   For any $s\in\supp{\sigma}$, we have
   \begin{align*}
     \sigma(s) + d \leqslant\,& \sum_{i \in\nats}\tau_i(s) \\
     =\,& \sum_{i  < n}\tau_i(s)  + \sum_{i   \geqslant n}\tau_i(s)
     \\
     \leqslant\,& \sum_{i < n}\tau_i(s)  + w\Bigl(\sum_{i   \geqslant
                   n}\tau_i(s)\Bigr) \\
      \leqslant\,& \sum_{i   < n}\tau_i(s)  + \frac{1}{2}d,
      \intertext{therefore}
      \sigma(s) + \frac{1}{2}d \leqslant\,& \sum_{i   < n}\tau_i(s)\tag*{$\qed$}
   \end{align*}
\noqed \end{proof}
%
Now we give the central notion of the section:
\begin{definition}
  A \emph{steady pre-normal form} is a program of the form $\sum_{n \in
    \nats} p_n \ml M_n$,  where
  \begin{itemize}
  \item for all $n \smin \nats$, the strategy $\tracesof{M_n}$ is
    well-founded
  \item for all $m \smin \nats$, we have $\sum_{n < m} p_n \ml \tracesof{M_n}
    \prec \sum_{n \in\nats} p_n \ml \tracesof{M_i}$. 
  \end{itemize}
  Such steady pre-normal form is a \emph{steady normal form} when the sequence $p$ is
  $(2^{-n-1})_{n\in\nats}$.
\end{definition}

\begin{lemma}\label{lem:steady-pre}
  Any steady pre-normal form is equivalent to a steady normal form.
\end{lemma}
\begin{proof}
  By splitting and regathering.
\end{proof}

\begin{lemma}\label{lem:main-lem}
  Let $M$ and $N$ be steady-normalizable programs.  If they are
  trace-equivalent, they are
  logically equivalent.
\end{lemma}
\begin{proof}
We have steady normal forms
  \begin{align*}
    M \equiv\, & \sum_{i\in\nats} 2^{-i-1} \ml M_i \\
    N \equiv\, & \sum_{i\in\nats} 2^{-i-1} \ml N_i
  \end{align*}
  and $\tracesof{M} = \tracesof{N}$.  \cref{prop:prec} tells us that
  \begin{itemize}[wide]
  \item for all $m \smin \nats$, there is $n \smin \nats$ such that  
  \begin{align*}
  \sum_{i < m}
   2^{-i-1} \tracesof{M_i} \prec \sum_{i < n}  2^{-i-1} \tracesof{N_i}
  \end{align*}
  \item for
  all $n \smin \nats$, there is $m \smin \nats$ such that 
  \begin{align*}
 \sum_{i < n}  2^{-i-1} \tracesof{N_i} \prec \sum_{i < m}  2^{-i-1} \tracesof{M_i} 
  \end{align*}
%
\end{itemize}
Thus we obtain strictly increasing sequences $(m_r)_{r\in\nats}$ and~$(n_{r})_{r
 \in\nats}$ of natural numbers satisfying $m_0 = 0 $ and
\begin{align*}
  \sum_{i < m_r}2^{-i-1}& \tracesof{M_i}\\ \prec &\; \sum_{i < n_r} 2^{-i-1}\tracesof{N_i}
  \\
  \prec &\; \sum_{i < m_{r+1}} 2^{-i-1}\tracesof{M_i}
  \end{align*}
For each $r \smin \nats$, we obtain a play-measure 
\begin{align*}
\sum_{i<n_r}2^{-i-1} \tracesof{N_i}  - \sum_{i <
    m_r} 2^{-i-1} \tracesof{M_i},
\end{align*}
which is well-founded since
  $\sum_{i<n_r} 2^{-i-1}\tracesof{N_i}$ is (being a finite sum of well-founded
  play-measures).  So, by \cref{prop:wfstratdef}(\ref{item:wfstratdef}), it is expressible as $a_r\tracesof{U_r}$
  for some $a_r >0$ and 
  program $U_r$.  Likewise the play-measure 
  \begin{align*}
  \sum_{i <
      m_{r+1}}2^{-i-1}\tracesof{M_i} - \sum_{i<n_r}2^{-i-1}\tracesof{N_i} 
  \end{align*}
  is expressible as
    $b_r \tracesof{V_r}$  for some $b_r > 0$ and
    program~$V_r$.   Now
  \cref{prop:wfstratdef}(\ref{item:wfcomplete}) gives the following.

\begin{flalign*}
\sum_{i \in [m_r \twodots m_{r+1})} \ofrac{2^{-i-1}}{a_r +
         b_r} \ml M_i
                                                     \equiv&\;
     \ofrac{a_r}{a_r + b_r} \ml U_r + \ofrac{b_r}{a_r + b_r} \ml  V_r &&(r \smin \nats)\\
\sum_{i \in [0 \twodots n_0)} \ofrac{2^{-i-1}}{a_0}\ml N_i \equiv&\;  U_0\\
\sum_{i \in [n_r \twodots
     n_{r+1})}\ofrac{2^{-i-1}}{a_r + b_{r+1}} \ml N_i \equiv&\;
   \ofrac{a_r}{a_r + b_{r+1}} \ml V_r + \ofrac{b_{r+1}}{a_r + b_{r+1}}
   \ml U_{r+1}&&(r \smin \nats)
\end{flalign*}
%
%
%
%
%
%
%
%
%
%
%
%
%
%
%
 So we have
  \begin{align*}
    M \equiv&\, \sum_{i\in\nats}2^{-i-1} M_i \\
      \equiv&\,   \sum_{r\in\nats} \sum_{i \in [m_r \twodots m_{r+1})}
                 2^{-i-1} M_i \\
      \equiv&\, \sum_{r\in\nats} (a_r U_r+ b_r V_r) \\
      \equiv&\, a_0 U_0 + \sum_{r\in\nats} (b_rV_r + a_{r+1}U_{r+1}) \\
      \equiv&\,  \sum_{i \in [0 \twodots n_0)} 2^{-i-1} N_i \\&\qquad + \sum_{r \in
               \nats} \sum_{i \in [n_r \twodots n_{r+1})} 2^{-i-1} N_i \\
      \equiv&\, \sum_{i\in\nats}2^{-i-1} N_i \\*
      \equiv&\, N
  \end{align*}
as required.
\end{proof}



Let us see how to obtain steady-normalizable programs.
\begin{lemma} %
  \begin{enumerate}[wide]
  \item If $M$ and $N$ are steady-normalizable, then so is $M +_p N$.
  \item If $M_n$ is steady-normalizable for all $n \smin \nats$, then
    so is $\sum_{n\in\nats}p_n \ml M_n$.
     \item Let $k \smin K$ have arity $n \smin \nats$.  If $M_j$ is steady-normalizable
    for all $j < n$, then so is $\inpu{k}(M_j)_{j < n}$.
  \end{enumerate}
\end{lemma}
\begin{proof}
  \begin{enumerate}[wide]
  \item We have steady normal forms
    \begin{align*}
      M \equiv&\; \sum_{i\in\nats}2^{-i-1} \ml M_i \\
      N \equiv&\; \sum_{i \in
                   \nats} 2^{-i-1} \ml N_i 
   \intertext{This gives } 
   M +_p N \equiv&\; \sum_{i\in\nats}2^{-i-1} \ml (M_i +_p N_i) 
    \end{align*}
    which is a steady normal form.
  \item We may assume all $p_n$ are positive.  We have steady normal forms
   \begin{align*}
       M_n \equiv&\;
   \sum_{i\in\nats} 2^{-i-1} \ml M_{n,i} \quad\quad \text{ for all $n \smin
                     \nats$.} 
     \intertext{This gives } 
   \sum_{n\in\nats}p_n\ml M_n \equiv&\;
                                        \sum_{r\in\nats} \beta_r \ml
                                        N_r \\
     \text{writing } \beta_r  \eqdef & \sum_{j \leqslant r}
                                        {p_{j}2^{-(r-j+1)}} \\
 N_r  \eqdef & \sum_{j \leqslant r} \frac{p_{j}2^{-(r-j+1)}}{\beta_r}\ml
                                        M_{j,r-j}
   \end{align*}
We prove that this is a steady pre-normal form, which is sufficient by \cref{lem:steady-pre}. 
Since $+_p$ preserves well-foundendess, we see that $\tracesof{N_r}$ is well-founded.  %
%
 Given $n \smin
\nats$, we want a
witness $d$ for
\begin{align*}
  \sum_{r < n} \beta_r \ml
                                        \tracesof{N_r}  \prec &\;
                                                                  \sum_{j
                                                                  \in
                                                                  \nats}
                                                                  \beta_r
                                                                  \ml \tracesof{N_r}                                          
\end{align*}
The left-hand side is equal to $\sum_{j < n} p_j \tau_j$ with $\tau_j
\eqdef \sum_{i < n-j} 2^{i} \tracesof{M_{j,i}}$, and the right-hand side to 
$\sum_{j\in\nats} p_j \sigma_j$ with $\sigma_j \eqdef \tracesof{M_j}$.  For each $j < n$,
let $d_j$ be a witness for $\tau_j \prec \sigma_j$.  We show that $d
\eqdef \min(\setbr{1}\cup
                                          \setbr{p_j d_j \mid j
                                            < n})$ has the desired
                                          property.  Any~$s$ in the
                                          support of~$\sum_{j < n} p_j
                                          \tau_j$ must be in the
                                          support of~$\tau_m$ for some
                                          $m < n$.  So we have
                                          \begin{align*}
                                            \Bigl(\sum_{j < n} p_j \tau_j\Bigr)(s)
                                            + d  \leqslant &\;
                                            \sum_{j < n} p_j
                                                        \begin{cases}
                                                          \tau_j(s) +
                                                          d_j &
                                                              \text{($j
                                                              = m$)}
                                                          \\
                                                          \tau_j(s) & \text{otherwise}
                                                        \end{cases} \\
                                             \leqslant &\; \Bigl(\sum_{j\in\nats}
                                                         p_j \sigma_j\Bigr)(s)
                                          \end{align*}
as required.
  \item %
  %
    For all $j<n$, we have a steady
    normal form
    \begin{flalign*}
    &&  M_j \equiv&\;  \sum_{i\in\nats} 2^{-i-1} \ml M_{j,i} & \text{ for
                     all $j < n$.} 
    \intertext{This gives }
    && \inpu{k}(M_j)_{j < n)} \equiv&\;\sum_{i\in\nats}
                                                 2^{-i-1} \ml N_i \\
    &&  \text{writing}\quad N_i \eqdef &\;  \inpu{k}(M_{j,i})_{j < n)} 
  %
  %
  %
    \end{flalign*}
We claim that this is  steady normal form.  Since $+_p$ preserves
well-foundendess, we see that $\tracesof{N_i}$ is well-founded.  Given $m \smin \nats$, we want a witness $d$ for
\begin{align*}
\sum_{i < m} 2^{-i-1} \tracesof{N_i} \prec&\; \sum_{i\in\nats} 2^{-i-1}
\tracesof{N_i} 
\intertext{For $j < n$, obtain a witness $d_j$ for}
\sum_{i < m} 2^{-i-1} \tracesof{M_{j,i}} \prec&\; \sum_{i\in\nats} 2^{-i-1}
\tracesof{M_{j,i}} 
\end{align*}
We show that $d \eqdef \min (\setbr{2^{-m}} \cup \setbr{d_j \mid j <
  n})$ has the desired property.  Any play in the support of $\sum_{i <
  m} 2^{-i-1} \tracesof{N_i}$ is either empty or $k$ or of the form
$k.j.s$.  For the case of $k$, we reason
\begin{align*}
  \Bigl(\sum_{i < m}& 2^{-i-1} \tracesof{N_i}\Bigr) (k) + d \\
  \leqslant &\; \Bigl(\sum_{i < m} 2^{-i-1}\Bigr) + 2^{-m} \\
  = &\; \sum_{i\in\nats} 2^{-i-1} \\
  = &\; \Bigl(\sum_{i\in\nats} 2^{-i-1} \tracesof{N_i}\Bigr)(k)
\end{align*}
and likewise for the empty play.  For the case of $k.j.s$ with \mbox{$j <n$}, 
the play $s$ is in the support of $\sum_{i < m}2^{-i-1}
\tracesof{M_{j,i}}$, so we have
\begin{align*}
  \Bigl(\sum_{i < m} 2^{-i-1}& \tracesof{N_i}\Bigr) (k.j.s) + d \\
  \leqslant &\; \Bigl(\sum_{i < m} 2^{-i-1} \tracesof{N_i}\Bigr) (s) + d_j \\ 
  \leqslant &\; \Bigl(\sum_{i\in\nats} 2^{-i-1} \tracesof{N_i}\Bigr) (s) \\
  = &\;  \Bigl(\sum_{i\in\nats} 2^{-i-1} \tracesof{N_i}\Bigr) (k.j.s)
\end{align*}
as required.\qed
  \end{enumerate}\noqed
\end{proof}

\begin{corollary}\label{cor:fin-stead-norm}
  For a finitary signature, every program is steady-normalizable.
  \end{corollary}

The finitarity hypothesis in \cref{cor:fin-stead-norm} cannot be removed:
\begin{proposition}\label{pro:inf-example}
  For the signature consisting of an $\omega$-ary operation $b$ and constants
  $(c_n)_{n\in\nats}$, let $M$ be the program $\inpu{b}\bigl(\sum_{i \leqslant n}
  \frac{1}{n+1} c_i\bigr)_{n\in\nats}$. 
  \begin{enumerate}[wide]
  \item No play-measure $\sigma$ other than 0 satisfies $\sigma \prec
    \tracesof{M}$.
  \item $M$ is not steady-normalizable.
  \end{enumerate}
\end{proposition}
%
\cref{lem:main-lem} and \cref{cor:fin-stead-norm} yield our main result:
\begin{theorem}\label{thm:comp_fin}
  For countably probabilistic programs on a finitary I/O signature, tensor-equivalence coincides with  trace-equivalence. 
\end{theorem}


 \section{Definable $=$ Victorious}\label{sec:victor}     

To characterize the definable strategies, the following is helpful.
\begin{definition}
 A \emph{partial counterstrategy} $\rho$ consists of a set $\rhoact$ of
 active-ending plays and a set $\rhopass$ of passive-ending plays
 satisfying the following:
 \begin{itemize}
   \item We have $s\in\rhopass$ if $s$ is of the form $t.k$ for $t \smin
     \rhoact$ and~$k \smin \Ops$.
   \item We have $\varepsilon\in\rhoact$.
   \item If $s.i\in\rhoact$, then $s\in\rhopass$.
    \item Any $s \smin \rhopass$ has at most one \enquote{prescribed input}, i.e., $i \smin \inarity{s}$
      such that $s.i\in\rhoact$.
    \end{itemize}
%
%
%
    A play $s \smin \rhopass$ with no prescribed inputs is called 
    a \emph{$\rho$-failure}, and the set of all such is written
    $\failof{\rho}$.  For any $m \smin \nats$, we write~$\rhoactof{m}$
    for the set of plays in $\rhoact$ of length $m$, and likewise~$\rhopassof{m}$ and $\rhofailof{m}$.  
  \end{definition}
Intuitively, $\rho$ deterministically tells the user what input to
provide, if any.  Although  $\rhopass$ is determined by $\rhoact$ and therefore redundant, including it is convenient.   %
%
%
%
%
%
%
%
%
%
%
%
%
%
%
%
%


\begin{definition}
   Let $\sigma$ be a play-measure and $\rho$ a partial counterstrategy.  For any $m
  \smin \nats$, put
  \begin{eqnarray*}
    \contprob{m}{\rho}{\sigma} &\eqdef  & \sum_{s \in
                                          \rhoactof{m}} \sigmaact(s) %
    %
    %
    %
    %
    %
  \end{eqnarray*}
\end{definition}
In the case that $\sigma$ is a strategy, we think of $\contprob{m}{\rho}{\sigma}$ as the probability that play between
$\sigma$ and $\rho$ lasts for at least $m$ output-input cycles.
%
%
%
\begin{lemma} \label{prop:decsurvive}
  For any play-measure $\sigma$ and  partial counterstrategy $\rho$,
  we have
  \begin{align}
    \label{eq:zerocstrat}
    \contprob{0}{\rho}{\sigma} =&\; w(\sigma) \\
      \label{eq:succcstrat}
      \contprob{m}{\rho}{\sigma} =&\; \sum_{s\in\rhofailof{m}} \sigmapass(s)
                               + \contprob{m+1}{\rho}{\sigma} \quad \text{
                                       for $m \smin \nats$}
   \end{align}
 \end{lemma}
 \begin{proof}
   Equation \eqref{eq:zerocstrat} is obvious, and for \eqref{eq:succcstrat} we have
   \begin{align*}
       \contprob{m}{\rho}{\sigma}
    =&\;   \sum_{s\in\rhoactof{m}} \sum_{k
                     \in K} \sigmapass(s.k) \\
    =&\;   \sum_{s\in\rhoactof{m}} \sum_{k
          \in K}  
          \begin{cases}
            \sigmapass(s.k) 	& \text{ if $s.k\in\failof{\rho}$} \\
            \sigmaact(s.k.i) 	& \text{ if $s.k.i\in\rhoact$}
          \end{cases} \\
    =&\; \sum_{s\in\rhofailof{m}} \sigmapass(s)
                               + \contprob{m+1}{\rho}{\sigma} \tag*{$\qed$}
  \end{align*}
\noqed\end{proof}
%
For a given play-measure $\sigma$, we thus obtain a decreasing sequence
\begin{displaymath}
  w(\sigma)  =  \contprob{0}{\rho}{\sigma} \geqslant \contprob{1}{\rho}{\sigma} \geqslant \cdots
\end{displaymath}
whose infimum we call  $\continf{\rho}{\sigma}$.  In the case that
$\sigma$ is a strategy, we think of this as the
probability that play between $\rho$ and $\sigma$ lasts forever.

