\begin{lemma}
  For any play-measure $\sigma$ and partial counterstrategy $\rho$, we have
  \begin{align*}
    \continf{\rho}{\sigma} =&\; w(\sigma) -  \sum_{s
                               \in
                               \failof{\rho}} \sigmapass(s)
  \end{align*}
\end{lemma}
\begin{proof}
  Follows from the equation
  \begin{align*}
    \continf{m}{\rho}{\sigma} =&\;  w(\sigma) -  \sum_{\substack{s
                               \in
