    \begin{lemma} \label{prop:victoreq} For a play-measure $\sigma$ of weight $w$, the following
      are equivalent.
      \begin{enumerate}[wide]
      \item \label{item:vict} $\sigma$ is victorious.
      \item \label{item:supff}  For all $x \smin [0,w)$, there is a finitely founded
        play-measure $\tau \leqslant \sigma$ of weight greater or equal $x$.
      \item \label{item:supvict} For all $x \smin [0,w)$, there is a victorious 
        play-measure $\tau \leqslant \sigma$ of weight greater or equal $x$.
      \end{enumerate}
   \end{lemma}
   \begin{proof}
For (\ref{item:supff}) $\Rightarrow$ (\ref{item:supvict}), we note
that any well-founded play-measure is victorious since it is definable.
%

%
%

For (\ref{item:supvict}) $\Rightarrow$ (\ref{item:vict}), let $\rho$
be a counterstrategy.  For any $\varepsilon > 0$, we show that
$\continf{\rho}{\sigma} \leqslant 2\varepsilon$.  Take a victorious play-measure
$\tau \leqslant \sigma$ of weight greater or equal $w(\sigma) - \varepsilon$.  For all $n \smin \nats$, we have
\begin{eqnarray*}
\contprob{n}{\rho}{\sigma} & \leqslant & \varepsilon +
\contprob{n}{\rho}{\tau}
\end{eqnarray*}
by induction on $n$, using \cref{prop:decsurvive}.  For the
inductive step we reason
\begin{flalign*}
  \contprob{n+1}{\rho}{\sigma} =&\; \contprob{n}{\rho}{\sigma} - \sum_{s \in
                         \rhofailof{n} } \sigmapass(s) \\
                      \leqslant&\; \varepsilon +
                                 \contprob{n}{\rho}{\tau} -
                                 \sum_{s \in
                         \rhofailof{n}} \taupass(s)
  & \text{ (IH and $\tau \leqslant \sigma$)} \\
    =&\; \varepsilon + \contprob{n+1}{\rho}{\tau}
\end{flalign*}
 Take $n$ large enough that
$\contprob{n}{\rho}{\tau} \leqslant \varepsilon$.  Then  $\continf{\rho}{\sigma} \
\leqslant \ \contprob{n}{\rho}{\sigma} \ \leqslant \ 2\varepsilon$ as required.

Lastly we prove (\ref{item:vict}) $\Rightarrow$ (\ref{item:supff}),  




 For each active-ending play $s$, define $\sigma.s$ to be the play-measure sending passive-ending $t$ to $\sigma(s.t)$.  Define $q(s)$ to be the
     supremum of all possible values of $w(\tau)$ for a finitely founded
     play-measure $\tau \leqslant \sigma.s$.

  For each passive-ending play $s.k$ we proceed similarly.  For $w
  \smin [0,1]$, say  that a \emph{$k$-play-measure} of weight $w$ is a family $(\sigma_i)_{i
   \in\arity{k}}$ of play-measures of weight $w$.  Define
  $\sigma.s.k$ to be the $k$-play-measure $(\sigma.s.k.i)_{i \in
    \arity{k}}$.  Define $q(s.k)$ to be the supremum of all
  possible values of $w(\tau)$ for a finitely founded $k$-play-measure 
  $\tau \leqslant \sigma.s.k$.  

  Thus we have $0 \leqslant q(s) \leqslant \sigma(s)$ for every active- or
  passive-ending $s$.  Furthermore, for every active-ending $s$, we
  have $q(s) = \sum_{k \in K} q(s.k)$, and for every passive-ending
  $s.k$, we have $q(s.k) = \inf_{i\in\arity{k}} q(s.k,i)$, taking this
  infimum to be $\sigma(s.k)$ if $\arity{k} = \emptyset$.  

Now, for all active- or passive-ending  $s$ we put $r(s) \eqdef
\sigma(s) - q(s)$.  Thus $0 \leqslant r(s) \leqslant \sigma(s)$.  Furthermore, for every active-ending
$s$, we have $r(s) = \sum_{k \in K} r(s,k)$, and for every
passive-ending $s.k$ we have $r(s.k) = \sup_{i\in\arity{k}}
r(s.k.i)$, taking this supremum to be 0 if $\arity{k} = \emptyset$.

We shall show that $r(0) = 0$ and hence $q(0) = w(\sigma)$, which
gives our required result.  Parenthetically,
it follows by induction that, for all active- or passive-ending $s$,
we have $r(s)
= 0$ and hence $q(s) =
\sigma(s)$.

For all $n \smin \nats$, put $a_n \eqdef 2 - \frac{1}{n+1}$.  This gives 
a sequence
\begin{math}
  1 = a_0 < a_1 < \cdots  
\end{math}.   
of numbers less than 2.  Choose a partial counterstrategy $\rho$ such that,
for any passive-ending $t.k$ with $|t| =n$ and $\arity{k} \not= \emptyset$, we have $r(\sigma(t.k)) \geqslant
\frac{a_{n}}{a_{n+1}} r(t.k)$ or equivalently $r(t.k) \leqslant
\frac{a_{n+1}}{a_{n}}r(\sigma(t.k))$.     For $t \smin \rho$ of length $n$, 
\begin{align*}
  r(t) =&\; \sum_{k \in K} r(t.k) \\*
  =&\; \sum_{\substack{k \in K \\ \arity{k} = \emptyset}} r(t.k) +
  \sum_{\substack{k \in K \\ \arity{k} \not= \emptyset}} r(t.k) \\
  \leqslant&\; 0 + \frac{a_{n+1}}{a_n} \sum_{\substack{k \in K \\ \arity{k} \not= \emptyset}} r(\sigma(t.k)) 
\end{align*}
Adding these equations over all such $t$ we get
\begin{align*}
    \sum_{\substack{t\in\rho \\ |t| = n}} r(t) \leqslant&\; 
                                                           \frac{a_{n+1}}{a_n}
                                                           \sum_{\substack{t
                                                          \in\rho \\
  |t| = n+1}} r(t)  
\end{align*}
and therefore
\begin{flalign*}
&& r(0) \leqslant &\; a_{n} \sum_{\substack{t\in\rho \\ |t| = n}}
                    r(t)  & \text{ (by induction on $n$)} \\
&&  \leqslant&\; 2 \sum_{\substack{t\in\rho \\ |t| = n}} \sigma(t)
 &\text{ (since $a_n
  < 2$ and $r(t) \leqslant \sigma(t)$)} \\
&& =&\; 2 \contprob{n}{\rho}{\sigma}
\end{flalign*}%
Since this holds for all $n \smin \nats$, we have
$r(0) \ \leqslant \ 2\continf{\rho}{\sigma} = 0$
  as required. 
   \end{proof}

   \begin{theorem}\label{thm:def}
     A strategy $\sigma$ is definable iff it is victorious.
   \end{theorem}
   \begin{proof}
        ($\Rightarrow$) follows from \cref{prop:presvictor}.
     To prove
     ($\Leftarrow$), we define for each $n \smin \nats$ a victorious
     strategy $\sigma_n$ of weight $2^{-n}$ and a finitely founded strategy $\tau_n$ of
     weight $2^{-n-1}$, as
     follows:
     \begin{itemize}
     \item We put $\sigma_0 \eqdef \sigma$.
     \item $\tau_n$ is a finitely founded strategy smaller or equal $\sigma_n$ of weight $2^{-n}$, which exists by
       \cref{prop:victoreq}(\ref{item:supff}).
     \item  We put $\sigma_{n+1} \eqdef \sigma_n - \tau_n$.
     \end{itemize}     
For all $n \smin \nats$ we have $\sigma = \sum_{k < n} \tau_k  +
\sigma_n$.  Since $\sigma_n (s) \leqslant w(\sigma_n) =
2^{-n-1}$ for all $s$, we have $\sigma = \sum_{k\in\nats}
\tau_k$.  \cref{prop:wfstratdef}(\ref{item:wfstratdef}) tells us that $\tau_k$ is the denotation
of some partial term $M_k$, so the program $\sum_{k\in\nats} M_k$
denotes $\sigma$.
   \end{proof}

   \section{Monads and theories}\label{sec:monadsth}
\subsection{Strategy monads} \label{sec:monads}

We now turn to the connections with monads on $\set$. Recall that $\dist$
and $\distfin$ are the monads of discrete and finitely supported distributions 
correspondingly. For the rest, let $S = (\arity{k})_{k\in\Ops}$ be a signature. 
  For any set $A$, write $S+A$ for the signature extending $S$ with 
  $A$ additional constants.  Then an \emph{$S$-term on $A$} is a term
  built up using operations in $S$ and $A$-many variables; this
  corresponds to a deterministic $(S+A)$-program.  

%
%
%

  We define the following monads.
  \begin{definition}
    \begin{enumerate}
    \item The \emph{free monad} $T_S$ sends a set $A$ to the set of
      all $S$-terms on $A$.
     \item The monad ${\distfin}_{S}$ sends a set $A$ to the set of
       finitely probabilistic $(S+A)$-terms modulo bisimilarity.
     \item The monad $\dist_{S}$ sends a set $A$ to the set of
       countably probabilistic  $(S+A)$-terms modulo
       bisimilarity.
     \item The monad $\finfound_{S}$ sends a set $A$ to the set of all finitely founded $(S+A)$ strategies,
    corresponding to finitely probabilistic $(S+A)$-terms modulo trace
    equivalence.
   \item The monad $\vict_{S}$ sends a set $A$ to the set of all victorious $(S+A)$ strategies,
    corresponding to countably probabilistic $(S+A)$-terms modulo trace
    equivalence.
    \end{enumerate}
  \end{definition}

