\subsection{Proof of  \Cref{prop:tensorholds}}
  Given $k \smin \Ops$, we show
  \begin{align*}
    \sum_{n\in\nats} p_n \ml \mathsf{Req}\,k?& (\sigma_{n,i})_{i \in
   \arity{k}}  =&\,\\  &\mathsf{Req}\,k? \Bigl(\sum_{n\in\nats} p_n \ml  \sigma_{n,i}\Bigr)_{i \in
                     \arity{k}}
                 \end{align*}
   as follows.  Any play beginning
         with an output other than $k$ is assigned 0 by each side.
         The play $k$ itself is assigned $1$ by each side.  A play of
         the form $k.i.s$ is assigned $\sum_{n\in\nats} p_n\ml
         \sigma_{n,i}(s)$ by each side.\qed

\subsection{Proof of  \Cref{pro:bisim}}
  We give the case of countable probabilistic choice.  Firstly, we
  define the \emph{crude} and \emph{rooted} programs
  inductively as follows.
  \begin{itemize}[wide]
  \item The program $\inpu{k}{ (M_{i})_{i \in
          \arity{k}} }$ is rooted if the programs $(M_{i}) _{i \in
        \arity{k}} $ are all crude.
   \item The program $\sum_{n < \alpha} p_n \ml M_n$, where $\alpha$
     is either $\omega$ or a natural number, is crude if the programs
     $(M_n)_{n < \alpha}$ are all crude.
  \end{itemize}
We prove that bisimilar crude programs are sum-equivalent, and
bisimilar rooted programs are sum-equivalent, by mutual induction.
For the rooted case, we note that
\begin{eqnarray*}
  \inpu{k}{ (M_{i})_{i \in
          \arity{k}} } & \sim & \inpu{l}{ (N_{i})_{i \in
          \arity{l}} }
\end{eqnarray*}
means that $k=l$ and, for all $i\in\arity{k}$, we have $M_i \sim
N_i$.  For the crude case, we note that
\begin{eqnarray*}
  \sum_{n < \alpha} p_n \ml M_n & \sim &  \sum_{n < \beta} q_n \ml N_n 
\end{eqnarray*}
means that, for any rooted program $R$, we have 
\begin{eqnarray*}
  \sum_{\substack{n < \alpha \\ M_n \sim R}} p_n & = & \sum_{\substack{n < \beta \\ N_n \sim R}} q_n
\end{eqnarray*}
So, up to sum-equivalence, we can gather up all the bisimilarity
classes on each side and get the same result.
\qed
\subsection{Proof of  \Cref{prop:finstuff}}
%
By induction, for each program $M$, the strategy $\tracesof{M}$ is
finitely founded, and the corresponding normal form is
equivalent to $M$. Therefore, if $M$ and $M'$ have the same trace
semantics $\sigma$, then they are both tensor-equivalent to
the corresponding normal form.
\qed
%
\subsection{Proof of  \Cref{prop:subsplit}}
 We assume that $M = \tesum_{k \in A} a_k \ml
        \inpu{k}(M_{k,i})_{i\in\arity{k}}$ is in shallow normal-form and that $L = \tesum_{k \in B} b_k \ml
