\begin{flalign*}
&& p \tracesof{L} (k.i.s) \leqslant &\; \tracesof{M}(k.i.s) && \\
  \text{i.e.} && p b_k \tracesof{L_{k,i}}(s) \leqslant &\; a_k
                                                              \tracesof{M_{k,i}}(s)
                                                            \end{flalign*}%
The inductive hypothesis gives $N_{k,i}$ such that 
  \begin{align*}
    M_{k,i} =\, & {L_{k,i}} +_{\frac{pb_k}{a_k}} N_{k,i}
  \end{align*}                                      
  Put 
  \begin{align*}
    N \eqdef\, & \sum_{k \in A} \begin{cases}
                 \frac{a_k - pb_k}{1-p}\ml  \inpu{k}(N_{k,i})_{i\in\arity{k}} & (k \in B) \\
                  \frac{a_k}{1-p}\ml \inpu{k}(M_{k,i})_{i\in\arity{k}}        & (k \not\in B)
                \end{cases}
  \end{align*}
 Clearly the coefficients are nonnegative and sum to 1.   Now we have
  \begin{align*}
    M \equiv\, & \sum_{k \in A} a_k\ml\inpu{k}(M_{k,i})_{i \in
                 \arity{k}} \\
      \equiv\, & \sum_{k \in A} 
                 \begin{cases}
                  a_k\ml\inpu{k} (L_{k,i}
                   +_{\frac{pb_k}{a_k}} N_{k,i})_{i\in\arity{k}} &
                                                                     (k
                                                                     \in
                   B) \\
                  a_k\ml\inpu{k}(M_{k,i})_{i\in\arity{k}} & (k \not\in B)
                 \end{cases} \\
      \equiv\, & \sum_{k \in A} \begin{cases}
                  a_k\ml \bigl(\inpu{k} (L_{k,i})_{i\in\arity{k}}\\
                   \qquad +_{\frac{pb_k}{a_k}} \inpu{k}(N_{k,i})_{i \in
                   \arity{k}}\bigr) &~\quad
                                                                     (k
                                                                     \in
                   B) \\
                  a_k\ml\inpu{k}(M_{k,i})_{i \in
                 \arity{k}} &\quad~ (k \not\in B)
                 \end{cases} \\
     \equiv\, & \sum_{k \in B} b_k\ml \inpu{k}  (L_{k,i})_{i
               \in\arity{k}}\\&\quad +_p \sum_{k \in A} 
                \begin{cases}
                 \frac{a_k - pb_k}{1-p}\ml  \inpu{k}(N_{k,i})_{i \in
                  \arity{k}} & (k \in B) \\
                  \frac{a_k}{1-p}\ml \inpu{k}(M_{k,i})_{i\in\arity{k}}
                             & (k \not\in B)
                \end{cases} \\
    =\, & L +_p N
  \end{align*}
  as required.\qed

\subsection{Proof of  \Cref{lem:impers-cancel}}
%
  There is a sequence $a= (a_n)_{n\in \nats}$ and an $a$-solution $r$ such that $x =
  \sum_{i\in\nats} 2^{-i-1} \ml a_i$ and $y = r_0$.  Then
  \begin{align*}
    y  \plushalf &\sum_{i\in\nats} 2^{-i-1} \ml r_{i+1}\\
     =&\, r_0 \plushalf
                                                      \sum_{i \in
                                                      \nats}
                                                              2^{-i-1} \ml r_{i+1}
    \\
                                                =&\, \sum_{i \in
                                                   \nats} 2^{-i-1}
                                                   \ml  r_i \\
                                                =&\, \sum_{i \in
                                                   \nats} 2^{-i-1}
                                                   \ml (a_i \plushalf r_{i+1}) \\
    =&\, \Bigl(\sum_{i\in\nats} 2^{-i-1} \ml a_i\Bigr) \plushalf \Bigl(\sum_{i \in
       \nats} 2^{-i-1} \ml 
          r_{i+1}\Bigr) \\
    =&\, x \plushalf \sum_{j\in\nats} 2^{-j-1} \ml 
          r_{j+1} \tag*{$\qed$}
   \end{align*}

\subsection{Proof of  \Cref{prop:light}}
  Any light pre-normal  form is light normalizable, by
  finitary splitting and regathering. Light normalizability is
  preserved by $\mathsf{Req}\,k?$ via the tensor law, obviously
  preserved by $+_p$, and preserved by countable
  probabilistic choice via the following argument.   Given $M_i \equiv 2^{-n-1} \ml M_{i,n}$
  for all $i \smin \nats$, and a sequence $(p_i)_{i\in\nats}$ of
  positive reals summing to~1, the program $\sum_{n\in\nats} p_n \ml
  M_n$  has light pre-normal form $\sum_{r\in\nats} \beta_r \ml N_r$,
  writing
  \begin{align*}
    \beta_r  \eqdef & \;\sum_{i \leqslant r} p_i^{i-r-1} \\
    N_r \eqdef & \; \sum_{j \leqslant r} \frac{p_i
                 2^{i-r-1}}{\beta_r} \ml M_{i,r-i}
  \end{align*}
  The result follows by induction over programs.
\qed

\subsection{Proof of  \Cref{pro:inf-example}}
  \begin{enumerate}[wide]
  \item Take a witness $d \smin (0,1]$ for $\sigma
    \prec \tracesof{M}$, and $n \smin \nats$ large enough that $n
  \geqslant \frac{1}{d}$, or equivalently $\frac{1}{n} \leqslant d$.
  We have
  \begin{align*}
    0 <&\, w(\sigma) 
     = \sigma(\varepsilon) 
     = \sigma(b) 
     = \sigma(b.n) 
     = \sum_{i \leqslant n} \sigma(b.n.c_i)
%
%
%
%
%
  \intertext{
  So there is $i \leqslant n$ such that $b.n.c_i\in\supp{\sigma}$, and therefore}
    d \leqslant&\,\sigma(b.n.c_i) + d 
      \leqslant \tracesof{M}(b.n.c_i) 
      = \frac{1}{n+1} 
      < \frac{1}{n}
%
%
%
%
  \end{align*}
  contradicting  $\frac{1}{n} \leqslant d$.
  \item Follows.\qed
  \end{enumerate}

\subsection{Proof of  \Cref{prop:presvictor}}
      Let $\rho$ be a partial counterstrategy.
      \begin{enumerate}[wide]
      \item  For all $m \smin \nats$ we have
        \begin{math}
\contprob{m}{\rho}{\sigma +_p \sigma'}  =  p \contprob{m}{\rho}{\sigma} + {(1-p)}
                                      \contprob{m}{\rho}{\sigma}
        \end{math}.  
        Therefore
        \begin{align*}
          \continf{\rho}{\sigma +_p \sigma'} =&\; p \continf{\rho}{\sigma} + (1-p)
                                             \continf{\rho}{\sigma} \\
          =&\; 0
        \end{align*}
      \item Similar.
      \item If $k\in\failof{\rho}$, then for all $m \smin \nats$ we
        have $P^{m+1}_{\rho}(\sfinpu{k}(\sigma_i)_{i \in I}) = 0$.
      Therefore $P_{\rho}(\sfinpu{k}(\sigma_i)_{i \in I}) = 0$.  On
    the other hand, if  $k.i \smin \rho$, then let $\rho/k$ be the
    partial counterstrategy consisting of all plays
    $s$ such that $k.i.s\in\rho$.  For all $m \smin \nats$ we have
    $\contprob{m+1}{\rho}{\sfinpu{k}(\sigma_i)_{i \in I}} =
  \contprob{m}{\rho/k}{\sigma_i}$.  Therefore $\continf{\rho}{\sfinpu{k}(\sigma_i)_{i \in I}} = 
                                                    \continf{\rho/k}{\sigma_i} 
    = 0$.
%
%
%
%
%
 %
 %
 %
 %
 %
 %
 %
 %
 %
 %
 %
\qed
     \end{enumerate}

