\begin{equation}
\alpha(\theta) = \alpha_0 \, \left(1 + k_{\alpha} \, (\theta - \theta_{\mathrm{ref}})\right)
\end{equation}

\item \textbf{Workload Flexibility Characterization}:

Definition 1 (Workload Flexibility): The available power flexibility at time $t$ for duration $\tau$ is:
\begin{equation}
F(t, \tau) = \sum_{k \in K} p_k(t) \, f_k(\tau) \, \left(1 - L_k(t, \tau)\right)
\end{equation}

where:
\begin{itemize}
  \item $p_k(t)$: Power fraction of workload class $k$
  \item $f_k(\tau)$: Deferability factor for duration $\tau$
  \item $L_k(t,\tau)$: Performance loss function
\end{itemize}



