\item \textbf{ Protection System Dynamics}: Following \cite{jimenezruiz2024datacenter}, voltage-sensitive disconnection behavior:


\begin{equation}
\frac{dN_{\text{trip}}}{dt} = 
\begin{cases}
\lambda_{\text{trip}}(V, f) \, (N_{\text{on}} - N_{\text{trip}}) & \text{if } V < V_{\text{threshold}} \text{ or } |f - f_0| > \Delta f_{\text{threshold}} \\
-\lambda_{\text{recon}} \, N_{\text{trip}} & \text{if } t > t_{\text{last\_trip}} + t_{\text{recon\_delay}} \\
0 & \text{otherwise}
\end{cases}
\end{equation}

\noindent where:

\begin{equation}
\lambda_{trip}(V,f) = \lambda_0 \, \exp\left(-\frac{(V - V_{threshold})^2}{2\sigma_V^2}\right) \, \exp\left(-\frac{(f - f_0)^2}{2\sigma_f^2}\right)
\end{equation}
\end{enumerate}
\vspace{0pt}
\subsection{VPP Component Models}

 \begin{enumerate} 
    \item \textbf{Battery Energy Storage System}: State-of-charge dynamics:
    \begin{equation}
\frac{\text{dSoC}}{dt} = \frac{1}{E_{\text{nom}}} \left( \eta_{\text{ch}} \, P_{\text{ch}} \, u_{\text{ch}} - \frac{P_{\text{dis}}}{\eta_{\text{dis}}} \, u_{\text{dis}} \right)
\end{equation}


\noindent Efficiency functions accounting for SoC and temperature:

\begin{equation}
\eta_{ch}(\text{dSoC},T) = \eta_{ch,0} - k_{ch,SoC} \, (\text{dSoC} - 0.5)^2 - k_{ch,T} \, (T - T_{ref})
\end{equation}

\item \textbf{Grid Interface Model}:
Point of common coupling voltage:

\begin{equation}
V_{pcc}(t) = V_{grid}(t) - Z_{th}(t) \, I_{pcc}(t)
\end{equation}

\begin{equation}
Z_{th}(t) = R_{th} + j\omega L_{th} \, \left(1 + k_{sat} \, |I_{pcc}(t)|^2\right)
\end{equation}

\end{enumerate}


