\subsection{Layer 0: Power Electronic Interface Control}

Control objective: Minimize high-frequency power oscillations while maintaining power factor.
State-space representation:

\begin{equation}
\dot{x}_0 = A_0 x_0 + B_0 u_0 + E_0 w_0
\end{equation}


where \( x_0 = [i_d, i_q, v_{dc}]^T \) represents d--q axis currents and DC link voltage.


Control law:

\begin{equation}
u_0 = -K_0 x_0 + F_f \, \hat{P}_{\mathrm{osc}}
\end{equation}

where \( F_f \) is a high-pass filter extracting oscillatory components.

\begin{equation}
F_f(s) = \frac{s}{s + \omega_c}
\end{equation}
with cutoff frequency $\omega_c$ selected based on workload characteristics\footnote{ This layer represents enhanced local control within data center power electronics, with VPP providing supervisory parameter updates at slower timescales.
}.


\subsection{Layer 1: Fast Power Dispatch}

Model Predictive Control formulation over horizon $N_p$:

\begin{equation}
\min_{u_1} \sum_{k=0}^{N_p} \left\| P_{\mathrm{DC}}(k|t) - P_{\mathrm{ref}}(k|t) \right\|_Q^2 + \left\| \Delta u_1(k|t) \right\|_R^2
\end{equation}


\begin{itemize}
  \item Power ramp constraints: $|\Delta P_{\mathrm{DC}}| \leq R_{\max} \, \Delta t$
  \item Thermal constraints: $\theta_{\mathrm{chip}} \leq \theta_{\max}$
  \item Workload constraints: $D_{\mathrm{job}} \leq D_{\max}$
\end{itemize}


\subsection{Layer 2: Flexibility Coordination}

Stochastic optimization problem:

\begin{equation}
\min_{u_2} \mathbb{E} \left[ \sum_t C_{\text{energy}}(t) \, P_{\text{grid}}(t) 
+ C_{\text{wear}} \, |P_{\text{BESS}}(t)| + C_{\text{perf}} \,   L(t) \right]
\end{equation}

Subject to:
\begin{equation}
\mathbb{P} \left\{ \text{QoS}(t) \geq \text{QoS}_{\min} \right\} \geq 1 - \varepsilon_{\text{QoS}}
\end{equation}

Checkpoint-aware scheduling constraint:
\begin{equation}
t_{\text{migrate}} \in T_{\text{checkpoint}} = \left\{ t : \text{checkpoint completed at } t \right\}
\end{equation}



\subsection{Layer 3: Market Integration}

Two-stage stochastic programming:

First stage (day-ahead):

\begin{equation}
\min_{P_{\text{DA}}} \, c_{\text{DA}}^T P_{\text{DA}} + \mathbb{E}_{\xi} \left[ Q(P_{\text{DA}}, \xi) \right]
\end{equation}

\begin{equation}
Q(P_{\text{DA}}, \xi) = \min_{P_{\text{RT}}} \, c_{\text{RT}}(\xi)^T P_{\text{RT}} + \pi^T (P_{\text{RT}} - P_{\text{DA}})
\end{equation}


\subsection{Inter-Layer Coordination}



\textbf{Theorem 1 (Hierarchical Stability)}: The multi-layer system is stable if:
\begin{enumerate}
    \item Each layer is individually stable.
    \item Time-scale separation: $\tau_{i+1}/\tau_i \geq 10$.
    \item Information consistency: $\|x_i^* - \pi_i(x_{i+1}^*)\|_2 \leq \varepsilon_{\text{coord}}$.
\end{enumerate}

where $\pi_i$ is the projection operator from layer $i+1$ to layer $i$.

Proof: See Appendix~\ref{sec:appendixA}.

\section{STABILITY ANALYSIS UNDER EXTREME DYNAMICS}
\label{sec_4}
\subsection{Small-Signal Stability with Pulsing Loads}

System linearization around periodic trajectory:


\begin{equation}
\Delta \dot{x} = A(t) \Delta x + B(t) \Delta u
\end{equation}

where \( A(t) = A_0 + A_p \cos(\omega_p t) \) captures pulsing effects.

\textbf{Theorem 2 (Pulsing Load Stability)}: The system remains small-signal stable if:
\begin{enumerate}
  \item All Floquet multipliers satisfy \(|\mu_i| < 1\) \citep{floquet1883equations}
  \item The pulsing participation factor satisfies:
\end{enumerate}


\begin{equation}
p_{\text{pulse}} < \frac{2 \zeta_{\min} \omega_0}{M_{\text{pulse}}}
\end{equation}

where \( M_{\text{pulse}} = {\|A_p\|_2}/{\|A_0\|_2} \).

Proof: See Appendix~\ref{sec:appendixb}.

\subsection{Large-Disturbance Stability}

Definition 2 (Critical Energy with Protection Dynamics):

\begin{equation}
W_{cr} = W_{cr,0} - \Delta W_{pulse} - \Delta W_{protection}
\end{equation}

where:
\begin{itemize}
  \item $W_{cr,0}$: Classical critical energy \citep{kundur2004definition,hatziargyriou2022definition} 
  \item $\Delta W_{pulse}$: Reduction due to pulsing loads
  \item $\Delta W_{protection}$: Impact of protection disconnections
\end{itemize}
\vspace{0.3cm}
\textbf{Theorem 3 (Transient Stability)}: The system maintains stability following a disturbance if:

\begin{enumerate}
    \item  Fault clearing time satisfies:

\begin{equation}
t_{\text{clear}} < t_{\text{cr}} \, \left(1 - k_p \, \frac{P_{\text{pulse}}}{P_{\text{base}}}\right)
\end{equation}

where \( k_p \in [0.3, 0.5] \) for gigawatt-scale loads.

\item  Post-fault trajectory satisfies the energy constraint:

\begin{equation}
V(x(t)) \leq W_{cr} - \int_0^t P_{trip}(\tau) \, d\tau
\end{equation}
\end{enumerate}

Proof: See Appendix~\ref{sec:appendixc}.

\subsection{Converter-Dominated System Stability}

For pure converter interfaces, stability requires:

\textbf{Theorem 4 (Impedance-Based Stability)}:The interconnected system is stable if

\begin{equation}
\left| \frac{Z_{DC}(j\omega)}{Z_{grid}(j\omega)} \right| < \frac{1}{G_m} \quad \forall \, \omega \in [\omega_l, \omega_h]
\end{equation}

where \( G_m > 2 \) provides adequate stability margin \citep{cigre2024multifrequency,milano2018foundations,kroposki2017achieving}.

