\section{APPENDIX A}
\label{sec:appendixA}

\textbf{PROOF OF HIERARCHICAL STABILITY}

We prove that the multi-layer control system is stable under the three stated conditions.

Given the hierarchical system with layers $i = 0, 1, 2, 3$, where each layer has dynamics:
\begin{equation}
\dot{x}_i = f_i(x_i, u_i, w_i) \tag{A.1}
\end{equation}
where $x_i \in \mathbb{R}^{n_i}$ is the state vector, $u_i \in \mathbb{R}^{m_i}$ is the control input, and $w_i \in \mathbb{R}^{p_i}$ represents disturbances.

\textbf{Condition 1: Individual Layer Stability} \\
For each layer $i$, assume there exists a Lyapunov function $V_i(x_i)$ such that:
\begin{equation}
\alpha_i(\|x_i\|) \leq V_i(x_i) \leq \beta_i(\|x_i\|) \tag{A.2}
\end{equation}
where $\alpha_i$ and $\beta_i$ are class $\mathcal{K}_\infty$ functions, and:
\begin{equation}
\dot{V}_i(x_i) \leq -\gamma_i(\|x_i\|) + \delta_i(\|w_i\|) \tag{A.3}
\end{equation}

where $\gamma_i$ is a class $\mathcal{K}$ function and $\delta_i$ is a class $\mathcal{K}$ function bounding the disturbance effect.

\textbf{Condition 2: Timescale Separation} \\
With $\tau_{i+1} / \tau_i \geq 10$, we apply singular perturbation theory. Define:
\begin{equation}
\varepsilon_i = \frac{\tau_i}{\tau_{i+1}} \leq 0.1 \tag{A.4}
\end{equation}

The system can be written in two-timescale form:
\begin{equation}
\dot{x}_{i+1} = f_{i+1}(x_{i+1}, h_i(x_i), w_{i+1}) \tag{A.5}
\end{equation}
\begin{equation}
\varepsilon_i \dot{x}_i = f_i(x_i, u_i, w_i) \tag{A.6}
\end{equation}
where $h_i(x_i)$ represents the quasi-steady-state mapping from layer $i$ to layer $i+1$.

For the fast subsystem (layer $i$), setting $\varepsilon_i = 0$:
\begin{equation}
0 = f_i(x_i, u_i, w_i) \tag{A.7}
\end{equation}

This yields the quasi-steady-state:
\begin{equation}
x_i^* = g_i(u_i, w_i) \tag{A.8}
\end{equation}

For the slow subsystem (layer $i+1$), substituting (A.8):
\begin{equation}
\dot{x}_{i+1} = f_{i+1}(x_{i+1}, h_i(g_i(u_i, w_i)), w_{i+1}) \tag{A.9}
\end{equation}

\textbf{Condition 3: Information Consistency} \\
The projection operator $\pi_i : \mathbb{R}^{n_{i+1}} \to \mathbb{R}^{n_i}$ satisfies:
\begin{equation}
\|x_i^* - \pi_i(x_{i+1}^*)\|_2 \leq \varepsilon_{\text{coord}} \tag{A.10}
\end{equation}

This ensures that the quasi-steady-state approximation error is bounded.

\textbf{Composite Lyapunov Function:} \\
Define the composite Lyapunov function:
\begin{equation}
V(x) = \sum_{i=0}^{3} \mu_i V_i(x_i) \tag{A.11}
\end{equation}
where $\mu_i > 0$ are weighting factors chosen such that $\mu_{i+1}/\mu_i = \mathcal{O}(\varepsilon_i)$.

Taking the time derivative:
\begin{equation}
\dot{V}(x) = \sum_{i=0}^{3} \mu_i \dot{V}_i(x_i) \tag{A.12}
\end{equation}

Substituting (A.3):
\begin{equation}
\dot{V}(x) \leq -\sum_{i=0}^{3} \mu_i \gamma_i(\|x_i\|) + \sum_{i=0}^{3} \mu_i \delta_i(\|w_i\|) \tag{A.13}
\end{equation}

Under the timescale separation condition, the boundary layer corrections satisfy:
\begin{equation}
\|x_i - x_i^*\| = \mathcal{O}(\varepsilon_i) \tag{A.14}
\end{equation}

Therefore:
\begin{equation}
\dot{V}(x) \leq -\gamma(\|x\|) + \delta(\|w\|) \tag{A.15}
\end{equation}
where $\gamma$ and $\delta$ are appropriate class $\mathcal{K}$ functions.

This establishes input-to-state stability (ISS) of the hierarchical system. For $w = 0$, we have $\dot{V}(x) < 0$ for $x \neq 0$, proving asymptotic stability.







\section{APPENDIX B}
\label{sec:appendixb}

FLOQUET THEORY APPLICATION FOR PULSING LOADS

We analyze the stability of the system with periodic pulsing loads using Floquet theory.

Consider the linearized system around a periodic trajectory:
\begin{equation}
\Delta\dot{x} = A(t)\Delta x + B(t)\Delta u \tag{B.1}
\end{equation}
where $A(t) = A_0 + A_p \cos(\omega_p t)$ is $T$-periodic with $T = \frac{2\pi}{\omega_p}$.

Floquet Theory Framework: \\
The fundamental matrix $\Phi(t)$ satisfies:
\begin{equation}
\dot{\Phi}(t) = A(t)\Phi(t), \quad \Phi(0) = I \tag{B.2}
\end{equation}

The monodromy matrix is:
\begin{equation}
M = \Phi(T) \tag{B.3}
\end{equation}

The Floquet multipliers $\mu_i$ are the eigenvalues of $M$. For stability, all $|\mu_i| < 1$.

Perturbation Analysis: \\
Let $\varepsilon = \|A_p\|_2 / \|A_0\|_2$ be the pulsing strength. For small $\varepsilon$, we expand:
\begin{equation}
\Phi(t) = \Phi_0(t) + \varepsilon \Phi_1(t) + \varepsilon^2 \Phi_2(t) + \mathcal{O}(\varepsilon^3) \tag{B.4}
\end{equation}
where $\Phi_0(t) = \exp(A_0 t)$.

First-order correction:
\begin{equation}
\dot{\Phi}_1(t) = A_0 \Phi_1(t) + A_p \cos(\omega_p t) \Phi_0(t) \tag{B.5}
\end{equation}

Using the variation of parameters formula:
\begin{equation}
\Phi_1(t) = \Phi_0(t) \int_0^t \Phi_0^{-1}(s) A_p \cos(\omega_p s) \Phi_0(s) \, ds \tag{B.6}
\end{equation}

Simplifying:
\begin{equation}
\Phi_1(t) = \int_0^t \exp(A_0(t - s)) A_p \exp(A_0 s) \cos(\omega_p s) \, ds \tag{B.7}
\end{equation}

Monodromy Matrix Approximation: \\
The monodromy matrix to first order:
\begin{equation}
M \approx \exp(A_0 T) + \varepsilon \int_0^T \exp(A_0(T - s)) A_p \exp(A_0 s) \cos(\omega_p s) \, ds \tag{B.8}
\end{equation}

For the eigenvalues of $M$, using perturbation theory:
\begin{equation}
\mu_i \approx \lambda_i (1 + \varepsilon \kappa_i) \tag{B.9}
\end{equation}
where $\lambda_i = \exp(\sigma_i T)$ are the eigenvalues of $\exp(A_0 T)$, with $\sigma_i$ being the eigenvalues of $A_0$.

Stability Condition: \\
For stability, $|\mu_i| < 1$ for all $i$. This requires:
\begin{equation}
|\lambda_i (1 + \varepsilon \kappa_i)| < 1 \tag{B.10}
\end{equation}

Assuming $A_0$ is stable ($\text{Re}(\sigma_i) < 0$), we have $|\lambda_i| < 1$. The condition becomes:
\begin{equation}
|1 + \varepsilon \kappa_i| < \frac{1}{|\lambda_i|} \tag{B.11}
\end{equation}

For the critical mode (minimum damping $\zeta_{\min}$), we have:
\begin{equation}
\sigma_{\text{crit}} = -\zeta_{\min} \omega_0 \tag{B.12}
\end{equation}

The stability condition becomes:
\begin{equation}
\varepsilon < \frac{\exp(\zeta_{\min} \omega_0 T) - 1}{|\kappa_{\text{crit}}|} \tag{B.13}
\end{equation}

Relating to the pulsing participation factor:
\begin{equation}
p_{\text{pulse}} = \frac{\varepsilon \omega_0 T}{2\pi} \tag{B.14}
\end{equation}

We obtain:
\begin{equation}
p_{\text{pulse}} < \frac{2 \zeta_{\min} \omega_0}{M_{\text{pulse}}} \tag{B.15}
\end{equation}
where $M_{\text{pulse}} = \|A_p\|_2 / \|A_0\|_2$.


\section{APPENDIX C}
\label{sec:appendixc}

TRANSIENT ENERGY FUNCTION FORMULATION

Consider the power system with $n$ generators and $m$ AI data center loads:
\begin{equation}
M_i \ddot{\delta}_i + D_i \dot{\delta}_i = P_{m_i} - P_{e_i}(\delta, V) - P_{\text{pulse},i}(t)
\tag{C.1}
\end{equation}

Define the transient energy function:
\begin{equation}
V(\delta, \omega) = V_{\text{ke}}(\omega) + V_{\text{pe}}(\delta) + V_{\text{pulse}}(\delta, t) + V_{\text{prot}}(\delta, V)
\tag{C.2}
\end{equation}

Kinetic energy:
\begin{equation}
V_{\text{ke}}(\omega) = \frac{1}{2} \sum_i M_i \omega_i^2
\tag{C.3}
\end{equation}

Potential energy:
\begin{equation}
V_{\text{pe}}(\delta) = -\sum_i P_{m_i}(\delta_i - \delta_i^s) - \int_{\delta^s}^{\delta} \sum_{ij} E_i' E_j' Y_{ij} \cos(\delta_i - \delta_j - \alpha_{ij}) \, d\delta
\tag{C.4}
\end{equation}

For periodic pulsing loads:
\begin{equation}
V_{\text{pulse}}(\delta, t) = \sum_i A_{\text{pulse},i} \int_{\delta_i^s}^{\delta_i} \sin(\omega_p t + \phi_i(\delta_i')) \, d\delta_i'
\tag{C.5}
\end{equation}

The protection system introduces discrete energy changes:
\begin{equation}
V_{\text{prot}}(\delta, V) = \sum_{k \in \text{tripped}} P_{k,\text{trip}} \int_{t_{\text{trip},k}}^t H(V - V_{\text{thresh}}) \, dt
\tag{C.6}
\end{equation}

The critical energy is the energy at the controlling unstable equilibrium point (UEP):
\begin{equation}
W_{\text{cr},0} = V(\delta^u, 0) - V(\delta^s, 0)
\tag{C.7}
\end{equation}

With pulsing loads and protection:
\begin{equation}
W_{\text{cr}} = W_{\text{cr},0} - \Delta W_{\text{pulse}} - \Delta W_{\text{protection}}
\tag{C.8}
\end{equation}

where
\begin{equation}
\Delta W_{\text{pulse}} = \max_{t \in [0,T]} \left[ V_{\text{pulse}}(\delta^u, t) - V_{\text{pulse}}(\delta^s, t) \right]
\tag{C.9}
\end{equation}
\begin{equation}
\Delta W_{\text{protection}} = \sum_{k \in \text{tripped}} P_{k,\text{trip}} \, t_{\text{clear}}
\tag{C.10}
\end{equation}

The system is transiently stable if:
\begin{equation}
V(\delta(t), \omega(t)) < W_{\text{cr}} \quad \forall t > t_{\text{clear}}
\tag{C.11}
\end{equation}

The critical clearing time $t_{\text{cr}}$ satisfies:
\begin{equation}
V(\delta(t_{\text{cr}}), \omega(t_{\text{cr}})) = W_{\text{cr}}
\tag{C.12}
\end{equation}

For gigawatt-scale pulsing loads:
\begin{equation}
t_{\text{cr}} \approx t_{\text{cr},0} \left(1 - k_p \frac{P_{\text{pulse}}}{P_{\text{base}}} \right)
\tag{C.13}
\end{equation}
where $k_p \in [0.3, 0.5]$ is determined from extensive simulations accounting for:
\begin{itemize}
    \item Pulsing amplitude and frequency
    \item Protection system settings
    \item System inertia distribution
    \item Network topology
\end{itemize}

The factor $k_p$ increases with:
\begin{itemize}
    \item Higher pulsing amplitude
    \item Lower system inertia
    \item Faster protection system response
    \item Weaker grid connection (lower SCR)
\end{itemize}

This completes the derivation of the transient energy function incorporating AI data center dynamics.











