\subsection{Lower bounds for the $L^p$-STC}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
The aim of this section is to obtain general and computable lower bounds for the $L^p$ congestion. First of all, we will adapt Proposition~\ref{p:lower_bounds} to the case of edge-weighted graphs.

Let $(G,\omega)$ be an edge-weighted graph. Let $\wp$ be a path in $(G,\omega)$, define $m_\omega(\wp)$ as the minimum edge-weight among the edges in the path $\wp$. Let $\mathcal{P}(u,v)$ be the family of maximal sets formed by pairwise edge-disjoint $(u,v)$-paths (i.e., each set has the maximum number of such paths). Let us define
$$
m_\omega(u,v) = \max_{M\in\mathcal{P}(u,v)}\left\{\sum_{\wp\in M}m_\omega(\wp)\right\}\;.
$$
Observe that $m_\omega(u,v)=m(u,v)$ if $\omega$ is constant equal to $1$.

\begin{prop}\label{p:weighted_bound_infty}
Let $(G,\omega)$ be an edge-weighted graph. Then
$$
\max_{u,v\in V} m_\omega(u,v)\leq\mathcal{C}_\infty(G,\omega)\;.
$$
\end{prop}
\begin{proof}
Let $u,v\in V$ and let $T$ be an arbitrary spanning tree. Let $e$ be an edge in $T$ so that $u\in X_e$ and $v\in X_e^c$. Let $M\in\mathcal{P}(u,v)$. For every $(u,v)$-path $\wp$ in $C$ we obtain at least one edge $e_\wp$ joining $X_e$ with $X_e^c$. The weight of this particular edge in $\wp$ must be geater or equal than $m_\omega(\wp)$ by definition. Since the paths in $M$ are pairwise edge-disjoint, the edges $e_\wp$ are also different and therefore $\cC(G,T,e,\omega)\geq \sum_{\wp\in M}m_\omega(\wp)$.
\end{proof}

We want to adapt the previous idea for the $L^p$-STC. Let $e = \overline{uv}$ be an edge of an edge-weighted connected graph $(G,\omega)$ and define $m_\omega(e) = m_\omega(u,v)$.

\begin{lemma}\label{l:path_inequality}
Let $(G,\omega)$ be an edge-weighted connected graph and let $T$ be any spanning tree. Let $e$ be an edge of $T$ then 
$$
m_\omega(e)\leq \cC(G,T,e, \omega)\;.
$$ 
\end{lemma}
\begin{proof}
Assume $e=\overline{uv}$, it follows that $u\in X_e$ and $v\in X_e^c$. Therefore, by the same argument given for Proposition~\ref{p:weighted_bound_infty}, we get $m_\omega(e)\leq \cC(G,T,e,\omega)$ as desired.
\end{proof}

\begin{prop}\label{p:m bound}
Let $(G,\omega)$ be an edge-weighted graph. Let $T_\ast$ be a Kruskal minimal spanning tree for the edge-weighted graph $(G, m_\omega)$ then
$$
\|(m_\omega(e))_{e\in E_{T_\ast}}\|_p\leq \cC_p(G,\omega)\;.
$$
\end{prop}
\begin{proof}
The Kruskal algorithm produces a minimal spanning tree by adding the minimal edges under the condition of not generating a cycle. Let $(e_1,e_2,\dots,e_{|V|-1})$ be an increasing ordering of the edges in $T_\ast$ respect to $m_\omega$. If $T$ is any other spanning tree, we can also order its edges in a similar way: $(e'_1,e'_2,\dots,e'_{|V|-1})$. The Kruskal algorithm guarantees that $m_\omega(e_i)\leq m_\omega(e'_i)$ for all $i$ and therefore $\|(m_\omega(e))_{e\in T_\ast}\|_p\leq \|(m_\omega(e))_{e\in T}\|_p$. But $m_\omega(e)\leq \cC(G,T,e,\omega)$ by Lemma~\ref{l:path_inequality}, this gives the inequality.
\end{proof}

If $G$ is unweighted then $m(e)$ can be computed in polynomial time by means of the Ford-Fulkerson algorithm \cite{Ford-Fulkerson}. For a weighted graph it is unclear if the computation of $m_\omega(u,v)$ can be done in polynomial time (the families of paths in $\cP(u,v)$ can be very large in general). In any case, since $m_\omega$ is a maximum it is rather easy to get reasonable lower bounds for $m_\omega(u,v)$.

For weighted graphs there is also a notion of weighted Cheeger constant.
Define the {\em weighted degree} of $v$ as $\deg_\omega(v)=\sum_{e\in I(v)} \omega(e)$ and $\delta_\omega = \min_{v\in V}\deg_\omega(v)$. For $X\subset V$, let $\vol_\omega(X)=\sum_{v\in X}\deg_\omega(v)$. The {\em weighted Cheeger constant} is defined as the maximal number $\phi_\omega(G)$ satisfiying
$$
e_\omega(X,X^c)\geq \phi_\omega(G)\cdot\min(\vol_\omega(X),\vol_\omega(X^c)) 
$$
for evey $X\subset V_G$.

Following the same argument as in \cite[Theorem 1(b)(c)]{Ostrovskii2010} we obtain 

$$
\cC_\infty(G,\omega)\geq \dfrac{\delta_\omega}{\Delta}\phi_\omega(G)\cdot\max(|V|-1,\diam(G)/2)
$$

For the $L^p$ congestion we need a local notion of Cheeger constant, namely $\phi_\omega(G,e)$ and defined as the maximal number satisfying the condition
$$
e_\omega(X,X^c)\geq \phi_\omega(G,e)\cdot\min(\vol_\omega(X),\vol_\omega(X^c)) 
$$
for every $X\subset V$ such that $X$ and $X^c$ are both adjacent to $e$. Observe that $\phi_\omega(G)=\min_{e\in E_G} \phi_\omega(G,e)$. From this localized Cheeger constant we get a lower bound for the edge congestion of an edge which is independent of any chosen minimal tree $T$ that contains that edge: 
$$\cC(G,T,e,\omega)\geq \delta_\omega\phi_\omega(G,e)\cdot\max\{(|V|-1)/\Delta,\lfloor\diam(G)/2\rfloor\}\;.$$

\begin{prop}
Let $(G,\omega)$ be an edge-weighted graph. Let $T_\ast$ be a Kruskal minimal spanning tree for the edge-weighted graph $(G, \phi_\omega(G,e))$ then
$$
\delta_\omega\|(\phi_\omega(G,e))_{e\in E_{T_\ast}}\|_p\cdot\max\left\{\dfrac{|V|-1}{\Delta},\left\lfloor\dfrac{\diam(G)}{2}\right\rfloor\right\}\leq \cC_p(G,\omega)\;.
$$
\end{prop}

\begin{proof}
It is analogous to Proposition~\ref{p:m bound}, just consider a Kruskal tree in $(G,\phi_\omega(G,\cdot))$ and the previous lower bound of the edge congestion by means of the localized weighted inequality. The term $\delta_\omega\max\{(|V|-1)/2,\diam(G)/2\}$ is just a constant term and does not affect to the minimal spanning tree computation, therefore it can be handled by the homogeneity of the norm.
\end{proof}

We include two final results that are also of independent interest.

\begin{prop}
For every edge weighted connected simple graph $(G,\omega)$ and every spanning tree $T$ we have:
$$
\sum_{e\in E_T}\omega(e) + 2\cdot\sum_{e\notin E_T}\omega(e)=2\cdot\omega(G)-\omega(T)\leq \cC_1(G,T,\omega)\;.
$$
\end{prop}
\begin{proof}
Let $e=\overline{uv}\in E_G$ arbitrary and let $T$ be any spanning tree. There exists a unique $(u,v)$-path $\wp$ in $T$. It follows that every edge in $\wp$ separates $u$ from $v$ and, hence, $\omega(e)$ is counted once for the edge congestion computation of each edge in $\wp$. Observe that $\wp$ has length $1$ if $e\in E_T$ and length at least $2$ if $e\notin E_T$ and the result follows.
\end{proof}

\begin{cor}\label{c:edge counting bound}
Let $(G,\omega)$ be an edge weighted graph $(G,\omega)$. Let $T_\ast$ be a maximal spanning tree of $(G,\omega)$, then
$$
\sum_{e\in E_{T_\ast}}\omega(e) + 2\cdot\sum_{e\notin E_{T_\ast}}\omega(e)=2\cdot\omega(G) - \omega(T_\ast)\leq \cC_1(G,\omega)\;.
$$
\end{cor}

In the case of an unweighted graph, i.e. $\omega = 1$, Corollary~\ref{c:edge counting bound} gives the bound $(|V|-1) + 2(|E|-|V|+1) = 2|E| - |V| + 1\leq \cC_1(G)$. This provides, via the H\"older inequality given in  Proposition~\ref{p:Holder}, the known lower bound given at the beginning of section~\ref{s:known results} for the STC problem.

At this point, we have to recall that the minimum $L^1$-STC problem on unweighted graphs is equivalent to minimizing the total stretch of a spanning tree (this was observed in \cite[Pag. 3]{Chandran-Cheung-Isaac2018}). Just for completeness, we include the equivalence between both problems and observe that this is no longer true for weighted graphs.

\begin{defn}[Total stretch of a spanning tree (see \cite{Elkin-Emek})]
Let $G=((V,E),\omega)$ be an edge-weighted graph. Let $T$ be a spanning tree of $G$. The stretch of an edge $e\notin E_T$ is defined as:
$$
\sigma(G,T,e,\omega)=\dfrac{\omega(\wp_e)}{\omega(e)}\,,
$$
where $\wp_e$ is the unique path in $T$ joining the adjacent vertices of $e$. The {\em (total) stretch} of $T$ in $(G,\omega)$ is defined as:
$$
\sigma(G,T,\omega) = \sum_{e\in E_G\setminus E_T} \sigma(e,T,\omega)\;;
$$
The low stretch of $G$, denoted as $\sigma(G,\omega)$ is the total stretch of minimal total stretch. Both $G$ and $\omega$ can be omitted from the notations when $G$ is clear in the context and it is unweighted.
\end{defn}

 There exists an algorithm for the LSST problem on weighted graphs, see \cite{Elkin-Emek}, that gets a spanning tree with stretch $O(|E|\log(|V|)^3)$ that runs in $O(|E|\log(|V|))$ time.

\begin{prop}\label{p:LSSTvsSTC}
Let $G$ be an unweighted graph and let $T$ be a spanning tree. Then $T$ minimizes the $L^1$-STC if and only if $T$ is a Low Stretch Spanning Tree. 
\end{prop}  
\begin{proof}
Given an edge $e=\overline{uv}\in E_G\setminus E_T$, let $\wp_e$ be the unique $(u,v)$-path in $T$. As above, observe that $e\in E(X_a)$ for some $a\in E_T$ if and only if $a\in \wp_e$. Since the $L^1$-congestion is the sum of all edge congestions in $T$, it follows that $e$ is counted $|\wp_e|$ times for the computation of $\cC_1(G,T)$ and therefore $$\cC_1(G,T) = |E_T| + \sum_{e\in E_G\setminus E_T}|\wp_e|\;.$$  Since $G$ is unweighted we identify it with a weighted graph with constants weights equal to $1$, thus $|\wp_e| = \sigma(T,e)$. Hence $\cC_1(G,T) = |V|-1 + \str(G,T)$, and the $L^1$-congestion and the total stretch of a spanning tree only differs by a constant term.
\end{proof}


In the case of edge-weighted graphs, a similar argument yields $\cC_1(G,T,\omega) = \sum_{e\in E_T}\omega(e) +\sum_{e\in E_G\setminus E_T}|\wp_e|\cdot\omega(e)$. Since $\omega$ does not need to be constant, there is no direct relation between $|\wp_e|\cdot \omega(e)$ and $\omega(\wp_e)/\omega(e)$. Thus, minimal spanning trees for $L^1$-congestion and weighted stretch can be different. For instance, let us consider the complete graph in three vertices $a,b,c$ with edge weights $\omega(\overline{ab})=1$, $\omega(\overline{bc})=1$, $\omega(\overline{ac})=2$, an easy computation yields that $\{\overline{ab},\overline{bc}\}$ has minimum LSST and $\{\overline{ab},\overline{ac}\}$ has minimum $L^1$-STC but not minimum stretch.

As a final comment in this section let us pose a question relative to the relation of congestions of graphs and subgraphs. It is known that the congestion of a subgraph can be larger than the congestion of the whole graph (see \cite[Lemma 5]{Kolman}) however this question is more interesting for spanning subgraphs, i.e., subgraphs with the same number of vertices as the total graph. This can be translated to the following question: is it possible to add edges to a graph an get a supergraph with lower STC?

The answer to this question is affirmative, but we still do not know (nontrivial) necessary conditions for this to happen. The following result is is implicit in several works in the literature, see e.g. \cite[Proposition 5.3]{Otachi-Boadlaender-Leeuwen}. 

\begin{prop}\label{p:better supergraph}
Let $G$ be an unweighted connected graph. There exists a supergraph $\tilde{G}$ with the same vertices as $G$ such that $\cC_\infty(\tilde{G})\leq \Delta + 1$.
\end{prop}
\begin{proof}
Let $v\in V_G$ be an arbitrary vertex. For every $u\in V_G$ add every edge $\overline{uv}$ that was not already in $E_G$, this supergraph will be called $\tilde{G}$. Let $\tilde{T}$ be the spanning tree formed by every edge in $\tilde{G}$ incident at $v$. Every vertex different to $v$ is terminal and hence the congestion of its adjacent edge is equal to its degree. The result follows.
\end{proof}

Thus, if $\cC_\infty(G) > \Delta + 1$, then there exists a supergraph with the same number of vertices as $G$ and lower congestion. An analogous result for weighted graphs is also possible but it depends in the weights of the new edges in the supergraph. The proof is analogous to the proof of Proposition~\ref{p:better supergraph}.

\begin{prop}Let $(G,\omega)$ be an edge-weighted connected graph. Let $(\tilde{G},\tilde{\omega})$ be a supergraph of $G$ with the same number of vertices as $G$. Suppose that there is a radial spanning tree whose center is some $v\in V_G$, then $\cC_\infty(\tilde{G},\tilde{\omega})\leq \max_{u\neq v}\{\deg_\omega(u) + \tilde{\omega}(\overline{uv})\}$.
\end{prop}
We think that a similar result as the given in Proposition~\ref{p:better supergraph} should hold for the $L^p$-STC problem. The study of the minimal number of edges needed to reduce the $L^p$-STC is left for a future work.


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{$L^p$-STC of complete (multipartite) graphs}\label{s:complete_graphs}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

In this subsection we deal with a specific family of simple unweighted graphs. These are the complete and complete bipartite graphs. We also give an upper bound for any complete multipartite graph that we conjecture to be tight.

The complete graph $K_n$ is easy to handle. If an edge $e$ of a spanning tree $T$ produces a partition of $G$ in two sets of size $m$ and $k$ (with $m+k = n$), then its congestion is easy to compute since every edge between these sets must exist in the complete graph:
$$
\cC(K_n,T,e)=|E(K_{m,n-m})|= m\cdot (n-m) = m\cdot n -m^2
$$

It is clear that $m\cdot n - m^2 \geq n-1$ for all $1\leq m\leq n-1$ (assuming $n>1$). Henceforth the edge congestion of any edge of any spanning tree is lower bounded by $(n-1)$. A radial spanning tree, i.e., a tree with a root vertex connected by an edge to any other vertex, minimizes the edge congestion of every edge and therefore is a minimal spanning tree for the $L^p$-congestion for every $p\in\N$. As a consequence we have:

$$
\cC_p(K_n)=\left( (n-1)^{p+1} \right)^{1/p}
$$

The $L^p$-STC of complete bipartite graphs $K_{m,n}$, $m\leq n$, is more difficult to obtain. In this section we compute its $L^1$-congestion, recall that this is equivalent to minimize the LSST problem.

Let $T$ be a spanning tree in $K_{m,n}$ and suppose that $e\notin E_T$ and let $\wp_e$ be the unique path in $T$ joining the adjacent vertices of $e$. It is clear that $|\wp_e|\geq 3$.

Let $T_\star$ be a spanning tree in $K_{m,n}$ such that every edge except one is terminal (only two vertices have degree $>1$). This spanning tree is unique up to isomorphism.

It is also clear that $|\wp_e| = 3$ for every $e\notin E_{T_\star}$, therefore $T_\star$ is a minimum LSST. By Proposition~\ref{p:LSSTvsSTC}, $T_\star$ is also a minimal $L^1$-STC. Thus
$$
\cC_1(K_{m,n})= 3nm - 2(n+m-1)\;.
$$

\begin{rem}
Observe that $T_\star$ minimizes the $L^1$-STC but not the classical STC problem. However, the spanning tree presented in \cite{Hruska2008} minimizes both the $L^1$ and $L^\infty$-STC's simultaneusly.
\end{rem}

For the multipartite case, let $X_1,\dots, X_k$ be the vertex partition associated to the complete multipartite graph $G=K_{n_1,\dots,n_k}$, where $|X_i|=n_i$ and $n_1\geq \dots\geq n_k$, set $N = n_1 + \dots + n_k$. 

Recall that a {\em terminal} vertex is a vertex of degree $1$ and a {\em terminal} edge is an edge adjacent to a terminal vertex.

The congestion of a terminal edge $e$ of a spanning tree whose adjacent terminal vertex belongs to $X_i$ is $N - n_i$. It is easy to see that every nonterminal edge has congestion larger than $N$, this fact does not depend on the spanning tree $T$.

For the specific case where $n_k=1$, there exists a (unique up to isomorphism) radial spanning tree such that every edge is terminal (precisely the one rooted at the unique point in $X_k$). By the previous affirmation this is a minimal $L^p$-congestion  spanning tree for every $p\in\N$.

More precisely, for $n_k=1$, we have $$\cC_p(K_{n_1,\dots,n_{k-1},1}) = \left( \sum_{i=1}^{k-1}n_i(N-n_i)^p\right)^{1/p}\;.
$$

When $n_k>1$ the situation is more complicated. In order to obtain a reasonable upper bound we consider two families of spanning trees, one of them is formed by trees similar to the one that minimizes the $L^\infty$-STC(as shown in \cite{Law-Ostrovskii}) and the other is formed by trees with just one nonterminal edge.

Let $1\leq j < i\leq k$. Define $T_M(i,j)$ as the spanning tree that connects a point of $X_i$ with every other point in $V\setminus X_i$, the remaining points of $X_i$ are connected, in one to one correspondence, with $n_i-1$ points in $X_{j}$.

Define $T_S(i,j)$ as the spanning tree that connects a point of $X_i$ with every other vertex in $V\setminus(X_i\cup X_j$) and with $n_{j}-1$ points of $X_{j}$, the remaining point on $X_{j}$ is connected to the remaining vertices in $X_i$.

Observe that each $T_S(i,j)$ has a unique nonterminal edge (with relatively large congestion) and each $T_M(i,j)$ has exactly $n_{j}-n_i +1$ nonterminal edges (with relatively small congestion). These should give good upper bounds for the $L^p$-congestion.

A direct computation yields:

$$\cC_p(G,T_S(i,j))^p = \sum_{\ell=1}^{k}n_\ell(N-n_\ell)^p - (N-n_{j})^p - (N-n_i)^p
+ (n_i(N-n_i-1) + 2 - n_{j})^p$$

and

$$\cC_p(G,T_M(i,j))^p = \sum_{\ell=1}^{k}n_\ell(N-n_\ell)^p - (n_i-1)(N-n_{j})^p - (N-n_i)^p + (n_i-1)(2N-n_i - n_{j}-2)^p\;.$$

For $p=1$ these expressions give the same value, i.e., for any choice of $(i,j)$ the $L^1$-congestions of $T_S(i,j)$ and $T_M(i,j)$ are the same. For $p>1$, this is not longer true, being $\cC_p(G,T_M(i,j))\leq \cC_p(G,T_S(i,j))$, that was expected as for $p$ big enough $T_S(i,j)$ do not give minimum STC. 

Among the $T_M(i,j)$'s, $1\leq j < i\leq k$, the minimum value of $\cC_p(G,T_M(i,j))$, for each $p\geq 1$, is achieved for $j=1$. This is clear since, for any fixed $n_i$, the expression of $\cC_p(G,T_M(i,j))$ is decreasing in $n_j$ for $n_k\leq n_j\leq n_1$. There is strong evidence (numerical and analytical) that the minimum is, in fact, obtained for $i=k$ or $i=2$ but we still do not have a complete proof for this conjecture. In any case, $T_M(2,1)$ minimizes the classical congestion and henceforth it minimizes the $L^p$-STC problem for large $p$. The number $\min\{\cC_p(G,T_M(k,1)),\cC_p(G,T(2,1))\}$ is used as a good upper bound for the $L^p$-STC problem on any complete multipartite graph. 

The $L^1$-STC of unweighted complete multipartite graphs can be computed from its equivalence with the LSST problem. We did not find an explicit reference to the computation of the low stretch of complete multipartite graphs, we present here a proof for completeness.

\begin{prop}\label{p:multipartite_avcong}
For $k\geq 3$ and $n_k>1$, we have:
\begin{align*}
\cC_1(K_{n_1,\dots,n_k})=\cC_1(K_{n_1,\dots,n_k},T_S(k,1))&=2\left(\sum_{i=1}^{k-2}\sum_{j=i+1}^{k-1} n_in_j\right) + 3(n_k-1)(N-n_k-1) + N-1\;.
\end{align*}
\end{prop}
\begin{proof} 
We shall find a minimum LSST. In the multipartite case for a given spanning tree $T$ and $e\notin E_T$ we have that $|\wp_e|\geq 2$. However, when $n_k>1$ is not possible to get a spanning tree where every edge has stretch $2$ (i.e., a radial one). Define $s_3(T)$ as the maximal number of edges with average stretch $\geq 3$. For any vertex $x$, define $\iota(x)\in\{1,\dots,k\}$ as the unique index so that $x\in X_{i(x)}$. Let $E_2(T)$ be the set of edges with stretch $2$.

We shall define, momentarily and for the sake of readability, $\sigma(e)=3$ for each edge in $E_T$. This will not affect to the computation of the LSST since every spanning tree has $N-1$ edges, this definition changes the stretch of a spanning tree by a constant term.

Suppose that $e =\overline{xy}$ is an edge whose stretch is $2$. Then, it must exist another vertex $z = z_e$, called the {\em node} of $e$, such that $\overline{zx},\overline{zy}\in E_T$. Then, for every $w\in X_{\iota(z)}$ we have one of the following possibilities:
\begin{itemize}
\item[(a)] Both edges $\overline{wx}$ and $\overline{wy}$ have stretch $\geq 3$. Observe that, if $\overline{wx}\in E_T$ and $w\neq z$ then $\overline{wy}\notin E_T$ and $\sigma(\overline{wy})=3$.

\item[(b)] If $\sigma(\overline{wx},T)=2$, then $\overline{wy}\notin E_T$ and $\sigma(\overline{wy},T)=4$ since $z$ and $w$ cannot be adjacent to the same edge. Thus the average stretch of both edges is $\geq 3$.
\end{itemize}

In the above situation, define $E^e(x)=\{\overline{xw}\mid\ w\in X_{\iota(z)}\}$ and $E^e(y)$ similarly. From (a) and (b), it follows that the edges in $E^e(x)\cup E^e(y)$ have average stretch $\geq 3$.

Let us make an important remark here, suppose that $\overline{xy}$ and $\overline{yq}$ are edges with stretch $2$, their nodes $z,z'$ belong to the same partition set and for some $w\in X_{\iota(z)}\setminus\{z,z'\}$ we have $\sigma(\overline{wx},T)=2$ (this is the extreme case (b)), then $\overline{wq}\notin E_T$ and $\sigma(\overline{wq},T)\geq 4$. This will be called the {\em Property}~$\star$. Property $\star$ has an interesting consequence:
\begin{claim}\label{cl:star property}
 let $e=\overline{xy}$ and $e'=\overline{pq}$ be different edges with strech $2$ and let $v\in X_{\iota(z_e)}, w\in X_{\iota(z_{e'})}$ be vertices so that $\overline{xv}$ and $\overline{qw}$ have stretch $2$, then $\overline{yv}$ and $\overline{pw}$ are different edges with stretch $\geq 4$.
\end{claim}
\begin{proof}[Proof of Claim~\ref{cl:star property}]
That $\sigma(\overline{yv},T)=4=\sigma(\overline{pw},T)$ is a consequence of (b). If $\overline{yv}=\overline{pw}$, then $y=p$ and $v=w$, in particular the nodes of $\overline{xy}$ and $\overline{pq}$ belong to the same partition set. But in this case we have a configuration where $\overline{xy},\overline{yq} $ have stretch $2$, their nodes belong to the same partition set and there is $w\in X_{\iota(z_e)}$ so that $\sigma(\overline{xw},T)=2 =\sigma(\overline{qw})$, this is forbidden by Property $\star$.
\end{proof}
Let us compute a lower bound for the number of edges in $s_3(T)$. Let us enumerate the vertices in $K_{n_1,\dots,n_k}$ as $x_{ij}$ where $1\leq i\leq k$ and $1\leq j\leq n_i$, we assume $x_{ij}\in X_i$.

Set $1\leq i\leq k-1$ and $1\leq j\leq n_i$ arbitrary. Suppose first that there exists an edge $e_{ij}$ with stretch $2$ adjacent to $x_{ij}$ whose node belong to $X_{i+1}\cup\cdots\cup X_k$. In this case $E^{e_{ij}}(x_{ij})$ is a set of edges with average stretch $3$ with at least $n_k$ elements, define $E(x_{ij}) = E^{e_{ij}}(x_{ij})$. If $x_{ij}$ is not adjacent to any edge with stretch $2$ and node in a partition set $X_{\ell}$ for some $\ell >i$, then every edge from $x_{ij}$ to a vertex in $X_{i+1}\cup\cdots\cup X_k$ has stretch $\geq 3$, these are $N-(n_1+\dots+n_i)\geq n_k$ edges with stretch $\geq 3$, these edges will define the set $E(x_{ij})$ in this case. In any case, for $x\neq y\in X_1\cup\dots\cup X_{k-1}$ we have $E(x)\cap E(y)=\emptyset$ by definition.

Define $$N_T=\bigcup_{i=1}^{k-1}\bigcup_{j=1}^{n_i} E(x_{ij})\;,$$
and recall that it depend in the choice of $e_{ij}$ for each $x_{ij}$.

It is clear that $|N_T| \geq (N-n_k)\cdot n_k$. It is not clear (and can be false in general) that $N_T$ has average stretch $\geq 3$ (by means of the extreme case (b)). However, the Claim~\ref{cl:star property} implies that any edge with stretch $2$ in $E^{\overline{xy}}(x)$ is univocally paired with one edge with stretch $\geq 4$ in $E^{\overline{xy}}(y)$. If our inductive construction added that edge in $E(y)$ then the average stretch of these two edges will be $3$ and there is nothing to fix, in other case we can add that edge of stretch $\geq 4$ not considered before to $N_T$. After adding these edges the average stretch of the final set will be $\geq 3$. 

Thus, by removing now the edges in $T$ that were artificially added in the previous construction, it follows that $s_3(T)\geq (N-n_k)\cdot n_k-(N-1) = (N-n_k-1)(n_k-1)$.

The spanning tree $T_S(k,1)$ satisfies that $s_3(T_S(k,1))=(N-n_k-1)(n_k-1)$ and therefore is minimal for both the LSST and $L^1$-STC problems. The proof is complete.
\end{proof}


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{First Algorithm: Congestion Descent}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

The idea of the first algorithm is to make small perturbations to an initial spanning tree in an edge-weighted connected graph $(G,\omega)$. Each perturbation is made in such a way that the $L^p$ congestion never increases. The algorithm will stop when no more congestion-reducing perturbations are possible.

Recall that every connected graph $G$ defines another graph $\cS_G$ whose vertices are the spanning trees of $G$, and two spanning trees are adjacent if and only if their edge sets are equal up to removing exactly one edge from each tree. Observe that $\cS_G$ is also connected.

The spanning tree congestion problem can be seen as an optimization of a function defined on $\cS_G$. Our algorithm is an analogue to a gradient descent algorithm adapted to our specific problem: from any spanning tree there is a path in $\cS_G$ to a minimal $L^p$-congestion spanning tree, our algorithm will find a path in $\cS_G$ to a local minimal congestion spanning tree in polynomial time. For the sake of simplicity, let $m = |E_G|$ and $n = |V_G|$.

Observe that the computation of the $L^p$-congestion, of a single spanning tree, can be done in $O(m\cdot n)$ time since any edge $\textbf{e}=\overline{uv}$, not in the tree, contributes only to the edge congestion of the edges in the unique path in $T$ joining $u$ and $v$, for each such edge $\textbf{e}$ we only need to compute that path in, at most, $O(n)$ time\footnote{For a tree $T$, finding a path between two points can be done in $O(\diam(T))$, typically $\diam(T)\ll n$.}.

Let $T$ be an arbitrary spanning tree and let $\bf{e}$ be an edge in $E_G\setminus E_{T}$. Let $\wp_{\bf{e}}=\{e_1,\dots, e_\ell\}$ be the unique path in $T$ joining the extreme points of $\bf{e}$.

\begin{prop}\label{p:equal_cong}
Let $T_{e\to\bf{e}}$ be the spanning tree obtained from $T$ by removing the edge $e\in\wp_{\bf{e}}$ and adding the edge $\bf{e}$. Then $T_{e\to\bf{e}}$ is a spanning tree and $\mathcal{C}(G,T,a)=\mathcal{C}(G,T_{e\to\bf{e}},a)$ for all $a\notin \{\bf{e}\}\cup\wp_{\bf{e}}$.
\end{prop}
\begin{proof}
Since $T$ is a spanning tree, adding the edge $\textbf{e}\notin E_T$ will produce exactly one cycle formed by $\bf{e}$ and the unique path $\wp_{\bf{e}}$ joining its extreme vertices. Removing any edge in this unique cycle will produce a subgraph without cycles and still connected, i.e., a spanning tree.

The connected components, of both $T_{e\to\bf{e}}$ and $T$, obtained by removing an edge which is not in the cycle $\{\bf{e}\}\cup\wp_{\bf{e}}$, are the same. Henceforth, the edge congestions of edges which are not in the cycle must be also the same (see Figure~\ref{f:cycle_perturbation}).

\end{proof}

\begin{figure}[h]
\centering
\includegraphics[scale=0.2]{cyclic_perturbation.png}

\caption{Example of a cycle perturbation in a spanning tree. Observe that only the edge congestion of bold edges can change.}
\label{f:cycle_perturbation}
\end{figure}

From Proposition~\ref{p:equal_cong}, it follows that we only need to compute the edge congestions of edges of $T_{e\to\bf{e}}$ that belong to $\{\textbf{e}\}\cup\wp_{\bf{e}}$ in order to compute the  $L^p$-congestion of $T_{e\to\bf{e}}$. Usually, $|\wp_{\bf{e}}|$ is much lower than the number of vertices.

If for some $\textbf{e}\in E_T$ the $L^p$-congestion of some $T_{e\to\bf{e}}$ is lower than the original one, then we choose the best perturbed spanning tree $T_{e\to\bf{e}}$ for $e\in \wp$. We repeat this procedure until no perturbed tree has lower congestion. The given tree is a local minimum in $\cS_G$ for the spanning tree congestion problem

The congestion descent algorithm has the following work-flow (see also Algorithm~\ref{alg:sCD}).
\begin{itemize}
\item[Step 1] Given $T$, compute a list $c$ formed by the edge congestions of the edges of $T$ and a list of paths $\wp_\textbf{e}$ joining the extremes of each $\textbf{e}\in E_G\setminus E_T$ (complexity at most $O(m\cdot n)$).

\item[Step 2] For each $e$ in $\wp_{\bf{e}}$, compute $\cC(G,T_{e\to\bf{e}},a)$ for $a\in \{\textbf{e}\}\cup \wp_{\textbf{e}}\setminus\{e\}$ (complexity at most $O(m n^2)$).

\item[Step 3] For each edge $e$ in $\wp$, compute $\|(\cC(G,T_{e\to\bf{e}},a))_{a\in \wp_e}\|_p$. If the minimum of these norms is lower than the former $\|(\cC(G,T,e))_{e\in \wp_{\textbf{e}}}\|_p$, then assign $T \gets T_{e\to\bf{e}}$ for the minimal congestion edge $e\in \wp_{\textbf{e}}$ and repeat the process (this is $O(p)$ from the previous step).

\item[Step 4] If no perturbation is possible for evey $\textbf{e}\notin E_{T}$, then $T$ is a local minimum for the $L^p$-STC. Otherwise change $T$ by $T_{e\to\bf{e}}$ and repeat the process.
\end{itemize}

\begin{algorithm}
\caption{$\rm{sCD}(G,T,p)$, $G$ graph, $T$ spanning tree, $p\in\N\cup\{\infty\}$}\label{alg:sCD}

$c$: array, $\rm{len}(c)= V-1$\;
\For{$e\in T$}
{
	$c[e] \gets \cC(G,T,e)$\;
}
local\_minimum $\gets$ False\;
\While{\rm{local\_minimum} $=$ \rm{False}}
{
G $\gets$ Randomized $G$\;
local\_control $\gets$ False\; 
\For{$\textbf{e}\notin T$}
{
cycle\_path = Find\_Cycle($T$, $\bf{e}$)\;
local\_congestion: array, $\rm{len}(\text{local\_congestion}) = \rm{len}(\rm{cycle\_path})$\;
\For{$e\in$ \rm{cycle\_path}}
{
local\_congestion[e] $\gets$ c[e]\;
}
current\_congestion $\gets$ local\_congestion\;
\For{$e \in$ \rm{cycle\_path}}
{
new\_T $\gets T$\;
new\_T[$e$]  $\gets \bf{e}$\;
new\_cycle\_path $\gets$ cycle\_path\;
new\_cycle\_path[$e$] $\gets \bf{e}$\;			
\For{$a\in$ \rm{new\_cycle\_path}}
{
\eIf{$a\in$ \rm{cycle\_path}}
{
current\_congestion[a] $\gets \cC(G,T_e,a)$\;
}{
current\_congestion[$e$] $\gets \cC(G,T_e,\bf{e})$\;
}

}
\If{$\|\rm{current\_congestion}\|_p < \|\rm{local\_congestion}\|_p$}
{
local\_control $\gets$ True\;
$T\gets \rm{new}\_T$\;
local\_congestion $\gets$ current\_congestion\;
\For{$a\in$ \rm{new\_cycle\_path}}
{
\eIf{$a\neq \bf{e}$}
{
$c[a] \gets$ current\_congestion[a]\;
}{
$c[e] \gets$ current\_congestion[$\bf{e}$]\;
}
}


}
}
}
\If{\rm{local\_control} = \rm{False}}
{
local\_minimum = True\;
}

}
\Return{ $\|c\|_p$, $\rm{new}\_T$}

\end{algorithm}

The complexity of a single perturbation instance is at most $O(m\cdot n^2)$. It is not difficult to bound the maximum number of instances: observe that there is a finite number of edge weights, therefore, if a perturbation is made, the difference between the $L^p$ congestions is uniformly lower bounded by a number $\varepsilon >0$. Assume that $\varepsilon > 0$ is given, it follows that at most $\mathcal{C}_p(G,T)/\varepsilon$ perturbations can be done.

Observe that a rough upper bound for every $L^p$-congestion is the number:
$$
b_{p,\omega} = M_\omega\cdot m\cdot(n-1)^{1/p}\;,
$$
where $M_\omega = \max_{e\in E_G} \omega(e)$.

In the specific case where $\omega$ is constant $1$, i.e. an unweighted graph, it follows that $b_{\infty,\omega} = m$ and $b_{1,\omega} = m\cdot(n-1)$. 

Assume first that $\omega$ takes values in $\N$, the $L^\infty$ congestion of some edge is reduced by at least $1$ when a perturbation instance succeeds and the global congestion does not increase. It follows that at most $(n-1)b_{p,\omega}$ perturbation instances can occur. The previous estimate tells us that the complexity of the congestion descent algorithm  for $p=\infty$, for integer weighted graphs, is upper bounded by $O(M_\omega m^2\cdot n^3)$. In the specific case of an unweighted graph the complexity is upper bounded by $O(m^2n^3)$.

When $\omega$ is not integer valuated, we can multiply the weight function by a sufficienlty large constant $K$ such that the difference between every different weight is more than $1$. By the same reasoning as in the  integer weighted case, the complexity of the algorithm will be polynomial for $K\cdot\omega$. Since $\cC(G,T,e,K\omega)=K\cdot \cC(G,T,e,\omega)\,,$  it follows that the algorithm executed for $K\cdot\omega$ visits exactly the same trees as the algorithm executed for $\omega$ and the polynomial complexity also follows.

The cases $1\leq p<\infty$ can be treated in a similar way. Recall that minimizing $\cC_p(G,T)$ is equivalent to minimize $\cC_p(G,T)^p$. At each descent congestion instance $\cC(G,T)^p$ must decrease by an integer number if the weights are integers (otherwise we can use a constant $K$ as before). In this case $\cC(G,T)^p\leq b_{p_\omega}^p = M_\omega^p\cdot m^p\cdot (n-1)$, thus the complexity\footnote{Our computer experiments suggest that the algorithm is, in general much faster than these estimatives in typical graphs.} of the algorithm is, at most, $O(K^pM_\omega^p m^{p+1}n^3)$.

At each descent instance of the algorithm, we shall randomize the list of edges in $G$, the purpose of this randomization is to allow the algorithm to explore different parts of the graph at each step avoiding any choice bias. The previous algorithm will be called the {\em strict congestion descent algorithm} and will be noted as ${\rm sCD}_p$. 

\begin{rem}\label{r:deep_sCD}
Observe that the ${\rm sCD}_p$ algorithm for large $p$ can be used to obtain interesting estimations of the $L^\infty$-STC by means of Proposition~\ref{p:Holder}. This approach has demonstrated to be relevant for some graphs as hypercube graphs. This version of the algorithm, i.e., to get the minimum $L^q$-congestion spanning tree among those explored by the ${\rm sCD}_p$ algorithm, will be denoted by ${\rm sCD}_{p,q}$. In this paper we only test the ${\rm sCD}_{10,\infty}$ as a proof of concept.
\end{rem}



The performance and discussion of the algorithm ${\rm sCD}_p$ in several families of graphs is given in the last section.  We also recall that we do not claim that our implementation is the best possible, significative gains in the theoretical complexity is expected in the future.

\section{Planar graphs}

\begin{defn}
A graph $G=(V,E)$ is called {\em planar} if there exists inclusions $i_V:V\to \R^2$ and $i_E:E\to C^\infty([0,1],\R^2)$ such that 
\begin{enumerate}
\item $i_E(e)(0)$ and $i_E(e)(1)$ are the images by $i_V$ of the adjacent vertices of $e$ for all $e\in E$.

\item $i_E(e)([0,1])\cap i_E(e')([0,1]) = i_V(e\cap e')$.

\item Each $i_E(e)$ is an embedding for all $e\in E$.
\end{enumerate}
Given a planar graph, we will always assume that the emebedding is implicit (i.e. both $i_V$ and $i_E$ were already defined). In this context, we will assume that $V\subset \R^2$ and each $e\in E$ is a smooth path which connects its adjacent vertices.

The trace of a path $e\in E$ will be denoted by $\bm{e}$ (in bold letter). Let $G=(V;E)$ be a planar graph, the subset of $\R^2$ consisting of the vertices and the traces of the edges will be denoted by ${\bm G}$ .
\end{defn}

\begin{defn}
A {\em cell} of a planar graph $G$ is the closure of a  connected component of $\R^2\setminus {\bf G}$.

\end{defn}

\begin{defn}[Dual Graph]
Let $G=(V,E)$ be a connected planar graph and let $V^\ast$ be the set of cells of $G$. The {\em dual graph} of $G$, denoted by $G^\ast$, is the multigraph $(V^\ast,E^\ast)$ such that $\overline{PQ}\in E^\ast$ if and only if there exists an edge in $E_G$ which is adjacent to the cell $P$ on one of its sides and to the cell $Q$ in its other side.

If $(G,\omega)$ is a weighted graph, then we can define a {\em dual weight} $\omega^\ast$ on $G^\ast$:  observe that every edge $e\in E_G$ defines a unique edge $e^\ast$ in $E^\ast$, define $\omega^\ast(e^\ast)=\omega(e)$. The edge $e^\ast$ will be called the {\em dual edge} of $e$.
\end{defn}

\begin{rem}\label{r:planar dual}
The dual graph is also a planar (multi)graph. Just place a vertex in the interior of each cell (called {\em centroids}) and each edge $e^\ast$ of the dual graph is represented as a smooth path joinig the respective centroids and meeting transversely a unique edge $e$ in $G$, exactly the one with same weight as the dual weight of $e^\ast$. This also  allows to define the dual edge $e^\ast\in E^\ast$ for each edge $e\in E$, in particular both graphs have the same number of edges.

Remark also, that the dual graph of a planar graph is always connected since every cell is connected with the unbounded cell by a path formed by finitely many dual edges.
\end{rem}

\begin{prop}[Folklore]
Let $G$ be a, possibly edge-weighted, planar graph. Let us consider the representation of $G^\ast$ in $\R^2$ given in Remark~\ref{r:planar dual}, then $(G^\ast)^\ast$ is isomorphic to $G$ and $(\omega^\ast)^\ast = \omega$.
\end{prop}

\begin{defn}[Dual Tree]
Let $G$ be a connected planar graph. Let $T$ be a spanning tree. Define the {\em dual tree} of $T$, denoted by $\widetilde{T}$, as the subgraph of $G^\ast$ generated by the edges of $G^\ast$ which are {\bf not} dual to edges of $T$.
\end{defn}

\begin{prop}
Let $G=(V,E)$ be a connected planar graph. Let $T$ be a spanning tree of $G^\ast$. Then $\widetilde{T}$ is also a spanning tree of $G$.
\end{prop}

\begin{proof}
On the one hand $\widetilde{T}$ cannot have a cycle, otherwise that cycle will disconnect $\R^2$ in several connected components. At least one cell will intersect one bounded connected component and at least one cell will intersect the unbounded one, since $T$ is spanning and connected it follows that there exists a path in $T$ connecting those cells. This path must meet transversely the cycle at some of its edges and that edge is dual to some edge in $T$. This is in contradiction with the definition of dual tree.

On the other hand, $\widetilde{T}$ must be spanning. If this were not the case, then $T$ must have at least one cycle enclosing a vertex in $V_G$ but this is impossible since $T$ is a tree. By a similar reason $\widetilde{T}$ must be connected, otherwise a cycle in $T$ would disconnect  $\widetilde{T}$ in (at least) two components.
\end{proof}

\begin{cor}
Let $G$ be a connected planar graph. Then $T$ is a spanning tree of $G$ if and only if $\widetilde{T}$ is a spanning tree of $G^\ast$. 
\end{cor}

The edge congestion of a spanning tree of a reduced planar graph is easy to compute from its dual tree. The next Proposition is a generalization of \cite[Pag. 6 (Key Observation)]{Law-Ostrovskii}.

\begin{prop}[Edge Congestion in a planar graph]\label{p:edge planar congestion}
Let $(G,\omega)$ be an edge-weighted connected planar graph and let $T$ be a spanning tree. Let $\widetilde{T}$ be its dual tree in $(G^\ast,\omega^\ast)$. Let $e\in E_T$ and let $e^\ast =\overline{PQ}$ be its dual edge. Let $\wp_{e^\ast}$ be the shortest $(P,Q)$-path in $\widetilde{T}$. It follows that $\mathcal{C}(G,T,e)=w(e) + w^\ast(\wp_{e^\ast})$, where $\omega^\ast(\wp_{e^\ast})$ denotes the sum of the dual weights of the (dual) edges in $\wp_{e\ast}$.
\end{prop}

\begin{proof}
Let $e\in E_T$ and let ${\wp_{e^\ast}}$ be the shortest path in $\widetilde{T}$ joining the cells in $e^\ast$. Since $G^\ast$ is also planar, it follows that $\wp_{e^\ast}$ can be embedded in $\R^2$ and also $e^\ast$ can be represented in $\R^2$ by the planar embedding depicted in Remark~\ref{r:planar dual}. Let $T_e$ denote the graph obtained from $T$ by removing the edge $e$. It is clear that ${\bm\wp}_{e^\ast}\cup {\bf e^\ast}$ is the trace of a simple loop in $\R^2$ that separates both connected components of $T_e$. The dual weights of the edges of this cycle are, by definition, the corresponding weights of the edges in $G$ that connect both components (recall that each edge meets transversely just one dual edge) and therefore the sum of these weights are precisely the edge congestion of $e$.

In the case where $P=Q$ (for instance when $e$ is adjacent to a degree $1$ vertex of $G$), $\wp_{e^\ast}$ is defined as an empty path (with length $0$).
\end{proof}

From the previous Proposition we obtain an easy lower bound for the edge congestion in edge-weighted planar graphs. The next is a generalization of the cycle rank of a graph as defined in \cite[Pag. 8]{Law-Ostrovskii}

\begin{defn}
Let $G$ be a connected planar graph and let $G^\ast$ be its dual graph. Let $e^\ast$ and edge of $G^\ast$ which is dual to an edge $e\in E_G$. Let $c_e^\ast$ denote a cycle in $G^\ast$ such that it contains $e^\ast$ and its dual weight is minimal.

The number $w^\ast(c_e^\ast)$ is called the {\em weighted cycle rank} of $e$ and it will be denoted by $\rm{r}_\omega(e)$.
\end{defn}

\begin{cor}
Let $(G,\omega)$ be an edge-weighted connected planar graph. Then $\rm{r}_\omega(e)\leq\mathcal{C}(G,T,e)$. In particular, $\max_{e\in E_G}\{\rm{r}_\omega(e)\}\leq  \mathcal{C}_\infty(G,\omega)$.
\end{cor}

\begin{cor}
Let $T_{\rm{R}}$ be a minimal spanning tree of the edge-weighted graph $(G,\rm{r}_\omega)$. Then

$$\left(\sum_{e\in E_{T_{\rm{R}}}}(\textrm{r}_\omega(e))^p\right)^{1/p}\leq  \mathcal{C}_p(G,\omega)\;.$$
\end{cor}
\begin{proof}
Let $T$ be a spanning tree of $G$. Let $(e_i)_{i=1}^k$ be an ordering of elements in $T$ by weighted-rank in increasing order and let $(e'_i)_{i=1}^k$ be a similar ordering for the edges in $T_{\rm{R}}$. By the Kruskal algorithm (see the proof of Proposition~\ref{p:m bound}), it follows that $\textrm{r}_\omega(e'_i) \leq \textrm{r}_\omega(e_i)$ for all $1\leq i\leq k$ and therefore 

\begin{align*}
\left(\sum_{e\in E_{T_{\rm{R}}}}(\textrm{r}_\omega(e))^p\right)^{1/p} &=\|(\textrm{r}_\omega(e'_i))_{i=1}^k\|_p\\ &\leq \|(\textrm{r}_\omega(e_i))_{i=1}^k\|_p \leq  \|(\mathcal{C}(G,T,e_i))_{i=1}^k\|_p = \mathcal{C}_p(G,T,\omega)
\end{align*}
\end{proof}

From the Proposition~\ref{p:edge planar congestion}, a good candidate for a minimal $L^p$-congestion spanning tree in an (unweighted) planar graph is a tree whose dual tree minimizes the stretch in the dual graph; this was already observed for the classical congestion in \cite{Law-Leung_Ostrovskii2014}. In the case of weighted graphs, we have to minimize the weights of paths but the idea remains the same.

\begin{rem}\label{r:radial_dual}
If $G^\ast$ admits a radial spanning tree $T$, i.e. a tree where a root vertex is connected with everything, then it is clear that $T$ minimizes the lengths of paths for every possible pair of cells in the dual graph. In this specific case $\widetilde{T}$ has minimal $L^p$-congestion for every $1\leq p\leq \infty$ whenever $G$ is unweighted, the edge congestion of every edge varies between $1$ and $3$.
\end{rem}

Weighted planar graphs whose dual graphs admit a radial spanning tree are the simplest ones for the study of the spanning tree congestion problem. However, even in this case, it is not true in general that the dual tree of a minimum $L^p$-congestion spanning tree is a radial spanning tree as it can be seen in the following example.

\begin{exmp}\label{ex:nonradial}
Let $G$ be the weighted\footnote{Observe that these weights satisfy the triangle inequality.} graph presented in Figure~\ref{f:nonradial}. Its dual graph $G^\ast$ admits a unique radial spanning tree. That one is dual of another spanning tree of $G$ whose $L^1$-congestion is $50$ (left). The spanning tree depicted in the right has $L^1$-congestion $42$, observe that its dual tree is linear (far from radial).
\begin{figure}[h]
\centering
\includegraphics[scale = 0.22]{nonradial2.png}
\caption{Radial dual trees do not need to be optimal for weighted planar graphs.}
\label{f:nonradial}
\end{figure}
\end{exmp}

However, there is a family of planar weighted graphs that always admit a radial minimal $L^p$-congestion spanning tree.

\begin{defn}
A connected graph $G$ is called  {\em cactus graph} if and only every edge belongs to at most one cycle.
\end{defn}

It is easy to show that every cactus graph is planar. Moreover, a planar graph is a cactus graph if and only if the maximal simple subgraph of the dual graph is a radial spanning tree.

\begin{prop}\label{p:minimal-cactus}
Let $(G,\omega)$ be a weighted cactus graph embedded in $\R^2$. Let $T$ be a minimal weight spanning tree in $(G^\ast,\omega^\ast)$. Then $\widetilde{T}$ is a minimal $L^p$-congestion spanning tree for every $p\in\N\cup\{\infty\}$.
\end{prop}
\begin{proof}
Every spanning tree of the dual graph of a cactus graph has the same root cell, namely $P$ and must be radial. Every cycle in the dual graph of a cactus graph has length $2$ (or $1$ if $G$ has a loop). By means of Proposition~\ref{p:edge planar congestion}, it follows that, for every spanning tree $\widetilde{T}$ of $G$, we get $\mathcal{C}(G,\widetilde{T},e)=w(e) + w^\ast(\overline{e^\ast})$ where $\overline{e^\ast}$ is the dual edge in the dual tree with the same adjacent vertices as $e^\ast$. Thus, the minimal weight spanning tree in the dual graph (with dual weights) minimizes each coordinate in the vector of edge-congestions and henceforth its dual minimizes the spanning tree $L^p$-congestion.
\end{proof}


Remark~\ref{r:radial_dual} and Propositions~\ref{p:edge planar congestion} and \ref{p:minimal-cactus} suggest that good candidates to minimal congestion spanning trees in planar graphs are those whose dual trees minimizes their weights and maximizes the degree at the minimum number of vertices (trying to be as radial as possible).

In the absence of weights, a first approach to this question are breadth first search trees or BFS-trees.

\begin{defn}[BFS Tree]
A spanning tree of a connected edge-weighted graph is called of {\em breadth first search} tree if and only if there exists a vertex $v$ such that the distance of any vertex to $v$ in the tree is the same as the distance in the graph. The vertex $v$ will be called the {\em root} of the BFS tree.
\end{defn}

In \cite[Proposition~1]{Ostrovskii2010}, BFS trees rooted at the unbounded cell are used to give an upper estimate to the $L^\infty$-congestion of connected planar graphs. However, we can consider arbitrary BFS trees in order to enhance that upper bound. Moreover, the example given in \cite[Figure~2]{Ostrovskii2010} is, in fact, the dual of a BFS tree rooted at one of the bounded cells. This is equivalent to change the planar embedding of the graph.

Usually, the STC on planar unweighted graphs is attained by a spanning tree whose dual is a BFS tree (this happens in lots of the examples studied in this work). We do not think that this is the general picture, but we still have no counterexample to this conjecture.

Thus, for unweighted graphs, a reasonably good upper bound for the $L^p$ congestion is given by the minimal $L^p$-congestion among the family of spanning trees which are dual to BFS trees in $G^\ast$. However, the set of BFS trees in the dual graph is, in general, very high to be computationally resolved.


\subsection{Second Algorithm: Branch optimization in BFS trees}

\begin{defn}
Let $T$ be a tree and $v\in V_T$ a distinguished vertex (called {\em root}). The {\em level} of a vertex $w\in V_T$ is its distance to the root. The $k$-level of $T$ is the set of vertices whose level is $k$, denote this set by $\Lvl_k(T,v)$.
\end{defn}

\begin{defn}[Relative $L^p$ congestion]
Let $G$ be a simple planar graph, let $T$ be a tree of the dual graph $G^\ast$ ($T$ does not need to be spanning).
Let $E^T\subset E_G$ be the set of edges $e$ such that $e^\ast$ is not an edge in $T$ and $e^\ast$ is adjacent to vertices of $T$. Let $\widehat{T}$ be any spanning tree in $G$ whose edge set includes $E^T$. Observe that the $L^p$-congestion $\mathcal{C}(G,\widehat{T},e)$ of every $e\in E^T$ can be computed by the formula given in Proposition~\ref{p:edge planar congestion} and does not depend on the choice of $\widehat{T}$.

The Relative $L^p$ congestion of $T$, denoted by  $\mathcal{RC}_p(G,T)$ is defined as 
$$
\max_{e\in E^T}(\mathcal{C}(G,\widehat{T},e))\,,\ \text{if}\ p=\infty
$$

$$
\dfrac{\sum_{e\in E^T}\mathcal{C}(G,\widehat{T},e)^p}{| E^T|}\,,\ \text{if}\ 1\leq p<\infty
$$

\end{defn}



Of course, when $T$ is a spanning tree and $1\leq p <\infty$, we get $\widehat{T}=\widetilde{T}$ and $$\left((|V_G| -1)\cdot\mathcal{RC}_p(G,T)\right)^{1/p} = \mathcal{C}_p(G,\widetilde{T})\;.$$

\begin{rem}\label{r:fast-planar-congestion}
The edge-congestions of edges in $E^T$ for a tree in $G^\ast$ can be computed very fast. By means of Proposition~\ref{p:edge planar congestion}, each edge congestion depends on the computation of a path in the tree $T$, this can be done in at most $O(|V_T|)$. Therefore, the computation of the relative congestion of $T$ can be done in, at most, $O(|E^T|\cdot|V_T|)$ time.
\end{rem}

\begin{defn}
Let $T$ be a rooted spanning tree of a graph. Let $T_k$ be the subtree of $T$ generated by the edges that join vertices in levels $\leq k$.

Let $T$ and $T'$ be BFS spanning trees with the same root. It is said that $T'$ is a {\em switch} at level $k$ from $T$ if $T'_k$ and $T_k$ are the same up to remove just one edge (see Figure~\ref{f:switch}).
\end{defn}

\begin{figure}[h]
\centering
\includegraphics[scale=0.2]{switch_tree.png}
\caption{Example of a switch at level $2$ in a BFS tree. Bold lines represent the tree at level $2$, dotted and dashed edges are those in $E^{T_2}$, and $T_e$ is obtained by switching the unique edge of $T_2$ adjacent to $u$ with $e$. If the tree lies in the dual graph, then dotted and dashed edges are dual to edges where the congestion can be computed. From $T_2$ to $T_e$ only the edge-congestion of the (duals of) dashed segments, which are those incident in $u$, may change.}
\label{f:switch}
\end{figure}

\begin{defn}[Locally Optimal Congestion BFS tree]
Let $G$ be a simple planar graph, let $T$ be a BFS spanning tree of the dual graph $G^\ast$ and let $v\in V^\ast$ be the root cell. It is said that $T$ has {\em Locally Optimal $L^p$-Congestion} ($p$-LOC tree) if and only if, for every $k\geq 0$, 
$$\mathcal{RC}_p(G,T_{k})\leq \mathcal{RC}_p(G,T'_{k}) $$ for every tree $T'$ which is a switch at level $k$ from $T$.
\end{defn}

Our second algorithm produces $p$-LOC-BFS spanning trees for each possible root cell in the dual graph in polynomial time. The upper bound in the $L^p$ congestion is chosen among the minimal $L^p$-congestions of the respective dual trees. For the implementation of this algorithm it is assumed that edges are represented as line segments in $\R^2$. Observe also that here $n = |V_{G^\ast}|$, $m=|E_{G^\ast}| = |E_{G}|$ and $\Delta$ is the maximum degree of $G^\ast$.

The algorithm follows the next workflow (see Algorithm~\ref{alg:LOC-BFS}):

\begin{itemize}
\item[Step $1$:] Choose $v$ as the root cell, define $T_1$ as the family of dual edges incident to the chosen root. Let $S_1$ be the vertices in $T_1$. Let $E_1$ be the edges in $E_{G^\ast}\setminus E_{T_1}$ adjacent to vertices in $S_1$. Compute the relative congestion at level $1$: $\mathcal{RC}_p(G,\tilde{T}_1,1)$. 

\item[Step $2$:] Inductively, assume $T_k$, $S_k$ and $E_k$ were already defined and the relative congestions were computed up to level $k$. Define $B_{k+1}$ as those cells in $V_{G^\ast}\setminus S_k$ that can be joined with $S_k$ by an edge, set $S_{k+1}=S_k\cup B_{k+1}$. Let $OE_{k+1}$ be the set of edges adjacent to vertices in $S_{k+1}$.

\item[Step $3$:] Let $T_{k+1}$ be an arbitrary BFS extension of $T_k$ to the vertex set $S_{k+1}$ and compute its relative $L^p$-congestion.

\item[Step $4$:] For each $u\in B_{k+1}$,  let $BE^u_k$ be the set of edges in $E_k$ adjacent to $u$. If $|BE^u_k|>1$ for some $u\in B_{k+1}$, then for each $e\in BE^u_k$ compute the relative congestion of the tree $T_e$ obtained by switching the edge $e$ with the edge in $T_{k+1}$ adjacent to $u$. Observe that the unique dual edges where the congestion can vary are those in $BE^u_k\setminus\{e\}$ and those in $OE_{k+1}$ incident in $u$. If $ \mathcal{RC}_p(G,\tilde{T}_{e},k+1)<\mathcal{RC}_p(G,\tilde{T}_{k+1},k+1)$, then replace $T_{k+1}$ with $T_e$, and repeat the process until $T_{k+1}$ is a locally optimal tree for switches at any level $j\leq k+1$.

\item[Step $5$:] Repeat the Step $4$ until $T_{k+1}$ is a spanning tree.

\end{itemize}

\begin{algorithm}

\caption{$\rm{LOC\_BFS}(G,V,p)$, $G$ planar graph, $V\subset\R^2$ vertex list, $p\in\N\cup\{\infty\}$}\label{alg:LOC-BFS}
\algsetup{linenosize=\small}
  \scriptsize
$T$: array, $\rm{len}(T)= 0$\;
$c$: array, $\rm{len}(c)= 0$\Comment*[r]{array of edge congestions}
%Dual\_Edges: array, $\rm{len}(\rm{Dual\_Edges})= 0$\;
$\tilde{G}$, $\tilde{V} \gets$ Dual\_Graph($G$,$V$) \Comment*[r]{$ \tilde{V}$: array, vertices(cells) of $\tilde{G}$}
\For{$v\in \tilde{V}$}
{
	$S\gets [v]$ \;
	$B\gets [v]$\;
	\While{$\rm{len}(T) < \rm{len}(V) -1$}
	{		
		P $\gets$ Edges($\tilde{G}$,$S$, $V\setminus S$)\;
		New\_$S \gets$ $S\cup\rm{Vertices}(P)$\;
		New\_$B \gets \text{New}\_S \setminus S$\;
		External\_Dual = Edges($\rm{New\_}B$,$\rm{New\_}B$)\;
		Edges : double array, \rm{len}(Switch\_Edges) = 	\rm{len}(New\_$B$)\;	
		\For{$p\in \rm{New\_}B$}
		{
		Edges[$p$] $\gets$ Edges(p,B)\;
		$T$\text{.append}(Edges[$p$][$0$])
		}
		$B \gets \rm{New\_B}$\;
		\For{$e\in$ \rm{External\_Dual}}
		{
		$\rm{c.append}(\cC(G,\rm{Dual}(T),\tilde{e})) $
		}
		\For{$p\in \rm{New\_}B$}
		{
		\If{$\rm{len}(Edges[p])>1$} 
			{	

			\For{$i\in \{1,\dots,\rm{len}(Edges[p])-1\}$}
				{
					$c\rm{.append}(\cC(G,\rm{Dual}(T),\widetilde{\text{Edges}[p][i]}))$ \Comment*[r]{$p$ is a switching point}
				}
			}
		}
		local\_minimum $\gets$ False\;
		\While{\rm{local\_minimum} $=$ \rm{False}}
		{
		Aux\_$T \gets T$\;
		Aux\_$c \gets c$\;
		local\_control = False\;
		\For{$p\in\rm{New\_}B$}
		{
			edge $= T	\cap \rm{Edges}[p]$	\;
			\If{$\rm{len}(\rm{Edges}[p]) >1$}
			{
			\For{$e\in \rm{Edges}[p]$, $e\neq\rm{edge}$}
			{
			$\rm{Aux\_}T[\rm{edge}] \gets e$\;
			$\rm{Aux\_}c[e] \gets \cC(G,\rm{Dual}(\rm{Aux\_}T),\widetilde{\rm{edge}})$\;
			\For{$a\in \rm{Edges}[p]$}
			{
				\If{$a\neq e$}
				{
				$\rm{Aux_c}[a]\gets \cC(G,\rm{Dual}(T),\widetilde{a})$\; 
				} 
			}
			\For{$a\in \rm{External\_Edges}$}
			{
				\If{$p\in a$}
				{
				$\rm{Aux\_}c[a] \gets \cC(G,\rm{Dual}(\rm{Aux\_}T),\widetilde{a})$ 
				}
			}
			\If{$\|\rm{Aux\_}c\|_p <\|c\|_p$}
			{
			local\_control = True\;
			$T \gets \rm{Aux\_}T$\;
			$c \gets \rm{Aux\_}c$\;
			\rm{\textbf{break for: line 35}}\;
			\rm{\textbf{break for: line 32}}\; 
			}
			}

			}		
		}
		\If{$\rm{local\_control} = \rm{False}$}
		{
		local\_minimum = True\;
		}
		}


	}
}

\Return{ $\|c\|_p$, $\rm{Dual}(T)$}
%\end{algorithmic}
\end{algorithm}

This algorithm will be denoted by ${\rm LOC\textendash BFS}_p$ and
it is clear that it runs in polynomial time. The computation of the $S_k$'s, $B_k$'s, $BE^u_{k}$'s and $OE_k$'s run also in linear time with the number of edges and can be done at the very beginning of the algorithm. Since this data is previously known, the vector of edge congestions of a tree $T_k$ can be obtained in $O(\Delta|B_k|)$ time since, at each step, the paths computed for $T_{k-1}$ can be used again to make a faster computation of the paths in $T_k$ and there are at most $\Delta\cdot |B_{k}|$ edges where the congestion must be computed. Observe that we  know, a priori, the extreme points of relevant paths to be considered for edge-congestion computation. 

The fifth step also runs in polynomial time for any initial random extension $T_{k+1}$ (and assuming the weight function is fixed). A switch operation can be performed in $O(\Delta)$ time. The reason for this is the fact that we need to compute a fairly small number of edge congestions at each switch operation: only congestions of edges which are dual to edges in $(BE^u_k\setminus\{e\})\cap E^{T_e}$ and edges adjacent to $u$ in $OE_{k+1}$ can change in a switch operation, the number of such edges is clearly bounded by the maximum vertex degree $\Delta$.


In the case $p=\infty$, the relative congestion of $T_{k}$ is, by construction, clearly bounded by $(2k+1)M_\omega$ where $M_\omega = \max_e\{\omega(e)\}$ since $2k$ is the diameter of $T_k$. If $\omega$ is integer valuated, at each succeeded switch operation, the relative congestion must descend by at least $1$. Therefore, a locally optimal tree (up to level $k$) is reached in, at most, $O(\Delta^2 \cdot |B_k|\cdot k\cdot M_\omega)$ operations. Since the sets $B_{k}$'s form a partition of $|V|$ and $k$ cannot be larger than twice the diameter of $G^\ast$. It follows that the global complexity for finding the final $\infty$-LOC-BFS tree is, therefore, at most $O(\Delta^2\cdot n\cdot d\cdot M_\omega)$, where $d$ is the diameter of $G^\ast$. The global complexity of the algorithm (running at every possible rooted vertex) is, at most, $O(M_\omega\Delta^2\cdot n^2d)$. The real valuated weight case and $p\in\N$ can be handled in a similar way as it was done in the first sCD algorithm. The complexity can, in general, increase depending in the weight function and the value of $p$.


\subsection{Third Algorithm: Recursive Optimal Congestion  in the dual graph }

For weighted spanning trees, BFS trees are not longer good options. The dual tree of a minimal $L^p$-congestion spanning tree of $G$ tends to avoid dual edges with large weight; otherwise, this large weight will compute at least twice for edge congestion computations (this is of great relevance when $p<\infty$). Therefore minimal $L^p$-congestion spanning trees on weighted graphs have a preference to include the heaviest edges.

For this third algorithm, we adapt some of the strategies given in the ${\rm LOC\textendash BFS}_p$ algorithm without using BFS trees. We shall compare the performance of both algorithms in the last section. As before $n = |V_{G^\ast}|$ and $m=|E_{G^\ast}| = |E_{G}|$.

The algorithm, denoted by ${\rm ROC}_p$, is described by the following recursive process (see also Algorithm~\ref{alg:ROC}):

\begin{itemize}
\item[Step $1$:] Choose a root cell $v_0\in V_{G^\ast}$. Set $S_0=\{v_0\}$ and let $T_0$ be the subgraph consisting of a single vertex $v_0$.

\item[Step $2$:] Suppose that $S_k$ and $T_k$ were defined. Define $B_{k+1}$ as those vertices in $V\setminus S_k$ adjacent to some vertex in $S_k$. For each $u\in B_{k+1}$, let $SE_u$ be the set   of edges of $G^\ast$ from $u$ to $S_k$.

\item[Step $3$:] If $|SE_u|\leq 1$ for all $u\in B_{k+1}$, then choose an edge $e$ from $S_k$ to $B_{k+1}$ such that $\omega(e)$ is minimum. If there are several such minimal edges, then choose the one that is incident with the vertex $w$ in $S_k$ where $\deg(w,\omega)/\deg(w)$ is minimum. If there are still more than one vertex to choose then, choose the vertex with higher degree among them. If there are still more than one choice, then take the vertex in $S_k$ with lowest index. This criterion for choosing the minimal edge is encoded in the subprogram Minimal\_Edge. Define $S_{k+1}$ as the union of $S_k$ with the vertex in $B_{k+1}$ adjacent to $e$.

\item [Step $4$:] If $|SE_u|> 1$ for some $u\in S_{k+1}$, then for each such $u$ and for each $e\in SE_u$, let us consider the trees $T_e = T_k + e$. Set $T_{k+1}$ as the tree $T_e$ with minimum relative $L^p$-congestion. If there are several choices with the same relative congestion, then follow the same criterion as in the previous step in order to choose $e$ univocally. Set $S_{k+1}$ as the vertex set of $T_{k+1}$.

\item[Step $5$] Repeat the previous process until a spanning tree is produced.
\end{itemize}

\begin{algorithm}
\caption{$\rm{ROC}(G,V,p)$, $G$ planar graph, $V\subset\R^2$ vertex list, $p\in\N\cup\{\infty\}$}\label{alg:ROC}
\algsetup{linenosize=\small}
  \scriptsize
$T$: array, $\rm{len}(T)= 0$\;
$c$: array, $\rm{len}(c)= 0$\Comment*[r]{array of edge congestions}
$\tilde{G}$, $\tilde{V} \gets$ Dual\_Graph($G$,$V$) \Comment*[r]{$ \tilde{V}$: array, vertices(cells) of $\tilde{G}$}
\For{$q\in \tilde{G}$}
{
$S$.append($q$)\;
\While{$\rm{len}(T) <\rm{len}(\tilde{V}) -1$}
{
Boundary\_Edges = Edges($S$,$V\setminus S$)\;
$B$ = Vertices(Boundary\_Edges)$\setminus S$\;
$W$: double array, \rm{len}(W)= \rm{len(B)}\;
\For{$v\in B$}
{
$W[v] \gets$ Edges($\tilde{G}$, $S$, $v$)\;
}
Rel\_Congestion = $\infty$\;
Rel\_$c \gets c$\;
Rel\_$T \gets T$\; 
	\eIf{$\rm{len}(W[v]) = 1\,,\ \forall v\in B$}
  	{
  	edge $\gets$ Minimal\_Edge($\tilde{G}$,Boundary\_Edges, $S$)\; 	
  	$T$.append(edge)\;
  	$S$.append(Target(edge))\;
  	}
  	{
  	Edges $\gets \emptyset$\;
  	Rel\_List $\gets \emptyset$\;
  	\For{$v\in B$}
  		{	
  		\For{$e\in W[v]$}
  		{
  		\rm{Aux\_}$T \gets T\cup\{e\}$)\;
   		\rm{Auc\_}$c \gets c$\;
		\For{$a\in W[v]\,,\ a\neq e$}
			{
			\rm{Aux\_}$c$\rm{.append}($\cC(G,\rm{Dual}(\rm{Aux\_}T),a)$)
			}
		}
		\eIf{$p<\infty$}
		{
		\rm{Aux\_Rel\_Congestion} = $\dfrac{\|\rm{Aux\_}c\|_p^p}{\rm{len}(c)+\rm{len}(W[v])-1}$\;
		}
		{
		\rm{Aux\_Rel\_Congestion} = $\|\rm{Aux\_}c\|_\infty$
		}
		\If{$\rm{Aux\_Rel\_Congestion} < Rel\_Congestion$}
		{
		Edges $\gets \{e\}$\;
		Rel\_List $\gets \{\rm{Auc\_}c\}$\;
		\rm{Rel\_Congestion} $\gets$ \rm{Aux\_Rel\_Congestion}\;
		Rel\_$c \gets \rm{Aux\_}c$\;
		Rel\_$T \gets \rm{Aux\_}T$\;  		
		}
		\ElseIf{$\rm{Aux\_Rel\_Congestion} = Rel\_Congestion$}
		{
		Edges.append(e)\;
		Rel\_List.append(\rm{Auc\_}c)\;
		}
 		}
 	edge = Minimal\_Edge($\tilde{G}$,Edges,$S$)\;
  	$T \gets T\cup\{\rm{edge}\}$\;
  	$c$ = Rel\_List[edge]\;
  		}
  	}
}
\Return $\|c\|_p$, $\rm{Dual}(T)$
\end{algorithm}

The ${\rm ROC}_p$ algorithm also runs in polynomial time. Computing $S_k$ and the sets $SE_u$ for each $u\in B_{k+1}$  is done, inductively, in the second step in, at most, $O(\Delta)$ time (we only add a single vertex to the tree at each step). Step $3$ is for free as can be made as a side computation in the fourth step. Step $4$ depends on the computation of at most $\Delta\cdot |B_{k+1}|$ relative $L^p$-congestions of trees with exactly $k+1$ vertices. For each one of these trees we only need to compute $|BE_u|\leq\Delta$ edge congestions for some $u\in|B_{k+1}|$, in order to obtain the corresponding relative congestions. All these edge congestions can be computed with complexity $O(\Delta)$ since we can reuse the paths already obtained for the computation of the tree $T_{k}$. Hence, since $|B_{k+1}|\leq k\Delta$, the complexity of this step is, at most, $O( \Delta^2\cdot k)$.

Since at each application of steps $2$, $3$ and $4$, the tree adds a vertex, the number of instances of the algorithm is $n-1$. Observe that the Minimal\_Edge choice does not add complexity since we only need to get information of the degree, weighted degree and index of an already known list of vertices. Thus, the complexity of the algorithm at a chosen root vertex is at most $O(\Delta^2\cdot n^2)$ and the total complexity for applying the full workflow to every possible rooted vertex is at most $O(\Delta^2\cdot n^3)$.

\begin{rem}
Observe that the execution time of ${\rm ROC}_p$ is polynomial for every weight function and its complexity does not depend on $\omega$ or $p\in\N\cup\infty$. This is an important advantage respect to the ${\rm sCD}_p$ and ${\rm LOC\textendash BFS}_p$ algorithms.
\end{rem}


