    \includegraphics[width=.7\linewidth,trim={35 20 25 15},clip]{fig/comm_graph2.eps}
    \caption{Communication graph.}
    \label{fig:comm_graph}
\end{figure}
\subsection{Distributed Control Formulation}
After the system is partitioned, the local, discrete-time optimization problem to be solved by each subnetwork is given by
\begin{subequations}
    \begin{multline}\label{eq:i_cost} 
       c\elb{i} = \min_{\mathclap{\widetilde{\dot{m}}_0,\theta\elb{U\elb{i}}}}\quad    \sum_{t_0}^{t_0+\Delta t} f \left( \dot{m}_{P}\elb{\mathcal{V}\elb{i}}, T_P\elb{N\elb{i}}, SOE\elb{U\elb{i}} \right)\\
    \text{subject to:}
    \end{multline}
    \begin{equation}\label{eq:i_temp}
           T_P\elb{N\elb{i}}(k+1)  = A\elb{i}T_P\elb{N\elb{i}} +E\elb{i} \begin{bmatrix}\widetilde{T}_{0}\\T_{setR}\\T_{amb}\end{bmatrix}
    \end{equation}
    \begin{equation}\label{eq:i_soe}
        SOE\elb{U\elb{i}}(k+1) = \dot{Q}_p\elb{U\elb{i}}-\dot{Q}_{out}\elb{U\elb{i}}
    \end{equation}
    \begin{equation}\label{eq:i_qp}
    \dot{Q}_p\elb{U\elb{i}} = \dot{m}_P\elb{U\elb{i}}c_p\left(T_P\elb{{U\elb{i}}^-}-T_{setR}\right)
    \end{equation}
    \begin{equation}\label{eq:i_dP}
        \Delta P_P\elb{\mathcal{V}\elb{i}} = \zeta\elb{\mathcal{V}\elb{i}} \left(\dot{m}_P\elb{\mathcal{V}\elb{i}}\right)^2
    \end{equation}
    \begin{equation}\label{eq:i_valve}
        \zeta\elb{U\elb{i}} = \mu\left({\theta\elb{U\elb{i}}}^{-1}-1\right)^2
    \end{equation}
    \begin{equation}\label{eq:i_flow}
        \Lambda_i \dot{m}_P\elb{\mathcal{V}\elb{i}} = \widetilde{\dot{m}}_S
    \end{equation}
    \begin{equation}\label{eq:i_pressure}
    \Delta P_P\elb{\mathcal{V}\elb{i}} = \Lambda_i^\top P_S\elb{\mathcal{E}\elb{i}}
    \end{equation}
    \begin{equation}\label{eq:i_flex}
         -C\elb{U\elb{i}}\Delta {T_b}\leq SOE\elb{U\elb{i}}\leq C\elb{U\elb{i}}\Delta {T_b}
    \end{equation}
    \begin{equation}\label{eq:i_theta}
        \theta_{min}<\theta\elb{U\elb{i}}<1
    \end{equation}
\end{subequations}
where \cref{eq:i_dP,eq:i_flex,eq:i_soe,eq:i_qp,eq:i_valve,eq:i_theta} are taken directly from \cref{sec:model}, considering only local variables.\par
In \cref{eq:i_temp}, $\widetilde{T}_0$ is the local inlet temperatures given by 
\begin{equation}
    \widetilde{T}_0 = \begin{bmatrix}
        T_0 & \text{if } v_{0^-}\in\mathcal{V}\elb{i}\\
        T_P\elb{\mathcal{N}\elb{i}_{T}}(p) & \text{if } \mathcal{N}\elb{i}_{T} \neq \emptyset
    \end{bmatrix}
\end{equation}
and $A\elb{i}$ and $B\elb{i}$ are subsets of the originals, and are functions of the local and neighboring mass flow rates. The vector of node mass flow rates in \cref{eq:i_flow}, $\widetilde{\dot{m}}_S$, is now given by 
\begin{equation}
    \widetilde{\dot{m}}_S\elb{v} =\begin{cases}
    \dot{m}_{i^+}\elb{v} & \text{if } v = v_{0^+}\\
    \dot{m}_{i^-}\elb{v} & \text{if } v = v_{0^-}\\
    \dot{m}_{i^-}\elb{v} & \text{if } v\in \mathcal{N}\elb{j}_{\dot{m}_{u}}\\
     \dot{m}_{i^+}\elb{v} & \text{if } v\in \mathcal{N}\elb{j}_{\dot{m}_{d}}\\
     \dot{m}_{j^+}\elb{v}(p) & \text{if } v\in \mathcal{N}\elb{i}_{\dot{m}_{u}}\\
     \dot{m}_{j^-}\elb{v}(p)& \text{if } v\in \mathcal{N}\elb{i}_{\dot{m}_{d}}\\
    0 &\text{otherwise}
    \end{cases}
\end{equation}
where $\dot{m}_{i^+}\geq0$ is a vector of controllable inlet flows, $\dot{m}_{i^-}\leq0$ is a vector of controllable outlet flows, and $\dot{m}_{j^-},\dot{m}_{j^+}$ are the flows controlled by the associated neighboring system.
Additionally, the controllable mass flow rate variables are combined into the control variable as
\begin{equation}
    \widetilde{\dot{m}}_0 = \begin{bmatrix}
        \dot{m}_{i^+}^\top&
        \dot{m}_{i^-}^\top
    \end{bmatrix}^\top
\end{equation}
This information is also used to recover the centralized plant mass flow $\dot{m}_0$ as
\begin{equation}
    \dot{m}_0 = \sum_{\mathclap{i=1\dots n_p\text{ s.t.}
    v_{0^+}\in\mathcal{V}\elb{i}}} \dot{m}_{i^+}\elb{v_{0^+}}(p)
\end{equation}
In subnetworks where any node pressures are dictated by a different subsystem, this pressure constraint is accounted for in \cref{eq:i_pressure} by setting additional split pressures according to
\begin{equation}\label{eq:constrP}
    P_S\elb{v} =\begin{cases}

    P\elb{v}_S(p) & \text{if } v \in\mathcal{N}_{\Delta P}\elb{i}\\
    0 & \text{if } v = v_{0^-}
    \end{cases} 
\end{equation}
where again the split pressure is associated with its downstream edge in the flow graph.
\subsection{Convergence}
Each subsystem solves the local optimization problem, assuming constant predicted values of the neighboring subsystems. After each solution, local variables 
\begin{equation}
    x_{\mathcal{N}} = \begin{bmatrix}
        {T_P\elb{\mathcal{N}\elb{j}_{T}}}^\top &
        {P_S\elb{\mathcal{N}_{\Delta P}\elb{j}}}^\top &
        {\widetilde{\dot{m}}_S{\elb{\mathcal{N}_{\dot{m}}\elb{j}}}}^\top
    \end{bmatrix}^\top
\end{equation}
are passed to neighboring subsystems. The predicted trajectories are then updated according to 
\begin{equation}
    x_{\mathcal{N}}\left(p+1\right) = \omega x_{\mathcal{N}}\left(p\right) + (1-\omega) x_{\mathcal{N}}
\end{equation}
where $\omega$ is the step size, and $p$ is the predicted solution. This process is iterated until convergence.\par
Two convergence criteria exist. First, the change in the passed variables and the subsystem cost meet
\begin{equation}
    \begin{bmatrix} x_{\mathcal{N}}\left(p\right)-x_{\mathcal{N}}\\ 
    c\elb{i}\left(p\right)-c\elb{i}
    \end{bmatrix} \leq \epsilon
\end{equation}
where $\epsilon$ is a vector of threshold values. Additionally, any subsystems in $\mathcal{N}\elb{i}$ must have also converged. Therefore, subsystems with limited dependent neighbors converge first, allowing dependent subsystems to follow. Solutions that depend on each other must converge at the same time.

\subsection{Feasibility}
If the optimization problem is solved for a single partition, a feasible solution is always available, assuming
\begin{enumerate}
    \item $C\elb{U}\Delta {T_b}$ is constant or increasing.
    \item An algebraic model of the heat exchanger and unconstrained plant flow, which  ensures unlimited $\dot{Q}_p\elb{U}$ 
    \item Solar irradiation and heat transfer into buildings are neglected.
\end{enumerate}
From these assumptions, it can be shown that if the building's heat capacity starts within the flexibility envelope, it will be able to remain within the flexibility envelope. However, if the optimization problem has more than one partition, a single subsystem will dictate $P_S\elb{v_{0^+}}$, removing assumption 2. This limit can mean that the required heat is not available to prevent a building from exceeding the lower limit of its flexibility envelope. To prevent infeasibility, a feasibility recovery algorithm is implemented, which allows other subsystems to establish a lower limit on the plant pressure, effectively restoring the unlimited flow assumption. Any subsystems where the building's heat demand can not be met temporarily solves an optimization with \cref{eq:i_cost} as
\begin{equation}
     \min_{\widetilde{\dot{m}},\theta\elb{U_i}} P_{slack}
\end{equation}
where $P_{slack}$ is the increase from the dictated plant pressure, and the constraint established in \cref{eq:i_pressure} is relaxed to 
\begin{equation}
    P_S\elb{v_{0^+}}\left(p\right) \rightarrow  P_{min}=P_S\elb{v_{0^+}}\left(p\right)+P_{slack}
\end{equation}
By minimizing the added slack, the minimum plant pressure needed to ensure feasibility, $P_{min}$,  is found. This lower pressure limit is then transmitted to the controlling subsystem, where the constraint
\begin{equation}
    P_S\elb{v_{0^+}}\geq P_{min}
\end{equation}
is added to ensure this feasibility is not violated. The distributed controller then functions as designed with the new constraint activated. Implementing this feasibility restoration guarantees the overall controller's feasibility regardless of the chosen partitioning.
\subsection{Stability}
Another key concern in selecting system partitions is stability. Here, the stability of the partitioned DHN is demonstrated regardless of the chosen partition to simplify the search for the OLM-minimizing partition. The stability of the partitioned DHN is formally proven in \cref{apx:stability}, and it is constructed using the passive nature of DHNs. First, the passive nature of a single element is demonstrated. Then, the passivity of the interconnected elements is shown. Finally, the zero-state detectability of the DHN is used to ensure stability results from the passive nature. 

\section{Simulation Study}\label{sec:case_study}
\subsection{Case Description}
The OLM minimizing partitioning will be looked at for the four-user network shown in \cref{fig:graphs}. Including pipes, the plant, and the users, this system has a total of 15 elements to be partitioned. The network was constructed using representative network parameters summarized in \cref{tbl:network} \cite{blizardDynamicallySimilarLabscale2023}. The network supply temperature, $T_0$ was assumed to be constant. The ambient temperature in typical meteorological year 3 (TMY3) was provided by NREL in the 2021 data set\cite{horowitz2019resstock}.\par
The buildings connected to the network are four residential buildings in Cook County, Illinois, with data taken from NREL's ResStock \cite{horowitz2019resstock}. The heat capacities were estimated from the building's OpenStock models and are presented in \cref{tbl:build}. Their nominal heat demands are shown in \cref{fig:demand}. It was assumed that the maximum allowable temperature deviation was 2\degree C.\par
The chosen optimization objective for \cref{eq:i_cost} was
\begin{equation}
    f = \frac{w_{C}}{n_{U\elb{i}}}\left(\frac{SOE\elb{U\elb{i}}}{C\elb{U\elb{i}}\Delta T_b}\right)^2+w_Q hAs\left(T_P\elb{N\elb{i}}-T_{amb}\right)
\end{equation}
which is a weighted combination of the percent of used heat capacity in the subgraph and the heat lost by the network, where $w_C=5$ and $w_Q=3\times10^{-6}$.\par
The simulations were performed in discrete time with a 10-minute control time step, a 30-second discretization of temperature variables, a 1-hour optimization horizon, and a 10-minute implementation horizon. The simulation was performed over a 12-hour window starting on January 28th. All optimization was performed using CasADi \cite{Andersson2019} and IPOPT \cite{wachterImplementationInteriorpointFilter2006}.
