    & = \theta_n \int_{0}^1 F^{-1}(1-q) g_n(p, q) dq - \theta_n \int_{0}^{1} F^{-1} (1-q) \cdot n (1-p)^{n} dq,\label{ratio_adap_res0}
\end{align}
