\begin{align*}
    \frac{\int_{0}^{1} F^{-1} (1-q) g_n(p,1)\, \mathrm{d}q}{\int_{0}^1 F^{-1}(1-q) g_{n}(p,q)\mathrm{d}q} & \leq \frac{(1-p)^{n-1} p n}{1-(1-p)^n}\leq 1,
\end{align*}
