\begin{proof}
    It is sufficient to show that the function 
    $f(v) = v/ \left( \sum_{j=1}^{i} \Pr[\text{Bin}(n,v) \geq j] \right)$ is non-decreasing for fixed  $i \in [n-1]$. Consider $g(v) = 1/f(v)$, and its derivative with respect to $v$: 
    \begin{align*}
        g'(v)&= \frac{1}{v^2} \left( \sum_{j=1}^{i} (\sum_{k = j}^{n}\binom{n}{k} kv^{k}(1-v)^{n-k} - \binom{n}{k} (n-k)v^{k+1}(1-v)^{n-k-1}) - \Pr[\text{Bin}(n,v) \geq j] \right)\\
        & = \frac{1}{v^2} \sum_{j=1}^{i} \frac{n!}{(n-j)!(j-1)!}v^j(1-v)^{n-j} - \frac{v^{n+1}}{1-v} - \Pr[\text{Bin}(n,v) \geq j]\\
        & = -\frac{i  v^{n+1}}{v^2 (1-v)} + \frac{1}{v^2} \sum_{j=1}^i (j \cdot \Pr[\text{Bin}(n,v) = j] - \Pr[\text{Bin}(n,v) \geq j]).
    \end{align*}
    Observe that $i v^{n+1}/ \left( v^2 (1-v) \right)$ is non-negative, and for each $k \in [1, i]$, $k \cdot \Pr[\text{Bin}(n,v) = k] - \sum_{j=1}^{k} \Pr[\text{Bin}(n,v) = j] = 0$, as $\Pr[\text{Bin}(n,v) \geq j] = \sum_{k=j}^{n} \Pr[\text{Bin}(n,v) = k]$. Thus, $ g'(v) \leq 0$, and $f(v)$ is non-decreasing in $v \in [0,q]$. 
\end{proof}

\begin{proof}[Proof of Lemma~\ref{lemma_hard_opt}]
    \begin{align*}
    v(\OPT) & \geq \sum_{i=2}^n p\cdot (1-p)^{i-1} \sum_{j=1}^{i-1} \int_{0}^{1} F^{-1}(1-u) \cdot (1-u)^{n-j} u^{j-1} \cdot j \cdot \binom{n}{j} du \\
    & = \int_{0}^{1} \sum_{i=2}^n p\cdot (1-p)^{i-1} \sum_{j=1}^{i-1} \frac{a_1}{n}\delta_{\lbrace 0 \rbrace}(u) \cdot (1-u)^{n-j} u^{j-1} \cdot j \cdot \binom{n}{j} du \\
    & \hspace{3cm} + \int_{0}^{\beta/n} \sum_{i=2}^n p\cdot (1-p)^{i-1} \sum_{j=1}^{i-1} a_2 \cdot (1-u)^{n-j} u^{j-1} \cdot j \cdot \binom{n}{j} du\\
    & = a_1 \sum_{i=2}^n p(1-p)^{i-1} + a_2 \sum_{i=2}^n \sum_{j=1}^{i-1} p\cdot (1-p)^{i-1} \Pr[\text{Bin}(n, \beta/n) \geq j] \\
    & = a_1(1-p)(1-(1-p)^{n-1}) + a_2 \sum_{j=1}^{i-1} \Pr[\text{Bin}(n, \beta/n) \geq j] [(1-p)^j - (1-p)^n].
\end{align*} 
The second equality recognizes that $\Pr[\text{Bin}(n, \beta/n) \geq j] = \int_{0}^{\beta/n} (1-u)^{n-j} u^{j-1} \cdot j \cdot \binom{n}{j} du$, and we recover the lemma by letting $n \to \infty$. 
\end{proof}


\begin{proof}[Proof of Lemma~\ref{lemma_hard_threshold}]
We derive the performance of $\ALG^q$ via direct calculation.
\begin{align}
    & v(\ALG^q) = A_n(q, p) \cdot \frac{\int_0^q F^{-1}(1-u) du}{q} = A_n(q, p) \cdot \frac{\int_0^q ({a_1}/{n})\delta_{\lbrace 0 \rbrace}(u) + a_2\mathbbm{I}_{(0, \beta/n]}(u)du}{q} \tag{Using~\eqref{exp:hard_dist}}\\
    & = \frac{A_n(q, p)}{q} \cdot \left(\frac{a_1}{n} + a_2 \cdot \min \{ q, \beta/n \} \right) \notag \\
    & = \max \left\lbrace \sup_{q \in [0, \beta/n]} \frac{A_n(q, p)}{q} \cdot \left(\frac{a_1}{n} + a_2 \cdot q \right),  \sup_{q \in [\beta/n, 1]} \frac{A_n(q, p)}{q} \cdot \left(\frac{a_1}{n} + \frac{a_2 \beta}{n} \right)\right\rbrace \notag \\
    & = \frac{1-p}{p} \cdot \max \left\lbrace \sup_{\lambda \in [0, \beta]} \frac{1}{\lambda} \left( 1 - \left(1-\frac{\lambda p}{n}\right)^n \right) \left( a_1 + a_2 \lambda \right), \sup_{\lambda \in [\beta, n]} \frac{1}{\lambda} \left( 1 - \left(1-\frac{\lambda p}{n}\right)^n \right) \left(a_1 + a_2 \beta \right) \right \rbrace,\label{exp_4.5_inter}
\end{align}
where the last equality follows from the change of variable $q= \lambda / n$. 
We denote by $r_1(\lambda)$ the second term in the maximum argument in~\eqref{exp_4.5_inter}. We have $r'_1(\lambda) = \frac{1}{\lambda^2} \left( \lambda p \left(1-\frac{\lambda p}{n}\right)^{n-1} + \left(1-\frac{\lambda p}{n}\right)^n - 1 \right)$, and for $\lambda = 2/p$, the derivative of $r_1$ becomes negative; hence,
 $\sup_{\lambda \in [\beta, n]} r_1(\lambda)$ can be restricted to $[\beta, \max \{\beta, 2/p\}]$. Next, letting $n \to \infty$ yields
\begin{align}\label{exp_4.5}
\lim_{n\to \infty} v(\ALG^q) = \frac{1-p}{p} \cdot \max \left\lbrace
\sup_{\lambda \in [0, \beta]} \frac{1-e^{-\lambda p}}{\lambda}  (a_1 + a_2 \lambda), \sup_{[\beta, \max \{\beta, 2/p\}]}\frac{1-e^{-\lambda p}}{\lambda} (a_1 + a_2 \beta)
\right\rbrace.
\end{align}

We denote by $r_2(\lambda)$ and $r_3(\lambda)$ the first and second terms in the maximum argument in~\eqref{exp_4.5}, respectively. Note that $r_2'(\lambda) = [a_1 (e^{-\lambda p} - 1) + p \lambda e^{-\lambda p} (a_1 + a_2 \lambda)]/\lambda^2$. Thus, $r_2{'}(\lambda^*) = 0$ implies that $e^{-\lambda^* p} \left( a_1 + a_1 p \lambda^* + a_2 p ({\lambda^{*}})^2 \right) = a_1 $; hence, $\sup_{\lambda \in [0, \beta]} r_2(\lambda)=\max\{r_2(\lambda^*),r_2(\beta),\lim_{\lambda\to 0} r_2(\lambda)\}$ where $0 < \lambda^* < \beta$, if it exists.
Moreover, $r_3(\lambda)$ is a decreasing function in $\lambda$, thus the supremum is attained at $\lambda = \beta$. We combine both cases to conclude the proof.
\end{proof}

