\begin{proof} [Proof of Proposition~\ref{prop:ub_opt}]
By the second characterization of $v^\epsilon(\OPT)$ in \eqref{exp:opt_value_complete}, we have
\begin{align*}
    v^\epsilon(\OPT) & = \int_{0}^1 F^{-1}(1-u) g_{n}(p, u) du\\
    & = \int_{0}^1 \left( \frac{\theta^*}{(1-p)n} \cdot \delta_{\lbrace 0 \rbrace}(u) - \frac{p}{1-p} \int_{y^{-1} (e^{-pnu})}^{1-\epsilon} \frac{1}{y'(s)} ds \mathbbm{I}_{(0, 1)}(u) \right) (1-p) \cdot n (1-pu)^{n-1} du \\
    & = \theta^* - \int_{0}^{1} \int_{y^{-1} (e^{-pnu})}^{1-\epsilon} \frac{1}{y'(s)} ds (1-pu)^{n-1} pn du \\
    & = \theta^* - \int_{e^{-np}}^1 \int_{y^{-1} (v)}^{1-\epsilon} \frac{1}{y'(s)} ds \left(1+\frac{\log(v)}{n}\right)^{n-1} \frac{dv}{v} \tag{Per $v = e^{-npu}$} \\
    & = \theta^* - \int_{0}^{1-\epsilon} \int_{\max\{y(s), e^{-np}\}}^1 \left(1+\frac{\log(v)}{n}\right)^{n-1} \frac{dv}{v} \frac{1}{y'(s)} ds \tag{Changing order of integration}\\
    & = \theta^* - \int_{0}^{1-\epsilon} \frac{1}{y'(s)} \left( 1- \left(1+\frac{\log(y(s))}{n}\right)^n\right) ds. \quad\text{(Per $y(s) > e^{-np}$ when $s \in (0, 1-\epsilon)$)} \qedhere
\end{align*}
\end{proof}

\begin{proof} [Proof of Lemma~\ref{lem: ub_adapt_be}]
    We first show that \eqref{exp: ub_adapt_sol} satisfies the Bellman equation \eqref{exp: ub_adapt_be}. 
    \begin{align*}
        & \int_{0}^{\mu} h(u) du -p \mu d(x) \\
        & = \int_{0}^{-\log(y(x))/p} \left( \theta^* \cdot \delta_{\lbrace 0 \rbrace}(u) - p \int_{y^{-1} (e^{-pu})}^{1} \frac{1}{y'(s)} ds \mathbbm{I}_{(0, 1)}(u) \right) du - p \cdot \frac{\log(y(x))}{p} \cdot \int_{x}^{1} \frac{1}{y'(s)} ds\\
        & = \theta^* - p \int_{0}^{1} \int_{0}^{\min\{-\log(y(x))/p, -\log(y(s))/p \}} du \frac{1}{y'(s)} ds - \log(y(x)) \int_{x}^{1} \frac{1}{y'(s)} ds\\
        & = \theta^* + \int_{0}^{1}  \frac{\max\{\log(y(x)), \log(y(s))\}}{y'(s)} ds - \int_{x}^{1} \frac{\log(y(x))}{y'(s)} ds \\
        & = \theta^* + \int_{0}^{x}  \frac{\log(y(s))}{y'(s)} ds + \int_{x}^{1}  \frac{\log(y(x))}{y'(s)} ds  -  \int_{x}^{1} \frac{\log(y(x))}{y'(s)} ds \tag{Monotonicity of $y(x)$}\\
        & = \theta^* + \int_{0}^{x}  \frac{y''(s)}{(y'(s))^2} ds \tag{Per $y''(x) = y'(x) \log(y(x))$}\\
        & = \theta^* - \frac{1}{y'(x)} + \frac{1}{y'(0)} = - \frac{1}{y'(x)} = -d'(x).
    \end{align*}

    Next, we show that $\mu$ is indeed the unique maximizer. We proceed in two steps: (i) the derivative with respect to $\mu$ is zero. (ii) the derivative is positive when $\mu = 0$, and the derivative is negative as $\mu \to \infty$. By Leibniz integral rule, we have $\frac{d}{d\mu} \left\lbrace \int_{0}^{\mu} h(u) du -p \mu d(x) \right\rbrace = h(\mu) - p \cdot d(x)$. 

    \noindent To verify (i), note that 
    \begin{align*}
        h(\mu) - p \cdot d(x) = \theta^* \cdot \delta_{\lbrace 0 \rbrace}(-\frac{\log(y(x))}{p}) - p \int_{x}^{1} \frac{1}{y'(s)} ds \mathbbm{I}_{(0, 1)}(\mu) - p \cdot \int_{x}^{1} -\frac{1}{y'(s)} ds = 0.
    \end{align*}

    \noindent To verify (ii), note that $\lim_{\mu \to \infty} h(\mu) - p \cdot d(x)  = -p \cdot d(x) < 0$ and
    \begin{equation*}
         h(0) - p \cdot d(x) = \theta^* - p \int_{0}^{1} \frac{1}{y'(s)} ds - p \cdot \int_{x}^{1} -\frac{1}{y'(s)} ds = \theta^* -p \cdot \int_{0}^{x} \frac{1}{y'(s)} ds > 0.\qedhere
