\begin{proof} [Proof of Claim~\ref{clm: ub_tilde}]
    Let $d_{i, \sigma} := d((1-\sigma)i/n))$ and $y_{i,\sigma} := y((1-\sigma)i/n))$. Then, we have
    \begin{align*}
        & \hspace{0.3cm} (1-p) \int_{0}^q F^{-1}(1-u) du + (1-pq)(1+\eta_{\sigma})d_{i+1, \sigma} \\
        & \leq \frac{1}{n} \int_{0}^{\mu} h(u) du + \left(1-\frac{p\mu}{n}\right)(1+\eta_{\sigma}) \left( d_{i, \sigma} + \frac{1-\sigma}{n} d'_{i, \sigma} \right)\tag{Rewrite $q = \frac{\mu}{n}$ \& concavity of $d_{i, \sigma}$} \\
        & =  (1+\eta_{\sigma}) d_{i,\sigma} + \frac{1}{n} \left(\int_{0}^{\mu} h(u) du - (1+\eta_{\sigma})p\mu d_{i,\sigma} \right) + \frac{1}{n} (1+\eta_{\sigma}) \left( d'_{i, \sigma} (1-\sigma) - \frac{p\mu}{n} d'_{i, \sigma} (1-\sigma) \right)\\
        & \leq \widetilde{D}_i - \frac{d'_{i, \sigma}}{n} + \frac{\eta_\sigma \log(y_{i,\sigma})}{n} d_{i, \sigma} + \frac{d'_{i, \sigma}}{n} + \frac{\eta_\sigma d'_{i, \sigma}}{n} - \frac{\sigma d'_{i, \sigma}}{n} - \frac{\sigma \eta_\sigma d'_{i, \sigma}}{n} + \frac{\log(y_{i,\sigma})}{n^2 }d'_{i, \sigma} (1-\sigma) (1+\eta_\sigma)\\
        & = \widetilde{D}_i + \frac{\eta_\sigma \log(y_{i,\sigma})}{n} d_{i, \sigma} + \frac{\eta_\sigma d'_{i, \sigma}}{n} - \frac{\sigma d'_{i, \sigma}}{n} - \frac{\sigma \eta_\sigma d'_{i, \sigma}}{n} + \frac{\log(y_{i,\sigma})}{n^2 }d'_{i, \sigma} (1-\sigma) (1+\eta_\sigma)
    \end{align*}
    Note that $\eta_\sigma \log(y_{i,\sigma}) d_{i, \sigma} < 0$, and since $d'_{i, \sigma} < 0$, it is sufficient to show that $\eta_\sigma  - \sigma - \sigma \eta_\sigma + \frac{\log(y_{i,\sigma})}{n} (1-\sigma) (1+\eta_\sigma) \geq 0$, which is guaranteed by \eqref{exp: eta_req}. 
\end{proof}


