\begin{eqnarray}
\label{eq:int_tparPhi}
    \delta D_-  \int_{-1}^{L}  \tpar_i \left( c_-(\vec{x}+\delta \xi \, \widehat n) \tpar_i \Phi(\vec{x}+\delta \xi \, \widehat n) \right) \,d\xi \approx \delta D_-  \tpar_i \left( \tpar_i \Phi(\vec{x}+\delta L \,\widehat n)  \int_{-1}^{L}   c_-(\vec{x}+\delta \xi \, \widehat n)  \,d\xi \right)
\end{eqnarray}
 where we consider that $\tpar_i$ is a differentiation in the direction orthogonal to the normal $\widehat n$, and
 % we assume that $\widetilde \Phi$ does not change significantly across the bubble thin layer. Furthermore, 
 since $\delta $ is very small, we assume $\tpar_i\Phi(\vec{x}+\delta \xi \, \widehat n)$ to be essentially constant inside the integral. 
 Making use of approximations in Eqs.~(\ref{eq:Mm_2D}-\ref{eq:M_2D}), we write 
\begin{eqnarray}
\label{eq:int_tparPhi3}
 \delta D_-  \tpar_i \left( \tpar_i \Phi(\vec{x}+\delta \xi \,\widehat n)  \int_{0}^{L+1}   c_-(\vec{x}+\delta \xi \, \widehat n)  \,d\xi \right) \approx D_- \tpar_i\left(M_- c_-^B\, \tpar_i \Phi  \right)\approx D_- M \tpar_i\left( c_- \,  \tpar_i \Phi \right),
\end{eqnarray}
where, the last approximation comes from Eq~\eqref{eq:M_2D}.

Now, making use of Eqs.~\eqref{eq:appr_dt}, \eqref{eq:appr_Delta}, \eqref{eq:int_tparPhi3} in  Eq.~\eqref{eq:delta_Jn_Jtau} in the limit of $\delta \to 0$, we obtain the boundary condition for $c_-$ at the bubble surface
\begin{align} 
	M \pad{}{t} c_-  =  D_- \left( \frac{\partial c_-}{\partial n} +
	  M \left( \Delta_\perp  c_-   + \tpar_i\left( c_- \, \tpar_i \Phi \right) \right) \right). 
\end{align}
At the end, in two- and three-dimensions, the system of equations is
\begin{subequations}
\label{system_multiscale_all}
\begin{align}
	\label{system_multiscale}
	\displaystyle \frac{\partial c_\pm}{\partial t} &= D_\pm \Delta c_\pm \pm \nabla\cdot \left( c_\pm \nabla \Phi \right) \quad \rm{in} \> \Omega \\ 
    -\varepsilon \Delta \Phi &= \frac{c_+}{m_+} - \frac{c_-}{m_-} \quad \rm{in} \> \Omega
\end{align}
\end{subequations}
together with the following boundary conditions for $c_\pm$ and $\Phi$:
\begin{subequations}
\label{system_multiscale_bc}
\begin{align}
	\displaystyle \nabla c_\pm \cdot \widehat n &= 0 \quad \rm{ on } \, \partial \Omega\setminus \Gamma_\mathcal{B} \\ \label{bc_multiscale_cp}
	  \displaystyle \nabla c_+ \cdot \widehat n &= 0 \quad \rm{ on }\, \Gamma_\mathcal{B}
 \\ \label{bc_multiscale_cm}
	\displaystyle M\frac{\partial c_-}{\partial t} &= D_-\left(\frac{\partial  c_-}{\partial n} + M \left( \Delta_\perp c_- +  \tpar_i\left( c_-   \tpar_i \Phi \right)\right) \right) \quad \rm{ on }\, \Gamma_\mathcal{B} \\ \nonumber
 \nabla \Phi \cdot \widehat n & = 0 \quad \rm{ on } \, \partial \Omega\setminus \Gamma_\mathcal{B} \\ 
 \varepsilon \nabla \Phi \cdot \widehat n & = Mc_- \quad \rm{ on } \, \Gamma_\mathcal{B}.
\end{align}
\end{subequations}
Notice that in two-dimensions the Laplace-Beltrami operator reduces to the second derivative with respect to the arclength of the boundary\footnote{Here by $\partial/\partial \tau$ 
we denote the derivative on $\Gamma_\mathcal{B}$, i.e.\ the derivative along the arclength that parametrizes the curve, likewise
$\partial^2/\partial \tau^2$ denotes the second derivative along $\Gamma_\mathcal{B}$, not the second derivative along the tangent direction. }
\begin{equation}
    \Delta_\perp c_\pm= \frac{\partial^2 c_\pm}{\partial \tau^2},
    \label{eq:BL2D}
\end{equation}
while $\tpar_i$ reduces to $\partial/\partial \tau$.







\section{One-dimensional discretization and validation for $\protect \delta \to 0$}
In this section, we discretize the one-dimensional problem with a second order accurate discretization in space and time. We further validate the two-species MPNP system in the limit $\delta \to 0$, demonstrating that the difference between the two approaches is an infinitesimal of order one in $\delta$. 
\subsection{Space discretization in one dimension}
The one dimensional domain is $\Omega^\delta = [- \delta ,1].$ 
%=\Omega^\delta _{\rm b} \cup \Omega^\delta _{\rm f}, $ where the portion describing the bubble action is $\Omega^\delta _{\rm b} = [- \delta ,L\delta ]$ while the fluid one is $ \Omega^\delta _{\rm f} = [L\delta ,1]$. {In all our calculations we used $L=2$.} 
The computational domain $\Omega^\delta_h$ is a discretization of $\Omega^\delta$ obtained by a uniform Cartesian mesh with spatial step $ h:   h  N_x = 1 +  \delta,\, N_x\in\mathbb N$. The concentrations $c_{\pm,i}$ are defined at the center of the cells with $x_i=-\delta  + (i-1/2) h \in\{1,\dots,N_x\} $. We choose a cell centered discretization in order to guarantee the exact conservation of the  
{total volume of the solute $v=\sum_i c_{\pm,i} h$}, which is a consequence of the zero boundary condition for the flux. The scheme is second order accurate and it is stable even in presence of a drift term, provided the following condition for the so called {mesh P\'{e}clet number}, pec, is satisfied \cite{Wesseling2023600}:
\begin{equation}
\label{eq_pec}
	{\rm pec} := \max_x\left|{\partial_x U_\pm}\right| h < {2}.
\end{equation} 
The full one dimensional problem~\eqref{eq_full_model_adim} is then discretized in space, leading to the following system of Differential-Algebraic equations:
\begin{subequations}
\label{eq_semi_discrete_full}
\begin{eqnarray}
\label{eq_semi_discrete_eq_c}
	\td{c_{\pm,h}}{t} &=& \left(\mathbb L^{\rm 1D} + \mathbb D^{\rm 1D}_\pm[U_\pm] \right)  c_{\pm,h} \pm \mathbb D^{\rm 1D}_\pm[c_{\pm,h}] \Phi_h, \quad c^0_{\pm,h} = c_{\pm,h}(t = 0) ,\\ \label{eq_semi_discrete_eq_phi}
 -\varepsilon \mathbb L^{\rm 1D}\, \Phi_h &=& \frac{c_{+,h}}{m_+} - \frac{c_{-,h}}{m_-}
\end{eqnarray}
\end{subequations}
where $\mathbb L^{\rm 1D},\mathbb D^{\rm 1D}\,\left[U_{\pm,h}\right] $ and $\mathbb D^{\rm 1D}\,\left[ c_{\pm,h}\right] $ are ${N_x} \times {N_x}$ matrices representing the discretization of the space derivatives, as follows
\begin{eqnarray} 
\label{eq_Lh}
\mathbb L^{\rm 1D}\, c_{\pm,h}\Big|_{j} &=& D_\pm \left( \frac{c_{\pm,j+1}  + c_{\pm,j-1} - 2c_{\pm,j}}{h^2} \right)
\\ \nonumber \mathbb D^{\rm 1D}_\pm\,\left[ U_{\pm,h}\right] \,c_{\pm,h}\Big|_{j} & = & D_\pm \frac{(U_{\pm,j+1}-U_{\pm,j})\,c_{\pm,j+1} + (U_{\pm,j+1}-2U_{\pm,j}+U_{\pm,j-1})\,c_{\pm,j} + (U_{\pm,j-1}-U_{\pm,j})\,c_{\pm,j-1}}{2h^2}
\\ \nonumber \mathbb D^{\rm 1D}_\pm\,\left[ c_{\pm,h}\right] \,\Phi_{h}\Big|_{j} & = & D_\pm 
\frac{(c_{\pm,j+1}+c_{\pm,j})\,\Phi_{j+1} - (c_{\pm,j+1}+2c_{\pm,j}+c_{\pm,j-1})\,\Phi_{j} + (c_{\pm,j}+c_{\pm,j-1})\,\Phi_{j-1}}{2h^2}
.
\end{eqnarray} 
The numerical solution at time $t$ is represented by the vector $c_{\pm,h}$, whose components $c_{\pm,i}(t)$ are approximations of the exact solution on the grid points of $\Omega_h$,  i.e.\
$c_{\pm,i}(t)\approx c_\pm(x_i,t)$. The quantities $ c^0_{\pm,h}$ and $ U_{\pm,h}$ are analogously defined. 

For the multiscale model (\ref{eq_final_system_1D}-\ref{eq_final_system_1D_bc}), the domain is $\Omega^0 = [0,1]$, while the discrete computational domain is $\Omega^0_h$, that we discretize as follows: $x_i=(i-1/2) h,\, i \in\{0,\dots,N\},  h  N = 1$. The semidiscrete numerical scheme is the following
\begin{subequations}
\label{eq_semi_discrete_mul}
\begin{eqnarray}
\label{eq_semi_discrete_eq_c_mul}
	\td{c_{\pm,h}}{t} &=& \mathbb L^{\rm 1D} c_{\pm,h} \pm \mathbb D^{\rm 1D}_\pm[c_{\pm,h}] \Phi_h, \quad c^0_{\pm,h} = c_{\pm,h}(t = 0),\\ \label{eq_semi_discrete_eq_phi_mul}
 -\varepsilon \mathbb L^{\rm 1D}\, \Phi_h &=& \frac{c_{+,h}}{m_+} - \frac{c_{-,h}}{m_-}.
\end{eqnarray}
\end{subequations}

To close the system we need to discretize the boundary conditions. 
To this purpose we add two ghost cells, one to the left of the boundary $x=0$, and call $c_{\pm,0}$ the value at the center of such a cell, and one to the right of the right boundary, and denote by $c_{\pm,N+1}$ their values.  To second order accuracy, the value of $c_-$ at $x=0$ is given by $c_{-,1/2}\approx (c_{-,0}+c_{-,1})/2$. Notice that boundary conditions 
\eqref{eq_final_system_bc_cp}, and (\ref{system_1_delta_3}-\ref{eq_final_system_bc_phi}) impose that  $c_{+,0} = c_{+,1}, \, c_{+,N+1} = c_{+,N}, \, c_{-,N+1} = c_{-,N}$ and $\Phi_{N+1} = \Phi_N$.


The discretization of \eqref{eq_semi_discrete_eq_c_mul} at the left boundary reads
\begin{equation}\label{eq:c_ghost}
    \frac M 2 \left(\td{c_{-,0}}{t} + \td{c_{-,1}}{t} \right)= D_-\left( \frac{c_{-,1}-c_{-,0}}{h} - \frac{c_{-,1} + c_{-,0}}{2} \frac{\Phi_1-\Phi_0}{h}  \right).
\end{equation}
%The first equation of  \eqref{eq_semi_discrete_eq_c_mul} for $c_{-,h}$ reads
% \begin{align}\label{eq:first}
%     \td{c_{-,1}}{ t} = D_-\left(\frac{c_{-,2}- 2c_{-,1} + c_{-,0}}{h^2} + \frac{c_{-,2} + c_{-,1}}{2} \frac{\Phi_2-\Phi_1}{h^2} - \frac{c_{-,1} + c_{-,0}}{2} \frac{\Phi_1-\Phi_0}{h^2}\right) 
% \end{align}
% Solving for $c_{-,0}$ from \eqref{eq:c_ghost} and replacing it in 
% \eqref{eq:first} we  obtain 
% \begin{align}
% \label{eq:bc_cpm}
%     \td{}{t} \left( c_{-,1} + \frac{M}{h}c_{-,1/2}\right) = D_- \left( \frac{c_{-,2}-c_{-,1}}{h^2} + \frac{c_{-,2} + c_{-,1}}{2} \frac{\Phi_2-\Phi_1}{h^2} \right). 
% \end{align}
Now we discretize the boundary condition for $\Phi$, that at the left boundary becomes % We start from Eq.~\eqref{eq_semi_discrete_eq_phi_mul}, calculated in $j = 1$
% \begin{equation}
% \varepsilon\left(\frac{\Phi_2 - \Phi_1}{h^2} - \frac{\Phi_1 - \Phi_0}{h^2} \right) = \frac{c_{-,1}}{m_-} - \frac{c_{+,1}}{m_+}    
% \end{equation}
% and using Eq.~\eqref{system_1_delta_2}, it becomes
% \begin{equation}
% \label{eq:bc_Phi}
%     \varepsilon \frac{\Phi_2 - \Phi_1}{h^2}  =  \left(1 + \frac{M}{h}\right) \frac{c_{-,1}}{m_-} - \frac{c_{+,1}}{m_+}.
% \end{equation}
\begin{equation}
\label{eq:Phi_ghost}
    \varepsilon \frac{\Phi_1 - \Phi_0}{h}  =  M \frac{c_{-,0} + c_{-,1} }{2}.
\end{equation}
Eqs.~(\ref{eq_semi_discrete_mul}-\ref{eq:Phi_ghost}) constitute a system of $3N+2$ equations  for the $3N+2$ unknowns $c_{+,i},\,  i = 1,\cdots,N, \> c_{-,i}, \, i = 0,\cdots,N$ and $\Phi_i, \, i = 0,\cdots,N$.

