\subsection{Time discretization in one dimension}
\label{sec:time_discretization_1D}
In this subsection, we describe the time discretization for the one dimensional problem. 
If we denote with $c_\pm^\delta$ and $c_\pm^0$ the solutions of the full and multiscale models, respectively, the problems~\eqref{eq_semi_discrete_full} and \eqref{eq_semi_discrete_mul} can be summarized as follows
\begin{equation}\label{eq:Theta_eps}
	\td{ \textbf{q}^\delta }{t} = \Theta^\delta [ \textbf{q}^\delta ]\textbf{q}^\delta,
\end{equation}
where $\textbf{q}^\delta = [c_{+,h},c_{-,h},\Phi_h]^\top$, and we distinguish between the cases $\delta > 0$ and $\delta = 0$:
\begin{equation}
\label{eq:sys_eps_1D}
  \Theta[{\bf q^\delta}] = \begin{pmatrix}
\mathbb L^{\rm 1D} + \mathbb D^{\rm 1D}_+[U_+] & {\underbar 0} & \mathbb D^{\rm 1D}_+[c_{+,h}]\\
\underbar 0 & \mathbb L^{\rm 1D} + \mathbb D^{\rm 1D}_-[U_-]  & \mathbb D^{\rm 1D}_-[c_{-,h}]\\
-\mathbb I  & \mathbb I & - \varepsilon \mathbb L^{\rm 1D} \\
\end{pmatrix}, \quad {\rm if } \, \delta > 0
\end{equation}
\begin{equation}
\label{eq:sys_0_1D}
  \Theta[{\bf q^0}] = \begin{pmatrix}
\mathbb L^{\rm 1D} & {\underbar 0} & \mathbb D^{\rm 1D}_+[c_{+,h}]\\
\underbar 0 & \mathbb L^{\rm 1D} & \mathbb D^{\rm 1D}_-[c_{-,h}]\\
-\mathbb I  & \mathbb I & - \varepsilon \mathbb L^{\rm 1D} \\
\end{pmatrix}, \quad {\rm if } \, \delta = 0
\end{equation}
with appropriate boundary conditions, defined in Eqs.~(\ref{eq:c_ghost}-\ref{eq:Phi_ghost}).


%%%%%%%%%%%%%

% \begin{eqnarray}
% \label{eq_Q_0}
% 	\Theta^0( c^0 ) =	\left\{
% 	\begin{matrix} %\left\{ \right\.
% 		D \Delta  c^0  & {\rm in } \, \Omega^0, \\
% 		\displaystyle DM^{-1} \frac{\partial  c^0 }{\partial x} \quad & {\rm on }\, x=0 
% 	\end{matrix}
% 	\right. \qquad {\rm if} \> \varepsilon=0   
% %\end{minipage}
% \end{eqnarray}
We apply IMEX method to \eqref{eq:Theta_eps}. Let us first set $\textbf{q}^1_E = \textbf{q}^n$, then the stage fluxes are calculated as
\begin{subequations}  
\label{eq_imex1}
\begin{align}
\label{eq_imex_qE}
    \textbf{q}_E^{i}& = \textbf{q}^n + \Delta t\,\sum_{j=1}^{\rm i-1}\widetilde a_{i,j}\Theta[\textbf{q}_E^j]\,\textbf{q}_I^j, \quad i = 1,\cdots,s \\
\label{eq_imex_qI}
  \textbf{q}_I^{i} &= \textbf{Q}^n + \Delta t\,\sum_{j=1}^{\rm i} a_{i,j}\Theta[\textbf{q}_E^j]\,\textbf{q}_I^j, \quad i = 1,\cdots,s 
\end{align}
\end{subequations}
and the numerical solution is finally updated with
\begin{align}
\label{eq_imex_q_bi}
   \textbf{q}^{n+1} &= \textbf{q}^n + \Delta t\sum_{i=1}^{\rm s} b(i) \Theta[\textbf{q}_E^i]\,\textbf{q}_I^i
\end{align}
where $\rm s$ is the number of stages of the scheme, and $\Delta t>0$ the time step. We choose a two stages IMEX-RK methods \cite{ascher1997implicit,pareschi2003high,pareschi2005implicit}, with the double Butcher tableau of the form
\begin{equation}
\label{b_tableau}
    \begin{array}{c|cc}
        0 & 0 & 0  \\
        1/(2\gamma) & 1/(2\gamma) & 0 \\ \hline
         & 1-\gamma & \gamma 
    \end{array} \hspace{4cm}
        \begin{array}{c|cc}
        \gamma & \gamma & 0  \\
        1 & 1-\gamma & \gamma \\ \hline
         & 1-\gamma & \gamma 
    \end{array}
\end{equation}
This scheme is L-stable and stiffly accurate. We refer to this scheme as IMEX-SA(2,2,2).



%The method that we consider takes into account two parameters, the range of the potential $\varepsilon$ and the discretization step $h=\Delta x$ (we chose $\Delta t \propto \Delta x$). In this section first we see the effect of the LJ potential, described in Eq.~\eqref{expr_U_LJ}, on the concentration (see Fig.~\ref{1D_full_complete}, left). As $\varepsilon$ decreases, the agreement between the two models gets better and better, as we see in Fig.~\ref{1D_full_complete} (right).



\section{Numerical results in one dimension}
\label{section_accuracy_test_1D}
In this section, we test the accuracy of the numerical method. We choose
an exact solution $ {\bf q}_{\rm exa}$ and augment the system~\eqref{eq:Theta_eps} as:
\begin{equation}\label{eq:Theta_eps2}
	\td{ \textbf{q}^\delta }{t} = \Theta^\delta [ \textbf{q}^\delta ] + {\bf f}^{\rm exa}({\bf q}^{\rm exa}),
\end{equation}
choosing ${\bf f}^{\rm exa}({\bf q}^{\rm exa}) = [f_+(c_+^{\rm exa}),f_-(c_-^{\rm exa}),f(\Phi^{\rm exa})]$ in such a way that $ {\bf q} = {\bf q}^{\rm exa}$ is the exact solution, see for example \cite{roache2002code}. We choose the following exact solutions:
\begin{subequations}
\label{exact_rho}
\begin{align} 	
c_\pm^{\rm exa}(x,t) &= v_0 \left( \cos(t)^2 c_\pm^0(x) + \sin(t)^2 c_\pm^1(x) \right), \\ 
\Phi^{\rm exa}(x,t) & = \cos(t) \cos(2\pi x), \\ \nonumber
c_\pm^\beta(x) &= \exp\left(-{\left(x-x_\pm^\beta\right)^2}/{\sigma}\right),\quad \beta = 0,1
\end{align}
\end{subequations}
where $x_+^0 = 0.45, x_-^0 = 0.5, x_+^1 = 0.5, x_-^1 = 0.55$, $M = 3$ (as we did in \cite{astuto2023multiscale}) and $v_0 = 10^{-4}$ denotes the total volume per unit surface (i.e.\ a length since we are in one space dimension).
%and $x_+^0 = ,x_+^1 = , x_-^0 = ,x_-^1 = $
We compute the ${L}^2$ norm of the relative error at $t=0.1$, as follows
\begin{align} 	\label{relativeerr}
{\rm error}({\bf q}) = \frac{|| {\bf q} - {\bf q}^{\rm exa}||}{||{\bf q}^{\rm exa}||},
\end{align}
for different values of $N$ and show the results in Fig.~\ref{fig:accuracy_1D}, for $\delta \neq 0$, and in Fig.~\ref{fig:accuracy_1D_MPNP}, for $\delta = 0$. We compare the accuracy of the method, showing that the order of accuracy does not depend on $\delta$ in Fig.~\ref{fig:accuracy_1D}, but it depends on $\varepsilon$, with a degradation of the order from 2 to $\approx$ 1, when $\varepsilon \to 0$.
