\section{Quasi--Neutral Limit (QNL)}
In this section, we deduce the Quasi-Neutral limit for the MPNP system in (\ref{system_multiscale_all}-\ref{system_multiscale_bc}). We start introducing two new quantities, that we obtain from the sum and the difference of the two concentrations, as follows
\[ \mathcal C = \frac{c_+}{m_+} + \frac{c_-}{m_-}, \qquad \mathcal Q = \frac 1 \varepsilon\left(\frac{c_+}{m_+} - \frac{c_-}{m_-}\right)\]
where $\mathcal{Q}$  is proportional to the difference of the net charge density divided by  $\varepsilon$, and presumably remains finite in the Quasi-Neutral limit $\varepsilon\to 0$. In this way, we avoid the instability in the Poisson equation for the electrostatic potential caused by the strong degeneracy when $\varepsilon \approx 0$. 

We rewrite system~(\ref{system_multiscale_all}-\ref{system_multiscale_bc}), using the two new quantities $\mathcal{C}$ and $\mathcal{Q}$, obtaining
\begin{subequations}
\label{eq_CQP_system}
\begin{align}
\label{eq_CQP_system_C}
    \frac{\partial \mathcal C}{\partial t} & = \widetilde D \Delta \mathcal C + \varepsilon \widehat D \Delta \mathcal Q + \nabla \cdot \left(\left(\widehat D \mathcal C + \varepsilon\widetilde D  \mathcal Q \right)\nabla \Phi \right), \qquad {\rm in } \, \Omega \\ \label{eq_CQP_system_Q}
  \frac{\partial \mathcal Q}{\partial t} & =  \frac{\widehat D}{\varepsilon} \Delta \mathcal C + \widetilde D \Delta \mathcal Q+ \nabla \cdot \left(\left( \frac{\widetilde D}{\varepsilon} \mathcal C + \widehat D \mathcal Q \right)\nabla \Phi \right), \qquad {\rm in } \, \Omega \\ \label{eq_CQP_system_Phi}
   -\Delta \Phi & = \mathcal Q, \qquad {\rm in } \, \Omega
   \end{align}
\end{subequations}
with boundary conditions
\begin{subequations}
\label{eq_CQP_system_bc}
 \begin{align}
  \label{eq_CQP_system_bc_C}
 \frac{M}{2} \frac{\partial \mathcal C}{\partial t} - \varepsilon \frac{M}{2} \frac{\partial  \mathcal Q}{\partial t} & = \widetilde D \frac{\partial \mathcal C}{\partial n} + \varepsilon \widehat D \frac{\partial \mathcal Q}{\partial n}  + \left(\widehat D \mathcal C+ \varepsilon \widetilde D \mathcal Q \right) \frac{\partial \Phi}{\partial n}, \qquad {\rm on } \, \Gamma_\mathcal{B} \\
      -\frac{M}{2\varepsilon} \frac{\partial \mathcal C}{\partial t} +  \frac{M}{2} \frac{\partial  \mathcal Q}{\partial t} & = \frac{\widehat D}{\varepsilon} \frac{\partial \mathcal C}{\partial n} + \widetilde D \frac{\partial \mathcal Q}{\partial n}  + \left(\frac{\widetilde D}{\varepsilon} \mathcal C+  \widehat D \mathcal Q \right) \frac{\partial \Phi}{\partial n}, \qquad {\rm on } \, \Gamma_\mathcal{B} \\ 
      \frac{\partial \Phi}{\partial n} & = \frac{M}{2\varepsilon}\mathcal C - \frac{M}{2}\mathcal Q, \qquad {\rm on } \, \Gamma_\mathcal{B}\\ 
   0 & = \widetilde D \frac{\partial \mathcal C}{\partial n} + \varepsilon \widehat D \frac{\partial \mathcal Q}{\partial n} , \qquad {\rm on } \, \Gamma_S \\  
    0 & = \frac{\widehat D}{\varepsilon} \frac{\partial \mathcal C}{\partial n} +  \widetilde D \frac{\partial \mathcal Q}{\partial n}, \qquad {\rm on } \, \Gamma_S \\
\frac{\partial \Phi}{\partial n} & = 0 , \qquad {\rm on } \, \Gamma_S  
\end{align}
\end{subequations}
where $\widetilde D = \left({D_+ + D_-}\right)/{2}, \widehat D = \left({D_+ - D_-}\right)/{2}.$ 

As $\varepsilon \to 0,$ we obtain the Quasi-Neutral limit model
\begin{subequations}
\label{eq:QNL}
\begin{align}
\label{eq_CQP_system_lim}
    \frac{\partial \mathcal C^0}{\partial t} & = \frac{\widetilde D^{\, 2} - \widehat D^{\, 2}}{\widetilde D} \Delta \mathcal C^0 \qquad {\rm in } \, \Omega \\
  0 & = \widehat D  \Delta \mathcal C^0 + \widetilde D \nabla \cdot \left( \mathcal C^0 \nabla \Phi^0 \right) \qquad {\rm in } \, \Omega \\
   -\Delta \Phi^0 & = \mathcal Q^0 \qquad {\rm in } \, \Omega 
\end{align}
\end{subequations}
with boundary conditions
\begin{subequations}
\label{eq:QNL_bc}
\begin{align}
   \frac{M}{2} \frac{\partial \mathcal C}{\partial t}  & = \widetilde D \frac{\partial \mathcal C}{\partial n}  + \widehat D \mathcal C\frac{\partial \Phi}{\partial n} \qquad {\rm on } \, \Gamma_\mathcal{B} \\
      -\frac{M}{2} \frac{\partial \mathcal C}{\partial t}  & = \widehat D \frac{\partial \mathcal C}{\partial n}  + \widetilde D \mathcal C \frac{\partial \Phi}{\partial n} \qquad {\rm on } \, \Gamma_\mathcal{B} \\ 
      \frac{\partial \Phi}{\partial n} & = \frac{M}{2\varepsilon}\mathcal C - \frac{M}{2}\mathcal Q \qquad {\rm on } \, \Gamma_\mathcal{B}\\ 
    \frac{\partial \mathcal C}{\partial n} & = 0  \qquad {\rm on } \, \Gamma_S \\  
 %   0 & = \widehat D \frac{\partial \mathcal C}{\partial n}, \qquad {\rm on } \, \Gamma_S \\
\frac{\partial \Phi}{\partial n} & = 0 \qquad {\rm on } \, \Gamma_S    \label{eq_CQP_system_lim_bc}
\end{align}
\end{subequations}
