\section{Two-dimensional space discretization and Asymptotic Preserving numerical scheme as $\protect \varepsilon \to 0$}
\label{sec_2D}
In this section, we describe the space and time discretization for the model~(\ref{eq_CQP_system}-\ref{eq_CQP_system_bc}). For the space discretization, we follow the strategy in \cite{astuto2024nodal}, a recently developed ghost-FEM method. The same space discretization has been extended to the numerical solution of biological network formation in a leaf-shaped domain in  \cite{astuto2024self}. Regarding the time discretization, we consider a second order Asymptotic Preserving numerical scheme
\cite[Section 1.3]{boscarino2024implicit}, \cite{jin1999efficient}.

\subsection{Variational formulation}
Here we consider the variational formulation of the system (\ref{eq_CQP_system}-\ref{eq_CQP_system_bc}). We introduce the two spaces $V$ and $W$ defined as
\begin{equation}
\label{eq:FEMspaces}
    V = \biggl\{ v\in H^1(\Omega) \biggr\}, \qquad W = \biggl\{ w\in H^1(\Omega) : \int_\Omega w\,{ \rm d}\Omega = 0\biggr\}.
\end{equation}
When imposing homogeneous Neumann boundary conditions in the Poisson equation, the potential
$\Phi$ is determined up to an additive constant, leading to a lack of uniqueness. To address this issue, in Eq.~\eqref{eq:FEMspaces} we impose an additional constraint in the space $W$, namely, that $\Phi$ has zero mean. 

Multiplying \eqref{eq_CQP_system_C} by a test function $v \in V$, and integrating over $\Omega$, we obtain
\begin{subequations}
\begin{align}
&\int_\Omega \frac{\partial \mathcal{C}}{\partial t} v\,{ \rm d}\Omega = 
\widetilde D \int_\Gamma \left(\nabla \mathcal C \cdot n \right) v \, { \rm d}\Gamma 
- \widetilde D \int_\Omega \nabla \mathcal{C} \cdot \nabla v \, { \rm d}\Omega 
+ \varepsilon \widehat D \int_\Gamma \left(\nabla \mathcal Q \cdot n \right)v  \, { \rm d}\Gamma 
- \varepsilon \widehat D \int_\Omega \nabla \mathcal Q \cdot \nabla v \, { \rm d}\Omega \\ & + \int_\Gamma \left( \left(  \widehat D \mathcal C  + \varepsilon \widetilde D \mathcal Q  \right)  \nabla \Phi \cdot n \right)  v \, { \rm d}\Gamma 
- \int_\Omega \left( \widehat D \mathcal C + \varepsilon \widetilde D \mathcal Q \right) \nabla \Phi \cdot \nabla v \, { \rm d}\Omega
%\\ &-\int_\Omega {\rm div} \left( (\mathcal{C}+r\mathbb{I}) \nabla p \right)\, q\,{ \rm d}x  = \int_\Omega S\, q\,{ \rm d}x && \forall q\in Q 
\end{align}
\end{subequations}
Taking into account the boundary condition in Eq.~\eqref{eq_CQP_system_bc_C}, we have
\begin{subequations}
\begin{align} \nonumber
&\int_\Omega \frac{\partial \mathcal{C}}{\partial t} v\,{ \rm d}\Omega = 
- \widetilde D \int_\Omega \nabla \mathcal{C} \cdot \nabla v \, { \rm d}\Omega  
- \varepsilon \widehat D \int_\Omega \nabla \mathcal Q \cdot \nabla v \, { \rm d}\Omega  
- \int_\Omega \left( \widehat D \mathcal C + \varepsilon \widetilde D \mathcal Q \right) \nabla \Phi \cdot \nabla v \, { \rm d}\Omega  \\ & 
+ \int_{\Gamma_\mathcal{B}} \left( \frac{M}{2} \frac{\partial \mathcal C}{\partial t} - \varepsilon \frac{M}{2} \frac{\partial \mathcal Q}{\partial t}\right)  v \, { \rm d}\Gamma
\end{align}
\end{subequations}
We adopt the same procedure on Eqs.~(\ref{eq_CQP_system_Q}-\ref{eq_CQP_system_Phi}), thus obtaining the variational formulation of our problem. 

\begin{pro}\label{pro:variational}
Find $\mathcal C(t), \mathcal Q(t) \in V$ and $\Phi(t) \in W$ for almost every $t\in(0,T)$, such that
\begin{subequations}
\label{eq_var_formulation}
\begin{align} 
&\left( \frac{\partial \mathcal{C}}{\partial t}, v\right)  = - \widetilde D \left( \nabla \mathcal{C},\nabla v \right)   - \varepsilon \widehat D \left( \nabla \mathcal Q, \nabla v \right)  - \left(\left( \widehat D \mathcal C + \varepsilon \widetilde D \mathcal Q \right) \nabla \Phi,\nabla v \right)   + \left( \frac{M}{2} \frac{\partial \mathcal C}{\partial t} - \varepsilon \frac{M}{2} \frac{\partial \mathcal Q}{\partial t}, v \right)_{L^2(\Gamma_\mathcal{B})}  \\ 
&\left( \frac{\partial \mathcal{Q}}{\partial t}, q \right)  = - \frac{\widehat D}{\varepsilon} \left( \nabla \mathcal{C},\nabla q  \right)   -  \widetilde D \left( \nabla \mathcal Q, \nabla q  \right)  - \left(\left( \frac{\widetilde D}{\varepsilon} \mathcal C +  \widehat D \mathcal Q \right) \nabla \Phi,\nabla q  \right)  + \left( -\frac{M}{2\varepsilon} \frac{\partial \mathcal C}{\partial t} + \frac{M}{2} \frac{\partial \mathcal Q}{\partial t}, q \right)_{L^2(\Gamma_\mathcal{B})} \\
&\left( \nabla \Phi,\nabla w\right)  + \left( \frac{M}{2\varepsilon}\mathcal C - \frac{M}{2}\mathcal Q, w\right)_{L^2(\Gamma_\mathcal{B})} = \left(\mathcal{Q},w\right) 
\end{align}
\end{subequations}
\end{pro}
where we denoted by $(\cdot,\cdot)$ the scalar product in $L^2(\Omega)$.
%to simplify and reduce the notation complexity. Consequently, our problem, when expressed in its variational formulation, is as follows.


\subsection{Space discretization in two dimensions}
\label{sec:space_discretization_2D}
In this section, we adopt a two-dimensional space discretization based on finite elements method \cite{astuto2024nodal,astuto2024comparison}. For the sake of completeness, we provide the relevant details of the spatial discretization.

The domain is $\Omega = [0,1]^2\setminus \mathcal{B} \subset R$, with $\mathcal{B}$ a circle centered in $(x_c,y_c)$ and radius $R_{\mathcal{B}}$, and $R$ a rectangular region. The set of grid points will be denoted by $\mathcal N$, with $\# \mathcal N = (1+N)^2$, the active nodes (i.e.,\ internal $\mathcal{I}$ or ghost $\mathcal{G}$) by $\mathcal A = \mathcal{I}\cup\mathcal{G} \subset \mathcal N$, the set of inactive points by $\mathcal O \subset \mathcal N$, with $\mathcal O\cup\mathcal A = \mathcal N$ and $\mathcal O \cap \mathcal A = \emptyset$ and the set of cells by $\mathcal C$, with $\# \mathcal C = N^2$. Finally, we denote by $\Omega_c = R\setminus \Omega$ the outer region in $R$.



Following the approach shown in  \cite{Osher2002,Russo2000,book:72748, Sussman1994}, the domain $\Omega$ is implicitly defined by a level set function $\phi(x,y)$ that is negative inside $\Omega$, positive in $R\setminus \Omega$ and zero on the boundary $\Gamma$:
\begin{equation}
	\Omega = \{(x,y): \phi(x,y) < 0\}, \qquad
	\Gamma_\mathcal{B} = \{(x,y): \phi(x,y) = 0\}.
\end{equation}
