Let us consider a general integrable function $f(x,y)$ defined in $\Omega$, with $F(x,y) = \int f(x,y) dx$ (in our strategy we consider the primitive in $x$ direction; analogue results can be obtained integrating in $y$ direction). We now define a vector function $\textbf{F}= (F,0)^\top$ which has the property \(\nabla \cdot \textbf{F} = f\).
Thus, we have
\begin{align}
\label{eq_diverg}
    \int_K fdx\, dy = \int_K \nabla \cdot  \textbf{F} \,dx\, dy = \int_{\partial K} \textbf{F}\cdot \textbf{n}\, dl,
\end{align}
where we applied Gauss theorem, and $\textbf{n} = (n_x,n_y)$ is the outer normal vector to $K$.
If $\mathcal{P}$ is the generic polygon with $m$ edges $l_r, \, r = 0,\ldots,m-1$ (see Fig.~\ref{fig:ref_cell}) 
 we can express \eqref{eq_diverg} as
\begin{align}
\label{eq_gauss_interval}
   \int_\mathcal{P} \nabla \cdot  \textbf{F}\, dx\, dy = \int_{\partial \mathcal{P}} \textbf{F}\cdot \textbf{n}\, d l = \sum_{r=0}^{m-1} \int_{l_r} \textbf{F}\cdot \textbf{n}\, dl = \sum_{r=0}^{m-1} \int_{l_r}  F {n}_x\, dl = \sum_{r=0}^{m-1} \int_{l_r}  F dy. 
\end{align}
To evaluate the integral over the generic edge $l_r$, we  choose the three-point Gauss-Legendre quadrature rule, which is exact for polynomials in $\mathbb P_5(\mathbb R)$. Thus, we write
\begin{equation}
     \int_{l_r}  F dy = \sum_{s = 1}^3w_sF(\widehat x_{r,s},\widehat y_{r,s}) (y_{P_{r+1}}-y_{P_r})
\end{equation}
where $w_s$ % \in \{5/18,4/9,5/18\}$,
and $\widehat x_{r,s}, \, s = 1,2,3$ are the weights and the nodes, respectively, of the considered quadrature rule, see Fig.~\ref{fig:ref_cell} (b).
% If we denote by $l$ the generic edge of $\Gamma^h$, we can consider a change of variable from $l \to [0,1]$, s.t.   
% \begin{equation}
%     (\phi,\phi)_l = \left(\widetilde \phi,\widetilde \phi\right)_{[0,1]}|l| = \left( \sum_{j=1}^3 w_j\phi(\widetilde x_j)\phi(\widetilde x_j)\right) |l|,\quad \widetilde x_j\in [0,1],
% \end{equation}
% \begin{figure}
%     \centering
%    \includegraphics[width=0.4\textwidth]{ABCRZ/Figures/quadrature_cells.pdf}
%     \caption{\textit{Scheme of the three quadrature points (circles) for each edge $l_i, \, i = 0,\cdots,4$. The squared points represent the vertices $P_i,\, i = 0,\cdots,4,$ of the polygon $\mathcal P$.}}
%     \label{fig:quadr_cells}
% \end{figure}
Choosing $f=v_{k_\eta}v_{k_\mu}\in \mathbb{Q}_2(K)\subset \mathbb P_4(K)$, and making use of \eqref{eq_gauss_interval}, we write
\begin{equation}
     \left( \left.v_i\right|_K , \left.v_j\right|_K \right) = \sum_{r=0}^{m-1} \left(\sum_{s=1}^3 w_s\Phi_{ij}(\widehat x_{r,s},\widehat y_{r,s}) (y_{P_{r+1}}-y_{P_r})\right)|l_r|.
\end{equation}
where $v_{ij} = \int v_i v_j\, dx$, and the formula is exact because $v_{ij} \in \mathbb P_5(K), \, \forall i,j \in \mathcal N$.

When evaluating the integrals described above, we observe stability issues arising from the presence of cut cells near the boundary $\Gamma_\mathcal{B}$. The problem derives from the inability to control the size of the cut cells, which can become arbitrarily small. Consequently, this can lead to a loss of coercivity in the bilinear form. 
In Fig.~\ref{fig:snapping} (a), we see a case in which the stability of the numerical scheme fails, and in panel (b), we present an approach to address this issue. In other words, to avoid instability, 
we evaluate the level set function $\phi$ at the vertices of each cell: if the value is {smaller than a threshold} (that we choose proportional to a power of the length of the cell, i.e.,
{if $0<-\phi<\zeta h^\alpha$, for suitable chosen $\zeta$ and $\alpha$}) we disregard the respective cell {by setting the level set function equal to a small positive value, as illustrated in Algorithm~\ref{alg_snap}; see also \cite{astuto2024nodal,astuto2024comparison}. In our numerical results it corresponds to the machine epsilon.} Alternative techniques are employed to address the ill-conditioning caused by the presence of small cells; see, for instance,
\cite{burman2015cutfem,lehrenfeld2016high,ahlkrona2021cut}.


\begin{algorithm}[H]
\caption{Snapping back to grid}\label{alg_snap}
\begin{algorithmic}
\For{$k \in \mathcal N$} 
\If{$\phi(k)<0 \quad \& \quad |\phi(k)|<
\zeta h^\alpha$} 
   \State $\phi(k) := \texttt{eps} $ 
\EndIf 
\EndFor
\end{algorithmic}
\end{algorithm}



\subsection{Asymptotic Preserving time discretization in two dimensions}
\label{sec:time_discretization_2D}
The concept of an Asymptotic-Preserving (AP) method has been introduced in \cite{jin1999efficient}. We consider a problem $\mathcal{P}^\varepsilon$ that depends on a (small) parameter $\varepsilon$. As the parameter vanishes, the problem becomes the limit problem  $\mathcal{P}^0$. Examples from the literature include compressible Euler equations that relax to the incompressible Euler system as the Mach number vanishes \cite{degond2009asymptotic,filbet2010class}, or the Boltzmann equation of rarefied gas dynamics, which relaxes to the compressible Euler equations as the Knudsen number vanishes \cite{filbet2011asymptotic}. We now consider a discretized version of the problem, which we denote by $\mathcal{P}^\varepsilon_h$, where $h$ stands for the discretization parameter. As $h\to 0$, the discrete problem converges to the continuous one. Typically, one solves the discrete problem to get an approximation of the continuous problem. In order to capture the limit for vanishingly small values of $\varepsilon$ one should solve problems with smaller and smaller $\varepsilon$, using a discretization parameter $h$ which resolves the small $\varepsilon$ scale. Such an approach may be very expensive. Conversely, an AP scheme becomes a consistent discretization of the limit problem $\mathcal{P}^0$ as $\varepsilon\to 0$, with no order relation between $h$ and $\varepsilon$.  The commutative diagram below shows the main property of AP schemes, defined as follows. A numerical scheme $\mathcal P^\varepsilon_h$ for problem $\mathcal{P}^\varepsilon$ with discretization parameter $h$ is called AP if it becomes a consistent discretization of the limit problem $\mathcal{P}^0$ as $\varepsilon\to 0$.  

\begin{figure}[H]
{\Large \[
  \begin{matrix}
\mathcal P_h^\varepsilon & {\longrightarrow} & \mathcal P^\varepsilon\\
\downarrow &  &  \downarrow\\
\mathcal P^0_h & \longrightarrow & \mathcal P^0 \\
\end{matrix}
\]
}

\caption{The AP diagram. $\mathcal P^\varepsilon$ is the original problem and $\mathcal P^\varepsilon_h$ its numerical approximation characterized by a discretization parameter $h$. The AP property corresponds to the request that $\mathcal P^0_h$ is consistent with $\mathcal{P}^0$ as $\varepsilon \to 0$, independently of $h$.}
\end{figure}
To reformulate system \eqref{eq_varform} using the computational matrices for the spatial derivatives, we express it as follows
\begin{subequations}
\label{eq:FEM_semidiscr}
\begin{align}
& \mathbb B[v_h]\frac{\partial \mathcal{C}_h}{\partial t} - \left( \frac{M}{2} \frac{\partial \mathcal C_h}{\partial t} - \varepsilon \frac{M}{2} \frac{\partial \mathcal Q_h}{\partial t}, v_h  \right)_{L^2\left(\Gamma_{\mathcal{B},h}\right)} = - \widetilde D \, \mathbb L[v_h] \, \mathcal{C}_h  - \varepsilon \widehat D\, \mathbb L[v_h]\, \mathcal Q_h - \mathbb H\left[ \widehat D \mathcal C_h + \varepsilon \widetilde D \mathcal Q_h,v_h \right]  \Phi_h  \\ 
&\varepsilon \mathbb B[q_h] \frac{\partial \mathcal{Q}_h}{\partial t} - \left( -\frac{M}{2} \frac{\partial \mathcal C_h}{\partial t} + \varepsilon\frac{M}{2} \frac{\partial \mathcal Q_h}{\partial t}, q_h  \right)_{L^2\left(\Gamma_{\mathcal{B},h}\right)} = - {\widehat D}\, \mathbb L[q_h]\, \,\mathcal{C}_h  -  \varepsilon \widetilde D \,\mathbb L[q_h]\, \, Q_h - \mathbb H \left[ {\widetilde D}\mathcal C_h + \varepsilon \widehat D \mathcal Q_h,q_h \right]  \Phi_h \\
& \mathbb L[w_h]\, \Phi_h +  \left( \frac{M}{2\varepsilon}\mathcal C_h - \frac{M}{2}\mathcal Q_h, w_h\right)_{L^2\left(\Gamma_{\mathcal{B},h}\right)} = \mathbb B[w_h] \, \mathcal{Q}_h 
\end{align}
\end{subequations}
where $\mathbb L[v_h] $ is the discrete operator that defines the stiffness matrix $\left( \nabla \bullet,\nabla v_h \right)_{L^2\left(\Omega_h\right)}$, such that $ \mathbb L[v_h] \, \mathcal C_h = \left( \nabla \mathbb \mathcal C_h,\nabla v_h\right)_{L^2\left(\Omega_h\right)}$; $ \mathbb H[\mathcal{C}_h,v_h]$ is the operator such that $\mathbb H \left[ \mathcal C_h,v_h \right]  \Phi_h = \left(  \mathcal C_h \nabla \Phi_h,\nabla v_h  \right)_{L^2\left(\Omega_h\right)}$; finally, we define the discrete operator $\mathbb B[v_h]$ for the mass matrix, such that $\mathbb B[v_h] \, \mathcal C_h = \left(\mathcal C_h,v_h\right)_{L^2\left(\Omega_h\right)}$. 


Here we perform the limit for  $\varepsilon \to 0$ in \eqref{eq:FEM_semidiscr}, that becomes
\begin{subequations}
\begin{align}
  \mathbb B[v_h]\frac{\partial \mathcal{C}^0_h}{\partial t} - \left( \frac{M}{2} \frac{\partial \mathcal C_h}{\partial t}, v_h  \right)_{L^2(\Gamma_{\mathcal{B},h})} & = - \widetilde D \, \mathbb L[v_h] \, \mathcal{C}^0_h  -  \mathbb H\left[ \widehat D \mathcal C^0_h,v_h \right]  \Phi^0_h  \\ 
 \left( \frac{M}{2} \frac{\partial \mathcal C_h}{\partial t} , q_h  \right)_{L^2(\Gamma_{\mathcal{B},h})} & = - {\widehat D} \mathbb L[q_h] \,\mathcal{C}^0_h - \mathbb H \left[ {\widetilde D} \mathcal C^0_h,q_h \right]  \Phi^0_h \\
 \mathbb L[w_h] \, \Phi^0_h & = \mathbb B[w_h] \, \mathcal{Q}^0_h.
\end{align}
\end{subequations}
After some algebra, we have
\begin{subequations}
\label{sys_qnl_discr}
\begin{align}
  \mathbb B[v_h]\frac{\partial \mathcal{C}^0_h}{\partial t} - \left( \frac{M}{2} \frac{\partial \mathcal C_h}{\partial t}, v_h  \right)_{L^2(\Gamma_{\mathcal{B},h})} & = -\frac{\widetilde D^{\, 2} - \widehat D^{\, 2}}{\widetilde D} \, \mathbb L[v_h] \, \mathcal{C}^0_h  \\ 
\left( \frac{M}{2} \frac{\partial \mathcal C_h}{\partial t} , q_h  \right)_{L^2(\Gamma_{\mathcal{B},h})}  & = -\widehat D\, \mathbb L[q_h] \, \mathcal C^0_h - \widetilde D \mathbb H \left[\mathcal C^0_h,q_h\right]\Phi^0_h \\
\mathbb L[w_h]\, \Phi^0_h & = \mathbb B[w_h]\, \mathcal{Q}^0_h
\end{align}
\end{subequations}
that is the numerical scheme for Eqs.~(\ref{eq:QNL}-\ref{eq:QNL_bc}).

Now we consider a time discretization for systems \eqref{eq:FEM_semidiscr}. We consider a final time $T$ and define the time step as $\Delta t = T/N_{\rm ts},\, N_{\rm ts} \in \mathbb N,$ denoting the nodes in time by $t^n = n\Delta t$ and $\mathcal{C}_h^n \approx \mathcal{C}_h(t^n), \, n = 0,\cdots,N_{\rm ts}$. A semi--implicit discretization is adopted to achieve second order of accuracy in time. In particular, we make use of implicit-explicit (IMEX) Runge--Kutta schemes \cite{pareschi2000implicit,boscarino2016high,astuto2023self}, which are multi-step methods based on $s$-stages. 

We rewrite Eqs.~\eqref{eq:FEM_semidiscr}  in a vectorial form
\begin{equation}
\label{eq:vectorial}
 \BB\td{\bf Q}{t} =\Theta [{\bf Q}] {\bf Q}
\end{equation}
where 
\begin{equation}
 \BB  = \begin{pmatrix}
 \mathbb B[v_h] & \underbar 0 & \underbar 0 \, \\
\underbar 0 & \varepsilon \mathbb B[q_h] &  \underbar 0 \,\\
\underbar 0 & \underbar 0 & \underbar 0 \, \\
\end{pmatrix} ,\qquad \Theta[{\bf Q}] = \begin{pmatrix}
- \widetilde D \mathbb L[v_h] & - \varepsilon \widehat D \mathbb L[v_h] & - \mathbb H\left[\widehat D \mathcal C_h + \widetilde D \varepsilon \mathcal Q_h,v_h\right]\\
- {\widehat D} \mathbb L[q_h] & - \varepsilon\widetilde D \mathbb L[q_h] &  - \mathbb H\left[{\widetilde D} \mathcal C_h + \widehat D \varepsilon \mathcal Q_h,q_h\right]\\
\underbar 0 & - \mathbb B[w_h] & \mathbb L[w_h] \\
\end{pmatrix} 
\end{equation}
and ${\bf Q} = [\mathcal C_h,\mathcal Q_h,\Phi_h]^\top$. 

To apply the IMEX method to \eqref{eq:vectorial}, we follow the strategy and the Butcher tableau seen in Section~\ref{sec:time_discretization_1D}. Let us first set $\textbf{Q}^1_E = \textbf{Q}^n$, then the stage fluxes are calculated as
\begin{subequations}  
\label{eq_imex}
\begin{align}
\label{eq_imex_QE}
    \BB  \textbf{Q}_E^{i}& =  \BB \textbf{Q}^n + \Delta t\,\sum_{j=1}^{ i-1}\widetilde a_{i,j}\Theta(\textbf{Q}_E^j)\textbf{Q}_I^j, \quad i = 1,\cdots,s \\
\label{eq_imex_QI}
     \BB \textbf{Q}_I^{i} &=  \BB  \textbf{Q}^n + \Delta t\,\sum_{j=1}^{ i}  a_{i,j}\Theta(\textbf{Q}_E^j)\textbf{Q}_I^j, \quad i = 1,\cdots,s 
\end{align}
\end{subequations}
and the numerical solution is finally updated with
\begin{align}
\label{eq_imex_Q_bi}
    \BB  \textbf{Q}^{n+1} &=  \BB  \textbf{Q}^n + \Delta t\sum_{i=1}^{\rm s}  b(i) \Theta(\textbf{Q}_E^i)\textbf{Q}_I^i.
\end{align}
The Butcher tableau that we employ is the one defined in Eq.~\eqref{b_tableau}.
