%    B {\bf Q}_I^1 &= B \begin{pmatrix}
%        \mathcal C^n \\ \mathcal Q^n \\ \underbar 0
%    \end{pmatrix}  + \Delta t\, \widehat a_{i,1} \begin{pmatrix}
% \widetilde D \mathbb L & \varepsilon \widehat D \mathbb L & \mathbb H\left(\widehat D \mathcal C_E^i + \widetilde D \varepsilon \mathcal Q_E^i\right)\\
% \frac{\widehat D}{\varepsilon} \mathbb L & \widetilde D \mathbb L &  \mathbb H\left(\frac{\widetilde D}{\varepsilon} \mathcal C_E^i + \widetilde D \varepsilon \mathcal Q_E^i\right)\\
% \underbar 0 & \mathbb I & -\varepsilon\mathbb L\, \\
% \end{pmatrix} {\bf Q}_I^1
% \end{align}
% while, for $i \geq 2$
% \begin{align}
%    {\bf Q}_{E}^{i}& = {\bf Q}_E^1 + \Delta t\,\sum_{j=1}^{\rm i-1}\widetilde a_{i,j} \left(\widetilde D \mathbb L  \mathcal C_{I}^j + \varepsilon \widehat D  \mathbb L  \mathcal Q_{I}^j + \mathbb H({\bf  Q}_E^i)\Phi_I^j\right), \quad i = 1,\cdots,s \\
%   \textbf{Q}_I^{i} &= {\bf Q}_E^1  + \Delta t\,\sum_{j=1}^{\rm i} \widehat a_{i,j}\left(\frac{\widehat D}{\varepsilon}\mathbb L  \mathcal C_{I}^j + \widetilde D\mathbb L  \mathcal Q_{I}^j + \mathbb H({\bf  Q}_E^i)\Phi_I^j\right), \quad i = 1,\cdots,s, 
% \end{align}



Here we prove that the numerical scheme (\ref{eq_imex}--\ref{eq_imex_Q_bi}) that we design for the system (\ref{eq_CQP_system}-\ref{eq_CQP_system_bc}), it is also a numerical scheme for the limit model in (\ref{eq:QNL}-\ref{eq:QNL_bc}). Let us look at the first steps:
\begin{align*}
    \mathcal{C}_E^1 &= \mathcal C^n \\
    \mathcal{Q}_E^1 &= \mathcal Q^n \\
    \mathbb B[v_h] \, \mathcal{C}_I^1 &= \mathbb B[v_h] \, \mathcal{C}_E^1 - a_{11}\Delta t \left(  \widetilde D \mathbb L[v_h]\, \mathcal C_I^1 +  \varepsilon \widehat D \mathbb L[v_h]\, \mathcal Q_I^1 + \mathbb H \left[\widehat D \mathcal C_E^1 + \widetilde D \varepsilon \mathcal Q_E^1,v_h\right]\Phi_I^1  \right) \\
  \varepsilon \mathbb B[q_h] \, \mathcal{Q}_I^1 &= \varepsilon \mathbb B[q_h] \, \mathcal{Q}_E^1 - a_{11}\Delta t \left(  {\widehat D} \mathbb L[q_h]\, \mathcal C_I^1 + \varepsilon \widetilde D \mathbb L[q_h]\, \mathcal Q_I^1 + \mathbb H \left[\widetilde D  \mathcal C_E^1 + \varepsilon \widehat D \mathcal Q_E^1,q_h\right]\Phi_I^1 \right)  \\
    0 &= \mathbb B[w_h] \, \mathcal Q^1_I - \mathbb L[w_h]\, \Phi_I^1
\end{align*}
and perform the limit $\varepsilon \to 0$. Thus it becomes
\begin{align*}
    \mathcal{C}_E^1 &= \mathcal C^n \\
    \mathcal{Q}_E^1 &= \mathcal Q^n \\
    \mathbb B[v_h] \, \mathcal{C}_I^1 &= \mathbb B[v_h] \, \mathcal{C}_E^1 - a_{11}\Delta t \left( \widetilde D \mathbb L[v_h]\, \mathcal C_I^1 + \widehat D \mathbb H \left[ \mathcal C_E^1,v_h \right]\Phi_I^1 \right) \\
    0 &= \widehat D  \mathbb L[q_h]\, \mathcal C_I^1  + \widetilde D \mathbb H \left[\mathcal C_E^1,q_h \right]\Phi_I^1 \\
    0 &= \mathbb B[w_h] \, \mathcal Q_I^1 - \mathbb L[w_h]\, \Phi_I^1
\end{align*}
that can be rewritten as
\begin{align*}
    \mathcal{C}_E^1 &= \mathcal C^n \\
    \mathcal{Q}_E^1 &= \mathcal Q^n \\
    \mathbb B[v_h] \, \mathcal{C}_I^1 &= \mathbb B[v_h] \, \mathcal{C}_E^1 - a_{11}\Delta t \frac{\widetilde D^{\, 2} - \widehat D^{\, 2}}{\widetilde D} \mathbb L[v_h]\, \mathcal C_I^1  \\
    0 &= \widehat D  \mathbb L[q_h]\, \mathcal C_I^1  + \widetilde D \mathbb H \left[\mathcal C_E^1,q_h \right]\Phi_I^1 \\
    0 &= \mathbb B[w_h] \, \mathcal Q_I^1 - \mathbb L[w_h]\, \Phi_I^1.
\end{align*}

Analogously, we proceed a with the second step and obtain 
\begin{align*}
    % \mathcal{C}_E^1 &= \mathcal C^n \\
    % \mathcal{Q}_E^1 &= \mathcal Q^n \\
    % \mathbb B \, \mathcal{C}_I^1 &= \mathbb B \, \mathcal{C}_E^1 -a_{11}\Delta t \frac{\widetilde D^{\, 2} - \widehat D^{\, 2}}{\widetilde D} \mathbb L\, \mathcal C_I^1  \\
    % 0 &= \widehat D  \mathbb L\, \mathcal C_I^1  + \widetilde D \mathbb H(\mathcal C_E^1 )\Phi_I^1 \\
    % 0 &= \mathbb B \, \mathcal Q_I^1 - \mathbb L\, \Phi_I^1\\
   \mathbb B[v_h] \, \mathcal{C}_E^2 &= \mathbb B[v_h] \, \mathcal{C}_E^1 - \widetilde a_{21}\Delta t \frac{\widetilde D^{\, 2} - \widehat D^{\, 2}}{\widetilde D} \mathbb L[v_h]\, \mathcal C_I^1 \\
    \mathbb B[v_h]\, \mathcal{C}_I^2 &= \mathbb B[v_h] \, \mathcal{C}_E^1 - a_{21}\Delta t \frac{\widetilde D^{\, 2} - \widehat D^{\, 2}}{\widetilde D} \mathbb L[v_h]\, \mathcal C_I^1 - a_{22}\Delta t \frac{\widetilde D^{\, 2} - \widehat D^{\, 2}}{\widetilde D} \mathbb L[v_h]\, \mathcal C_I^2  \\
    0 &= \widehat D  \mathbb L[q_h]\, \mathcal C_I^2  + \widetilde D \mathbb H \left[\mathcal C_E^2,q_h \right]\Phi_I^2 \\
    0 &= \mathbb B[w_h] \, \mathcal Q_I^2 - \mathbb L[w_h]\, \Phi_I^2.
\end{align*}
that is the second order IMEX scheme applied to the limit model in (\ref{eq:QNL}-\ref{eq:QNL_bc}).


