\subparagraph{Almost-universality of $U$.}
We now prove the following.

\begin{theorem}
The graph $U$ is $(\kappa, \STI)$-almost-universal.
\end{theorem}

We prove the two conditions for almost-universality in two separate lemmas.

\begin{lemma}\label{lem:satisfyW}
	The graph $U$ satisfies $\STI$.
\end{lemma}
\begin{proof}
	Take an infinite path $u^0 \re{w_0} u^1 \re{w_1} \dots $ in $U$.
	For all $i$, let
	\[
	b_i = \begin{cases}
		0 &\tif |u^i|+ w_i= |u^{i+1}|, \\
		1 &\tow.
	\end{cases}
	\]
	For each $i$, we have $|u^i|+w_i \geq |u^{i+1}|+b_i$.
	Therefore, for all $k$,
	\[
	\sum_{i=0}^{k-1}w_i \geq |u^{k}| - |u^{0}| + \sum_{i=0}^{k-1} b_i \geq \sum_{i=0}^{k-1} b_i - |u^{0}|.
	\]
	If $\sum_{i=0}^{k-1} b_i$ goes to $+\infty$, then by the above it also holds that $\sum_{i=0}^{k-1} w_i \to +\infty$, as wanted.
	So we assume otherwise: there is $i_0$ such that for $i \geq i_0$, $b_i=0$.
	Then, for all $i \geq i_0$, we have $|u^{i}| + w_i = |u^{i+1}|$ and thus $u^i >_\lex u^{i+1}$; this contradicts the well-foundedness of~$<_\lex$.
\end{proof}


\begin{lemma}\label{lem:embedSmallGraphs}
    For all trees $T<\kappa$ satisfying $\STI$, there exists a vertex $v_0$ of $T$ such that $T[v_0] \to U$.
\end{lemma}


\begin{proof}
Let $T<\kappa$ be a tree satisfying $\STI$.
Given a finite path $\pi$, we let $w(\pi)$ denote the sum of the weights appearing on $\pi$.
For all $v \in T$, define
\[
    n(v) = - \inf \{w(\pi) \mid \pi \text{ is a non-empty finite path from } v\} \in \Z \cup \{+\infty\}.
\]
We note that for all edges $v \re w v'$, it holds that $n(v) + w \geq n(v')$.

\begin{claim} \label{claim:v0}
There exists a vertex $v_0$ such that $n(v_0) <0$.
\end{claim}
\begin{claimproof}
Assume towards a contradiction that for all vertices $v$, $n(v) \ge0$.
In other words, from all vertices, there is a non-empty path of weight~$\le 0$.
By concatenating such paths, we get a path whose weight does not converge to $+\infty$, which contradicts the fact that $T$ satisfies $\STI$.
\end{claimproof}

Using the above claim, let $v_0$ be a vertex such that $n(v_0)<0$.
We will construct a mapping $\phi\colon T[v_0] \to U$.
The following claim will be useful for the definition of this morphism.
We say that an edge $v \re w v'$ of $T$ is \emph{tight} if $n(v) + w = n(v')$, and that a (finite or infinite) path is \emph{tight} if it is comprised only of tight edges.

\begin{claim}\label{claim:tightpaths}
Let $\pi$ be an infinite tight path from $v_0$.
For each $k\geq 0$, there are finitely many vertices~$v$ on $\pi$ satisfying $n(v) \leq k$.
\end{claim}

\begin{claimproof}
Denote $\pi = v_0 \re{w_0} v_1 \re{w_1} \dots$;
since all edges are tight, we have
\[
    n(v_i) = n(v_0) + \sum_{j<i} w_j.
\]
Since $\pi$ satisfies $\STI$, $\sum_{j<i} w_j$ converges to $+\infty$; therefore, so does $n(v_i)$.
The result follows.
\end{claimproof}

We now define a morphism $\phi\colon T[v_0] \to U$.
First, notice that all vertices $v$ in $T[v_0]$ are such that $n(v) < +\infty$; otherwise, we would also have $n(v_0) = +\infty$.
For $v$ in $T[v_0]$, we define the length of the tuple $\phi(v)$ to be $\max\{n(v)+1,0\}\in\N$ (in particular, if $n(v)<0$, then~$\phi(v)$ is the empty tuple).
For a vertex $v$ in $T[v_0]$ with $n(v)\geq 0$ and $0\leq k \leq n(v)$, the $k$-th coordinate of $\phi(v)$ is defined as follows.
Informally, we count the number of vertices $v'$ with $n(v') \leq k$ on a tight path starting in $v$.
Formally, define $T_{v,k}$ to be the graph with vertices
\[
    V(T_{v,k})=\{v' \in V(T) \mid \text{there is a tight path from $v$ to $v'$ and $n(v') \leq k$} \},
\]
and edges
\[
    \begin{aligned}
    E(T_{v,k})=\{v'_1 \re w v'_2 \mid w \text{ is the weight of a tight path from $v'_1$ to $v'_2$} \\ \text{whose inner vertices $v'$ satisfy $n(v')>k$} \}.
    \end{aligned}
\]
The graph $T_{v,k}$ is actually a tree with root $v$ when $k = n(v)$, but is in general a disjoint union of trees.

Claim~\ref{claim:tightpaths} implies that $T_{v,k}$ is well-founded (it does not admit any infinite path).
The rank of a vertex in a well-founded disjoint union of trees is an ordinal number defined to be~$0$ for leaves, and one plus the supremum rank of its successors for non-leaves.
The rank of~$T_{v,k}$, written~$\rk(T_{v,k})$, is the supremum rank of its vertices (note that it is $<\kappa$).

We set the $k$-th coordinate of $\phi(v)$ to be the rank of $T_{v,k}$, thus
\[
    \phi(v)=(\rk(T_{v, 0}),\rk(T_{v, 1}),\dots,\rk(T_{v, n(v)})).
\]
\begin{claim} \label{claim:morphism}
The map $\phi\colon V(T[v_0]) \to V(U)$ defines a morphism from $T[v_0]$ to $U$.
\end{claim}

\begin{claimproof}
	Consider an edge $v \re w v'$; we show that $\phi(v) \re{w} \phi(v')$ is an edge in $U$.

	First, notice that we have in general that $n(v) + w \ge 0$: indeed, $\pi = v \re w v'$ is a non-empty path from $v$ so, by definition of $n(v)$, $-n(v) \le w$.

If $n(v') < 0$, then
\[
	|\phi(v)| +w = \max(n(v)+1,0) +w \geq n(v)+1+w \ge 1 > 0 = |\phi(v')|,
\]
thus $\phi(v) \re{w} \phi(v')$ is an edge in $U$.

We now assume in the rest of the proof that $n(v') \ge 0$.
We reason according to whether the edge $v \re w v'$ is tight.
\begin{itemize}
	\item First, assume that edge $v \re w v'$ is not tight, i.e., that $n(v) + w > n(v')$.
	Then the argument is similar to the previous one:
	\[
	|\phi(v)| + w \geq n(v)+1+w > n(v') + 1 = |\phi(v')|,
	\]
	where the last equality uses that $n(v') \ge 0$.
	\item Second, assume $v \re w v'$ is tight, i.e., $n(v) + w = n(v')$.
	Therefore,
	\[
	|\phi(v)| + w \geq n(v) + 1 + w = n(v') + 1 = |\phi(v')|,
	\]
	so it suffices to show that $\phi(v) >_\lex \phi(v')$.

	Let $k \leq \min\{n(v), n(v')\}$.
	As $v'$ is reachable from $v$, $T_{v',k}$ is a subgraph of $T_{v,k}$.
	Therefore, $\rk(T_{v,k}) \geq \rk(T_{v',k})$.
	If~$n(v) > n(v')$, we deduce that $\phi(v) >_\lex \phi(v')$ ($\phi(v)$ is a longer tuple and starts with values at least as large).
	If $n(v) \le n(v')$, with $k=n(v)$, since $v$ is a vertex (in fact, the root) of $T_{v,n(v)}$ but not of $T_{v',n(v)}$, we get $\rk(T_{v,n(v)}) > \rk(T_{v',n(v)})$.
	We also conclude that $\phi(v) >_\lex \phi(v')$, as required.
	\claimqedhere
	\end{itemize}
\end{claimproof}

This ends the proof of positionality of $\STI$.
\end{proof}

